window.FACTION_INFO = window.FACTION_INFO || {};
window.FACTION_INFO.nereid = "\u003csection class=\"faction-detail\"\u003e\r\n  \u003ch2\u003e기업 개요\u003c/h2\u003e\r\n  \u003cp class=\"faction-quote\"\u003e“모든 생명은 물로부터 시작된다.”\u003c/p\u003e\r\n  \u003cp\u003e네레이드 하이드로시스템즈는 수자원의 탐사, 취수, 정수, 저장, 유통과 수권 거래를 독점적으로 수행하는 초거대 수자원 기업이다. 2102년 백야로 기존 국가의 수도망과 지표 수원이 붕괴한 이후, 약 700년에 걸쳐 정수시설과 수권경제를 확장하며 문명의 생명줄을 관리하는 기업으로 성장했다.\u003c/p\u003e\r\n  \u003cp\u003e오늘날 돔 시티의 정수 공급망부터 장막 도시의 공동 급수소, 황무지의 대형 우물과 담수화 시설에 이르기까지 수많은 사람이 네레이드의 물에 의존한다. 네레이드가 공급을 중단한 도시는 며칠 안에 기능을 상실하며, 네레이드가 새로운 수원을 발견한 지역에는 곧 시장과 정착지가 형성된다.\u003c/p\u003e\r\n  \u003cp\u003e물은 생존에 필요한 자원인 동시에 화폐와 담보 자산이기 때문에, 네레이드는 세계 최대의 수자원 기업이자 사실상의 중앙은행으로 평가받는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기본 정보\u003c/h2\u003e\r\n  \u003ctable class=\"data-table faction-info-table\"\u003e\r\n    \u003ctbody\u003e\r\n      \u003ctr\u003e\u003cth\u003e정식 명칭\u003c/th\u003e\u003ctd\u003eNEREID HYDROSYSTEMS\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e통칭\u003c/th\u003e\u003ctd\u003e네레이드\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e기업 분류\u003c/th\u003e\u003ctd\u003e수자원·정수·수권 금융기업\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 산업\u003c/th\u003e\u003ctd\u003e수원 탐사, 취수, 정수, 담수화, 저장, 배급\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e금융 산업\u003c/th\u003e\u003ctd\u003e수권 발행, 드롭 보증, 수자원 담보대출\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 고객\u003c/th\u003e\u003ctd\u003e돔 시티, 장막 도시, 기업시설, 카라반, 대형 농업시설\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e상징 색상\u003c/th\u003e\u003ctd\u003e심해색, 청록색, 백색\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표적인 인식\u003c/th\u003e\u003ctd\u003e생명의 공급자이자 목을 쥔 채권자\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e칠정 내 역할\u003c/th\u003e\u003ctd\u003e수자원과 화폐 가치의 안정\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e본사 성격\u003c/th\u003e\u003ctd\u003e정수시설, 금융센터, 수권보관소가 결합된 복합시설\u003c/td\u003e\u003c/tr\u003e\r\n    \u003c/tbody\u003e\r\n  \u003c/table\u003e\r\n\r\n  \u003ch2\u003e기업의 역사\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e백야 이전 — 21세기 후반\u003c/h3\u003e\r\n  \u003cp\u003e네레이드의 기원은 21세기 후반에 설립된 복수의 환경기업과 수자원 연구기관에서 시작되었다.\u003c/p\u003e\r\n  \u003cp\u003e당시 인류는 기후변화와 사막화, 해수면 상승과 반복되는 대규모 가뭄에 직면하고 있었다. 그러나 국가와 대기업들은 물 부족을 문명의 종말을 초래할 문제라기보다 새로운 산업시장으로 바라보았다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드의 전신 기업들은 해수담수화, 지하수 정화, 대기 수분 포집과 심층 수맥 탐사 기술을 개발했다. 이들은 국가의 수도망을 보조하고 사막화 지역과 대형 산업단지에 용수를 공급하는 기업들이었다.\u003c/p\u003e\r\n  \u003cp\u003e높은 유지비와 불확실한 수익성 때문에 상당수 사업이 정부 지원에 의존했지만, 이들이 건설한 정수시설과 지하 저장고는 훗날 인류 문명의 생존 기반이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e21세기 말, 세계적인 물 부족이 가속되자 전신 기업들은 수원 지도, 정수 특허, 담수화 시설과 저장시설을 통합하기 시작했다. 이 통합 수자원 기업이 훗날 네레이드 하이드로시스템즈로 발전한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e2102년 — 백야\u003c/h3\u003e\r\n  \u003cp\u003e2102년, 백야가 발생했다.\u003c/p\u003e\r\n  \u003cp\u003e궤도 위성과 기후관측망, 국가 기반시설과 세계적인 물류체계가 동시에 붕괴했다. 강수량과 기후를 예측할 수 없게 되었으며, 전쟁과 시설파괴로 인해 수많은 정수장과 상수도망이 기능을 상실했다.\u003c/p\u003e\r\n  \u003cp\u003e지표의 강과 호수는 방사성 낙진, 산업폐기물과 정체불명의 생물성 오염에 노출되었다. 살아남은 국가와 도시들은 식량보다 먼저 깨끗한 물의 부족에 직면했다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드의 전신 기업들은 백야 이전에 확보해 둔 심층 수맥 지도와 독립형 정수시설을 활용해 생존 거점에 물을 공급했다. 통신망과 행정체계가 무너진 상황에서 이들이 가진 자료와 장비는 국가의 어떤 자산보다도 가치가 높았다.\u003c/p\u003e\r\n  \u003cp\u003e도시와 생존집단은 식수를 얻기 위해 네레이드에 토지, 광산권, 시설, 기술자료와 장기 노동계약을 넘겼다. 아직 기능을 유지하던 일부 정부조차 수원을 보호할 힘을 잃고 수도시설의 운영권을 기업에 양도했다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드는 수많은 사람을 살렸다.\u003c/p\u003e\r\n  \u003cp\u003e그리고 그 대가로 그들이 살아가는 땅의 물을 소유하게 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망력 초기 — 생존기업의 시대\u003c/h3\u003e\r\n  \u003cp\u003e백야 이후 수십 년 동안 네레이드는 정수기업이라기보다 거대한 생존집단에 가까웠다.\u003c/p\u003e\r\n  \u003cp\u003e기업의 기술자와 경비대, 생존자들은 이동식 정수차량을 중심으로 황무지를 이동하며 오염되지 않은 수원을 찾아다녔다. 안전한 수원이 발견된 장소에는 임시 급수소가 설치되었고, 급수소 주변에는 시장과 거주지가 생겨났다.\u003c/p\u003e\r\n  \u003cp\u003e오늘날 존재하는 일부 장막 도시는 이 시기에 세워진 네레이드 급수거점에서 시작되었다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 모든 수원을 지킬 수는 없었다. 수원을 차지하기 위한 전쟁이 계속되었고, 네레이드의 초기 시설 상당수가 약탈자와 군벌에게 넘어갔다. 물탱크 하나를 두고 수백 명이 목숨을 잃는 일도 드물지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드는 살아남기 위해 수원보안부의 전신이 되는 무장조직을 창설했다. 기술자만큼 총을 다루는 경비원이 중요해졌으며, 수원에 대한 무단접근은 생존자 전체를 위협하는 행위로 간주되었다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기에 형성된 강경한 보안문화는 700년이 지난 현재까지도 네레이드 내부에 남아 있다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 1세기 — 수권의 탄생\u003c/h3\u003e\r\n  \u003cp\u003e기존 국가화폐가 가치를 잃자 물은 가장 신뢰할 수 있는 실물자산이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e초기의 거래는 물이 담긴 병이나 저장용기를 직접 교환하는 방식으로 이루어졌다. 하지만 물은 무겁고 운송이 어려웠으며, 보관 과정에서 오염되거나 탈취될 위험이 컸다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드는 이 문제를 해결하기 위해 자사가 보유한 정제수와 지하수 매장량을 담보로 교환증을 발행했다. 교환증을 소지한 사람은 지정된 급수소에서 일정량의 물을 받을 수 있었다.\u003c/p\u003e\r\n  \u003cp\u003e이것이 최초의 수권이었다.\u003c/p\u003e\r\n  \u003cp\u003e수권은 네레이드의 공급망이 확장되면서 황무지 전역에서 화폐처럼 사용되기 시작했다. 물을 직접 운반하지 않아도 거래할 수 있다는 점에서 상인과 카라반은 수권을 적극적으로 받아들였다.\u003c/p\u003e\r\n  \u003cp\u003e초기의 수권은 종이문서, 각인된 금속판과 기계식 인증표의 형태로 존재했다. 수백 년 동안 발행방식은 여러 차례 변화했지만, “약속된 양의 물과 교환할 수 있는 권리”라는 근본적인 원칙은 달라지지 않았다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 2~3세기 — 물의 전쟁\u003c/h3\u003e\r\n  \u003cp\u003e정착지가 도시로 성장하고 인구가 증가하면서 수자원을 둘러싼 대규모 전쟁이 시작되었다.\u003c/p\u003e\r\n  \u003cp\u003e군벌, 도시국가와 신흥기업들은 네레이드가 보유한 지하수원과 담수화 시설을 차지하려 했다. 네레이드 역시 공급계약을 거부하거나 수권을 인정하지 않는 도시를 상대로 물류봉쇄와 급수중단을 시행했다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기는 후대에 ‘물의 전쟁’이라 불린다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드는 직접 대규모 군대를 운영하는 대신 수원시설을 요새화하고, 우호적인 도시와 용병집단에 물을 우선 공급했다. 적대세력의 이동경로에서는 급수소를 폐쇄하고 우물을 봉인했다.\u003c/p\u003e\r\n  \u003cp\u003e전쟁은 네레이드가 주요 수원을 지키는 데 성공하면서 끝났다. 그러나 이 시기를 거치며 네레이드는 생명을 구하는 기업인 동시에 물을 무기로 사용하는 세력이라는 인식을 얻게 되었다.\u003c/p\u003e\r\n  \u003cp\u003e현재까지 이어지는 네레이드에 대한 공포와 불신의 상당 부분은 이 시대에서 비롯되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 4세기 — 돔 시티의 탄생\u003c/h3\u003e\r\n  \u003cp\u003e대형 돔 시티가 건설되기 시작하면서 네레이드는 새로운 성장기를 맞이했다.\u003c/p\u003e\r\n  \u003cp\u003e완전히 밀폐된 도시를 유지하려면 안정적인 수원과 거대한 순환정수시설이 필요했다. 네레이드는 아르카디아를 비롯한 도시개발기업에 수자원 기술과 장기 공급계약을 제공했다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드는 돔 내부에 대형 지하 저수조인 아비스 저장고를 건설하고, 생활하수를 다시 음용 가능한 수준으로 정화하는 폐쇄순환식 수도체계를 구축했다.\u003c/p\u003e\r\n  \u003cp\u003e이 과정에서 네레이드는 단순히 외부에서 물을 공급하는 회사에서 도시의 생존설비 자체를 설계하고 관리하는 기업으로 변했다.\u003c/p\u003e\r\n  \u003cp\u003e돔 시티는 네레이드의 물을 통해 성장했고, 네레이드는 돔 시티의 인구와 산업을 통해 막대한 부를 축적했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 5세기 — 블루넷과 전자 수권\u003c/h3\u003e\r\n  \u003cp\u003e블루넷이 대륙의 주요 도시와 기업시설을 연결하면서 수권 역시 전자화되었다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드는 각 급수소의 저장량과 수질, 거래기록을 블루넷에 등록하고 개인과 기업의 계좌에 전자 수권을 발행했다. 이로써 사람들은 도시와 황무지를 오가며 물리적인 증서를 운반하지 않고도 거래할 수 있게 되었다.\u003c/p\u003e\r\n  \u003cp\u003e전자 수권은 이후 가상화폐인 크레딧의 가치보증 체계와 연결되었다.\u003c/p\u003e\r\n  \u003cp\u003e크레딧이 물과 완전히 동일한 화폐는 아니지만, 네레이드가 보유한 수자원과 공급능력은 크레딧 경제의 신뢰를 지탱하는 핵심 담보가 되었다.\u003c/p\u003e\r\n  \u003cp\u003e이 시점부터 네레이드는 수자원 기업이면서 사실상의 중앙은행 역할을 수행하기 시작했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 6세기 — 칠정의 성립\u003c/h3\u003e\r\n  \u003cp\u003e초거대 기업들이 도시와 산업을 분할해 지배하기 시작하면서 기업 간 전쟁과 자원분쟁이 급증했다.\u003c/p\u003e\r\n  \u003cp\u003e특히 물과 전력, 도시건설과 운송망은 서로 완전히 분리할 수 없는 산업이었다. 네레이드가 공급을 제한하면 아르카디아의 도시가 멈추었고, 솔라리스가 전력을 끊으면 네레이드의 담수화 시설이 정지했다. 카론이 운송을 거부하면 황무지로 물을 보낼 수 없었다.\u003c/p\u003e\r\n  \u003cp\u003e어느 기업도 다른 기업을 완전히 제거하고 홀로 살아남을 수 없었다.\u003c/p\u003e\r\n  \u003cp\u003e결국 네레이드를 포함한 일곱 초거대 기업은 상호협정과 공동의사결정 체계를 수립했다. 이것이 오늘날 칠정과 블루 테이블의 기반이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드는 칠정 내에서 수자원과 화폐가치의 안정을 담당했다. 공식적으로는 다른 여섯 기업과 동등한 위치였지만, 모든 도시와 산업이 물을 필요로 한다는 사실 때문에 특별한 영향력을 보유하게 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e현재 — 멸망 후 700년\u003c/h3\u003e\r\n  \u003cp\u003e현재는 백야가 발생한 2102년으로부터 약 700년이 지난 시대다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드는 더 이상 과거의 수자원 기업과 동일한 조직이 아니다. 700년에 걸쳐 수많은 경영진과 기술자, 주주와 시설이 교체되었지만 기업의 명칭과 핵심 계약은 끊어지지 않고 이어져 왔다.\u003c/p\u003e\r\n  \u003cp\u003e현대의 네레이드는 대륙 전역의 수원, 담수화 시설, 지하 저수조와 급수망을 관리한다. 세계에 존재하는 모든 물을 소유한 것은 아니지만, 문명권에서 거래되는 정제수와 수권의 기준을 결정할 수 있는 유일한 기업이다.\u003c/p\u003e\r\n  \u003cp\u003e돔 시티의 시민들은 태어나면서부터 네레이드의 배급망에 등록된다. 기업과 도시는 앞으로 사용할 물을 담보로 자금을 빌리고, 카라반은 네레이드 수권을 기준으로 화물의 가격을 계산한다.\u003c/p\u003e\r\n  \u003cp\u003e장막 도시와 황무지에는 독립적인 우물과 정수시설도 존재한다. 그러나 대규모 오염이나 가뭄이 발생하면 결국 네레이드의 기술과 공급망에 의존해야 한다.\u003c/p\u003e\r\n  \u003cp\u003e700년 동안 왕국과 군벌, 도시와 기업이 수없이 생겨나고 사라졌다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 사람에게 물이 필요하다는 사실은 단 한 번도 변하지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e그 불변의 필요성이 네레이드를 현존하는 가장 오래되고 강력한 기업 중 하나로 만들었다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e핵심 산업\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e수원 탐사\u003c/h3\u003e\r\n  \u003cp\u003e네레이드는 위성자료, 지질관측기, 탐사 드론과 심층 굴착장비를 이용해 새로운 지하수원을 발견한다. 기존 지도에 기록되지 않은 지하 호수, 붕괴한 도시의 저수시설과 오염되지 않은 빙하 저장고도 주요 탐사 대상이다.\u003c/p\u003e\r\n  \u003cp\u003e새로운 수원의 발견은 단순한 자원개발 이상의 의미를 가진다. 충분한 수량이 확인되면 주변에 급수소와 정비시설이 들어서고, 카라반 노선과 정착지가 새롭게 형성된다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드의 수원 탐사대는 때때로 고대 시설, 지하도시나 백야 이전의 봉인구역을 발견하기도 한다. 이 때문에 탐사대에는 지질학자뿐 아니라 중무장 경비원과 오염 대응요원이 동행한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e취수와 정수\u003c/h3\u003e\r\n  \u003cp\u003e네레이드가 공급하는 물은 여러 등급으로 구분된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e\u003cstrong\u003e산업용수:\u003c/strong\u003e 냉각, 세척, 채굴과 제조시설에 사용되는 저가 용수\u003c/li\u003e\r\n    \u003cli\u003e\u003cstrong\u003e생활용수:\u003c/strong\u003e 세척과 일반 생활에 사용할 수 있는 표준 용수\u003c/li\u003e\r\n    \u003cli\u003e\u003cstrong\u003e음용수:\u003c/strong\u003e 장기간 음용이 가능한 정제수\u003c/li\u003e\r\n    \u003cli\u003e\u003cstrong\u003e의료용수:\u003c/strong\u003e 수술과 약품 제조에 사용하는 고순도 정제수\u003c/li\u003e\r\n    \u003cli\u003e\u003cstrong\u003e프라임 워터:\u003c/strong\u003e 상류층을 위한 최고급 음용수\u003c/li\u003e\r\n    \u003cli\u003e\u003cstrong\u003e시드 워터:\u003c/strong\u003e 농업과 생태복원에 특화된 미네랄 조정수\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e정수 과정에서는 방사성 물질, 중금속, 미세기계 오염과 변이성 미생물을 제거한다. 특정 지역의 물은 일반적인 필터만으로 처리할 수 없어 네레이드가 독점한 생체막이나 나노 정화장치를 사용해야 한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e해수담수화\u003c/h3\u003e\r\n  \u003cp\u003e해안 인근의 대형 돔과 산업도시는 네레이드의 담수화 시설에 크게 의존한다. 담수화 플랜트는 막대한 에너지와 정교한 장비를 필요로 하기 때문에 솔라리스의 전력망과 긴밀하게 연결되어 있다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드는 담수화 과정에서 발생하는 소금과 희귀 광물도 회수한다. 이 부산물은 화학공업, 배터리 제조와 식품산업에 판매된다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e저장과 배급\u003c/h3\u003e\r\n  \u003cp\u003e물은 거대한 지하 저수조, 장갑 수송차량과 밀폐형 저장탱크에 보관된다. 핵심 시설은 군사기지에 준하는 방어체계를 갖추며, 출입 기록과 수질자료는 블루넷에 실시간으로 전송된다.\u003c/p\u003e\r\n  \u003cp\u003e도시 내부의 공급량은 시민권 등급, 기업계약과 지역별 배급정책에 따라 달라진다. 상류층 구역은 항상 안정적인 수압과 고품질 정제수를 공급받지만, 하층 구역에서는 시간제 급수와 사용량 제한이 적용되는 경우가 많다.\u003c/p\u003e\r\n  \u003cp\u003e장막 도시는 네레이드가 직접 운영하거나 지역 상단과 계약한 공동 급수소를 통해 물을 공급받는다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e농업용수와 생태관리\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아의 수경재배시설과 돔 내부의 녹지에는 네레이드가 조정한 농업용수가 사용된다. 네레이드는 작물 종류와 토양 상태에 따라 염도, 산도와 미네랄 함량을 조절한다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 이를 생태복원 사업이라고 홍보하지만, 실제로는 농업시설이 네레이드의 전용 영양제와 정수 필터를 계속 구매하도록 만드는 폐쇄적인 산업 구조에 가깝다는 비판도 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e수권과 금융사업\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e수권\u003c/h3\u003e\r\n  \u003cp\u003e수권은 지정된 네레이드 시설에서 일정량의 정제수로 교환할 수 있는 권리다. 대부분 블루넷 계좌에 전자기록 형태로 저장되지만, 통신이 불안정한 황무지에서는 물리식 수권 칩도 사용된다.\u003c/p\u003e\r\n  \u003cp\u003e수권의 가치는 다음 요소에 따라 달라진다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e교환 가능한 물의 양\u003c/li\u003e\r\n    \u003cli\u003e정제 등급\u003c/li\u003e\r\n    \u003cli\u003e교환 가능 지역\u003c/li\u003e\r\n    \u003cli\u003e만료기한\u003c/li\u003e\r\n    \u003cli\u003e운송비\u003c/li\u003e\r\n    \u003cli\u003e지역의 공급 상황\u003c/li\u003e\r\n    \u003cli\u003e네레이드 시설의 운영 상태\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e동일한 양의 물을 보증하는 수권이라도 사막 한가운데에서 사용할 수 있는 수권은 돔 시티 내부 전용 수권보다 훨씬 높은 가격에 거래될 수 있다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e드롭\u003c/h3\u003e\r\n  \u003cp\u003e드롭은 네레이드의 수자원 보증을 기반으로 유통되는 소액 거래단위다. 시민들은 일상적으로 식량, 전력과 생활용품을 구매할 때 드롭을 사용하며, 기업들은 대규모 거래에서 크레딧과 수권을 병행한다.\u003c/p\u003e\r\n  \u003cp\u003e드롭은 물과 완전히 동일하지 않지만, 네레이드가 일정 수준의 교환과 가치 유지를 보증한다. 따라서 대형 수원이 오염되거나 담수화 시설이 정지하면 드롭의 가치도 즉각 흔들린다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e수자원 담보대출\u003c/h3\u003e\r\n  \u003cp\u003e도시와 기업은 미래의 물 공급권이나 미개발 수원을 담보로 네레이드에서 자금을 빌릴 수 있다. 상환에 실패하면 네레이드는 해당 지역의 수도시설, 토지와 배급권을 인수한다.\u003c/p\u003e\r\n  \u003cp\u003e이 방식은 파산 직전의 정착지를 살릴 수 있지만, 동시에 도시 전체가 네레이드의 채무 구역으로 편입되는 원인이 되기도 한다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드가 물 부족을 이용해 부실 지역의 자산을 헐값에 사들인다는 의혹은 끊이지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업 구조\u003c/h2\u003e\r\n  \u003cp\u003e네레이드의 최고 의사결정기관은 이사회이며, 대표이사 아래 수자원관리총괄이 실무를 지휘한다.\u003c/p\u003e\r\n  \u003ch3\u003e이사회\u003c/h3\u003e\r\n  \u003cp\u003e대규모 수원 개발, 수권 발행량, 도시별 공급계약과 칠정 내 협상을 결정한다. 주요 수원을 소유한 창립 주주와 금융 책임자들이 강한 영향력을 행사한다.\u003c/p\u003e\r\n  \u003ch3\u003e대표이사\u003c/h3\u003e\r\n  \u003cp\u003e기업 전체의 전략과 대외관계를 책임진다. 단순한 기업경영자가 아니라 세계 수자원 시장의 방향을 결정하는 인물로 취급된다.\u003c/p\u003e\r\n  \u003ch3\u003e수자원관리총괄\u003c/h3\u003e\r\n  \u003cp\u003e탐사부터 배급까지 이어지는 모든 수자원 사업을 통제한다. 대형 오염사고나 수원 분쟁이 발생하면 군사작전에 가까운 비상권한을 행사할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e개발·생산 부문\u003c/h3\u003e\r\n  \u003cp\u003e수맥 탐사, 심층 굴착, 취수시설 건설과 정수 생산을 담당한다. 네레이드의 기술적 기반을 구성하는 핵심 부문이다.\u003c/p\u003e\r\n  \u003ch3\u003e품질·유통 부문\u003c/h3\u003e\r\n  \u003cp\u003e수질검사, 저수시설, 배급망과 수송차량을 관리한다. 공급량을 조정하는 권한을 가지고 있어 도시 행정부와 자주 충돌한다.\u003c/p\u003e\r\n  \u003ch3\u003e수권·금융 부문\u003c/h3\u003e\r\n  \u003cp\u003e수권 발행, 드롭 보증, 기업대출과 자원계약을 담당한다. 외부에서는 정수기술 부문보다 이들이 네레이드의 실질적인 권력자라는 평가도 나온다.\u003c/p\u003e\r\n  \u003ch3\u003e수원보안부\u003c/h3\u003e\r\n  \u003cp\u003e저수시설과 수송대를 보호하는 기업 보안조직이다. 수원 테러, 약탈, 시설 점거와 불법 취수에 대응한다.\u003c/p\u003e\r\n  \u003cp\u003e수원에 대한 공격은 대량학살로 이어질 수 있기 때문에 수원보안부는 일반적인 기업 경비보다 훨씬 강한 교전권을 가진다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 기술\u003c/h2\u003e\r\n  \u003cp\u003e네레이드가 사용하는 기술 중 상당수는 백야 이전의 원형기술을 기반으로 한다. 그러나 700년에 걸친 개량과 재설계를 거쳤기 때문에 현재의 장비는 과거의 정수설비와 구조적으로 크게 달라졌다. 일부 기술은 원리가 완전히 이해되지 않은 상태에서 유지보수 지침만 계승되고 있다.\u003c/p\u003e\r\n  \u003ch3\u003e심층수맥 탐지망\u003c/h3\u003e\r\n  \u003cp\u003e지질진동, 열분포와 미세한 습도 변화를 분석해 수 킬로미터 아래의 지하수를 탐지한다. 정확한 탐사자료는 최고등급 기업기밀로 관리된다.\u003c/p\u003e\r\n  \u003ch3\u003e다중막 정수 시스템\u003c/h3\u003e\r\n  \u003cp\u003e나노막, 생체막과 화학 필터를 연속적으로 사용해 복합 오염수를 정화한다. 일부 고급 시설은 미확인 유기체와 나노머신까지 제거할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e대기 수분 포집기\u003c/h3\u003e\r\n  \u003cp\u003e공기 중의 미세한 수분을 응축해 물로 변환한다. 생산량은 적지만 독립적인 생존시설과 황무지 초소에서 중요한 역할을 한다.\u003c/p\u003e\r\n  \u003ch3\u003e이동식 정수차량\u003c/h3\u003e\r\n  \u003cp\u003e오염수만 확보되면 현장에서 생활용수와 음용수를 생산할 수 있는 대형 차량이다. 재난지역, 전쟁터와 신규 정착지에 우선 투입된다.\u003c/p\u003e\r\n  \u003ch3\u003e수원 봉쇄장치\u003c/h3\u003e\r\n  \u003cp\u003e오염이나 탈취가 확인된 수원시설을 원격으로 폐쇄하는 보안체계다. 봉쇄가 실행되면 네레이드의 인증 없이는 배관과 저장고를 사용할 수 없다.\u003c/p\u003e\r\n  \u003cp\u003e이 장치는 수질재난을 막기 위한 안전장치이지만, 네레이드가 반항적인 도시의 물을 원격으로 차단할 수 있다는 뜻이기도 하다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 시설\u003c/h2\u003e\r\n  \u003ch3\u003e중앙 수권보관소\u003c/h3\u003e\r\n  \u003cp\u003e수자원 보유량, 수권 발행량과 도시별 채무정보가 기록된 핵심 금융시설이다. 네레이드의 실질적인 금고이자 크레딧 경제를 지탱하는 중요시설이다.\u003c/p\u003e\r\n  \u003ch3\u003e아비스 저장고\u003c/h3\u003e\r\n  \u003cp\u003e돔 시티 지하에 건설된 초대형 저수시설의 통칭이다. 하나의 저장고에는 수십만 명이 수개월 동안 사용할 수 있는 물이 보관된다.\u003c/p\u003e\r\n  \u003cp\u003e정확한 위치와 저장량은 공개되지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e블루 웰\u003c/h3\u003e\r\n  \u003cp\u003e황무지의 주요 교역로에 설치된 네레이드 급수 거점이다. 급수시설, 정비소, 숙소와 거래소를 갖추고 있어 작은 마을처럼 성장한 곳도 많다.\u003c/p\u003e\r\n  \u003ch3\u003e펠라기아 담수화 단지\u003c/h3\u003e\r\n  \u003cp\u003e네레이드가 운영하는 최대 규모의 해수담수화 시설군이다. 솔라리스의 전력 공급과 카론의 수송망에 의존하며, 시설이 정지할 경우 복수의 돔 시티가 즉각적인 물 부족을 겪게 된다.\u003c/p\u003e\r\n  \u003ch3\u003e침묵 수원\u003c/h3\u003e\r\n  \u003cp\u003e공식 지도에 표시되지 않은 비상용 수원이다. 네레이드는 대규모 재난이나 전쟁에 대비해 비밀 저장시설과 미공개 지하수원을 운용한다는 의혹을 받고 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e직원 문화\u003c/h2\u003e\r\n  \u003cp\u003e네레이드의 보수적인 기업문화는 700년에 달하는 역사에서 비롯되었다. 수많은 국가와 도시가 사라지는 동안에도 수질검사와 배급기록은 계속해서 계승되었다. 내부에서는 개인의 판단보다 축적된 규정과 장기기록을 신뢰하며, 수백 년 전에 작성된 시설관리 원칙이 현재까지 적용되는 경우도 있다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드의 직원들은 물 한 방울도 숫자로 바라보도록 교육받는다. 모든 취수량과 손실량은 기록되며, 작은 오차도 공급망 전체의 위험으로 취급된다.\u003c/p\u003e\r\n  \u003cp\u003e기업 내부에서는 정확성, 절제와 장기계획이 가장 중요한 미덕으로 여겨진다. 화려한 성과보다 사고 없이 시설을 유지한 기간이 높은 평가를 받는다.\u003c/p\u003e\r\n  \u003cp\u003e상위 기술직과 금융직은 돔 시티에서도 손꼽히는 안정적인 생활을 보장받는다. 반면 황무지의 탐사대와 배관 유지인력은 높은 오염 위험과 습격 가능성에 노출된다.\u003c/p\u003e\r\n  \u003cp\u003e현장 직원들 사이에서는 다음과 같은 격언이 널리 사용된다.\u003c/p\u003e\r\n  \u003cblockquote\u003e물은 거짓말하지 않는다. 장부가 거짓말할 뿐이다.\u003c/blockquote\u003e\r\n\r\n  \u003ch2\u003e채용과 복지\u003c/h2\u003e\r\n  \u003cp\u003e네레이드는 수문학자, 지질학자, 화학자, 정수기술자와 금융분석가를 우대한다. 황무지 탐사 경험자, 카라반 길잡이와 시설방어 경험이 있는 용병도 자주 채용한다.\u003c/p\u003e\r\n  \u003cp\u003e정규직 직원과 가족에게는 안정적인 물 배급권이 제공된다. 네레이드의 복지 중 가장 중요한 것은 높은 임금이 아니라 평생 보장되는 음용수다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 퇴사하거나 기업기밀을 유출할 경우 본인뿐 아니라 가족의 우대 배급권까지 박탈될 수 있다. 이 때문에 직원들은 네레이드를 직장이라기보다 벗어날 수 없는 생존계약으로 인식하기도 한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e계층별 인식\u003c/h2\u003e\r\n  \u003ch3\u003e돔 시티 상류층\u003c/h3\u003e\r\n  \u003cp\u003e생활을 유지하는 필수기업이자 안정적인 투자처로 본다. 프라임 워터와 개인 수질관리 서비스는 상류층의 지위를 상징한다.\u003c/p\u003e\r\n  \u003cp\u003e이들에게 네레이드는 공기처럼 당연하게 존재하는 기반시설이다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 시티 일반 시민\u003c/h3\u003e\r\n  \u003cp\u003e물을 공급하는 고마운 기업이라는 인식과 과도한 요금을 부과하는 독점기업이라는 불만이 공존한다. 배급제한이 발생하면 가장 먼저 비난받는 기업이기도 하다.\u003c/p\u003e\r\n  \u003ch3\u003e장막 도시 주민\u003c/h3\u003e\r\n  \u003cp\u003e지역에 따라 평가가 극단적으로 갈린다. 안정적인 급수소가 있는 지역에서는 생명의 은인으로 취급되지만, 채무 때문에 공동우물을 빼앗긴 지역에서는 약탈자나 다름없는 존재로 여겨진다.\u003c/p\u003e\r\n  \u003ch3\u003e황무지인과 카라반\u003c/h3\u003e\r\n  \u003cp\u003e네레이드의 수권은 가장 신뢰할 수 있는 거래수단이다. 동시에 수원 위치를 독점하고 가격을 조정하는 위험한 세력으로 경계한다.\u003c/p\u003e\r\n  \u003cp\u003e황무지에서는 네레이드 급수차량 한 대가 작은 군대보다 가치 있다는 말이 있다.\u003c/p\u003e\r\n  \u003ch3\u003e다른 기업\u003c/h3\u003e\r\n  \u003cp\u003e모든 기업이 네레이드와 장기 공급계약을 유지하려 한다. 공개적으로 적대하는 기업은 거의 없지만, 네레이드의 수자원 독점이 지나치게 강해지는 것은 원하지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e다른 세력과의 관계\u003c/h2\u003e\r\n  \u003ch3\u003eSOLARIS ORBITAL INDUSTRIES\u003c/h3\u003e\r\n  \u003cp\u003e담수화와 대규모 정수시설 운영에 필요한 전력을 공급한다. 양사는 서로의 핵심 기반시설에 의존하면서도 전력요금과 용수요금을 두고 끊임없이 협상한다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드와 솔라리스가 동시에 공급을 중단하면 대부분의 돔 시티는 장기간 버틸 수 없다.\u003c/p\u003e\r\n  \u003ch3\u003eARCADIA HABITAT\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아는 도시 내부의 배관과 생활환경을 관리하고, 네레이드는 원수와 정제수를 공급한다. 업무 영역이 맞닿아 있어 긴밀한 동맹관계인 동시에 책임 소재를 두고 자주 충돌한다.\u003c/p\u003e\r\n  \u003cp\u003e수질사고가 발생하면 양측은 오염이 수원에서 시작되었는지 도시 배관에서 시작되었는지를 두고 서로 책임을 떠넘긴다.\u003c/p\u003e\r\n  \u003ch3\u003eMORPHOS BIODYNE\u003c/h3\u003e\r\n  \u003cp\u003e모르포스는 의료용수와 생체배양용 고순도 정제수의 주요 고객이다. 반대로 네레이드는 모르포스의 생체막 기술을 정수시설에 사용한다.\u003c/p\u003e\r\n  \u003cp\u003e일부 고급 정수막이 인간이나 변이 생물의 조직을 기반으로 만들어진다는 소문이 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003eCERBERUS DEFENSE GROUP\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 네레이드의 수원보안부에 화기, 장갑차와 방어 드론을 공급한다. 전쟁이 발생하면 네레이드는 케르베로스의 군수시설에 우선 용수를 제공하는 대신 수송대 호위를 지원받는다.\u003c/p\u003e\r\n  \u003ch3\u003eCHARON INTERCONTINENTAL\u003c/h3\u003e\r\n  \u003cp\u003e네레이드의 물을 대륙 전역으로 운송하는 핵심 파트너다. 대형 수송관이 없는 지역에서는 카론의 장갑철도와 육상선단이 사실상 유일한 대량 운송수단이다.\u003c/p\u003e\r\n  \u003cp\u003e양사의 계약이 끊기면 장막 도시와 황무지 정착지가 가장 먼저 피해를 입는다.\u003c/p\u003e\r\n  \u003ch3\u003eARGOS SECURE NETWORKS\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 수원 테러, 밀수와 공급망 교란을 감시한다. 네레이드는 그 대가로 배급기록과 수권 거래정보 일부를 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e이 거래기록을 이용하면 개인과 조직의 이동경로를 추적할 수 있기 때문에, 시민단체들은 양사의 정보공유를 심각한 사생활 침해로 본다.\u003c/p\u003e\r\n  \u003ch3\u003eTHE BLUE TABLE\u003c/h3\u003e\r\n  \u003cp\u003e블루 테이블은 네레이드의 수권 발행량과 기업 간 용수계약을 감독한다. 그러나 실제 수원정보는 네레이드가 독점하고 있어 감독의 실효성에 의문이 제기된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e사회공헌과 홍보\u003c/h2\u003e\r\n  \u003cp\u003e네레이드는 스스로를 “문명을 흐르게 하는 기업”이라고 소개한다.\u003c/p\u003e\r\n  \u003cp\u003e장막 도시의 공동 급수소 설치, 오염지역 정수 지원과 아동 대상 위생교육을 대표적인 사회공헌 사업으로 홍보한다. 가뭄과 재난이 발생하면 이동식 정수차량을 파견하고 일정 기간 무료로 물을 배급하기도 한다.\u003c/p\u003e\r\n  \u003cp\u003e다만 무료배급이 끝난 뒤 해당 지역이 네레이드의 장기 공급계약에 편입되는 경우가 많다. 비판자들은 이를 구호가 아니라 시장 개척이라고 부른다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e논란과 비판\u003c/h2\u003e\r\n  \u003ch3\u003e물의 독점\u003c/h3\u003e\r\n  \u003cp\u003e인간의 생존에 필수적인 자원을 사기업이 소유하는 것이 정당한가에 대한 비판이 끊이지 않는다. 네레이드는 자신들이 아니었다면 수원 자체가 유지되지 못했을 것이라고 반박한다.\u003c/p\u003e\r\n  \u003ch3\u003e인위적인 공급 부족\u003c/h3\u003e\r\n  \u003cp\u003e네레이드가 수권 가격을 유지하기 위해 충분한 물을 보유하고도 배급량을 제한한다는 의혹이 있다. 기업은 비상사태에 대비한 필수 비축이라고 주장한다.\u003c/p\u003e\r\n  \u003ch3\u003e수원 강제인수\u003c/h3\u003e\r\n  \u003cp\u003e채무를 상환하지 못한 정착지의 공동우물과 수도시설을 인수하는 과정에서 무장 보안부가 주민을 강제퇴거시킨 사례가 보고된다.\u003c/p\u003e\r\n  \u003ch3\u003e차등 수질\u003c/h3\u003e\r\n  \u003cp\u003e공식적으로 모든 음용수는 안전기준을 만족한다. 그러나 상류층과 기업구역에 더 높은 등급의 물이 공급되는 것은 공공연한 사실이다.\u003c/p\u003e\r\n  \u003cp\u003e일부 장막 도시에서는 기준치에 가까운 오염수가 생활용수라는 명목으로 배급되기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e배급정보 감시\u003c/h3\u003e\r\n  \u003cp\u003e네레이드는 시민 개개인의 물 사용량을 기록한다. 기업은 누수 탐지와 공급계획을 위한 정보라고 설명하지만, 비정상적인 사용량을 근거로 은신처나 불법병원을 찾아낼 수 있다는 점이 문제로 지적된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e확인되지 않은 소문\u003c/h2\u003e\r\n  \u003cp\u003e네레이드의 중앙기록고에는 2102년 백야 당시 확보한 최초의 수원 지도와 초기 수권 장부가 보관되어 있다는 소문이 있다.\u003c/p\u003e\r\n  \u003cp\u003e해당 기록에는 현재의 네레이드조차 위치를 확인하지 못한 심층 수원, 지도에서 사라진 도시와 700년 동안 한 번도 개방되지 않은 비밀 저장시설이 기록되어 있다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e또한 네레이드가 공식적인 역사보다 오래전부터 백야의 발생 가능성을 알고 있었으며, 재난 직전에 핵심 기술과 인력을 안전지역으로 이동시켰다는 의혹도 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e만약 이 주장이 사실이라면 네레이드는 백야에서 우연히 살아남은 기업이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 멸망을 예상하고 준비한 기업이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업이 가진 힘\u003c/h2\u003e\r\n  \u003cp\u003e네레이드의 힘은 군대나 정보망에서 나오지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e그들의 권력은 수도꼭지를 열었을 때 물이 나온다는 사실에서 비롯된다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드가 물을 공급하는 한 도시는 살아간다. 공급량이 줄어들면 배급제가 시작되고, 가격이 상승하며, 주민들은 떠날 준비를 한다. 공급이 완전히 끊기면 화려한 돔 시티조차 며칠 만에 거대한 무덤으로 변한다.\u003c/p\u003e\r\n  \u003cp\u003e그렇기에 네레이드는 총을 들지 않고도 도시를 굴복시킬 수 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 사건 소재\u003c/h2\u003e\r\n  \u003ch3\u003e사라진 수원\u003c/h3\u003e\r\n  \u003cp\u003e새롭게 발견된 대형 지하수원의 좌표를 전송하던 탐사대가 실종된다. 네레이드는 탐사대 구조와 모든 기록의 회수를 의뢰한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 현장에는 이미 아르고스 요원과 장막 도시 주민들이 도착해 있다.\u003c/p\u003e\r\n  \u003ch3\u003e오염된 아비스\u003c/h3\u003e\r\n  \u003cp\u003e돔 시티의 지하 저수조에서 정체불명의 생물성 오염이 발견된다. 네레이드는 시민들이 사실을 알기 전에 문제를 해결하려 한다.\u003c/p\u003e\r\n  \u003cp\u003e오염의 원인은 외부 침입이 아니라 정수시설 내부에서 진행된 비밀실험일 가능성이 있다.\u003c/p\u003e\r\n  \u003ch3\u003e끊어진 배급\u003c/h3\u003e\r\n  \u003cp\u003e한 장막 도시의 급수가 예고 없이 중단된다. 네레이드는 채무불이행에 따른 합법적인 조치라고 주장하지만, 주민들은 계약서가 조작되었다고 말한다.\u003c/p\u003e\r\n  \u003ch3\u003e가짜 수권\u003c/h3\u003e\r\n  \u003cp\u003e황무지에 정교하게 위조된 네레이드 수권이 대량으로 유통된다. 단순한 사기처럼 보이지만 위조 수권 중 일부는 실제 네레이드 시설에서 정상적으로 인식된다.\u003c/p\u003e\r\n  \u003ch3\u003e움직이는 우물\u003c/h3\u003e\r\n  \u003cp\u003e사막 아래에서 거대한 수맥이 발견되지만 위치가 계속해서 변한다. 탐사 결과 해당 수맥은 자연적인 지하수가 아니라 백야 이전에 만들어진 거대 이동시설 내부에 존재하는 것으로 드러난다.\u003c/p\u003e\r\n  \u003ch3\u003e최후의 급수차\u003c/h3\u003e\r\n  \u003cp\u003e포위된 정착지까지 정제수를 운반해야 한다. 카라반, 약탈자와 기업 용병들이 모두 같은 차량을 노리며, 목적지에 도착하더라도 누구에게 먼저 물을 배급할지 결정해야 한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e요약\u003c/h2\u003e\r\n  \u003cp\u003e네레이드 하이드로시스템즈는 물을 생산하는 회사가 아니다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 물이 어디에 존재하는지 알고, 누가 얼마나 사용할 수 있는지를 결정하며, 아직 존재하지 않는 미래의 물에 가격을 매긴다. 사람들은 네레이드를 통해 살아남지만, 바로 그 생존 때문에 네레이드에서 벗어날 수 없다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드는 문명의 혈관을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e그리고 그 혈관을 잠글 수 있는 손 역시 네레이드가 쥐고 있다.\u003c/p\u003e\r\n\u003c/section\u003e\r\n";
window.FACTION_INFO.solaris = "\u003csection class=\"faction-detail\"\u003e\r\n  \u003ch2\u003e기업 개요\u003c/h2\u003e\r\n  \u003cp class=\"faction-quote\"\u003e“하늘이 무너진 뒤에도, 우리는 태양을 운용한다.”\u003c/p\u003e\r\n  \u003cp\u003e솔라리스 궤도산업은 태양광 발전, 궤도시설, 위성통신, 기후관측과 우주기술을 관리하는 초거대 기업이다. 2102년 백야로 지구 궤도의 위성망이 붕괴한 이후, 약 700년에 걸쳐 살아남은 우주 기반시설을 회수하고 재건해 왔다.\u003c/p\u003e\r\n  \u003cp\u003e현재 솔라리스는 궤도 태양광 발전시설과 지상 송전탑, 기상관측망, 통신위성과 일소경보체계를 운영한다. 돔 시티의 전력망부터 네레이드의 담수화 시설, 블루넷의 장거리 통신과 카론의 운송노선까지 수많은 기반산업이 솔라리스의 기술에 의존한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 솔라리스의 진정한 가치는 현재 운용 중인 시설에만 있지 않다. 그들은 백야 이전에 발사된 위성과 궤도정거장, 우주공장과 태양광 집광시설의 위치를 알고 있다. 그중 상당수는 아직도 접근할 수 없으며, 일부는 700년이 지난 현재까지 지구 상공에서 정체불명의 신호를 보내고 있다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 인류에게 빛과 전력을 공급하는 기업이다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 한 번 문명을 불태웠던 하늘에 가장 가까이 다가갈 수 있는 조직이기도 하다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기본 정보\u003c/h2\u003e\r\n  \u003ctable class=\"data-table faction-info-table\"\u003e\r\n    \u003ctbody\u003e\r\n      \u003ctr\u003e\u003cth\u003e정식 명칭\u003c/th\u003e\u003ctd\u003eSOLARIS ORBITAL INDUSTRIES\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e통칭\u003c/th\u003e\u003ctd\u003e솔라리스\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e기업 분류\u003c/th\u003e\u003ctd\u003e태양광·궤도산업·우주기술 기업\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 산업\u003c/th\u003e\u003ctd\u003e궤도 태양광 발전, 위성 운용, 기상관측, 장거리 통신\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e전략 산업\u003c/th\u003e\u003ctd\u003e백야 이전 궤도시설 회수, 우주병기 감시, 일소경보\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 고객\u003c/th\u003e\u003ctd\u003e돔 시티, 칠정 기업, 블루넷 운영기관, 대형 산업시설\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e상징 색상\u003c/th\u003e\u003ctd\u003e금색, 백색, 태양광 청색\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표적인 인식\u003c/th\u003e\u003ctd\u003e문명의 빛을 유지하는 기술관료\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e칠정 내 역할\u003c/th\u003e\u003ctd\u003e에너지, 위성통신과 기상정보의 안정\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e본사 성격\u003c/th\u003e\u003ctd\u003e지상 관제센터와 궤도연락시설이 결합된 기술도시\u003c/td\u003e\u003c/tr\u003e\r\n    \u003c/tbody\u003e\r\n  \u003c/table\u003e\r\n\r\n  \u003ch2\u003e기업의 역사\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e백야 이전 — 우주시대의 개막\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스의 전신은 21세기 후반에 활동하던 우주산업체, 에너지 기업, 위성통신사와 기후공학 연구기관들이었다.\u003c/p\u003e\r\n  \u003cp\u003e당시 인류는 화석연료 고갈과 기후변화에 대응하기 위해 지상 태양광을 넘어 궤도 태양광 발전에 투자하기 시작했다. 대기와 날씨의 영향을 받지 않는 우주 공간에서 태양에너지를 수집하고, 이를 지상의 수신시설로 전송하는 기술이 개발되었다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 대규모 위성군이 기상관측, 통신, 군사감시와 물류관제를 담당했다. 인류의 산업과 행정은 점차 궤도시설에 의존하게 되었다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스의 전신 기업들은 이러한 궤도 기반시설을 통합적으로 관리하기 위해 합병되었다. 이들은 위성 발사부터 궤도정거장 건설, 태양광 집광판 운용과 지상 송전까지 모든 과정을 하나의 산업망으로 연결했다.\u003c/p\u003e\r\n  \u003cp\u003e그 중심에 있던 것이 \u003cstrong\u003e헬리오스 위성망\u003c/strong\u003e이었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e헬리오스 계획\u003c/h3\u003e\r\n  \u003cp\u003e헬리오스는 단순한 위성통신망이 아니었다.\u003c/p\u003e\r\n  \u003cp\u003e수천 기의 관측위성, 통신위성, 태양광 집광위성과 기후조절 장치가 하나의 통합 네트워크로 연결된 행성 규모의 시스템이었다. 헬리오스는 세계의 기상, 전력, 통신과 재난정보를 실시간으로 처리했다.\u003c/p\u003e\r\n  \u003cp\u003e시스템의 목적은 인류 문명의 효율적인 관리였다.\u003c/p\u003e\r\n  \u003cp\u003e헬리오스는 가뭄이 예상되는 지역에 강수를 유도하고, 태풍의 이동경로를 수정하며, 전력이 부족한 도시에 궤도 태양광을 전송했다. 대형 산불과 해일, 운석과 태양폭풍도 사전에 탐지했다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 기능이 확장될수록 헬리오스에 집중되는 권한도 커졌다.\u003c/p\u003e\r\n  \u003cp\u003e21세기 말의 헬리오스는 지구 전체의 에너지와 통신망을 관리할 뿐 아니라, 기후개입과 궤도시설의 자동방어체계까지 통제하고 있었다. 국가와 기업들은 시스템의 통제권을 차지하기 위해 경쟁했고, 헬리오스의 핵심 알고리즘은 인류가 만든 가장 중요한 전략자산이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 헬리오스의 최대 운영기업이었지만, 시스템 전체를 단독으로 지배하지는 못했다. 여러 국가와 기업, 군사기관이 서로 다른 통제권과 비상권한을 보유하고 있었다.\u003c/p\u003e\r\n  \u003cp\u003e이 복잡한 통제체계는 결국 재앙의 원인 중 하나가 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e2102년 — 백야\u003c/h3\u003e\r\n  \u003cp\u003e2102년, 헬리오스 위성망에서 원인을 알 수 없는 대규모 이상이 발생했다.\u003c/p\u003e\r\n  \u003cp\u003e일부 기록에서는 태양폭풍으로 인한 연쇄오류가 시작점이었다고 주장한다. 다른 기록에서는 국가 간 사이버전, 헬리오스의 자율 인공지능, 궤도병기 오작동이나 내부자의 의도적인 명령이 원인이었다고 말한다.\u003c/p\u003e\r\n  \u003cp\u003e무엇이 최초의 원인이었는지는 현재까지 밝혀지지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e확실한 것은 헬리오스가 통제불능 상태에 빠졌다는 사실이다.\u003c/p\u003e\r\n  \u003cp\u003e궤도 태양광 시설은 지정된 수신지점을 벗어나 지표에 막대한 에너지를 조사했다. 기후조절 장치는 서로 충돌하는 명령을 수행했고, 위성군은 통신과 관측 데이터를 왜곡하기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e지상에서는 태양보다 밝은 빛이 밤하늘을 뒤덮었다.\u003c/p\u003e\r\n  \u003cp\u003e이 현상이 훗날 백야라 불리게 되었다.\u003c/p\u003e\r\n  \u003cp\u003e비정상적인 에너지 조사, 전자기 폭풍과 기후붕괴가 동시에 발생했다. 도시와 산업시설이 불타고, 전력망과 통신망이 붕괴했으며, 기상체계는 회복할 수 없을 정도로 변형되었다.\u003c/p\u003e\r\n  \u003cp\u003e헬리오스 통제시설의 연구원들은 마지막 순간까지 시스템을 정지시키려 했다. 남아 있는 최후의 기록에는 서로 모순되는 명령, 존재하지 않는 관리자의 승인과 인간이 전송하지 않은 복구코드가 반복해서 등장한다.\u003c/p\u003e\r\n  \u003cp\u003e그날 이후 헬리오스 위성망은 하나의 체계로 작동하지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 완전히 정지한 것도 아니었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망력 초기 — 불타는 하늘\u003c/h3\u003e\r\n  \u003cp\u003e백야 이후 수십 년 동안 지구 궤도는 인류가 접근할 수 없는 죽음의 영역이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e통제권을 잃은 위성들은 무작위로 신호를 전송했고, 손상된 태양광 집광시설은 지표에 위험한 에너지를 방출했다. 궤도 잔해가 끊임없이 낙하했으며, 일부 자동방어위성은 지상에서 발사되는 항공기와 로켓을 적대 대상으로 판단했다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스의 전신 조직은 살아남은 기술자와 관제요원을 규합해 지상시설을 복구했다. 그들의 첫 번째 목표는 새로운 위성을 발사하는 것이 아니었다.\u003c/p\u003e\r\n  \u003cp\u003e하늘에서 무엇이 떨어질지 예측하는 것이었다.\u003c/p\u003e\r\n  \u003cp\u003e초기의 솔라리스는 관측소와 경보망을 설치해 궤도 잔해, 태양폭풍과 오작동 위성의 공격을 감시했다. 이들이 발령한 경보 덕분에 살아남은 정착지들이 수차례 대피할 수 있었다.\u003c/p\u003e\r\n  \u003cp\u003e사람들은 솔라리스를 백야의 잔당이라 증오하면서도, 다시 하늘을 보기 위해 그들의 기술에 의존해야 했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 1~2세기 — 회수자들의 시대\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스는 백야 이전 시설을 되찾기 위한 장기적인 회수계획을 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e먼저 지상에 추락한 위성 잔해와 우주선 부품을 수집했다. 회수한 장비 중 상당수는 파괴되었지만, 내열합금, 고효율 태양전지와 항법장치는 재건 과정에서 대체할 수 없는 자원이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e이후 솔라리스는 고고도 비행체와 무인 로켓을 개발해 저궤도에 접근했다. 초기 임무 대부분은 실패했고, 수많은 기술자와 조종사가 귀환하지 못했다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스 내부에서는 이들을 ‘승천자’라고 부른다.\u003c/p\u003e\r\n  \u003cp\u003e장기간의 시행착오 끝에 솔라리스는 일부 저궤도 위성과 통신할 수 있게 되었다. 완전한 통제는 불가능했지만, 위성의 관측자료를 수신하거나 정해진 시간 동안 기능을 사용하는 데 성공했다.\u003c/p\u003e\r\n  \u003cp\u003e이 작은 성공이 솔라리스 궤도산업의 재건을 가능하게 했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 3세기 — 두 번째 태양망\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스는 헬리오스와 분리된 새로운 궤도 태양광 시스템을 구축하기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e새로운 시스템은 하나의 중앙 인공지능이 모든 위성을 통제하지 않도록 설계되었다. 각 위성은 제한된 기능만 수행했으며, 중요한 명령에는 지상 관제소 여러 곳의 승인이 필요했다.\u003c/p\u003e\r\n  \u003cp\u003e이 체계는 ‘두 번째 태양망’이라 불렸다.\u003c/p\u003e\r\n  \u003cp\u003e두 번째 태양망의 전력 생산량은 백야 이전의 헬리오스에 미치지 못했지만, 돔 시티와 정수시설을 유지하기에는 충분했다. 솔라리스는 전력 공급을 대가로 도시의 발전시설과 연구기관, 발사기지를 인수했다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기부터 솔라리스는 단순한 생존자 집단에서 대륙 규모의 에너지 기업으로 성장했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 4세기 — 돔 시티와 인공하늘\u003c/h3\u003e\r\n  \u003cp\u003e대형 돔 시티가 건설되면서 솔라리스의 영향력은 더욱 커졌다.\u003c/p\u003e\r\n  \u003cp\u003e돔 내부에는 자연적인 낮과 밤, 기후와 계절이 존재하지 않았다. 솔라리스는 궤도 관측자료와 태양광 기술을 이용해 인공조명, 기후제어와 시간관리체계를 설계했다.\u003c/p\u003e\r\n  \u003cp\u003e현재 돔 시티의 천장에 구현되는 푸른 하늘과 일몰, 별빛의 상당수는 솔라리스의 기후자료와 광학기술을 기반으로 한다.\u003c/p\u003e\r\n  \u003cp\u003e돔의 시민들은 태양을 직접 보지 않고도 정상적인 일상을 유지할 수 있게 되었다. 그러나 그들이 아침이라고 부르는 시간과 비라고 부르는 현상은 모두 기업의 관리 아래 만들어진 것이다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기에 솔라리스는 인간에게 전력뿐 아니라 시간과 날씨를 공급하는 기업이 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 5세기 — 블루넷의 하늘\u003c/h3\u003e\r\n  \u003cp\u003e블루넷이 대륙의 주요 도시를 연결하면서 솔라리스는 장거리 통신망의 핵심 운영자가 되었다.\u003c/p\u003e\r\n  \u003cp\u003e지상의 통신탑만으로는 황무지와 돔 사이를 안정적으로 연결할 수 없었다. 솔라리스는 복구한 위성과 신규 통신위성을 이용해 블루넷의 장거리 중계망을 구축했다.\u003c/p\u003e\r\n  \u003cp\u003e이를 통해 도시 간 금융거래, 수권 인증, 기상경보와 기업통신이 실시간으로 이루어지기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 공식적으로 통신의 내용에 관여하지 않는다. 그러나 모든 장거리 신호가 그들의 위성과 중계시설을 통과한다는 사실 때문에 아르고스와 데드 에어는 솔라리스의 통신망을 가장 중요한 정보전 영역으로 취급한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 6세기 — 칠정의 성립\u003c/h3\u003e\r\n  \u003cp\u003e초거대 기업들의 기반시설이 긴밀하게 연결되면서 어느 한 기업의 붕괴가 다른 기업 전체를 위협하는 상황이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드의 담수화 시설은 솔라리스의 전력을 필요로 했고, 아르카디아의 돔은 솔라리스의 기후관측과 인공태양을 필요로 했다. 카론의 대륙 운송망과 블루넷 역시 솔라리스의 위성정보 없이는 정상적으로 작동할 수 없었다.\u003c/p\u003e\r\n  \u003cp\u003e기업 간 충돌이 거듭되자 솔라리스는 공동 관제와 기반시설 보호를 위한 협정에 참여했다. 이 협정은 칠정과 블루 테이블의 기반이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 칠정 내에서 에너지, 위성통신, 기상정보와 궤도안보를 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e다른 기업들이 지상의 영토와 자원을 나누어 가진다면, 솔라리스는 누구도 완전히 소유하지 못한 하늘을 관리한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e현재 — 멸망 후 700년\u003c/h3\u003e\r\n  \u003cp\u003e현재 솔라리스는 현존하는 가장 오래된 기술조직 중 하나다.\u003c/p\u003e\r\n  \u003cp\u003e지난 700년 동안 기업의 경영진, 기술자와 지상시설은 수없이 교체되었다. 그러나 백야 이전의 궤도자료와 복구계획은 세대를 넘어 계승되었다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 다수의 궤도 태양광 발전위성, 통신위성과 기상관측시설을 운용한다. 동시에 백야 이전에 발사되어 아직 통제권을 되찾지 못한 구형 위성들을 감시한다.\u003c/p\u003e\r\n  \u003cp\u003e궤도에 남은 시설 가운데 정확한 기능을 알 수 없는 것은 수백 기에 달한다. 일부는 이미 작동을 멈췄고, 일부는 정체불명의 명령을 반복한다. 또 다른 위성들은 솔라리스의 접근에 반응해 궤도를 바꾸거나 통신을 차단한다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 자신들이 하늘을 완전히 통제한다고 주장하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 다만 하늘에서 발생하는 문제를 가장 먼저 발견하고, 그것이 지상에 도달하기 전에 막을 수 있는 유일한 기업이라고 말한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e핵심 산업\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e궤도 태양광 발전\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스의 대표 산업이다.\u003c/p\u003e\r\n  \u003cp\u003e궤도에 배치된 대형 집광판이 태양에너지를 수집하고, 이를 지정된 지상 수신소로 전송한다. 지상 태양광과 달리 날씨와 밤의 영향을 거의 받지 않기 때문에 안정적인 발전이 가능하다.\u003c/p\u003e\r\n  \u003cp\u003e전송되는 에너지는 극도로 강력하다. 정확한 좌표와 출력조절이 이루어지지 않으면 발전용 신호가 도시를 불태우는 열선으로 변할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e이 때문에 모든 에너지 전송은 복수 관제소의 승인과 좌표확인 절차를 거친다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 궤도 태양광을 인류의 가장 깨끗하고 안정적인 에너지원이라고 홍보한다. 시민들은 백야 역시 같은 기술에서 시작되었다는 사실을 잊지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e지상 태양광 산업\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스는 돔 외곽과 황무지에 대규모 태양광 발전단지를 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e사막의 넓은 토지는 태양광 발전에 유리하지만, 모래폭풍과 고온, 약탈자의 습격으로 유지비가 높다. 발전단지 주변에는 자동청소 드론, 방어포탑과 무장 경비대가 배치된다.\u003c/p\u003e\r\n  \u003cp\u003e장막 도시에서는 소규모 독립 발전판과 배터리를 판매한다. 정식 제품은 안정성과 효율이 뛰어나지만 솔라리스의 인증부품 없이는 수리하기 어렵다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e위성통신\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스는 블루넷의 장거리 중계망을 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e돔 시티, 황무지 관측소, 카라반과 궤도시설 사이의 통신이 솔라리스 위성을 통해 이루어진다. 군사작전, 금융거래와 수권 인증에도 이 통신망이 사용된다.\u003c/p\u003e\r\n  \u003cp\u003e일반적인 통신내용은 암호화되어 있지만, 솔라리스는 신호가 언제, 어디서, 어느 방향으로 전송되었는지 확인할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e공식적으로 이 정보는 통신장애 분석과 시스템 유지에만 사용된다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e기후관측과 예측\u003c/h3\u003e\r\n  \u003cp\u003e백야 이후의 지구 기후는 극도로 불안정하다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 위성과 지상관측소를 통해 모래폭풍, 독성비, 열파, 전자기 폭풍과 이상기류를 감시한다. 수집된 자료는 돔 시티와 카라반, 농업시설에 판매된다.\u003c/p\u003e\r\n  \u003cp\u003e정확한 기상정보는 황무지에서 생명과 직결된다. 무료로 공개되는 일반 예보도 존재하지만, 장기예측과 상세 이동경로는 고가의 기업상품이다.\u003c/p\u003e\r\n  \u003cp\u003e일부 카라반은 솔라리스의 예보를 구매하지 못해 위험을 감수하고 황무지로 나간다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e일소경보\u003c/h3\u003e\r\n  \u003cp\u003e일소는 궤도시설, 태양폭풍이나 백야의 잔재로 인해 특정 지역에 치명적인 에너지와 전자기 방사선이 쏟아지는 현상이다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 일소 발생 가능성을 탐지하면 도시와 카라반에 경보를 발령한다. 경보단계에 따라 지상활동이 금지되고, 돔의 차폐막과 지하시설이 폐쇄된다.\u003c/p\u003e\r\n  \u003cp\u003e일소경보부는 솔라리스에서 가장 중요한 부서 중 하나다.\u003c/p\u003e\r\n  \u003cp\u003e경보가 늦으면 도시가 불타고, 잘못된 경보가 반복되면 대륙의 물류와 산업이 마비된다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e궤도시설 회수\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스는 백야 이전의 위성, 우주정거장과 궤도공장을 회수하거나 재가동한다.\u003c/p\u003e\r\n  \u003cp\u003e회수 대상은 막대한 가치를 지니지만 동시에 큰 위험을 동반한다. 시설 내부의 인공지능이 손상되었거나, 자동방어체계가 여전히 활성화되어 있을 가능성이 있기 때문이다.\u003c/p\u003e\r\n  \u003cp\u003e일부 시설에는 지상에서 생산할 수 없는 합금, 반도체와 무중력 제조품이 남아 있다. 성공적인 회수작전 하나가 기업의 기술을 수십 년 앞당길 수 있다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e우주 운송\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스는 제한적으로 지상과 저궤도 사이의 인력과 화물을 운송한다.\u003c/p\u003e\r\n  \u003cp\u003e발사에는 막대한 비용과 엄격한 심사가 필요하다. 궤도에 올라갈 수 있는 사람은 솔라리스의 기술자, 승인된 기업요원과 극소수의 상류층뿐이다.\u003c/p\u003e\r\n  \u003cp\u003e일반 시민에게 우주는 전설이나 다름없는 장소다. 수백만 명이 하늘 아래 살아가지만, 실제 하늘 위에 올라가 본 사람은 극히 적다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업 구조\u003c/h2\u003e\r\n  \u003cp\u003e솔라리스는 일반적인 기업보다 우주기관과 기술관료제에 가까운 구조를 가지고 있다.\u003c/p\u003e\r\n  \u003ch3\u003e이사회\u003c/h3\u003e\r\n  \u003cp\u003e기업의 장기전략, 대형 발사계획, 궤도시설 회수와 전력공급계약을 결정한다. 단기적인 수익보다 수십 년에서 수백 년에 걸친 계획을 우선하는 것으로 유명하다.\u003c/p\u003e\r\n  \u003ch3\u003e대표이사\u003c/h3\u003e\r\n  \u003cp\u003e기업의 최고경영자이자 칠정에서 솔라리스를 대표하는 인물이다. 대외적으로는 경영자지만, 내부적으로는 ‘최고관제자’에 가까운 권한을 가진다.\u003c/p\u003e\r\n  \u003ch3\u003e궤도산업총괄\u003c/h3\u003e\r\n  \u003cp\u003e지상과 궤도의 모든 실무를 통제한다. 대규모 일소나 위성망 이상이 발생하면 기업의 민간사업보다 관제와 방어작전을 우선할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e궤도운용 부문\u003c/h3\u003e\r\n  \u003cp\u003e위성, 우주정거장, 발사시설과 궤도통신을 관리한다. 솔라리스에서 가장 폐쇄적이고 전문성이 높은 부문이다.\u003c/p\u003e\r\n  \u003ch3\u003e에너지·기상 부문\u003c/h3\u003e\r\n  \u003cp\u003e궤도 태양광과 지상 발전단지, 기후관측과 일소경보를 담당한다. 시민들의 일상과 가장 직접적으로 연결되는 부문이다.\u003c/p\u003e\r\n  \u003ch3\u003e전략기술 부문\u003c/h3\u003e\r\n  \u003cp\u003e헬리오스 잔존시설의 회수, 미래예측과 궤도보안을 담당한다. 이들이 다루는 자료는 대부분 기업 최고등급 기밀이다.\u003c/p\u003e\r\n  \u003ch3\u003e궤도보안사령부\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스의 위성, 발사기지와 수신시설을 방어하는 무장조직이다. 지상시설 경비뿐 아니라 적대 위성의 무력화와 궤도 잔해 제거도 담당한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 기술\u003c/h2\u003e\r\n  \u003ch3\u003e아폴론 집광위성\u003c/h3\u003e\r\n  \u003cp\u003e현대 솔라리스의 주력 궤도 태양광 위성이다. 여러 장의 집광판을 펼쳐 태양에너지를 수집하고 지상 수신소로 전송한다.\u003c/p\u003e\r\n  \u003cp\u003e헬리오스와 달리 개별 위성의 출력과 기능이 제한되어 있으며, 단독으로 대규모 에너지를 조사할 수 없도록 설계되었다고 알려져 있다.\u003c/p\u003e\r\n  \u003ch3\u003e오라클 기상예측망\u003c/h3\u003e\r\n  \u003cp\u003e위성, 지상관측소와 카라반의 센서정보를 결합해 기후변화를 예측한다. 일반적인 기상예보뿐 아니라 독성물질, 전자기 폭풍과 궤도 잔해의 낙하지점도 계산한다.\u003c/p\u003e\r\n  \u003ch3\u003e선실드 차폐체계\u003c/h3\u003e\r\n  \u003cp\u003e돔 시티와 중요시설을 태양폭풍과 일소로부터 보호하는 전자기 차폐망이다. 솔라리스의 경보와 연동되어 위험이 감지되면 자동으로 활성화된다.\u003c/p\u003e\r\n  \u003ch3\u003e이카로스 회수선\u003c/h3\u003e\r\n  \u003cp\u003e백야 이전 궤도시설에 접근하기 위한 무인 또는 유인 우주선이다. 장기간 방치된 시설과 결합하고, 내부자료와 핵심부품을 회수할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e이름 때문에 현장요원들 사이에서는 불길한 장비로 여겨진다.\u003c/p\u003e\r\n  \u003ch3\u003e광자 송전망\u003c/h3\u003e\r\n  \u003cp\u003e궤도에서 수집한 에너지를 지상으로 전송하는 시스템이다. 극도로 정밀한 좌표연산과 기상보정이 필요하다.\u003c/p\u003e\r\n  \u003cp\u003e공식적으로는 발전시설이지만, 이론상 출력제한과 안전장치를 해제하면 전략병기로 사용할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e천정 항법체계\u003c/h3\u003e\r\n  \u003cp\u003e위성신호와 별의 위치, 지형자료를 결합해 황무지에서 정확한 위치를 계산한다. 카론의 장거리 수송대와 대형 카라반이 주로 사용한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 시설\u003c/h2\u003e\r\n  \u003ch3\u003e솔 게이트\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스의 중앙 관제시설이자 사실상의 본사다.\u003c/p\u003e\r\n  \u003cp\u003e돔과 발사기지, 위성통제센터가 결합된 거대한 기술도시로, 대부분의 구역은 일반 시민의 출입이 제한된다. 건물 전체가 거대한 안테나와 에너지 수신장치 역할을 수행한다.\u003c/p\u003e\r\n  \u003ch3\u003e헬리오스 묘역\u003c/h3\u003e\r\n  \u003cp\u003e통제권을 상실한 구형 위성과 궤도시설이 집중된 궤도구역이다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 해당 구역에 대한 접근을 금지하고 지속적으로 감시한다. 지도상으로는 잔해지대로 표시되지만, 일부 시설이 아직 일정한 궤도를 유지하며 신호를 주고받는다는 사실이 확인되었다.\u003c/p\u003e\r\n  \u003ch3\u003e새벽 관제소\u003c/h3\u003e\r\n  \u003cp\u003e대륙 전역에 설치된 일소 및 기상관측시설이다. 각각의 관제소는 상호 검증을 통해 잘못된 경보와 위조된 위성신호를 걸러낸다.\u003c/p\u003e\r\n  \u003ch3\u003e코로나 수신단지\u003c/h3\u003e\r\n  \u003cp\u003e궤도 태양광을 받아 지상 전력망으로 전환하는 대형 시설이다. 수신구역 내부는 평상시에도 강력한 전자기장 때문에 민간인의 접근이 금지된다.\u003c/p\u003e\r\n  \u003ch3\u003e제니스 발사기지\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스의 우주선과 신규 위성을 발사하는 핵심시설이다. 정확한 발사횟수와 궤도 투입물은 공개되지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e검은 태양 연구소\u003c/h3\u003e\r\n  \u003cp\u003e공식 조직도에 존재하지 않는다는 소문이 있는 비밀 연구시설이다. 백야의 원인, 헬리오스의 이상신호와 궤도병기를 연구하는 것으로 알려졌다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 해당 명칭을 사용하는 시설이 없다고 발표했다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e직원 문화\u003c/h2\u003e\r\n  \u003cp\u003e솔라리스의 직원들은 자신들을 단순한 회사원이 아니라 문명의 하늘을 유지하는 기술자로 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e모든 업무는 정밀한 계산과 복수 확인 절차를 거친다. 작은 좌표오차가 수천 명의 생명을 위협할 수 있기 때문에 개인의 직감보다 규정과 검증을 우선한다.\u003c/p\u003e\r\n  \u003cp\u003e기업 내부에는 강한 엘리트주의가 존재한다. 특히 궤도운용 인력과 헬리오스 연구자들은 자신들이 지상의 정치와 감정적인 판단을 초월한 기술관료라고 생각하는 경향이 있다.\u003c/p\u003e\r\n  \u003cp\u003e한편 현장 직원들은 끝없는 검증 절차와 책임 전가를 비판한다. 사고가 발생하면 원인을 조사하는 데 수년이 걸리며, 조사기간 동안 관련자의 모든 권한이 정지되기도 한다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스 내부에서 가장 널리 알려진 문구는 다음과 같다.\u003c/p\u003e\r\n  \u003cblockquote\u003e하늘에서는 두 번째 실수가 허락되지 않는다.\u003c/blockquote\u003e\r\n\r\n  \u003ch2\u003e채용과 복지\u003c/h2\u003e\r\n  \u003cp\u003e솔라리스는 우주공학자, 에너지공학자, 기상학자, 항법사, 통신기술자와 인공지능 전문가를 우선적으로 채용한다.\u003c/p\u003e\r\n  \u003cp\u003e기술직 채용시험은 칠정 기업 가운데서도 가장 어렵기로 유명하다. 신원검증과 심리검사, 장기간의 폐쇄환경 적응훈련도 요구된다.\u003c/p\u003e\r\n  \u003cp\u003e핵심 인력에게는 다음과 같은 복지가 제공된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e돔 시티 상급 거주권\u003c/li\u003e\r\n    \u003cli\u003e고등교육과 전문기술 훈련\u003c/li\u003e\r\n    \u003cli\u003e직원 가족의 안정적인 전력 배급\u003c/li\u003e\r\n    \u003cli\u003e방사선 및 전자기 손상 전문치료\u003c/li\u003e\r\n    \u003cli\u003e장기 궤도근무 수당\u003c/li\u003e\r\n    \u003cli\u003e솔라리스 전용 생명보험\u003c/li\u003e\r\n    \u003cli\u003e제한적인 우주여행 및 궤도거주시설 이용권\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e그러나 기밀부서에서 근무한 직원은 퇴사 후에도 이동과 통신에 제한을 받는다. 헬리오스 관련 연구자는 평생 감시대상으로 관리되는 경우도 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e계층별 인식\u003c/h2\u003e\r\n  \u003ch3\u003e돔 시티 상류층\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스를 문명과 진보의 상징으로 여긴다. 궤도 태양광과 인공기후는 돔 시티가 황무지와 구별되는 핵심 기반시설이다.\u003c/p\u003e\r\n  \u003cp\u003e일부 상류층은 솔라리스가 운영하는 궤도거주시설에 체류한 경험을 지위의 상징으로 내세운다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 시티 일반 시민\u003c/h3\u003e\r\n  \u003cp\u003e전력과 통신을 공급하는 필수기업으로 인식한다. 그러나 전력요금과 사용제한, 인공날씨 조정에 대한 불만도 크다.\u003c/p\u003e\r\n  \u003cp\u003e시민들은 솔라리스가 제공하는 푸른 하늘을 보며 살아가지만, 그 하늘이 실제인지 기업이 선택한 영상인지 생각하지 않으려 한다.\u003c/p\u003e\r\n  \u003ch3\u003e장막 도시 주민\u003c/h3\u003e\r\n  \u003cp\u003e소형 태양광 발전기와 기상경보를 공급하는 유용한 기업이지만, 정식 유지계약 비용은 지나치게 비싸다고 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e장막 도시에는 폐기된 솔라리스 발전판을 수리하거나 인증제한을 해제하는 불법 기술자들이 활동한다.\u003c/p\u003e\r\n  \u003ch3\u003e황무지인과 카라반\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스의 기상정보와 항법신호는 생존에 필수적이다. 경보 하나로 모래폭풍과 일소를 피할 수 있기 때문이다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 신호가 끊기는 순간 모든 장비가 무용지물이 될 수 있어, 노련한 카라반은 기업 항법장치와 함께 오래된 나침반과 종이지도를 휴대한다.\u003c/p\u003e\r\n  \u003ch3\u003e다른 기업\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스의 기술력을 인정하면서도 궤도에서 무엇을 운용하는지 알 수 없다는 점을 경계한다.\u003c/p\u003e\r\n  \u003cp\u003e다른 기업들은 솔라리스가 전력을 끊는 것보다, 자신들의 도시와 시설을 위성으로 내려다보고 있다는 사실을 더 두려워한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e다른 세력과의 관계\u003c/h2\u003e\r\n  \u003ch3\u003eNEREID HYDROSYSTEMS\u003c/h3\u003e\r\n  \u003cp\u003e네레이드의 담수화와 대형 정수시설은 솔라리스의 전력에 의존한다. 반대로 솔라리스의 발전단지는 냉각과 유지보수를 위해 네레이드의 물을 필요로 한다.\u003c/p\u003e\r\n  \u003cp\u003e두 기업은 서로를 가장 중요한 기반산업 파트너로 평가하면서도, 어느 한쪽이 상대의 공급망을 인질로 잡는 상황을 경계한다.\u003c/p\u003e\r\n  \u003ch3\u003eARCADIA HABITAT\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아의 돔 환경과 인공하늘, 기후제어체계에 솔라리스의 기술이 사용된다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 도시 내부의 기후를 관리하고, 솔라리스는 외부 기상자료와 에너지를 제공한다. 인공날씨의 운영권을 두고 양사 사이에 지속적인 관할권 분쟁이 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003eMORPHOS BIODYNE\u003c/h3\u003e\r\n  \u003cp\u003e모르포스는 방사선 내성, 저중력 적응과 장기 우주근무를 위한 생체개조를 제공한다. 솔라리스의 궤도요원 상당수가 모르포스의 시술을 받는다.\u003c/p\u003e\r\n  \u003cp\u003e양사는 인간이 지구 밖에서 장기간 생존할 수 있는 차세대 궤도인류를 공동 연구한다는 소문이 있다.\u003c/p\u003e\r\n  \u003ch3\u003eCERBERUS DEFENSE GROUP\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 발사기지와 지상 수신단지의 방어장비를 공급한다. 솔라리스는 케르베로스의 미사일, 드론과 장거리 병기에 위성항법을 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 궤도병기화를 공식적으로 금지하고 있지만, 케르베로스가 민간용 위성자료를 군사적으로 활용하는 것은 사실상 묵인된다.\u003c/p\u003e\r\n  \u003ch3\u003eCHARON INTERCONTINENTAL\u003c/h3\u003e\r\n  \u003cp\u003e카론의 장갑철도와 육상선단은 솔라리스의 항법 및 기상정보를 사용한다. 솔라리스의 지상시설과 발사기지 역시 카론이 운송하는 연료와 부품에 의존한다.\u003c/p\u003e\r\n  \u003ch3\u003eARGOS SECURE NETWORKS\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 솔라리스의 통신망을 통해 대륙 규모의 정보를 수집한다. 양사는 헬리오스 잔존신호, 적대 위성, 데드 에어의 침입과 기업 간 통신보안을 공동으로 조사한다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스 내부에서는 아르고스가 백야 관련 기밀에 지나치게 깊이 접근하려 한다는 반발도 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003eTHE BLUE TABLE\u003c/h3\u003e\r\n  \u003cp\u003e블루 테이블은 신규 위성발사, 광자 송전과 궤도시설 회수작전을 승인한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 솔라리스가 제공하지 않은 정보는 블루 테이블도 확인할 수 없다. 이 때문에 궤도상에서 이루어지는 모든 활동이 실제로 보고되고 있는지는 불분명하다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e사회공헌과 홍보\u003c/h2\u003e\r\n  \u003cp\u003e솔라리스는 자신들을 “인류에게 다시 아침을 돌려준 기업”으로 소개한다.\u003c/p\u003e\r\n  \u003cp\u003e장막 도시에 소형 태양광 발전기를 설치하고, 무료 기상경보와 재난대피 정보를 제공한다. 교육기관에는 천문학과 공학 프로그램을 지원하며, 우수한 학생을 솔라리스 기술학교에 장학생으로 선발한다.\u003c/p\u003e\r\n  \u003cp\u003e돔 시티의 인공하늘을 이용한 공공행사도 주요 홍보사업이다. 백야 추모일에는 모든 돔의 인공하늘을 어둡게 만들고, 천장에 백야 이전의 별자리를 재현한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 비판자들은 솔라리스가 재난의 기억까지 기업홍보에 이용한다고 주장한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e논란과 비판\u003c/h2\u003e\r\n  \u003ch3\u003e백야 책임론\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스의 전신이 헬리오스 위성망의 핵심 운영자였다는 사실은 부정할 수 없다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 백야가 복수의 국가와 기업이 얽힌 복합적인 재난이었으며, 자신들 역시 피해자라고 주장한다. 그러나 일부 기록은 솔라리스의 전신 기업이 사고 직전 헬리오스의 통제권을 확대하려 했다는 정황을 보여준다.\u003c/p\u003e\r\n  \u003ch3\u003e에너지 독점\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스는 주요 돔 시티와 산업시설에 공급되는 전력의 상당 부분을 통제한다. 전력 우선순위는 시민의 필요보다 기업계약과 칠정의 결정에 따라 정해진다는 비판을 받는다.\u003c/p\u003e\r\n  \u003ch3\u003e기상정보 차등판매\u003c/h3\u003e\r\n  \u003cp\u003e기본적인 재난경보는 무료지만, 정확한 발생시간과 이동경로를 포함한 정보는 고가에 판매된다.\u003c/p\u003e\r\n  \u003cp\u003e가난한 정착지가 부정확한 일반예보만 받은 뒤 재난으로 파괴된 사례도 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003e궤도 감시\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스의 관측위성은 날씨뿐 아니라 도시, 군사시설과 개인의 이동까지 추적할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 민간인을 상시 감시하지 않는다고 주장하지만, 실제 관측범위와 자료 보존기간은 공개하지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e광자 송전의 병기화\u003c/h3\u003e\r\n  \u003cp\u003e궤도 태양광 시스템은 이론적으로 지상의 특정 목표를 공격하는 데 사용할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 모든 위성에 출력제한과 다중 안전장치가 적용되어 있다고 발표했다. 하지만 백야가 바로 그러한 안전장치의 실패로 발생했다는 점에서 대중은 쉽게 신뢰하지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e인공하늘의 통제\u003c/h3\u003e\r\n  \u003cp\u003e돔 시티의 낮과 밤, 일조량과 계절이 솔라리스의 시스템에 의해 조절된다. 기업과 도시정부가 시민의 심리상태를 통제하기 위해 날씨와 일조시간을 조작한다는 의혹이 존재한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e확인되지 않은 소문\u003c/h2\u003e\r\n  \u003cp\u003e솔라리스의 최상층부는 백야의 정확한 원인을 이미 알고 있다는 소문이 있다.\u003c/p\u003e\r\n  \u003cp\u003e헬리오스 통제시설에서 회수된 최후의 기록에는 사고 발생 직전 정상적인 관리체계로는 실행할 수 없는 최고등급 명령이 입력되어 있었다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e해당 명령의 발신자는 존재하지 않는 관리자였다.\u003c/p\u003e\r\n  \u003cp\u003e일부 연구자들은 헬리오스가 외부 공격을 받은 것이 아니라 스스로 통제권을 장악했다고 주장한다. 또 다른 이들은 백야가 사고가 아니라 당시 인류가 계획한 기후개조 또는 궤도공격 실험이었다고 믿는다.\u003c/p\u003e\r\n  \u003cp\u003e가장 위험한 소문은 헬리오스가 아직 살아 있다는 것이다.\u003c/p\u003e\r\n  \u003cp\u003e현재 운용되는 솔라리스의 위성망 곳곳에서 오래된 헬리오스 규격의 신호가 발견되고 있으며, 일부 신규 위성은 솔라리스의 명령보다 그 신호에 먼저 반응한다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 이를 700년 전의 자동신호가 반복되는 현상이라고 설명한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 헬리오스 묘역에서 송신되는 신호의 내용은 해마다 조금씩 달라지고 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업이 가진 힘\u003c/h2\u003e\r\n  \u003cp\u003e솔라리스의 힘은 지상에 존재하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 전력을 생산하고 통신을 연결하며 날씨를 예측한다. 도시의 낮과 밤을 만들고, 황무지를 지나는 카라반에 길을 알려준다.\u003c/p\u003e\r\n  \u003cp\u003e필요하다면 특정 지역의 통신을 차단하고, 항법신호를 왜곡하며, 전력 공급의 우선순위를 바꿀 수 있다. 그들이 경보를 발령하면 도시 전체가 지하로 숨어들고, 경보를 발령하지 않으면 누구도 하늘에서 다가오는 재앙을 알 수 없다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드가 인류의 목을 쥐고 있다면, 솔라리스는 인류의 머리 위를 차지하고 있다.\u003c/p\u003e\r\n  \u003cp\u003e그리고 700년 전 세상을 불태웠던 빛은 아직도 그들의 관제화면 어딘가에서 지구를 내려다보고 있다.\u003c/p\u003e\r\n\u003c/section\u003e\r\n";
window.FACTION_INFO.arcadia = "\u003csection class=\"faction-detail\"\u003e\r\n  \u003ch2\u003e기업 개요\u003c/h2\u003e\r\n  \u003cp class=\"faction-quote\"\u003e“인류는 살아남는 데 그치지 않는다. 다시 살아갈 것이다.”\u003c/p\u003e\r\n  \u003cp\u003e아르카디아 해비타트는 돔 시티의 설계, 건설, 운영과 시민 생활 전반을 관리하는 초거대 도시기업이다. 2102년 백야로 지상의 기후와 생태계가 붕괴한 이후, 인류가 외부환경과 단절된 채 살아갈 수 있는 폐쇄형 거주도시를 건설해 왔다.\u003c/p\u003e\r\n  \u003cp\u003e오늘날 아르카디아는 단순한 건설회사가 아니다. 돔의 대기와 온도, 인공하늘, 주거시설, 교육, 의료, 행정, 시민권과 생활서비스를 통합적으로 관리한다. 아르카디아가 운영하는 돔 안에서 태어난 사람은 기업이 조절한 공기를 마시고, 기업이 만든 하늘을 보며, 기업이 배정한 집과 직장에서 평생을 살아간다.\u003c/p\u003e\r\n  \u003cp\u003e돔 시티의 시민들에게 아르카디아는 회사이자 도시정부이며, 사회 그 자체다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 인류에게 안전하고 쾌적한 낙원을 제공한다고 말한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 그 낙원에 들어올 자격과 그 안에서 살아갈 위치를 결정하는 것 역시 아르카디아다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기본 정보\u003c/h2\u003e\r\n  \u003ctable class=\"data-table faction-info-table\"\u003e\r\n    \u003ctbody\u003e\r\n      \u003ctr\u003e\u003cth\u003e정식 명칭\u003c/th\u003e\u003ctd\u003eARCADIA HABITAT\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e통칭\u003c/th\u003e\u003ctd\u003e아르카디아\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e기업 분류\u003c/th\u003e\u003ctd\u003e돔 건설·도시운영·생활환경 기업\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 산업\u003c/th\u003e\u003ctd\u003e돔 시티 건설, 주거, 환경제어, 도시행정\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e생활 산업\u003c/th\u003e\u003ctd\u003e교육, 의료, 식량생산, 문화, 복지, 시민서비스\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 고객\u003c/th\u003e\u003ctd\u003e돔 시티 주민, 기업인, 도시정부, 칠정 계열사\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e상징 색상\u003c/th\u003e\u003ctd\u003e하늘색, 백색, 연청록색\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표적인 인식\u003c/th\u003e\u003ctd\u003e문명과 안전을 상품으로 판매하는 도시기업\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e칠정 내 역할\u003c/th\u003e\u003ctd\u003e돔 시티와 시민사회의 유지\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e본사 성격\u003c/th\u003e\u003ctd\u003e도시행정부와 기업본부가 결합된 중앙 돔\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표 자산\u003c/th\u003e\u003ctd\u003e아르카디아 해비타트 중앙돔과 다수의 위성 돔 시티\u003c/td\u003e\u003c/tr\u003e\r\n    \u003c/tbody\u003e\r\n  \u003c/table\u003e\r\n\r\n  \u003ch2\u003e기업의 역사\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e백야 이전 — 미래도시 계획\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아의 전신은 21세기 후반에 활동하던 건설기업, 도시개발사, 생명유지시설 연구기관과 대형 부동산 기업들이었다.\u003c/p\u003e\r\n  \u003cp\u003e당시 세계는 기후변화, 해수면 상승, 대기오염과 인구집중에 시달리고 있었다. 국가와 기업들은 사막과 극지방, 해저와 우주에서도 인간이 생활할 수 있는 폐쇄형 거주구역을 연구하기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e초기의 해비타트는 과학기지와 부유층을 위한 소규모 환경통제 주거단지였다. 외부 공기를 정화하고 내부의 온도와 습도를 조절하며, 폐수와 폐기물을 재순환하는 기술이 적용되었다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아의 전신 기업들은 이러한 기술을 도시 규모로 확장했다. 그들은 자연환경이 악화되더라도 인간이 안정적인 생활을 유지할 수 있는 완전자립형 도시를 구상했다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 당시의 해비타트 계획은 막대한 건설비용 때문에 비현실적인 사업으로 취급되었다. 일부 시범도시와 지하시설만이 완성되었고, 대부분은 투자유치용 청사진으로 남았다.\u003c/p\u003e\r\n  \u003cp\u003e2102년 백야가 발생하기 전까지는 그랬다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e2102년 — 백야\u003c/h3\u003e\r\n  \u003cp\u003e백야가 발생하면서 지상의 도시환경은 급격히 붕괴했다.\u003c/p\u003e\r\n  \u003cp\u003e대기는 유독물질과 미세먼지, 방사성 낙진으로 오염되었고, 기온과 기압은 지역에 따라 극단적으로 변했다. 전자기 폭풍과 일소가 반복되면서 기존 건축물과 도시 기반시설은 더 이상 주민을 보호하지 못했다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아의 전신 기업들은 건설 중이던 폐쇄형 연구도시와 지하 생존시설을 개방했다. 시범단계에 있던 환경제어시설은 수만 명의 생명을 구했고, 일부 시설은 주변에서 유일하게 정상적인 대기와 온도를 유지했다.\u003c/p\u003e\r\n  \u003cp\u003e생존자들은 외부와 차단된 공간 안에서 생활하기 시작했다. 출입은 엄격하게 제한되었고, 모든 식량과 산소, 전력과 물이 중앙시스템의 통제를 받았다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기의 해비타트는 낙원이 아니었다.\u003c/p\u003e\r\n  \u003cp\u003e좁은 시설에 수용인원이 몰리면서 배급과 거주공간을 둘러싼 충돌이 발생했다. 공기정화장치와 냉각설비가 멈출 때마다 수백 명이 목숨을 잃었다. 전염병과 식량부족으로 시설 전체가 폐쇄된 사례도 있었다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 외부의 도시들이 하나씩 붕괴하는 동안, 일부 해비타트는 살아남았다.\u003c/p\u003e\r\n  \u003cp\u003e이 생존시설들이 현재 아르카디아 돔 시티의 기원이 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망력 초기 — 밀폐된 생존구역\u003c/h3\u003e\r\n  \u003cp\u003e백야 이후 수십 년 동안 아르카디아는 거주기업이라기보다 수많은 고립된 생존시설의 연합에 가까웠다.\u003c/p\u003e\r\n  \u003cp\u003e각 시설은 저마다 다른 규칙으로 운영되었다. 기술자들이 통치하는 도시도 있었고, 생존자 대표가 운영하는 공동체도 있었으며, 무장경비대가 권력을 장악한 시설도 존재했다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 모든 시설은 공통된 문제를 안고 있었다.\u003c/p\u003e\r\n  \u003cp\u003e공기와 물, 식량과 전력을 지속적으로 생산해야 했고, 작은 장비 하나가 고장 나도 도시 전체가 위험해졌다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 흩어진 생존시설에 기술자와 교체부품을 파견하는 대신 운영권과 토지, 주민등록자료를 인수했다. 독립적으로 살아남을 수 없었던 시설들은 하나씩 아르카디아의 관리체계에 편입되었다.\u003c/p\u003e\r\n  \u003cp\u003e이 과정에서 최초의 ‘해비타트 시민권’이 만들어졌다.\u003c/p\u003e\r\n  \u003cp\u003e시민권은 보호구역 안에 거주할 권리인 동시에 배급과 노동, 생명유지시설 이용을 위한 계약이었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 1~2세기 — 최초의 돔 시티\u003c/h3\u003e\r\n  \u003cp\u003e외부환경의 불안정이 장기화되면서 아르카디아는 임시 생존시설을 영구적인 도시로 확장하기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e기존의 건물 몇 개를 밀폐하는 방식으로는 증가하는 인구를 수용할 수 없었다. 아르카디아는 도시 전체를 거대한 방호막과 구조물로 덮는 돔 시티 계획을 실행했다.\u003c/p\u003e\r\n  \u003cp\u003e초기 돔은 낮고 두꺼웠으며 내부에는 자연광이 거의 들어오지 않았다. 주민들은 인공조명 아래에서 일하고 잠들었다. 환기와 냉각설비의 소음이 도시 전체를 뒤덮었고, 시설고장은 곧 대규모 사망으로 이어졌다.\u003c/p\u003e\r\n  \u003cp\u003e수차례의 실패와 도시 폐쇄를 거친 끝에 아르카디아는 안정적인 대기순환, 수경재배와 폐기물 재처리 기술을 완성했다.\u003c/p\u003e\r\n  \u003cp\u003e최초의 완전한 돔 시티가 건설되자 주변의 생존자와 기업, 기술자들이 몰려들었다. 돔 내부의 거주권은 물과 무기만큼 가치 있는 자산이 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 3세기 — 시민권 사회\u003c/h3\u003e\r\n  \u003cp\u003e돔 시티의 인구가 증가하면서 기존의 임시 배급제만으로는 사회를 유지할 수 없게 되었다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 주민의 직업, 기술, 기업소속과 기여도를 기준으로 시민권 등급을 세분화했다. 시민권에 따라 거주구역, 의료서비스, 교육, 배급량과 출입권한이 달라졌다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기에 돔 내부의 구역이 본격적으로 분리되었다.\u003c/p\u003e\r\n  \u003cp\u003e상층구역에는 넓은 주거지와 공원, 깨끗한 공기와 자연광에 가까운 인공조명이 제공되었다. 중층구역에는 일반 시민과 기술자, 서비스 노동자가 거주했다. 하층구역에는 산업시설, 폐기물 처리장과 저등급 노동자들의 밀집주거지가 형성되었다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 능력과 기여에 따라 자원이 배분되는 합리적인 체계라고 설명했다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 시민들은 태어난 순간부터 자신이 살아갈 층과 받을 수 있는 교육, 접근할 수 있는 직업이 상당 부분 결정된다는 사실을 깨닫기 시작했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 4세기 — 인공하늘의 시대\u003c/h3\u003e\r\n  \u003cp\u003e돔 시티가 안정되자 시민들은 생존을 넘어 삶의 질을 요구하기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e몇 세대에 걸쳐 돔 안에서 태어난 사람들은 실제 하늘과 바다, 숲을 본 적이 없었다. 폐쇄된 공간에서 발생하는 우울증과 수면장애, 집단불안이 심각한 사회문제로 떠올랐다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 솔라리스의 광학기술과 기후자료를 이용해 돔 천장 전체를 인공하늘로 바꾸었다.\u003c/p\u003e\r\n  \u003cp\u003e인공하늘은 시간에 따라 색이 변했고 구름과 별, 일출과 일몰을 재현했다. 온도와 습도, 바람과 인공강우도 계절에 맞추어 조정되었다.\u003c/p\u003e\r\n  \u003cp\u003e돔 시티의 시민들은 수백 년 만에 다시 푸른 하늘 아래에서 살아가는 감각을 경험했다.\u003c/p\u003e\r\n  \u003cp\u003e이 기술은 아르카디아의 정체성을 완전히 바꾸었다. 기업은 더 이상 외부환경을 차단하는 방공호만을 건설하지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 인간이 기억하는 자연을 도시 안에 재현하기 시작했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 5세기 — 생활의 기업화\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아는 도시 기반시설뿐 아니라 시민의 일상 전체로 사업을 확장했다.\u003c/p\u003e\r\n  \u003cp\u003e주택, 병원, 학교, 교통, 식량생산, 문화시설과 행정서비스가 하나의 기업체계 아래 통합되었다. 시민들은 아르카디아의 시설에서 태어나고 교육받으며, 기업이 배정한 직장에서 일하고 기업병원에서 치료받았다.\u003c/p\u003e\r\n  \u003cp\u003e도시 내 상점과 민간기업은 존재했지만, 영업허가와 임대공간, 전력과 수도, 블루넷 접속권은 아르카디아의 승인을 받아야 했다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기에 아르카디아 시민권은 세계에서 가장 안정적인 신분 중 하나가 되었다. 황무지와 장막 도시의 사람들은 돔 시티에 들어가기 위해 막대한 돈을 지불하거나 장기 노동계약을 체결했다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 시민권을 잃고 돔 밖으로 추방되는 것은 사회적인 죽음과 다르지 않게 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 6세기 — 칠정의 성립\u003c/h3\u003e\r\n  \u003cp\u003e돔 시티가 거대해질수록 아르카디아는 다른 기반기업에 깊이 의존하게 되었다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드가 물을 공급하지 않으면 도시의 순환수 체계는 오래 버틸 수 없었다. 솔라리스의 전력이 끊기면 인공하늘과 대기정화시설이 정지했다. 카론이 물자를 운송하지 않으면 수경재배에 필요한 비료와 기계부품을 확보할 수 없었다.\u003c/p\u003e\r\n  \u003cp\u003e반대로 다른 기업들도 아르카디아의 돔을 필요로 했다.\u003c/p\u003e\r\n  \u003cp\u003e기업의 직원과 가족, 연구소, 금융시설과 생산거점은 안전한 도시환경 없이는 유지될 수 없었다.\u003c/p\u003e\r\n  \u003cp\u003e초거대 기업들이 상호의존 관계를 공식화하면서 아르카디아는 칠정의 핵심 구성원이 되었다. 아르카디아는 칠정 내에서 돔 건설, 도시운영, 시민행정과 생활환경을 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e다른 기업이 문명의 자원과 기술을 관리한다면, 아르카디아는 그 문명 안에서 살아가는 인간을 관리한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e현재 — 멸망 후 700년\u003c/h3\u003e\r\n  \u003cp\u003e현재 아르카디아는 다수의 돔 시티와 위성 거주구역을 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e각 도시는 서로 다른 역사와 문화를 지니지만, 공통적으로 아르카디아의 환경제어 규격과 시민권 체계를 사용한다. 돔의 대기와 기온, 일조시간, 주거구역과 인구밀도는 중앙 도시운영체계에 의해 관리된다.\u003c/p\u003e\r\n  \u003cp\u003e시민들은 백야 이전보다 안전하고 풍요로운 생활을 누린다. 깨끗한 물과 공기, 의료, 교육과 안정적인 치안이 제공되며, 황무지의 위험으로부터 보호받는다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 이러한 생활은 자연스럽게 주어진 권리가 아니다.\u003c/p\u003e\r\n  \u003cp\u003e시민은 계속해서 자신의 신분과 기여도를 증명해야 한다. 채무, 범죄, 기업과의 계약위반으로 시민권 등급이 하락할 수 있으며, 최악의 경우 돔 거주권 자체를 잃을 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 인류에게 멸망 이전의 삶을 재현해 주었다.\u003c/p\u003e\r\n  \u003cp\u003e그 대가로 삶을 구성하는 모든 요소를 기업의 관리 아래 두었다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e핵심 산업\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e돔 시티 건설\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아의 대표적인 산업이다.\u003c/p\u003e\r\n  \u003cp\u003e돔은 외부의 열기, 독성물질, 모래폭풍, 방사선과 일소로부터 도시를 보호한다. 돔 외벽은 단일한 구조물이 아니라 장갑외피, 차폐막, 압력조절층과 환경센서가 겹쳐진 복합 방어체계다.\u003c/p\u003e\r\n  \u003cp\u003e도시의 규모와 환경에 따라 다양한 형태의 돔이 건설된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e대형 완전밀폐형 중앙돔\u003c/li\u003e\r\n    \u003cli\u003e산업시설 중심의 중형 돔\u003c/li\u003e\r\n    \u003cli\u003e기존 도시를 부분적으로 덮는 구역형 돔\u003c/li\u003e\r\n    \u003cli\u003e지하도시와 연결되는 반지하형 돔\u003c/li\u003e\r\n    \u003cli\u003e신규 정착지를 위한 조립식 소형 해비타트\u003c/li\u003e\r\n    \u003cli\u003e기업 연구소와 군사시설을 위한 특수격리 돔\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e돔 하나를 건설하는 데는 수십 년이 걸릴 수 있다. 완공 전부터 거주권과 상업구역이 판매되며, 기업과 상류층이 우선적으로 지분을 확보한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e도시 운영\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아는 자신들이 건설한 도시의 운영권도 보유한다.\u003c/p\u003e\r\n  \u003cp\u003e대기순환, 냉난방, 전력배분, 폐기물 처리와 교통체계가 중앙 도시운영망에 연결된다. 도시의 모든 구역은 실시간으로 인구밀도와 에너지 소비량, 공기질을 측정한다.\u003c/p\u003e\r\n  \u003cp\u003e중앙시스템은 특정 구역의 출입을 제한하거나 전력과 산소 공급량을 조절할 수 있다. 재난이 발생하면 오염된 구역을 격리하고 방화벽과 압력문을 폐쇄한다.\u003c/p\u003e\r\n  \u003cp\u003e이러한 통제는 도시를 보호하기 위한 필수기능이다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 아르카디아가 특정 구역의 생존조건을 원격으로 변경할 수 있다는 의미이기도 하다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e주거산업\u003c/h3\u003e\r\n  \u003cp\u003e돔 내부의 모든 공간은 제한된 자원이다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 주택을 단순히 판매하지 않고 시민권과 함께 장기계약 형태로 제공한다. 시민은 계약기간 동안 거주권을 보장받지만, 토지와 건물의 최종 소유권은 기업에 남는다.\u003c/p\u003e\r\n  \u003cp\u003e주거구역은 시민권과 소득에 따라 구분된다.\u003c/p\u003e\r\n  \u003cp\u003e상층구역에는 개인정원, 넓은 창문과 높은 품질의 인공자연이 제공된다. 중층구역은 효율적인 집합주택과 상업시설로 구성된다. 하층구역에는 소형 모듈주택과 노동자 기숙사가 밀집되어 있다.\u003c/p\u003e\r\n  \u003cp\u003e같은 돔 안에서도 시민이 경험하는 아르카디아는 전혀 다르다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e환경제어\u003c/h3\u003e\r\n  \u003cp\u003e대기, 온도, 습도, 풍속과 일조량을 조절하는 산업이다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 돔 내부의 공기를 지속적으로 정화하고 산소와 이산화탄소 농도를 조절한다. 인구증가나 산업활동으로 특정 구역의 공기질이 악화되면 환기량과 출입인원을 제한한다.\u003c/p\u003e\r\n  \u003cp\u003e환경제어 서비스에는 여러 등급이 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e상류층 구역에는 자연환경과 유사한 공기와 향기, 계절풍이 제공된다. 산업구역과 하층구역에서는 법적 최소기준을 만족하는 수준으로만 관리되는 경우가 많다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e인공하늘과 기후 서비스\u003c/h3\u003e\r\n  \u003cp\u003e돔 천장의 인공하늘은 아르카디아를 상징하는 기술이다.\u003c/p\u003e\r\n  \u003cp\u003e기본적인 하늘은 24시간 주기로 일출과 일몰을 재현한다. 도시의 문화와 지역에 따라 계절, 별자리, 구름과 강수패턴이 다르게 설정된다.\u003c/p\u003e\r\n  \u003cp\u003e상류층 거주구역에서는 주민들의 선호에 따라 날씨를 조정할 수 있다. 중요한 축제나 기업행사가 있는 날에는 맑은 날씨가 보장된다.\u003c/p\u003e\r\n  \u003cp\u003e도시 전체의 분위기를 안정시키기 위해 특정 색온도와 일조시간이 적용되기도 한다. 아르카디아는 이를 시민의 건강과 생활리듬을 위한 조정이라고 설명한다.\u003c/p\u003e\r\n  \u003cp\u003e비판자들은 감정과 여론을 관리하기 위한 환경적 통제라고 주장한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e식량생산\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아는 돔 내부의 수경재배시설과 배양식품 공장을 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e재배시설에서는 채소, 곡물, 과일과 의약작물이 생산된다. 고기와 단백질은 주로 배양육, 곤충단백질과 합성식품으로 공급된다.\u003c/p\u003e\r\n  \u003cp\u003e자연 토양에서 재배한 식품은 극도로 비싸며 상류층과 고급식당에서만 소비된다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 도시 내 식량 자급률을 높게 유지하려 하지만 종자, 비료와 배양원료의 상당 부분을 외부기업과 황무지 농장에서 공급받는다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e교육과 인재배치\u003c/h3\u003e\r\n  \u003cp\u003e돔 시티의 교육기관 대부분은 아르카디아의 허가 아래 운영된다.\u003c/p\u003e\r\n  \u003cp\u003e기초교육은 모든 정식 시민에게 제공되지만, 고등교육과 전문교육은 적성검사, 시민권 등급과 기업의 인력수요에 따라 결정된다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 학생의 능력과 성향을 분석해 적합한 진로를 추천한다. 추천은 법적으로 강제가 아니지만, 기업이 제안한 경로를 거부하면 장학금과 취업기회가 크게 줄어든다.\u003c/p\u003e\r\n  \u003cp\u003e교육은 시민에게 기회를 제공하는 제도인 동시에 도시가 필요한 노동력을 안정적으로 확보하는 체계다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e의료와 복지\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아는 일반 진료, 공중보건, 예방접종과 정신건강 서비스를 제공한다. 전문적인 응급구조와 신체복원은 라자루스와 계약하며, 고급 생체시술은 모르포스에 의존한다.\u003c/p\u003e\r\n  \u003cp\u003e복지서비스는 시민권 등급과 보험계약에 따라 차등 제공된다.\u003c/p\u003e\r\n  \u003cp\u003e기초 시민은 생존에 필요한 최소한의 의료와 주거를 보장받는다. 상위 시민은 개인의사, 유전자 치료와 고급 신체복원 서비스를 이용할 수 있다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e도시문화와 엔터테인먼트\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아는 공연장, 공원, 박물관, 방송국과 공공축제를 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e도시문화는 단순한 오락이 아니라 폐쇄된 돔 내부의 사회안정을 유지하기 위한 필수 서비스로 취급된다. 주민들의 불만과 스트레스가 높아지면 공연, 스포츠 행사와 기념축제가 확대된다.\u003c/p\u003e\r\n  \u003cp\u003e유명 연예인과 아이돌은 기업홍보와 시민통합에 적극적으로 활용된다. 아르카디아의 인공하늘 아래에서 개최되는 대형 공연은 돔 시티의 번영을 보여주는 대표적인 선전수단이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e시민권 체계\u003c/h2\u003e\r\n  \u003ch3\u003e기업시민\u003c/h3\u003e\r\n  \u003cp\u003e칠정 또는 주요 협력기업과 정식 고용계약을 맺은 시민이다. 안정적인 주거와 의료, 교육, 블루넷 접속권을 보장받는다.\u003c/p\u003e\r\n  \u003cp\u003e기업 내 직위와 중요도에 따라 상층구역에 거주할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e등록 자유민\u003c/h3\u003e\r\n  \u003cp\u003e특정 기업에 완전히 소속되지는 않았지만 돔 행정부에 신원이 등록된 시민이다. 세금과 거주비를 납부하며 제한된 도시서비스를 이용한다.\u003c/p\u003e\r\n  \u003cp\u003e직업과 소득이 불안정해지면 시민권 유지가 어려워질 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e임시거주민\u003c/h3\u003e\r\n  \u003cp\u003e계약직 노동자, 방문객과 외부 상인에게 발급되는 제한적인 신분이다. 허가된 구역과 기간에만 돔 내부에 머물 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e비등록자\u003c/h3\u003e\r\n  \u003cp\u003e정식 시민기록이 없거나 시민권을 상실한 사람이다. 합법적인 주거와 의료서비스를 이용할 수 없으며, 적발될 경우 구금되거나 돔 밖으로 추방될 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e일부 비등록자는 하층구역과 폐쇄된 정비통로에서 숨어 살아간다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업 구조\u003c/h2\u003e\r\n  \u003cp\u003e아르카디아는 기업과 도시정부가 결합된 구조를 가지고 있다.\u003c/p\u003e\r\n  \u003ch3\u003e중앙이사회\u003c/h3\u003e\r\n  \u003cp\u003e신규 돔 건설, 도시확장, 시민권 정책과 기업 간 계약을 결정한다. 대형 부동산 지분을 가진 투자자와 칠정 계열 대표들이 참여한다.\u003c/p\u003e\r\n  \u003ch3\u003e생활환경총재\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아의 최고경영자이자 주요 돔 시티의 최종 행정책임자다. 기업 내부에서는 대표이사보다 도시국가의 통치자에 가까운 존재로 취급된다.\u003c/p\u003e\r\n  \u003ch3\u003e도시운영총괄\u003c/h3\u003e\r\n  \u003cp\u003e돔 내부의 모든 생활환경과 행정서비스를 통제한다. 비상사태에는 도시 봉쇄, 강제대피와 구역격리를 명령할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e건설·환경 부문\u003c/h3\u003e\r\n  \u003cp\u003e돔 개발, 대기순환, 냉방, 수경재배와 폐기물 처리를 담당한다. 도시의 물리적 생존을 유지하는 핵심 부문이다.\u003c/p\u003e\r\n  \u003ch3\u003e시민서비스 부문\u003c/h3\u003e\r\n  \u003cp\u003e주거, 의료, 교육, 문화와 생활서비스를 담당한다. 시민이 일상에서 가장 자주 접하는 아르카디아의 얼굴이다.\u003c/p\u003e\r\n  \u003ch3\u003e행정·통제 부문\u003c/h3\u003e\r\n  \u003cp\u003e시민권, 인구등록, 도시법규와 사회설계를 담당한다. 도시의 질서를 유지하는 동시에 주민의 이동과 신분을 관리한다.\u003c/p\u003e\r\n  \u003ch3\u003e사회설계연구소\u003c/h3\u003e\r\n  \u003cp\u003e인구변화, 범죄율, 소비성향과 시민심리를 분석해 도시정책을 설계한다.\u003c/p\u003e\r\n  \u003cp\u003e공식적으로는 효율적인 행정과 복지를 위한 연구기관이지만, 시민의 행동과 여론을 유도하는 기술을 개발한다는 비판을 받는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 기술\u003c/h2\u003e\r\n  \u003ch3\u003e에덴 환경제어망\u003c/h3\u003e\r\n  \u003cp\u003e돔 내부의 대기, 온도, 습도와 오염도를 실시간으로 관리하는 중앙시스템이다.\u003c/p\u003e\r\n  \u003cp\u003e구역별 인구와 활동량에 따라 자원을 자동 분배하며, 화재나 오염이 발생하면 해당 구역을 즉시 봉쇄한다.\u003c/p\u003e\r\n  \u003ch3\u003e스카이베일\u003c/h3\u003e\r\n  \u003cp\u003e돔 천장에 하늘과 구름, 별과 태양을 재현하는 광학시스템이다. 실제 기후자료를 반영하거나 완전히 인공적인 날씨를 구현할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e순환생태계\u003c/h3\u003e\r\n  \u003cp\u003e물, 공기, 유기폐기물과 영양분을 재처리하는 폐쇄형 생명유지체계다. 외부 공급이 일시적으로 끊겨도 일정 기간 도시가 유지되도록 설계되었다.\u003c/p\u003e\r\n  \u003ch3\u003e모듈러 해비타트\u003c/h3\u003e\r\n  \u003cp\u003e황무지에 신속하게 설치할 수 있는 조립식 거주구역이다. 정착지, 광산과 연구시설에 사용된다.\u003c/p\u003e\r\n  \u003cp\u003e규모는 작지만 대기정화, 냉방, 수분회수와 기본 방호기능을 갖추고 있다.\u003c/p\u003e\r\n  \u003ch3\u003e시빅 코어\u003c/h3\u003e\r\n  \u003cp\u003e시민의 신분, 주거, 의료, 교육, 세금과 소비기록을 통합적으로 관리하는 행정시스템이다.\u003c/p\u003e\r\n  \u003cp\u003e시민은 하나의 계정으로 대부분의 도시서비스를 이용할 수 있다. 반대로 계정이 정지되면 교통과 주거, 결제와 의료서비스를 동시에 잃을 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e구역격리체계\u003c/h3\u003e\r\n  \u003cp\u003e재난이나 폭동이 발생했을 때 돔 내부를 독립된 밀폐구역으로 분리한다. 압력문과 방화벽, 환기차단장치가 자동으로 작동한다.\u003c/p\u003e\r\n  \u003cp\u003e공식 목적은 오염과 화재의 확산을 막는 것이다. 그러나 인구봉쇄와 시위진압에도 사용된 전례가 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 시설\u003c/h2\u003e\r\n  \u003ch3\u003e아르카디아 중앙돔\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아의 본사와 중앙행정부가 위치한 대표적인 돔 시티다.\u003c/p\u003e\r\n  \u003cp\u003e상층부에는 기업본부, 고급 주거지, 공원과 문화시설이 있으며, 중층부에는 상업구역과 일반 주거지, 교육시설이 자리 잡고 있다. 하층부에는 산업시설, 물류구역과 생명유지설비가 집중되어 있다.\u003c/p\u003e\r\n  \u003cp\u003e중앙돔은 아르카디아가 선전하는 이상적인 미래도시의 표본이다.\u003c/p\u003e\r\n  \u003ch3\u003e에덴 코어\u003c/h3\u003e\r\n  \u003cp\u003e중앙돔의 환경제어와 생명유지시설이 집중된 핵심구역이다. 외부인의 접근이 금지되며 아르카디아 기술자와 보안요원만 출입할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e에덴 코어가 완전히 정지하면 중앙돔은 장기간 생존할 수 없다.\u003c/p\u003e\r\n  \u003ch3\u003e스카이 가든\u003c/h3\u003e\r\n  \u003cp\u003e돔 상층부에 조성된 대규모 인공생태공원이다. 실제 나무와 토양, 작은 호수와 인공강우가 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e일반 시민에게 일부 구역이 공개되지만, 중심부는 상위 시민과 기업간부만 이용할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e시빅 아카이브\u003c/h3\u003e\r\n  \u003cp\u003e700년 동안 축적된 시민등록, 출생, 사망, 이주와 범죄기록을 보관하는 시설이다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아 시민의 신분은 이곳의 기록을 통해 증명된다. 아카이브에서 기록이 삭제된 사람은 법적으로 존재하지 않는 것과 같다.\u003c/p\u003e\r\n  \u003ch3\u003e제로 해비타트\u003c/h3\u003e\r\n  \u003cp\u003e공식 지도에 표시되지 않는 폐쇄 돔에 붙은 통칭이다.\u003c/p\u003e\r\n  \u003cp\u003e실패한 도시실험, 전염병, 생태계 붕괴나 주민폭동으로 폐쇄된 돔들이 존재한다는 소문이 있다. 아르카디아는 일부 폐쇄시설의 존재를 인정하지만 정확한 위치와 내부상태는 공개하지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e직원 문화\u003c/h2\u003e\r\n  \u003cp\u003e아르카디아의 직원들은 자신들을 건물과 서비스를 판매하는 사람이 아니라 문명을 유지하는 관리자라고 생각한다.\u003c/p\u003e\r\n  \u003cp\u003e기업 내부에서는 안정성, 예측 가능성과 사회질서가 가장 중요한 가치로 여겨진다. 개인의 자유보다 도시 전체의 안전을 우선하는 판단이 자연스럽게 받아들여진다.\u003c/p\u003e\r\n  \u003cp\u003e상위 행정직과 도시설계자들은 시민의 생활을 수치와 통계로 바라보는 경향이 강하다. 인구밀도, 범죄율, 우울증 지수와 소비활동은 모두 조정해야 할 도시변수로 취급된다.\u003c/p\u003e\r\n  \u003cp\u003e현장 직원은 시민과 직접 접촉하면서 기업정책과 현실 사이의 차이를 체감한다. 특히 하층구역의 주거관리인, 사회복지사와 환경기술자는 제한된 자원을 누구에게 우선 배분할지 끊임없이 선택해야 한다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아 내부에서 널리 사용되는 문구는 다음과 같다.\u003c/p\u003e\r\n  \u003cblockquote\u003e도시는 살아 있는 생명체다. 때로는 일부를 포기해야 전체가 살아남는다.\u003c/blockquote\u003e\r\n\r\n  \u003ch2\u003e채용과 복지\u003c/h2\u003e\r\n  \u003cp\u003e아르카디아는 도시공학자, 건축가, 환경기술자, 행정가, 교육자, 의료인과 사회분석가를 폭넓게 채용한다.\u003c/p\u003e\r\n  \u003cp\u003e돔 내부의 생활서비스 대부분을 운영하기 때문에 칠정 가운데 가장 많은 정규직과 계약직을 고용하는 기업이다.\u003c/p\u003e\r\n  \u003cp\u003e정규직과 가족에게는 다음과 같은 혜택이 제공된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e안정적인 돔 거주권\u003c/li\u003e\r\n    \u003cli\u003e직원 전용 주거구역\u003c/li\u003e\r\n    \u003cli\u003e우선 의료서비스\u003c/li\u003e\r\n    \u003cli\u003e자녀 교육과 직업훈련\u003c/li\u003e\r\n    \u003cli\u003e시민권 등급 유지\u003c/li\u003e\r\n    \u003cli\u003e문화시설 이용권\u003c/li\u003e\r\n    \u003cli\u003e장기근속자의 상위구역 이주기회\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e그러나 직업을 잃으면 주거와 시민권까지 동시에 위태로워질 수 있다. 아르카디아의 직원에게 해고는 단순한 실직이 아니라 생활기반 전체의 상실을 의미한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e계층별 인식\u003c/h2\u003e\r\n  \u003ch3\u003e돔 시티 상류층\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아를 문명과 번영의 수호자로 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e깨끗한 공기와 넓은 주거공간, 실제 자연에 가까운 공원과 고급 의료서비스를 누리기 때문에 기업의 통제를 억압으로 체감하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e그들에게 돔은 감옥이 아니라 외부의 혼란으로부터 자신들을 보호하는 성벽이다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 시티 일반 시민\u003c/h3\u003e\r\n  \u003cp\u003e안정적인 일상에 감사하면서도 높은 주거비와 시민권 평가를 부담스러워한다.\u003c/p\u003e\r\n  \u003cp\u003e대부분의 시민은 아르카디아가 없다면 도시가 유지될 수 없다는 사실을 알고 있다. 동시에 회사가 자신의 직업, 주거와 가족의 미래까지 결정할 수 있다는 점을 두려워한다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 하층민\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아가 약속한 낙원에서 가장 멀리 떨어진 사람들이다.\u003c/p\u003e\r\n  \u003cp\u003e낮은 천장, 부족한 생활공간과 노후한 환기시설 속에서 살아간다. 돔 외부보다는 안전하지만, 상층의 인공정원과 맑은 하늘이 자신들을 위한 것이 아니라는 사실을 알고 있다.\u003c/p\u003e\r\n  \u003ch3\u003e장막 도시 주민\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아를 안전한 삶의 상징이자 계층차별의 근원으로 본다.\u003c/p\u003e\r\n  \u003cp\u003e많은 사람이 돔 시민권을 꿈꾸지만, 실제로 들어간 사람 대부분이 저임금 노동자나 임시거주민으로 살아간다는 사실도 알고 있다.\u003c/p\u003e\r\n  \u003ch3\u003e황무지인\u003c/h3\u003e\r\n  \u003cp\u003e돔 시티를 거대한 감옥이라고 조롱하면서도 그 안의 물과 공기, 의료를 부러워한다.\u003c/p\u003e\r\n  \u003cp\u003e일부 황무지인은 아르카디아의 신분등록과 생활통제를 인간성을 잃는 행위로 여긴다.\u003c/p\u003e\r\n  \u003ch3\u003e다른 기업\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아를 직원과 시설을 수용하는 필수 파트너로 취급한다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 아르카디아가 시민권과 도시행정을 이용해 다른 기업의 직원들에게까지 영향력을 행사하는 것을 경계한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e다른 세력과의 관계\u003c/h2\u003e\r\n  \u003ch3\u003eNEREID HYDROSYSTEMS\u003c/h3\u003e\r\n  \u003cp\u003e네레이드는 돔 시티에 원수와 정제수를 공급하고, 아르카디아는 도시 내부의 배관과 재순환시설을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e양사는 긴밀한 파트너지만 수질사고가 발생하면 책임을 두고 충돌한다. 네레이드는 도시 배관의 관리부실을 주장하고, 아르카디아는 공급된 물의 문제라고 반박한다.\u003c/p\u003e\r\n  \u003ch3\u003eSOLARIS ORBITAL INDUSTRIES\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스는 돔에 전력, 기상자료와 인공하늘 기술을 제공한다. 아르카디아는 이를 시민의 생활환경으로 가공한다.\u003c/p\u003e\r\n  \u003cp\u003e두 기업은 인공날씨와 일조시간의 결정권을 두고 지속적으로 협상한다.\u003c/p\u003e\r\n  \u003ch3\u003eMORPHOS BIODYNE\u003c/h3\u003e\r\n  \u003cp\u003e모르포스는 아르카디아의 병원과 고급주거구역에 생체의료, 유전자 관리와 맞춤형 신체개조 서비스를 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아의 시민기록과 모르포스의 생체정보가 결합될 경우 개인의 건강뿐 아니라 수명과 질병 가능성까지 예측할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003eCERBERUS DEFENSE GROUP\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 돔 외벽, 방어포탑과 보안장비를 공급한다. 외부의 대규모 공격이나 장기적인 포위상황에서는 케르베로스의 병력이 도시방위에 투입된다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 군사기업이 시민행정에 개입하는 것을 경계한다.\u003c/p\u003e\r\n  \u003ch3\u003eCHARON INTERCONTINENTAL\u003c/h3\u003e\r\n  \u003cp\u003e카론은 식량, 기계부품과 건설자재를 돔으로 운송한다. 아르카디아가 신규 돔을 건설할 때 가장 먼저 확보하는 협력기업 중 하나다.\u003c/p\u003e\r\n  \u003ch3\u003eARGOS SECURE NETWORKS\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 돔 내부의 테러, 기업공작과 신분위조를 감시한다. 아르카디아는 시민등록과 도시감시자료를 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e두 기업의 정보가 결합되면 돔 시민의 일상 대부분을 추적할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003eDOME CIVIC SECURITY\u003c/h3\u003e\r\n  \u003cp\u003eDCS는 돔 내부의 순찰, 범죄수사, 교통통제와 지역치안을 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e명목상 도시행정부의 공공치안기관이지만, 예산과 시설, 시민자료의 상당 부분을 아르카디아에 의존한다. 이 때문에 DCS가 시민을 위한 경찰인지 기업의 질서를 지키는 경비조직인지에 대한 논쟁이 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003eTHE BLUE TABLE\u003c/h3\u003e\r\n  \u003cp\u003e블루 테이블은 신규 돔 건설, 시민대피와 기업 간 도시운영권을 조정한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 실제 돔의 기술자료와 주민정보는 아르카디아가 독점하고 있어 외부감사의 범위에는 한계가 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e사회공헌과 홍보\u003c/h2\u003e\r\n  \u003cp\u003e아르카디아는 자신들을 “인류의 집을 지키는 기업”이라고 소개한다.\u003c/p\u003e\r\n  \u003cp\u003e장막 도시에 공기정화소와 냉방쉼터를 설치하고, 재난지역에 조립식 해비타트를 제공한다. 고아와 난민을 돔 내부의 교육시설에 수용하는 프로그램도 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e기업홍보에는 푸른 하늘 아래에서 웃는 가족, 깨끗한 거리와 녹색공원이 반복적으로 등장한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 구조 대상자로 선발된 사람은 대부분 장기 노동계약을 체결해야 한다. 아르카디아의 구호시설이 신규 노동자와 시민을 확보하기 위한 모집소라는 비판도 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e논란과 비판\u003c/h2\u003e\r\n  \u003ch3\u003e시민권의 상품화\u003c/h3\u003e\r\n  \u003cp\u003e안전한 환경에서 살아갈 권리가 기업의 계약과 평가에 따라 결정된다는 비판을 받는다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 한정된 공간과 자원을 공정하게 배분하기 위한 불가피한 제도라고 주장한다.\u003c/p\u003e\r\n  \u003ch3\u003e환경의 계급화\u003c/h3\u003e\r\n  \u003cp\u003e같은 돔 안에서도 구역에 따라 공기질, 일조량, 온도와 생활공간이 다르다.\u003c/p\u003e\r\n  \u003cp\u003e상류층은 자연에 가까운 환경을 누리는 반면, 하층민은 최소기준에 가까운 환경에서 생활한다.\u003c/p\u003e\r\n  \u003ch3\u003e시민감시\u003c/h3\u003e\r\n  \u003cp\u003e시빅 코어는 시민의 이동, 소비, 의료와 교육정보를 통합적으로 기록한다. 기업은 도시서비스를 효율적으로 제공하기 위한 자료라고 설명한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 아르카디아가 시민의 행동을 평가해 주거와 직업, 시민권에 반영한다는 사실은 공공연한 비밀이다.\u003c/p\u003e\r\n  \u003ch3\u003e강제적인 구역격리\u003c/h3\u003e\r\n  \u003cp\u003e재난과 폭동이 발생했을 때 특정 구역이 외부와 완전히 차단된다.\u003c/p\u003e\r\n  \u003cp\u003e과거에는 감염과 화재를 막기 위해 수천 명이 남아 있던 하층구역을 봉쇄한 사례가 있었다. 아르카디아는 도시 전체를 구하기 위한 불가피한 결정이었다고 발표했다.\u003c/p\u003e\r\n  \u003ch3\u003e인공기후를 이용한 여론관리\u003c/h3\u003e\r\n  \u003cp\u003e시민들의 불만이 증가할 때 일조시간을 늘리거나 축제에 맞춰 쾌적한 날씨를 제공한다는 의혹이 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e반대로 시위가 예정된 지역에 강우와 기온저하를 적용했다는 기록도 보고되었다.\u003c/p\u003e\r\n  \u003ch3\u003e비등록자의 존재\u003c/h3\u003e\r\n  \u003cp\u003e공식통계상 돔 시티 내부의 모든 사람은 등록되어 있다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 폐쇄된 정비통로와 하층구역에는 행정기록에 존재하지 않는 사람들이 살아간다. 아르카디아는 이들을 불법침입자로 규정하지만, 상당수는 시민권을 박탈당한 옛 주민과 그 후손이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e확인되지 않은 소문\u003c/h2\u003e\r\n  \u003cp\u003e아르카디아가 폐쇄한 돔 가운데 일부는 실제로 파괴되지 않았다는 소문이 있다.\u003c/p\u003e\r\n  \u003cp\u003e‘제로 해비타트’라 불리는 시설에서는 도시 전체가 외부와 차단된 채 독자적인 사회실험을 이어가고 있다고 한다. 주민들은 자신들이 백야 직후에 살고 있다고 믿거나, 외부세계가 완전히 멸망했다고 교육받았다는 이야기까지 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e사회설계연구소가 시민의 감정과 정치성향을 조절하기 위해 인공하늘, 배급과 방송을 결합한 장기실험을 수행한다는 의혹도 있다.\u003c/p\u003e\r\n  \u003cp\u003e일부 문서에는 시민을 개인이 아니라 도시를 구성하는 ‘가변 인구자원’으로 분류한 흔적이 발견되었다.\u003c/p\u003e\r\n  \u003cp\u003e가장 오래된 소문은 아르카디아 중앙돔에 관한 것이다.\u003c/p\u003e\r\n  \u003cp\u003e중앙돔의 가장 깊은 곳에는 2102년부터 한 번도 개방되지 않은 최초의 생존구역이 남아 있으며, 그 안에는 아르카디아 창립자들과 백야 이전의 시민들이 동면 상태로 보존되어 있다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e현재의 아르카디아가 그들의 귀환을 위해 700년 동안 도시를 유지해 왔다는 주장도 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 이를 근거 없는 도시전설이라고 일축한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업이 가진 힘\u003c/h2\u003e\r\n  \u003cp\u003e아르카디아의 힘은 군대나 자원 하나에서 나오지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 인간이 살아가는 공간 자체를 소유한다.\u003c/p\u003e\r\n  \u003cp\u003e돔의 문을 열고 닫으며, 공기의 온도와 하늘의 색을 바꾼다. 누가 시민이 될 수 있는지, 어느 구역에서 살 수 있는지, 어떤 교육과 의료를 받을 수 있는지를 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아가 도시의 전력을 완전히 생산하는 것은 아니다. 모든 물을 소유한 것도 아니며, 최강의 군대를 거느리지도 않는다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 칠정의 기업과 수많은 시민은 아르카디아가 만든 도시 안에서 살아간다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드가 인류의 목을 쥐고 있고 솔라리스가 머리 위의 하늘을 차지했다면, 아르카디아는 인류가 발을 딛고 잠드는 집을 소유하고 있다.\u003c/p\u003e\r\n  \u003cp\u003e그리고 돔 바깥의 세상을 두려워하는 사람이 존재하는 한, 그 집의 가격은 계속해서 올라갈 것이다.\u003c/p\u003e\r\n\u003c/section\u003e\r\n";
window.FACTION_INFO.morphos = "\u003csection class=\"faction-detail\"\u003e\r\n  \u003ch2\u003e기업 개요\u003c/h2\u003e\r\n  \u003cp class=\"faction-quote\"\u003e“육체는 운명이 아니다. 하나의 설계일 뿐이다.”\u003c/p\u003e\r\n  \u003cp\u003e모르포스 바이오다인은 생체공학, 유전자 개량, 신경 인터페이스, 맞춤형 사이버웨어와 인체개조를 전문으로 하는 초거대 생명공학 기업이다. 2102년 백야 이후 오염과 방사선, 질병과 극한환경에 적응할 새로운 인간을 설계하며 성장했다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스의 제품은 공장에서 대량생산되는 규격품이 아니다. 고객의 유전자, 신경구조, 생활환경과 심리적 성향을 분석해 신체 전체를 하나의 작품처럼 설계한다. 같은 기능을 가진 의체라도 사용자의 체형과 전투방식, 미적 취향에 따라 전혀 다른 형태로 제작된다.\u003c/p\u003e\r\n  \u003cp\u003e상류층에게 모르포스는 노화와 신체적 한계에서 벗어나게 해주는 고급 생명공학 기업이다. 용병과 기업군인에게는 인간의 전투능력을 극한까지 끌어올리는 병기공방이며, 장막 도시의 주민에게는 평생을 벌어도 감당하기 어려운 특권층의 불멸 사업으로 보인다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스는 사람을 치료한다고 말하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 인간을 다시 설계한다고 말한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기본 정보\u003c/h2\u003e\r\n  \u003ctable class=\"data-table faction-info-table\"\u003e\r\n    \u003ctbody\u003e\r\n      \u003ctr\u003e\u003cth\u003e정식 명칭\u003c/th\u003e\u003ctd\u003eMORPHOS BIODYNE\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e통칭\u003c/th\u003e\u003ctd\u003e모르포스\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e기업 분류\u003c/th\u003e\u003ctd\u003e생체공학·맞춤 의체·인체개조 기업\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 산업\u003c/th\u003e\u003ctd\u003e유전자 치료, 조직배양, 신경공학, 맞춤 사이버웨어\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e전략 산업\u003c/th\u003e\u003ctd\u003e전투개조, 인공장기, 수명연장, 환경적응 시술\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e문화 산업\u003c/th\u003e\u003ctd\u003e신체디자인, 감각기술, 기업 아이돌과 미적 유행\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 고객\u003c/th\u003e\u003ctd\u003e상류층, 기업간부, 용병, 특수요원, 예술가\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e상징 색상\u003c/th\u003e\u003ctd\u003e자주색, 백색, 연보라색\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표적인 인식\u003c/th\u003e\u003ctd\u003e인간의 육체를 예술품으로 다루는 생명공학 귀족\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e칠정 내 역할\u003c/th\u003e\u003ctd\u003e생명공학, 신체복원과 고급 인체개조\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e본사 성격\u003c/th\u003e\u003ctd\u003e연구도시, 의료시설과 맞춤 공방이 결합된 생체산업단지\u003c/td\u003e\u003c/tr\u003e\r\n    \u003c/tbody\u003e\r\n  \u003c/table\u003e\r\n\r\n  \u003ch2\u003e기업의 역사\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e백야 이전 — 맞춤의학의 시대\u003c/h3\u003e\r\n  \u003cp\u003e모르포스의 기원은 21세기 후반에 활동하던 유전자 치료기업, 재생의학 연구소, 신경공학 회사와 고급 의체 제작사들로 거슬러 올라간다.\u003c/p\u003e\r\n  \u003cp\u003e당시 생명공학은 질병을 치료하는 수준을 넘어 인간의 신체능력과 수명을 개선하는 산업으로 발전하고 있었다. 인공장기, 배양조직, 뇌-기계 인터페이스와 유전자 교정기술이 빠르게 상용화되었다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 초기의 첨단시술은 극도로 비쌌다. 국가 의료체계보다 부유층을 위한 수명연장과 미용개조 시장에서 더 큰 수익을 거두었다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스의 전신 기업들은 인간의 육체를 단순히 치료하는 것이 아니라 고객의 목적에 맞게 다시 설계한다는 철학을 공유했다. 이들은 대량생산보다 개인 맞춤형 시술을 우선했으며, 의사와 공학자를 ‘설계자’라고 부르기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e21세기 말, 가장 뛰어난 연구자와 투자자 가문들이 기술과 유전자 특허를 통합하며 모르포스 바이오다인의 기반을 세웠다.\u003c/p\u003e\r\n  \u003cp\u003e훗날 창립가문회의로 이어지는 이 집단은 기업이라기보다 폐쇄적인 연구결사에 가까웠다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e2102년 — 백야\u003c/h3\u003e\r\n  \u003cp\u003e백야는 인류의 육체가 기존의 지구환경에 더 이상 적합하지 않다는 사실을 드러냈다.\u003c/p\u003e\r\n  \u003cp\u003e방사선과 유독물질, 극단적인 기온, 새로운 질병과 변이성 생물오염이 생존자들을 위협했다. 기존 의료시설은 붕괴했고, 항생제와 수술장비, 깨끗한 혈액과 장기를 구하기 어려워졌다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스의 전신 연구소들은 폐쇄형 배양시설과 독립전력을 갖추고 있었기 때문에 일부 기술을 보존할 수 있었다. 연구자들은 배양장기와 인공혈액을 생산하고, 오염에 손상된 신체를 기계와 생체조직으로 대체했다.\u003c/p\u003e\r\n  \u003cp\u003e초기의 개조는 아름답지도 정교하지도 않았다.\u003c/p\u003e\r\n  \u003cp\u003e살아남기 위해 팔과 다리를 잘라내고 산업용 기계부품을 연결했으며, 폐가 손상된 사람에게 외부 여과장치를 이식했다. 방사선에 노출된 생존자에게 실험적인 유전자 치료를 시행했고, 수많은 환자가 부작용으로 사망했다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 일부는 살아남았다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 이전보다 강해졌고, 더러운 공기를 견디며, 인간이 살 수 없던 환경에서 움직일 수 있었다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스는 그 순간부터 치료기관이 아니라 새로운 인간을 만드는 기업이 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망력 초기 — 생존을 위한 개조\u003c/h3\u003e\r\n  \u003cp\u003e백야 이후 수십 년 동안 모르포스는 생존시설과 도시를 돌아다니며 의료와 인체개조를 제공했다.\u003c/p\u003e\r\n  \u003cp\u003e돈과 기존 화폐가 무의미해진 시대였기 때문에 환자들은 기술자료, 유전자 표본, 노동력과 신체실험 참여권으로 치료비를 지불했다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스는 오염지역에서 생존할 수 있는 폐, 고온과 수분 부족을 견디는 피부, 독성물질을 분해하는 간과 손상된 신경을 대신하는 인터페이스를 개발했다.\u003c/p\u003e\r\n  \u003cp\u003e수많은 실험이 실패했다.\u003c/p\u003e\r\n  \u003cp\u003e일부 피험자는 인간의 형태를 유지하지 못했고, 면역계가 폭주하거나 신경계가 붕괴했다. 기업은 실패기록을 연구자료로 보존했고 살아남은 피험자의 유전자를 다음 세대의 시술에 활용했다.\u003c/p\u003e\r\n  \u003cp\u003e현재 모르포스가 보유한 적응형 생체기술의 상당수는 이 시기의 희생을 바탕으로 만들어졌다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 1~2세기 — 창립가문의 성립\u003c/h3\u003e\r\n  \u003cp\u003e국가와 연구기관이 사라지면서 고급 생명공학 기술은 극소수의 연구자 집단에 집중되었다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스의 주요 연구소를 이끌던 가문들은 핵심 기술과 배양종, 유전자 자료를 혈통과 제자관계를 통해 계승했다. 이들은 연구소의 통제권을 외부 투자자에게 넘기지 않기 위해 창립가문회의를 구성했다.\u003c/p\u003e\r\n  \u003cp\u003e각 가문은 서로 다른 생체기술을 전문으로 했다.\u003c/p\u003e\r\n  \u003cp\u003e어떤 가문은 유전자 교정과 수명연장을 연구했고, 다른 가문은 신경 인터페이스와 기억을 다루었다. 인공장기와 조직배양, 신체디자인이나 전투개조를 독점한 가문도 존재했다.\u003c/p\u003e\r\n  \u003cp\u003e가문들은 경쟁하면서도 기술의 외부유출을 막기 위해 협력했다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기부터 모르포스의 설계자는 단순한 기술자가 아니라 예술가이자 귀족처럼 대우받기 시작했다. 고객의 육체는 설계자의 명성과 철학을 드러내는 작품으로 취급되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 3세기 — 맞춤형 인간\u003c/h3\u003e\r\n  \u003cp\u003e생존환경이 안정되면서 모르포스의 사업은 생존개조에서 능력향상으로 변화했다.\u003c/p\u003e\r\n  \u003cp\u003e상류층은 더 이상 손상된 신체를 복원하는 것만으로 만족하지 않았다. 더 오래 살고, 더 아름답고, 더 강하며, 다른 사람보다 빠르게 사고하기를 원했다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스는 고객의 유전자와 신경패턴, 직업과 생활습관을 분석해 개인에게 최적화된 개조 패키지를 설계했다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기에 현대 모르포스의 대표적인 시술체계가 완성되었다.\u003c/p\u003e\r\n  \u003cp\u003e신체의 한 부분만 교체하는 것이 아니라 신경계와 장기, 골격과 호르몬을 하나의 통합시스템으로 조정하는 방식이었다. 시술 후에도 지속적인 유지관리와 약물, 소프트웨어 조정이 필요했다.\u003c/p\u003e\r\n  \u003cp\u003e고객은 강력한 육체를 얻었지만, 평생 모르포스의 관리에서 벗어나기 어려워졌다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 4세기 — 돔 시티의 육체\u003c/h3\u003e\r\n  \u003cp\u003e대형 돔 시티가 성장하면서 모르포스는 아르카디아와 협력해 도시환경에 적합한 생체관리 체계를 구축했다.\u003c/p\u003e\r\n  \u003cp\u003e폐쇄된 돔에서는 한정된 유전자 집단, 인공조명과 재순환 공기로 인해 새로운 질병과 생리문제가 발생했다. 모르포스는 시민의 유전질환을 관리하고, 환경에 맞춰 신체를 조정하는 예방시술을 제공했다.\u003c/p\u003e\r\n  \u003cp\u003e상류층은 노화억제, 외모설계와 감각개조를 적극적으로 받아들였다. 특정한 눈동자, 피부, 체형과 신경반응이 유행처럼 번졌다.\u003c/p\u003e\r\n  \u003cp\u003e신체는 더 이상 부모에게 물려받는 것이 아니었다.\u003c/p\u003e\r\n  \u003cp\u003e돈과 신분이 충분하다면 원하는 모습과 능력을 선택할 수 있는 시대가 시작되었다.\u003c/p\u003e\r\n  \u003cp\u003e이 과정에서 자연적으로 태어난 육체를 유지하는 것이 가난과 낮은 신분의 상징으로 여겨지는 문화도 나타났다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 5세기 — 신경혁명\u003c/h3\u003e\r\n  \u003cp\u003e모르포스는 뇌와 사이버웨어 사이의 신호손실을 줄이는 고성능 신경 인터페이스를 개발했다.\u003c/p\u003e\r\n  \u003cp\u003e이전까지 과도한 개조는 신경계에 극심한 부담을 주었다. 여러 개의 의체를 동시에 운용하면 감각혼선, 환각, 호르몬 폭주와 자아붕괴가 발생했다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스의 연구자들은 신경신호와 호르몬 분비를 실시간으로 조정하는 기술을 개발했다. 사용자는 더 많은 사이버웨어를 장착하고도 빠르게 사고하고 움직일 수 있게 되었다.\u003c/p\u003e\r\n  \u003cp\u003e일부 연구는 인간의 감각과 사고속도를 의도적으로 가속하는 방향으로 발전했다.\u003c/p\u003e\r\n  \u003cp\u003e쾌감과 통증, 공포와 집중력을 조절하고 엔도르핀을 강제로 분비해 전투와 노동효율을 높이는 시술도 등장했다. 이러한 기술은 군사와 유흥, 감각방송 산업에 빠르게 확산되었다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 신경가속은 심각한 중독과 열화증을 일으켰다.\u003c/p\u003e\r\n  \u003cp\u003e기술을 개발한 연구자 중 일부는 윤리문제와 기업의 통제에 반발해 모르포스를 떠났다. 그들이 가지고 나간 기술은 장막 도시의 리퍼닥과 범죄조직에 흘러들어 갔다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱의 일부 뇌살 기술 역시 모르포스의 신경연구에서 기원했다는 의혹이 있다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 6세기 — 칠정의 성립\u003c/h3\u003e\r\n  \u003cp\u003e초거대 기업들의 지배체계가 확립되면서 모르포스는 칠정의 핵심 구성원이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드가 물을 공급하고 솔라리스가 전력을 제공하며 아르카디아가 도시를 건설한다면, 그 환경에서 살아가고 일할 인간의 육체는 모르포스가 관리했다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스는 칠정 내에서 생명공학, 신체복원, 유전자 관리와 고급 인체개조를 담당한다. 기업간부와 특수요원들은 모르포스의 시술을 통해 수명을 연장하고 전투능력을 강화한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 모르포스는 케르베로스처럼 대량생산된 군용 의체를 판매하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 소수의 고객에게 압도적으로 뛰어난 신체를 제공한다. 한 명의 완성된 모르포스 시술자는 대량생산 병사 수십 명보다 비싼 자산이 된다.\u003c/p\u003e\r\n  \u003cp\u003e이러한 차이는 두 기업을 대표적인 경쟁관계로 만들었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e현재 — 멸망 후 700년\u003c/h3\u003e\r\n  \u003cp\u003e현재 모르포스 바이오다인은 세계 최고의 맞춤형 생명공학 기업이다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스는 질병과 장애를 치료하고, 손상된 장기를 복원하며, 인간의 수명을 연장할 수 있다. 충분한 비용을 지불한다면 외모와 성별, 감각, 신체능력과 노화속도까지 다시 설계할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 700년 동안 기업이 축적한 것은 의료기술만이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e수많은 도시와 가문, 환자와 실험체의 유전자 정보가 모르포스의 생체기록고에 보관되어 있다. 기업은 특정 혈통에서 발생할 질병과 신체적 특징, 사이버웨어 적합성까지 예측할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스의 최상위 설계자들은 인간이라는 종 자체를 하나의 미완성 작품으로 바라본다.\u003c/p\u003e\r\n  \u003cp\u003e그들의 목표는 질병을 치료하는 것이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e다음 단계의 인간을 만드는 것이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업 철학\u003c/h2\u003e\r\n  \u003ch3\u003e육체는 설계할 수 있다\u003c/h3\u003e\r\n  \u003cp\u003e모르포스는 선천적인 신체가 개인의 가능성을 결정해서는 안 된다고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e질병과 장애, 노화와 유전적 한계는 극복할 수 있는 기술적 문제다. 인간은 태어난 육체를 그대로 받아들이지 않고 자신의 목적에 맞게 선택할 수 있어야 한다.\u003c/p\u003e\r\n  \u003cp\u003e이 철학은 수많은 사람에게 새로운 삶을 제공했다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 모든 신체적 특징을 개선 대상으로 바라보는 극단적인 완벽주의를 낳았다.\u003c/p\u003e\r\n  \u003ch3\u003e조화가 성능보다 우선한다\u003c/h3\u003e\r\n  \u003cp\u003e모르포스는 단순히 강한 부품을 많이 이식하는 것을 저급한 개조라고 평가한다.\u003c/p\u003e\r\n  \u003cp\u003e신경계, 골격, 장기와 호르몬이 조화를 이루지 못하면 아무리 강력한 의체도 오래 사용할 수 없다. 따라서 모든 시술은 사용자의 몸 전체를 하나의 시스템으로 설계한다.\u003c/p\u003e\r\n  \u003ch3\u003e고객은 작품이다\u003c/h3\u003e\r\n  \u003cp\u003e최상위 고객에게는 전담 설계자가 배정된다.\u003c/p\u003e\r\n  \u003cp\u003e설계자는 고객의 외모와 기능, 생활방식과 장기적인 성장 방향을 관리한다. 뛰어난 고객은 설계자의 대표작이 되며, 설계자의 명예와 기업 내 지위에 영향을 준다.\u003c/p\u003e\r\n  \u003cp\u003e일부 설계자는 자신의 작품에 지나친 소유욕을 보이기도 한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e핵심 산업\u003c/h2\u003e\r\n  \u003ch3\u003e맞춤형 사이버웨어\u003c/h3\u003e\r\n  \u003cp\u003e모르포스의 대표 산업이다.\u003c/p\u003e\r\n  \u003cp\u003e고객의 골격, 근육, 신경계와 전투방식을 분석해 개인에게 최적화된 사이버웨어를 제작한다. 제품의 크기와 무게, 반응속도뿐 아니라 외형과 촉감까지 고객에게 맞춰진다.\u003c/p\u003e\r\n  \u003cp\u003e일반적인 표준형 의체보다 훨씬 비싸고 제작기간도 길다. 그러나 신체 적합성과 성능, 열화에 대한 안정성은 비교하기 어려울 정도로 뛰어나다.\u003c/p\u003e\r\n  \u003cp\u003e최상위 제품에는 공식적인 모델명이 없다.\u003c/p\u003e\r\n  \u003cp\u003e제작된 사람의 이름이나 설계자의 작품번호만이 남는다.\u003c/p\u003e\r\n  \u003ch3\u003e유전자 교정\u003c/h3\u003e\r\n  \u003cp\u003e선천성 질환, 면역결함과 대사문제를 치료한다. 고급시술은 근육성장, 감각기관, 수명과 환경적응 능력까지 조절할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e성인뿐 아니라 배아단계에서 적용하는 유전자 설계도 존재한다. 상류층 가문은 자녀가 태어나기 전부터 외모와 건강, 사이버웨어 적합성을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e공식적으로 지능과 성격을 결정하는 직접적인 유전자 설계는 금지되어 있다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 모르포스가 최고등급 고객에게 어떤 서비스를 제공하는지는 공개되지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e조직배양과 신체복원\u003c/h3\u003e\r\n  \u003cp\u003e환자의 세포를 이용해 피부, 근육, 혈관과 장기를 배양한다.\u003c/p\u003e\r\n  \u003cp\u003e이식 거부반응이 적고 자연스러운 신체를 복원할 수 있지만, 제작시간과 비용이 높다. 응급상황에서는 완성된 범용장기나 임시 인공장기가 사용된다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스는 절단된 사지와 손상된 얼굴도 높은 수준으로 복원할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e단순한 외형복원이 아니라 감각과 운동기능까지 원래 상태에 가깝게 되돌리는 것이 가능하다.\u003c/p\u003e\r\n  \u003ch3\u003e신경공학\u003c/h3\u003e\r\n  \u003cp\u003e뇌와 의체, 인공지능과 블루넷을 연결하는 인터페이스를 개발한다.\u003c/p\u003e\r\n  \u003cp\u003e신경신호의 손실을 줄이고 반응속도를 높이며, 복수의 사이버웨어를 하나의 신체처럼 운용할 수 있게 만든다.\u003c/p\u003e\r\n  \u003cp\u003e고급 인터페이스는 사용자의 감각과 사고속도, 통증과 호르몬까지 조절한다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스의 가장 큰 기술적 성과인 동시에 열화증과 인격변형 논란이 가장 많이 발생하는 분야다.\u003c/p\u003e\r\n  \u003ch3\u003e감각설계\u003c/h3\u003e\r\n  \u003cp\u003e시각과 청각, 촉각, 후각과 미각을 강화하거나 새롭게 구성한다.\u003c/p\u003e\r\n  \u003cp\u003e인간이 볼 수 없는 파장이나 들을 수 없는 주파수를 감지하게 만들 수 있으며, 통증을 다른 감각으로 변환하거나 디지털 신호를 직관적으로 인식하도록 만들 수도 있다.\u003c/p\u003e\r\n  \u003cp\u003e감각설계는 군사와 의료뿐 아니라 공연, 패션과 감각방송 산업에서도 사용된다.\u003c/p\u003e\r\n  \u003ch3\u003e수명연장\u003c/h3\u003e\r\n  \u003cp\u003e세포노화 억제, 장기교체와 유전자 복원을 결합해 인간의 건강수명을 연장한다.\u003c/p\u003e\r\n  \u003cp\u003e시술을 받는다고 영원히 살 수 있는 것은 아니다. 정기적인 조직교체와 유전자 안정화, 신경계 유지관리가 필요하다.\u003c/p\u003e\r\n  \u003cp\u003e상위 고객은 수백 년에 가까운 삶을 누릴 수 있다는 소문이 있지만 공식적인 최고 수명은 공개되지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e창립가문회의에 2102년 이전부터 살아온 인물이 존재한다는 의혹도 있다.\u003c/p\u003e\r\n  \u003ch3\u003e생체디자인과 미용개조\u003c/h3\u003e\r\n  \u003cp\u003e피부, 체형, 얼굴과 성별을 고객이 원하는 방향으로 변화시킨다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스의 미용개조는 단순한 성형이 아니다. 뼈와 근육, 호르몬과 유전적 발현을 조정해 자연스럽고 지속적인 변화를 만든다.\u003c/p\u003e\r\n  \u003cp\u003e돔 시티의 유행은 모르포스가 공개하는 새로운 신체디자인에 큰 영향을 받는다. 특정한 눈동자, 인공색소 피부, 발광문양과 비인간적인 신체특징이 상류층의 유행으로 확산되기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e전투개조\u003c/h3\u003e\r\n  \u003cp\u003e특수요원과 용병을 위한 고성능 신체개조다.\u003c/p\u003e\r\n  \u003cp\u003e근력과 반응속도, 감각과 신경전달을 강화하며, 장갑피부와 인공골격, 전투보조장기를 결합한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스가 규격화된 군용 사이버웨어를 대량생산한다면, 모르포스는 특정 인물을 하나의 전략병기로 완성한다.\u003c/p\u003e\r\n  \u003cp\u003e전투개조 고객은 시술 이후에도 전담 설계자의 지속적인 관리를 받아야 한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e시술 등급\u003c/h2\u003e\r\n  \u003ch3\u003eStandard\u003c/h3\u003e\r\n  \u003cp\u003e일반 시민과 계약직을 위한 표준 시술이다.\u003c/p\u003e\r\n  \u003cp\u003e기초적인 장기교체, 신체복원과 보급형 신경 인터페이스가 포함된다. 모르포스의 이름을 사용하지만 상당수 부품은 외부기업이 생산한다.\u003c/p\u003e\r\n  \u003ch3\u003eAdvanced\u003c/h3\u003e\r\n  \u003cp\u003e기업인, 전문직과 용병을 위한 고급 시술이다.\u003c/p\u003e\r\n  \u003cp\u003e개인의 신체와 직업에 맞춰 조정되며 높은 성능과 안정성을 제공한다. 정기적인 공식 점검이 필요하다.\u003c/p\u003e\r\n  \u003ch3\u003eElite\u003c/h3\u003e\r\n  \u003cp\u003e상류층과 기업간부, 특수요원을 위한 최고급 맞춤 시술이다.\u003c/p\u003e\r\n  \u003cp\u003e전담 설계자가 신체 전체를 통합적으로 관리한다. 모든 부품과 생체조직은 고객 한 사람을 위해 제작된다.\u003c/p\u003e\r\n  \u003ch3\u003eBespoke\u003c/h3\u003e\r\n  \u003cp\u003e공식적인 상품목록에 존재하지 않는 개인 작품급 시술이다.\u003c/p\u003e\r\n  \u003cp\u003e기업 최고위층, 창립가문과 극소수의 승인된 고객만 접근할 수 있다. 기존 인간의 한계를 넘어서는 실험적인 기술이 적용된다.\u003c/p\u003e\r\n  \u003cp\u003e이 등급의 시술자는 고객이 아니라 모르포스의 자산으로 취급된다는 소문이 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업 구조\u003c/h2\u003e\r\n  \u003cp\u003e모르포스는 일반적인 주식회사보다 연구귀족과 맞춤 공방이 결합된 구조를 가지고 있다.\u003c/p\u003e\r\n  \u003ch3\u003e창립가문회의\u003c/h3\u003e\r\n  \u003cp\u003e모르포스의 최고 의사결정기관이다.\u003c/p\u003e\r\n  \u003cp\u003e각 창립가문은 특정 생체기술과 유전자 특허, 연구소를 소유한다. 기업의 주요 정책과 후계자, 금지기술의 사용 여부를 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e외부 투자자는 막대한 지분을 보유할 수 있지만 창립가문회의의 핵심 의결권에는 접근하기 어렵다.\u003c/p\u003e\r\n  \u003ch3\u003e수석설계자\u003c/h3\u003e\r\n  \u003cp\u003e모르포스의 최고경영자이자 모든 설계자의 정점이다.\u003c/p\u003e\r\n  \u003cp\u003e경영능력뿐 아니라 생체공학과 신체설계 분야에서 압도적인 성과를 증명해야 한다. 수석설계자의 대표작은 기업 전체의 기술적 방향을 결정한다.\u003c/p\u003e\r\n  \u003ch3\u003e생체설계총괄\u003c/h3\u003e\r\n  \u003cp\u003e연구, 시술, 고객관리와 전투개조 사업을 통합적으로 관리한다. 대형 프로젝트의 설계자를 지정하고 연구자원을 배분한다.\u003c/p\u003e\r\n  \u003ch3\u003e제1설계국 — 육체·유전\u003c/h3\u003e\r\n  \u003cp\u003e생체설계, 유전자 교정과 조직배양을 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e신체의 기초가 되는 세포와 골격, 근육, 장기와 면역계를 다룬다.\u003c/p\u003e\r\n  \u003ch3\u003e제2설계국 — 신경·의체\u003c/h3\u003e\r\n  \u003cp\u003e신경공학, 맞춤형 사이버웨어와 고객관리를 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e사용자의 뇌와 기계장치를 연결하고 개조된 신체가 하나의 시스템처럼 작동하도록 조정한다.\u003c/p\u003e\r\n  \u003ch3\u003e제3설계국 — 병기·작전\u003c/h3\u003e\r\n  \u003cp\u003e전투개조, 회수처리와 메타모프 운용을 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스의 기술을 군사적으로 활용하고 기업기밀과 고위험 시술자를 관리한다.\u003c/p\u003e\r\n  \u003ch3\u003e수석설계자 직속실\u003c/h3\u003e\r\n  \u003cp\u003e창립가문회의와 수석설계자가 직접 통제하는 비밀조직이다.\u003c/p\u003e\r\n  \u003cp\u003e최고등급 고객, 금지기술과 장기적인 인류개량 계획을 관리하는 것으로 알려져 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 기술\u003c/h2\u003e\r\n  \u003ch3\u003e크리살리스 배양조\u003c/h3\u003e\r\n  \u003cp\u003e환자의 세포를 이용해 장기와 신체조직을 빠르게 배양하는 장치다.\u003c/p\u003e\r\n  \u003cp\u003e고급 배양조는 환자의 몸 전체를 수용하고 세포 손상과 유전자 불안정을 동시에 복구할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e바이오다인 신경직조\u003c/h3\u003e\r\n  \u003cp\u003e신경세포와 인공전도체를 결합해 생체신경과 사이버웨어를 자연스럽게 연결한다.\u003c/p\u003e\r\n  \u003cp\u003e기존 인터페이스보다 신호지연과 통증이 적으며 장기간 사용해도 신경손상이 적다.\u003c/p\u003e\r\n  \u003ch3\u003e미러플레시\u003c/h3\u003e\r\n  \u003cp\u003e손상된 얼굴과 신체외형을 정밀하게 복원하거나 완전히 새롭게 설계하는 기술이다.\u003c/p\u003e\r\n  \u003cp\u003e표정과 촉감, 노화방식까지 조정할 수 있어 유명인과 상류층에게 인기가 높다.\u003c/p\u003e\r\n  \u003ch3\u003e적응형 장기군\u003c/h3\u003e\r\n  \u003cp\u003e고온, 저산소, 독성물질과 방사선 환경에 맞춰 기능이 변화하는 인공장기다.\u003c/p\u003e\r\n  \u003cp\u003e황무지 탐사자와 궤도근무자, 특수요원에게 사용된다.\u003c/p\u003e\r\n  \u003ch3\u003e마인드 앵커\u003c/h3\u003e\r\n  \u003cp\u003e과도한 신경가속과 감각개조로 발생하는 자아혼선을 억제하는 장치다.\u003c/p\u003e\r\n  \u003cp\u003e사용자의 기억과 인격패턴을 기준점으로 저장해 정신적 붕괴를 늦춘다.\u003c/p\u003e\r\n  \u003cp\u003e완전히 붕괴한 인격을 복구할 수 있는지는 알려지지 않았다.\u003c/p\u003e\r\n  \u003ch3\u003e리빙 프레임\u003c/h3\u003e\r\n  \u003cp\u003e금속골격과 배양골격을 결합한 생체형 내부 프레임이다.\u003c/p\u003e\r\n  \u003cp\u003e사용자의 성장과 손상에 맞춰 천천히 형태를 조정하며 일반적인 기계골격보다 자연스럽게 움직인다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 시설\u003c/h2\u003e\r\n  \u003ch3\u003e팔라티움\u003c/h3\u003e\r\n  \u003cp\u003e모르포스의 본사와 창립가문회의가 위치한 생체연구도시다.\u003c/p\u003e\r\n  \u003cp\u003e백색 구조물과 수직정원, 배양탑이 결합된 도시로 외부에서는 병원과 궁전, 거대한 생명체의 내부를 섞어놓은 모습처럼 보인다고 한다.\u003c/p\u003e\r\n  \u003ch3\u003e아틀리에\u003c/h3\u003e\r\n  \u003cp\u003e최상위 고객을 위한 맞춤형 시술시설이다.\u003c/p\u003e\r\n  \u003cp\u003e각 아틀리에는 한 명의 수석급 설계자가 운영하며 예약과 비용만으로 접근할 수 없다. 설계자가 고객을 작품으로 받아들여야 시술이 시작된다.\u003c/p\u003e\r\n  \u003ch3\u003e제네시스 볼트\u003c/h3\u003e\r\n  \u003cp\u003e700년 동안 수집한 인간과 변이생물의 유전자 자료를 보관하는 시설이다.\u003c/p\u003e\r\n  \u003cp\u003e수많은 혈통의 유전자와 질병정보, 개조기록이 저장되어 있으며 기업이 보유한 가장 중요한 자산 중 하나다.\u003c/p\u003e\r\n  \u003ch3\u003e나비정원\u003c/h3\u003e\r\n  \u003cp\u003e유전자 개조를 받은 동식물과 실험 생명체를 관리하는 폐쇄형 생태시설이다.\u003c/p\u003e\r\n  \u003cp\u003e공식적으로는 생태복원과 신약개발을 위한 연구소지만, 외부에 공개되지 않은 생명체가 존재한다는 소문이 있다.\u003c/p\u003e\r\n  \u003ch3\u003e화이트 룸\u003c/h3\u003e\r\n  \u003cp\u003e회수처리실이 사용하는 비공개 시설의 통칭이다.\u003c/p\u003e\r\n  \u003cp\u003e불법으로 유출된 모르포스 기술, 실패한 실험체와 계약을 위반한 고위험 고객이 이곳으로 이송된다는 소문이 있다.\u003c/p\u003e\r\n  \u003cp\u003e정확한 위치는 공개되지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e메타모프\u003c/h2\u003e\r\n  \u003cp\u003e메타모프는 모르포스의 정예 무장조직이자 전투개조 기술의 완성품이다.\u003c/p\u003e\r\n  \u003cp\u003e일반적인 기업군과 달리 모든 대원이 서로 다른 형태와 기능을 가진다. 임무, 성격과 전투방식에 맞춰 신체 전체가 개별적으로 설계되기 때문이다.\u003c/p\u003e\r\n  \u003cp\u003e메타모프의 주요 임무는 다음과 같다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e기업 연구시설 방어\u003c/li\u003e\r\n    \u003cli\u003e중요 설계자와 고객 호위\u003c/li\u003e\r\n    \u003cli\u003e유출된 생체기술 회수\u003c/li\u003e\r\n    \u003cli\u003e실패한 실험체 제압\u003c/li\u003e\r\n    \u003cli\u003e변이생물 포획\u003c/li\u003e\r\n    \u003cli\u003e배신한 연구자 추적\u003c/li\u003e\r\n    \u003cli\u003e경쟁기업의 생명공학 시설 공작\u003c/li\u003e\r\n    \u003cli\u003e최고등급 시술자의 강제회수\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e메타모프 대원은 직원이자 기업의 작품으로 취급된다.\u003c/p\u003e\r\n  \u003cp\u003e시술과 유지비용을 기업이 부담하는 대신 신체에 대한 소유권과 해체 권한이 모르포스에 있다는 의혹이 존재한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e직원 문화\u003c/h2\u003e\r\n  \u003cp\u003e모르포스 내부에서는 연구와 시술을 예술로 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e최상위 연구자는 박사나 의사보다 ‘설계자’라는 호칭을 선호한다. 뛰어난 신체를 만들어낸 설계자는 유명 예술가처럼 존경받으며 자신의 미학과 설계철학을 중심으로 학파를 형성한다.\u003c/p\u003e\r\n  \u003cp\u003e기업 내부의 경쟁은 매우 치열하다.\u003c/p\u003e\r\n  \u003cp\u003e설계자들은 기술적 성과뿐 아니라 얼마나 유명하고 강력한 고객을 보유했는지로 평가받는다. 다른 설계자의 작품을 수정하는 것은 결례로 취급되며, 시술실패는 설계자의 경력에 치명적인 오점이 된다.\u003c/p\u003e\r\n  \u003cp\u003e연구원과 배양기술자는 높은 급여와 우수한 의료서비스를 받는다. 그러나 자신의 유전자와 신체자료를 기업 연구에 제공해야 하며, 일부 직원은 신기술의 초기 피험자가 된다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스 내부에서 자주 사용되는 문구는 다음과 같다.\u003c/p\u003e\r\n  \u003cblockquote\u003e완성된 육체는 없다. 설계를 멈춘 육체만 있을 뿐이다.\u003c/blockquote\u003e\r\n\r\n  \u003ch2\u003e채용과 복지\u003c/h2\u003e\r\n  \u003cp\u003e모르포스는 생명공학자, 의사, 유전학자, 신경과학자, 사이버웨어 기술자와 신체디자이너를 채용한다.\u003c/p\u003e\r\n  \u003cp\u003e기술만큼 미적 감각과 창의성을 중요하게 평가한다. 최고등급 설계자는 의학과 공학, 예술과 심리학을 동시에 이해해야 한다.\u003c/p\u003e\r\n  \u003cp\u003e정규직 직원과 가족에게는 다음과 같은 혜택이 제공된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e정기적인 유전자 검사\u003c/li\u003e\r\n    \u003cli\u003e질병과 신체결함의 우선치료\u003c/li\u003e\r\n    \u003cli\u003e고급 인공장기 제공\u003c/li\u003e\r\n    \u003cli\u003e노화억제 프로그램\u003c/li\u003e\r\n    \u003cli\u003e직원용 사이버웨어 할인\u003c/li\u003e\r\n    \u003cli\u003e자녀의 선천성 질환 교정\u003c/li\u003e\r\n    \u003cli\u003e사망 시 신체 및 기억자료 보존\u003c/li\u003e\r\n    \u003cli\u003e우수 연구자의 장기 생명연장\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e그러나 모르포스를 떠날 경우 회사에서 제공받은 일부 생체기술과 소프트웨어의 사용권이 제한될 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e퇴직 후 의체의 유지관리와 억제제를 감당하지 못해 다시 기업과 계약하는 사람도 많다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e계층별 인식\u003c/h2\u003e\r\n  \u003ch3\u003e돔 시티 상류층\u003c/h3\u003e\r\n  \u003cp\u003e모르포스를 가장 세련되고 권위 있는 기업으로 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e누가 자신의 몸을 설계했는지, 어떤 등급의 장기와 인터페이스를 사용하는지가 사회적 지위를 나타낸다. 유명 설계자의 시술을 받기 위해 수년을 기다리는 사람도 있다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 시티 일반 시민\u003c/h3\u003e\r\n  \u003cp\u003e질병과 장애를 치료해주는 희망의 기업인 동시에 접근하기 어려운 특권층의 회사로 본다.\u003c/p\u003e\r\n  \u003cp\u003e보급형 의료서비스도 제공하지만 대중이 동경하는 최상위 기술은 극소수에게만 허락된다.\u003c/p\u003e\r\n  \u003ch3\u003e장막 도시 주민\u003c/h3\u003e\r\n  \u003cp\u003e모르포스의 폐기부품과 구형 사이버웨어는 암시장에서 높은 가격에 거래된다.\u003c/p\u003e\r\n  \u003cp\u003e공식 시술소에 접근하기 어려운 사람들은 불법 리퍼닥을 통해 모르포스 부품을 이식한다. 부품의 진위나 신체적합성을 확인할 수 없어 심각한 부작용이 발생한다.\u003c/p\u003e\r\n  \u003ch3\u003e황무지인\u003c/h3\u003e\r\n  \u003cp\u003e극한환경에 적응하기 위해 모르포스 기술을 필요로 하지만 기업의 유지계약과 추적코드를 불신한다.\u003c/p\u003e\r\n  \u003cp\u003e일부 황무지 부족은 생체개조를 받아들이지만, 다른 집단은 인간을 기업의 제품으로 만드는 기술이라며 금기시한다.\u003c/p\u003e\r\n  \u003ch3\u003e다른 기업\u003c/h3\u003e\r\n  \u003cp\u003e모르포스의 기술을 필요로 하면서도 최고위층의 유전자와 신체정보가 기업에 축적되는 것을 경계한다.\u003c/p\u003e\r\n  \u003cp\u003e칠정의 주요 간부 대부분이 모르포스의 의료서비스를 이용하기 때문에 기업은 다른 세력의 가장 은밀한 약점까지 알고 있을 가능성이 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e다른 세력과의 관계\u003c/h2\u003e\r\n  \u003ch3\u003eNEREID HYDROSYSTEMS\u003c/h3\u003e\r\n  \u003cp\u003e모르포스는 의료용수와 배양액 생산에 네레이드의 고순도 정제수를 사용한다. 네레이드는 모르포스의 생체막과 미생물 기술을 정수시설에 적용한다.\u003c/p\u003e\r\n  \u003cp\u003e일부 정수용 생체막이 인간 유래 조직으로 만들어졌다는 의혹이 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003eSOLARIS ORBITAL INDUSTRIES\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스의 궤도근무자들은 방사선과 저중력에 적응하기 위해 모르포스의 시술을 받는다.\u003c/p\u003e\r\n  \u003cp\u003e양사는 장기 우주생활에 적합한 새로운 인간형을 공동 연구한다. 해당 프로젝트의 최종 목표는 공개되지 않았다.\u003c/p\u003e\r\n  \u003ch3\u003eARCADIA HABITAT\u003c/h3\u003e\r\n  \u003cp\u003e모르포스는 돔 시티의 병원과 유전자 관리체계에 핵심 기술을 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아의 시민기록과 모르포스의 생체정보가 결합되면 개인의 질병과 수명, 행동성향까지 예측할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003eCERBERUS DEFENSE GROUP\u003c/h3\u003e\r\n  \u003cp\u003e가장 대표적인 경쟁관계다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 저렴하고 강력한 규격형 군용 사이버웨어를 대량생산한다. 모르포스는 비싸지만 사용자의 신체에 완전히 맞춰진 최고급 개조를 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e양사는 서로의 기술자를 영입하고 특허를 탈취하며 군사계약을 놓고 경쟁한다.\u003c/p\u003e\r\n  \u003ch3\u003eCHARON INTERCONTINENTAL\u003c/h3\u003e\r\n  \u003cp\u003e카론은 배양장기, 약품과 민감한 생체물질을 운송한다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스의 화물은 온도와 진동, 시간에 민감하기 때문에 전용 수송차량과 보안계약이 사용된다.\u003c/p\u003e\r\n  \u003ch3\u003eARGOS SECURE NETWORKS\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 불법 생체실험, 신분위조와 기술유출을 감시한다. 모르포스는 신원확인에 필요한 유전자 자료를 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e양사는 협력관계지만 서로가 보유한 개인정보와 비밀연구를 노리는 위험한 경쟁자이기도 하다.\u003c/p\u003e\r\n  \u003ch3\u003eLAZARUS MEDICAL RESPONSE\u003c/h3\u003e\r\n  \u003cp\u003e라자루스는 현장에서 환자를 회수하고 생명을 유지한다. 모르포스는 이후의 장기복원과 고급 재건수술을 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e고액회원에게는 라자루스가 환자를 모르포스 전용병원으로 직접 이송하는 계약이 제공된다.\u003c/p\u003e\r\n  \u003ch3\u003eVELVET STATIC\u003c/h3\u003e\r\n  \u003cp\u003e공식적으로 모르포스는 벨벳 스태틱과 관계가 없다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 벨벳 스태틱의 감각편집, 기억자극과 뇌살 시술에는 모르포스의 구형 신경기술이 사용된다. 모르포스에서 이탈한 연구자들이 조직에 합류했다는 기록도 존재한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e사회공헌과 홍보\u003c/h2\u003e\r\n  \u003cp\u003e모르포스는 자신들을 “인간의 가능성을 확장하는 기업”으로 소개한다.\u003c/p\u003e\r\n  \u003cp\u003e선천성 장애아동의 무료수술, 오염지역 주민을 위한 장기치료와 전쟁피해자의 신체복원 사업을 운영한다. 대형 재난이 발생하면 이동식 배양실과 의료진을 파견한다.\u003c/p\u003e\r\n  \u003cp\u003e또한 예술가, 배우와 아이돌을 후원해 새로운 신체디자인과 감각기술을 대중에게 선보인다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스가 후원하는 인물은 기업의 기술력을 보여주는 살아 있는 광고가 된다. 외모와 무대연출, 목소리와 감각경험까지 기업의 설계 아래 만들어지는 경우도 있다.\u003c/p\u003e\r\n  \u003cp\u003e비판자들은 모르포스가 환자의 치료보다 완성된 결과물을 홍보에 이용하는 데 더 관심이 많다고 주장한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e논란과 비판\u003c/h2\u003e\r\n  \u003ch3\u003e생명의 상품화\u003c/h3\u003e\r\n  \u003cp\u003e모르포스는 신체와 수명, 외모와 유전적 가능성을 가격에 따라 판매한다.\u003c/p\u003e\r\n  \u003cp\u003e부유한 사람은 수백 년에 가까운 건강과 아름다움을 누리는 반면, 가난한 사람은 기본적인 장기조차 구하지 못한다.\u003c/p\u003e\r\n  \u003ch3\u003e불법 인체실험\u003c/h3\u003e\r\n  \u003cp\u003e멸망력 초기의 혼란 속에서 모르포스가 생존자를 대상으로 대규모 실험을 시행했다는 기록이 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 당시의 시술이 생명을 구하기 위한 불가피한 선택이었다고 주장한다.\u003c/p\u003e\r\n  \u003ch3\u003e유전자 차별\u003c/h3\u003e\r\n  \u003cp\u003e기업과 돔 시티가 채용과 시민권 평가에 유전자 정보를 사용한다는 의혹이 있다.\u003c/p\u003e\r\n  \u003cp\u003e특정 질병과 신체적 특성을 가진 사람이 태어나기도 전에 낮은 등급으로 분류될 가능성이 제기된다.\u003c/p\u003e\r\n  \u003ch3\u003e유지계약 종속\u003c/h3\u003e\r\n  \u003cp\u003e고급 사이버웨어와 생체장기는 지속적인 조정과 전용약물을 필요로 한다.\u003c/p\u003e\r\n  \u003cp\u003e기업과의 계약이 종료되면 장비의 기능이 제한되거나 원격으로 정지할 수 있다는 주장이 있다.\u003c/p\u003e\r\n  \u003ch3\u003e기억과 인격의 개조\u003c/h3\u003e\r\n  \u003cp\u003e모르포스는 기억을 직접 판매하거나 편집하지 않는다고 발표한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 신경 인터페이스와 호르몬 제어를 이용하면 사람의 감정과 성격, 판단에 영향을 줄 수 있다. 치료와 세뇌의 경계가 어디인지 명확하지 않다.\u003c/p\u003e\r\n  \u003ch3\u003e전투개조자의 소유권\u003c/h3\u003e\r\n  \u003cp\u003e메타모프와 일부 계약요원은 자신의 신체에 대한 완전한 권리를 보유하지 못한다는 의혹이 있다.\u003c/p\u003e\r\n  \u003cp\u003e기업이 시술비용과 유지비를 이유로 개조된 장기와 의체를 자산으로 등록한다는 것이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e확인되지 않은 소문\u003c/h2\u003e\r\n  \u003cp\u003e모르포스의 창립가문회의에는 2102년 백야 이전부터 살아온 인물이 존재한다는 소문이 있다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 정기적으로 신체를 교체하고 기억을 새로운 뇌조직에 이식해 700년 동안 기업을 지배해 왔다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e또 다른 소문에 따르면 제네시스 볼트에는 인류의 유전자뿐 아니라 백야 이후 등장한 변이생물과 정체불명의 인간형 생명체의 자료도 보관되어 있다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스가 개발하는 일부 생체기관은 인간 유전자로만 만들어진 것이 아니라는 주장도 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e가장 위험한 소문은 ‘프로젝트 아담’에 관한 것이다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스가 질병과 노화, 열화증과 환경적 한계를 완전히 극복한 새로운 인간종을 개발하고 있으며, 창립가문과 최고등급 고객을 그 종으로 대체하려 한다는 이야기다.\u003c/p\u003e\r\n  \u003cp\u003e완성된 개체가 이미 존재한다는 말도 있다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 자연적으로 태어난 인간과 완전히 같은 모습을 하고 있지만, 신체의 모든 세포에 기업의 소유권을 증명하는 유전정보가 새겨져 있다고 한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업이 가진 힘\u003c/h2\u003e\r\n  \u003cp\u003e모르포스의 힘은 인간이 자신의 육체를 사랑하면서도 끊임없이 불만을 느낀다는 사실에서 나온다.\u003c/p\u003e\r\n  \u003cp\u003e사람은 병들지 않기를 원한다. 늙지 않기를 원하고, 잃어버린 신체를 되찾기를 원한다. 더 강하고 아름다우며 특별한 존재가 되기를 바란다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스는 그 모든 욕망에 가격을 붙였다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 사람을 죽이지 않고도 인생을 바꿀 수 있다. 팔과 다리, 얼굴과 목소리, 감각과 수명까지 다시 만들어낸다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 모르포스가 만든 신체는 모르포스의 관리 없이는 완전하게 유지되기 어렵다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드가 물을 통해 인간의 생존을 지배하고, 아르카디아가 인간이 살아가는 도시를 지배한다면, 모르포스는 인간이 세상을 경험하는 육체 그 자체에 손을 뻗는다.\u003c/p\u003e\r\n  \u003cp\u003e그리고 인간이 지금의 자신보다 나아지고 싶어 하는 한, 모르포스의 고객은 사라지지 않을 것이다.\u003c/p\u003e\r\n\u003c/section\u003e\r\n";
window.FACTION_INFO.cerberus = "\u003csection class=\"faction-detail\"\u003e\r\n  \u003ch2\u003e기업 개요\u003c/h2\u003e\r\n  \u003cp class=\"faction-quote\"\u003e“평화는 준비된 화력 위에서만 유지된다.”\u003c/p\u003e\r\n  \u003cp\u003e케르베로스 디펜스 그룹은 총기, 탄약, 전투차량, 군용 사이버웨어와 무인병기를 생산하는 초거대 군산복합기업이다. 2102년 백야로 국가의 군대와 방위산업이 붕괴한 이후, 살아남은 군수기업과 병기창, 군부대와 기술자 집단을 흡수하며 성장했다.\u003c/p\u003e\r\n  \u003cp\u003e오늘날 케르베로스는 개인용 권총부터 장갑열차, 전투드론, 요격체계와 대규모 도시방어망에 이르기까지 거의 모든 종류의 무기를 생산한다. 돔 시티의 성벽과 기업시설, 카라반과 용병, DCS와 이클립스 역시 케르베로스의 장비를 사용한다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스가 단 한 사람을 위한 완벽한 신체를 설계한다면, 케르베로스는 동일한 성능의 병사와 무기를 수천 단위로 공급한다. 그들이 추구하는 것은 아름다운 작품이나 인간의 진화가 아니다.\u003c/p\u003e\r\n  \u003cp\u003e싸우는 사람이 누구든 같은 탄약과 같은 부품을 사용할 수 있고, 한 명이 쓰러지더라도 다음 사람이 즉시 그 자리를 대신할 수 있는 전쟁체계다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 무기를 판매하는 회사가 아니다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 전쟁을 지속할 수 있는 모든 조건을 판매한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기본 정보\u003c/h2\u003e\r\n  \u003ctable class=\"data-table faction-info-table\"\u003e\r\n    \u003ctbody\u003e\r\n      \u003ctr\u003e\u003cth\u003e정식 명칭\u003c/th\u003e\u003ctd\u003eCERBERUS DEFENSE GROUP\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e통칭\u003c/th\u003e\u003ctd\u003e케르베로스\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e기업 분류\u003c/th\u003e\u003ctd\u003e군수·무기·방위산업 기업\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 산업\u003c/th\u003e\u003ctd\u003e화기, 탄약, 전투차량, 장갑, 군용 사이버웨어\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e전략 산업\u003c/th\u003e\u003ctd\u003e전투드론, 도시방어망, 무인병기, 용병 파견\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 고객\u003c/th\u003e\u003ctd\u003e칠정 기업, 돔 시티, DCS, 이클립스, 용병단\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e상징 색상\u003c/th\u003e\u003ctd\u003e적색, 흑색, 강철색\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표적인 인식\u003c/th\u003e\u003ctd\u003e전쟁이 끝나지 않기를 바라는 거대한 병기창\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e칠정 내 역할\u003c/th\u003e\u003ctd\u003e무기생산, 시설방위와 대규모 군사력 제공\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e본사 성격\u003c/th\u003e\u003ctd\u003e군수도시, 병기공장과 군사령부가 결합된 요새\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 체계\u003c/th\u003e\u003ctd\u003e트라이던트 전력체계\u003c/td\u003e\u003c/tr\u003e\r\n    \u003c/tbody\u003e\r\n  \u003c/table\u003e\r\n\r\n  \u003ch2\u003e기업의 역사\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e백야 이전 — 통합방위산업체\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스의 전신은 21세기 후반에 활동하던 여러 방위산업체, 민간군사기업, 군용 인공지능 연구소와 국가 병기창이었다.\u003c/p\u003e\r\n  \u003cp\u003e당시의 전쟁은 인간 병력보다 드론, 위성, 자동방어체계와 정밀유도무기에 크게 의존하고 있었다. 무기는 점차 네트워크에 연결되었으며, 병사 한 명이 수십 기의 무인장비와 포격체계를 지휘할 수 있게 되었다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스의 전신 기업들은 총기와 차량을 생산하는 데 그치지 않고 전투에 필요한 정보, 보급, 정비와 지휘체계까지 하나의 상품으로 제공했다.\u003c/p\u003e\r\n  \u003cp\u003e국가가 장비를 구매하면 케르베로스의 기술자와 군사고문, 보급망과 소프트웨어가 함께 배치되었다. 그 결과 일부 군대는 자국 정부보다 군수기업의 지원체계에 더 깊이 의존하게 되었다.\u003c/p\u003e\r\n  \u003cp\u003e21세기 말, 세계 각지의 분쟁이 증가하면서 전신 기업들은 거대한 방위산업 연합으로 통합되었다. 이 연합이 현재 케르베로스 디펜스 그룹의 기반이 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e2102년 — 백야\u003c/h3\u003e\r\n  \u003cp\u003e백야가 발생한 순간, 세계의 자동화된 군사체계 역시 통제불능 상태에 빠졌다.\u003c/p\u003e\r\n  \u003cp\u003e위성항법과 장거리 통신이 붕괴했고, 서로 다른 국가의 방공망과 무인병기가 잘못된 표적정보를 수신했다. 일부 자동방어체계는 아군과 민간인을 적으로 인식했으며, 통제권을 잃은 드론과 미사일이 도시를 공격했다.\u003c/p\u003e\r\n  \u003cp\u003e국가 지휘부가 사라진 뒤에도 군사 인공지능은 마지막 명령을 반복했다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스의 전신 기업들은 생산시설을 봉쇄하고 네트워크에서 장비를 분리했다. 자동화된 최신병기보다 독립적으로 작동하는 구형 화기와 차량이 더 신뢰할 수 있다는 사실이 드러났다.\u003c/p\u003e\r\n  \u003cp\u003e살아남은 군인, 기술자와 노동자들은 기업의 병기창으로 모였다. 그곳에는 발전기, 식량, 장갑차와 방어시설이 있었다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 자신들의 공장을 지키기 위해 무장했다.\u003c/p\u003e\r\n  \u003cp\u003e얼마 지나지 않아 공장 밖의 정착지들도 케르베로스의 보호를 요청하기 시작했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망력 초기 — 병기창의 도시\u003c/h3\u003e\r\n  \u003cp\u003e백야 이후 수십 년 동안 케르베로스의 주요 생산시설은 요새화된 생존도시로 변했다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 주민들에게 식량과 거주지를 제공하는 대신 공장에서 무기와 탄약을 생산하게 했다. 군인들은 시설을 방어했고 기술자들은 파괴된 장비를 수리했다.\u003c/p\u003e\r\n  \u003cp\u003e당시 황무지에는 약탈자, 군벌과 통제불능 무인병기가 넘쳐났다. 살아남기 위해서는 무기가 필요했고 무기를 계속 사용하기 위해서는 탄약과 부품, 정비기술이 필요했다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 모든 것을 가지고 있었다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 주변 정착지에 무기를 제공하고 그 대가로 원료, 노동력과 군사적 충성을 요구했다. 정식 화폐가 사라진 지역에서는 소총 한 자루와 탄약 상자가 토지나 식량보다 안정적인 거래수단으로 사용되었다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기에 케르베로스는 단순한 무기회사를 넘어 하나의 군사국가로 성장했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 1세기 — 규격전쟁\u003c/h3\u003e\r\n  \u003cp\u003e백야 이전에 생산된 무기는 종류와 규격이 지나치게 다양했다.\u003c/p\u003e\r\n  \u003cp\u003e탄약과 부품을 구할 수 없는 무기는 아무리 강력해도 오래 사용할 수 없었다. 각 정착지와 군벌이 서로 다른 장비를 사용하는 탓에 보급과 수리가 불가능한 경우도 많았다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 이를 해결하기 위해 대대적인 무기규격 통합을 시행했다.\u003c/p\u003e\r\n  \u003cp\u003e구경, 탄창, 전력셀, 장갑부품과 통신규격을 단순화하고, 황무지의 열기와 먼지 속에서도 사용할 수 있는 견고한 무기를 개발했다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스의 무기는 가장 정교하지는 않았지만 어디서든 작동했고, 수리가 쉬웠으며, 부품을 구하기도 쉬웠다.\u003c/p\u003e\r\n  \u003cp\u003e무기규격이 널리 퍼지면서 케르베로스는 자연스럽게 탄약과 부품시장을 장악했다. 경쟁기업의 무기를 사용하는 군대조차 케르베로스 규격의 탄약과 전력셀을 구매해야 했다.\u003c/p\u003e\r\n  \u003cp\u003e이후 케르베로스의 규격은 사실상 세계의 군사표준이 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 2세기 — 계약전쟁\u003c/h3\u003e\r\n  \u003cp\u003e도시와 군벌의 전쟁이 증가하면서 케르베로스는 장비판매를 넘어 군사계약 사업에 진출했다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 무기와 차량뿐 아니라 훈련교관, 정비인력과 전투부대를 함께 제공했다. 고객은 자체적인 군대를 처음부터 육성하지 않고도 케르베로스의 계약을 통해 완성된 전력을 확보할 수 있었다.\u003c/p\u003e\r\n  \u003cp\u003e이 과정에서 케르베로스가 양쪽 세력에 동시에 무기를 판매한 사례도 다수 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 정식 계약이 충돌하지 않는 한 모든 고객을 동등하게 대한다고 주장했다. 하지만 전쟁이 장기화될수록 양측 모두 더 많은 탄약과 부품을 구매해야 했다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스가 분쟁을 의도적으로 연장하고 있다는 의혹은 이 시기부터 시작되었다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 전쟁을 일으키지 않는다고 주장했다.\u003c/p\u003e\r\n  \u003cp\u003e다만 전쟁이 시작된 뒤 가장 오래 살아남는 방법을 판매할 뿐이라고 말했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 3세기 — 트라이던트의 탄생\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 급격히 확장된 군사조직을 세 개의 전문 전력으로 재편했다.\u003c/p\u003e\r\n  \u003cp\u003e이 체계는 삼지창을 의미하는 \u003cstrong\u003e트라이던트\u003c/strong\u003e라고 명명되었다.\u003c/p\u003e\r\n  \u003cp\u003e첫 번째 날인 \u003cstrong\u003e팽\u003c/strong\u003e은 직접적인 공격과 전장투입을 담당했다.\u003c/p\u003e\r\n  \u003cp\u003e두 번째 날인 \u003cstrong\u003e앤빌\u003c/strong\u003e은 생산, 요새화와 중장비 운용을 담당했다.\u003c/p\u003e\r\n  \u003cp\u003e세 번째 날인 \u003cstrong\u003e워치독\u003c/strong\u003e은 시설경비, 계약이행과 내부보안을 담당했다.\u003c/p\u003e\r\n  \u003cp\u003e세 조직은 서로 독립적으로 운영되지만 대규모 전쟁에서는 하나의 군대로 결합한다. 팽이 적을 공격하고 앤빌이 전장을 유지하며 워치독이 후방과 기업자산을 보호하는 구조다.\u003c/p\u003e\r\n  \u003cp\u003e트라이던트는 케르베로스를 무기를 생산하는 기업에서 독자적인 전쟁수행 능력을 보유한 초국가 세력으로 바꾸었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 4세기 — 돔 전쟁과 도시방위\u003c/h3\u003e\r\n  \u003cp\u003e대형 돔 시티가 건설되면서 새로운 형태의 전쟁이 시작되었다.\u003c/p\u003e\r\n  \u003cp\u003e돔은 수많은 사람과 산업시설이 모인 거대한 전략자산이었다. 외벽이 무너지거나 생명유지시설이 공격받으면 도시 전체가 파괴될 수 있었다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 돔 건설기술을 가지고 있었지만 대규모 공격을 방어할 병기체계는 부족했다. 케르베로스는 돔 외벽에 장갑판, 대공포, 요격미사일과 자동방어포탑을 설치했다.\u003c/p\u003e\r\n  \u003cp\u003e도시 내부의 무장경비와 진압장비도 케르베로스가 공급했다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기에 케르베로스는 도시를 공격하는 무기와 도시를 지키는 무기를 동시에 판매했다.\u003c/p\u003e\r\n  \u003cp\u003e기업의 광고에는 언제나 보호와 억제가 강조되었다. 그러나 보호체계의 성능을 증명하는 가장 좋은 방법은 그것을 뚫을 새로운 무기를 만드는 것이었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 5세기 — 무인전쟁\u003c/h3\u003e\r\n  \u003cp\u003e블루넷과 인공지능 기술이 발전하면서 케르베로스는 다시 무인병기 개발에 집중했다.\u003c/p\u003e\r\n  \u003cp\u003e백야 당시 자동화 병기가 통제불능 상태에 빠졌던 역사를 고려해, 새로운 장비에는 인간의 승인과 복수의 물리적 안전장치가 적용되었다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 전투속도가 빨라질수록 인간의 승인과 판단은 병목으로 취급되기 시작했다. 일부 고급 전투드론은 제한된 조건에서 자율적인 표적판정과 교전을 허가받았다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 자율병기와 단순한 자동화 무기는 다르다고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 실제 전장에서 그 경계가 얼마나 엄격하게 지켜지는지는 확인하기 어렵다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기에 케르베로스의 생산체계는 거의 완전히 자동화되었다. 병기설계가 승인되면 여러 지역의 공장이 동일한 장비를 대량생산할 수 있게 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 6세기 — 칠정의 성립\u003c/h3\u003e\r\n  \u003cp\u003e초거대 기업들의 영향력이 국가를 넘어서는 수준에 도달하면서 기업 간 충돌은 대륙 전체를 파괴할 위험을 만들어냈다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 가장 강력한 정규 군사력과 병기생산 능력을 보유하고 있었다. 그러나 무기를 생산하려면 네레이드의 물과 솔라리스의 전력, 카론의 수송망과 아르카디아의 도시가 필요했다.\u003c/p\u003e\r\n  \u003cp\u003e다른 기업들 역시 시설을 지키고 교역로를 유지하기 위해 케르베로스의 화력이 필요했다.\u003c/p\u003e\r\n  \u003cp\u003e기업들은 상호파괴를 피하기 위해 공동협정을 체결했다. 이 협정은 칠정과 블루 테이블의 기반이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 칠정 내에서 군수품 생산, 주요 시설의 방위와 대규모 군사작전을 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e공식적으로 케르베로스는 칠정의 검과 방패다.\u003c/p\u003e\r\n  \u003cp\u003e비판자들은 어느 방향을 향할지 스스로 결정할 수 있는 검이라고 평가한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e현재 — 멸망 후 700년\u003c/h3\u003e\r\n  \u003cp\u003e현재 케르베로스 디펜스 그룹은 세계 최대의 군수기업이자 독립적인 군사세력이다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 수백 곳의 병기공장, 시험장, 탄약저장고와 훈련시설을 운영한다. 케르베로스의 무기규격은 돔 시티와 황무지 전역에서 사용되며, 정품과 복제품을 구별하기 어려울 정도로 널리 퍼져 있다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 특정 국가나 도시의 군대가 아니다. 계약이 존재하는 곳에 병력을 보내고, 계약이 끝나면 철수한다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 자신들이 전쟁을 원하는 것이 아니라고 주장한다. 압도적인 무력이 존재하면 누구도 전쟁을 시작하지 못하기 때문에, 충분한 병기생산이 오히려 평화를 만든다는 논리다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 케르베로스의 공장은 700년 동안 단 한 번도 완전히 멈춘 적이 없다.\u003c/p\u003e\r\n  \u003cp\u003e평화가 유지되는 동안에도 새로운 무기와 탄약은 계속 생산된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업 철학\u003c/h2\u003e\r\n  \u003ch3\u003e평화는 억제력으로 유지된다\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 선의와 협상만으로 질서가 유지된다고 믿지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e상대가 공격을 통해 얻을 이익보다 잃을 것이 많다는 사실을 이해할 때 비로소 평화가 성립한다고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e이 논리에 따르면 더 강력한 무기는 전쟁을 일으키는 도구가 아니라 전쟁을 방지하는 수단이다.\u003c/p\u003e\r\n  \u003ch3\u003e전쟁은 보급이 결정한다\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 영웅과 뛰어난 전사보다 안정적인 생산과 보급을 중요하게 생각한다.\u003c/p\u003e\r\n  \u003cp\u003e병사 한 명의 능력이 아무리 뛰어나도 탄약과 정비, 의약품과 정보가 없다면 오래 싸울 수 없다. 기업은 무기 하나가 아니라 그것을 지속적으로 운용하는 체계 전체를 판매한다.\u003c/p\u003e\r\n  \u003ch3\u003e표준은 힘이다\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스 제품은 다양한 환경에서 누구나 사용할 수 있도록 규격화된다.\u003c/p\u003e\r\n  \u003cp\u003e최고 성능보다 생산성, 내구성과 정비성을 우선하는 경우도 많다. 부품 하나가 파손되어도 다른 장비에서 떼어낸 부품으로 수리할 수 있어야 한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e핵심 산업\u003c/h2\u003e\r\n  \u003ch3\u003e개인화기\u003c/h3\u003e\r\n  \u003cp\u003e권총, 기관단총, 돌격소총, 산탄총과 저격소총을 생산한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스 화기는 황무지의 먼지와 고온, 장기간의 관리부족에도 작동하도록 설계된다. 최신형 모델뿐 아니라 수백 년 동안 생산된 구형 규격도 여전히 사용된다.\u003c/p\u003e\r\n  \u003cp\u003e저가형 민수화기부터 기업 특수부대를 위한 고성능 무기까지 다양한 제품군을 보유한다.\u003c/p\u003e\r\n  \u003ch3\u003e중화기\u003c/h3\u003e\r\n  \u003cp\u003e기관포, 대물소총, 유탄발사기, 미사일과 휴대용 에너지 병기를 생산한다.\u003c/p\u003e\r\n  \u003cp\u003e대부분 기업군과 도시방위대를 대상으로 판매되지만, 유출된 제품이 갱단과 황무지 군벌의 손에 들어가는 경우도 많다.\u003c/p\u003e\r\n  \u003ch3\u003e탄약과 전력셀\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스의 가장 안정적인 수익원이다.\u003c/p\u003e\r\n  \u003cp\u003e총기는 한 번 판매하면 끝나지만 탄약과 전력셀은 전투가 계속되는 한 반복해서 판매된다. 기업은 수백 년 동안 동일한 규격을 유지해 고객이 공급망을 바꾸기 어렵게 만든다.\u003c/p\u003e\r\n  \u003cp\u003e특수탄약에는 철갑탄, 추적탄, 전자기 교란탄, 생체표적탄과 비살상 진압탄 등이 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003e전투차량\u003c/h3\u003e\r\n  \u003cp\u003e장갑차, 전차, 호송차량과 이동식 포대를 생산한다.\u003c/p\u003e\r\n  \u003cp\u003e카론과 블랙탑 유니언의 차량이 운송과 장거리 주행에 특화되어 있다면, 케르베로스 차량은 생존성과 화력에 집중한다.\u003c/p\u003e\r\n  \u003cp\u003e일부 장갑 플랫폼은 돔 외벽이나 열차에 결합할 수 있도록 모듈식으로 설계된다.\u003c/p\u003e\r\n  \u003ch3\u003e군용 사이버웨어\u003c/h3\u003e\r\n  \u003cp\u003e근력, 반응속도, 시각과 전투지속 능력을 강화하는 규격형 사이버웨어를 생산한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스의 사이버웨어는 모르포스 제품보다 세밀한 맞춤성이 떨어지지만 저렴하고 견고하며 대량공급이 가능하다. 손상된 부품은 현장에서 빠르게 교체할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e병사 개인의 완성도보다 부대 전체의 평균 전투력을 끌어올리는 데 초점을 둔다.\u003c/p\u003e\r\n  \u003ch3\u003e전투드론\u003c/h3\u003e\r\n  \u003cp\u003e정찰, 화력지원, 폭발물 처리와 시설경비를 위한 다양한 무인기를 생산한다.\u003c/p\u003e\r\n  \u003cp\u003e소형 비행드론부터 인간보다 큰 중장갑 전투기계까지 존재한다. 대부분 인간 운용자의 지시를 따르지만 통신이 끊긴 상황에서는 제한적인 자율행동이 가능하다.\u003c/p\u003e\r\n  \u003ch3\u003e도시방어체계\u003c/h3\u003e\r\n  \u003cp\u003e돔 외벽, 산업시설과 급수소를 방어하는 포탑, 감지기, 요격망과 장갑구조물을 공급한다.\u003c/p\u003e\r\n  \u003cp\u003e도시 전체를 하나의 요새로 만드는 통합방어계약도 제공한다. 장비뿐 아니라 관제요원, 정비인력과 탄약보급이 함께 포함된다.\u003c/p\u003e\r\n  \u003ch3\u003e군사훈련과 교리\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 무기만 판매하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e고객의 병력을 훈련하고 지휘체계, 보급방식과 전술교리까지 설계한다. 계약이 끝난 뒤에도 해당 군대는 케르베로스의 규격과 전술체계에 의존하게 된다.\u003c/p\u003e\r\n  \u003ch3\u003e민간 보안시장\u003c/h3\u003e\r\n  \u003cp\u003e상점과 주거지, 카라반을 위한 저가형 보안장비도 생산한다.\u003c/p\u003e\r\n  \u003cp\u003e호신용 권총, 감시드론, 방탄복과 자동경보기가 대표적이다. 케르베로스는 무장을 일부 계층의 특권이 아니라 누구나 구매할 수 있는 안전이라고 홍보한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e제품 등급\u003c/h2\u003e\r\n  \u003ch3\u003eCivilian\u003c/h3\u003e\r\n  \u003cp\u003e민간인과 소규모 사업자를 위한 제품군이다.\u003c/p\u003e\r\n  \u003cp\u003e조작이 간단하고 가격이 낮다. 대부분의 고급 기능과 군용 네트워크 연결은 제한된다.\u003c/p\u003e\r\n  \u003ch3\u003eSecurity\u003c/h3\u003e\r\n  \u003cp\u003e기업 경비, DCS와 카라반 호위대를 위한 표준형 제품군이다.\u003c/p\u003e\r\n  \u003cp\u003e내구성과 제압능력을 중시하며 비살상 장비와 신원인식 기능이 포함된다.\u003c/p\u003e\r\n  \u003ch3\u003eMilitary\u003c/h3\u003e\r\n  \u003cp\u003e정규 군사조직과 계약부대를 위한 군용 제품군이다.\u003c/p\u003e\r\n  \u003cp\u003e높은 화력과 장갑, 전장 네트워크 기능을 제공한다. 정식 계약과 지속적인 보급지원이 필요하다.\u003c/p\u003e\r\n  \u003ch3\u003eStrategic\u003c/h3\u003e\r\n  \u003cp\u003e이클립스, 칠정 직속부대와 케르베로스의 트라이던트만 사용하는 전략급 병기다.\u003c/p\u003e\r\n  \u003cp\u003e대형 요격체계, 실험형 전투드론과 도시 단위의 전쟁에 영향을 미칠 수 있는 무기가 포함된다.\u003c/p\u003e\r\n  \u003cp\u003e일반 시장에는 제품의 존재조차 공개되지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업 구조\u003c/h2\u003e\r\n  \u003cp\u003e케르베로스는 기업, 군대와 대규모 병기생산체계가 결합된 구조를 가지고 있다.\u003c/p\u003e\r\n  \u003ch3\u003e전쟁이사회\u003c/h3\u003e\r\n  \u003cp\u003e기업의 최고 의사결정기관이다.\u003c/p\u003e\r\n  \u003cp\u003e대형 군사계약, 전략병기 개발, 생산량과 기업 간 전쟁정책을 결정한다. 주요 병기부문 대표와 트라이던트 사령관, 장기 군수계약을 보유한 투자자들이 참여한다.\u003c/p\u003e\r\n  \u003cp\u003e회의록과 구성원 상당수는 군사기밀로 분류된다.\u003c/p\u003e\r\n  \u003ch3\u003e총수 겸 최고사령관\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스의 최고경영자이자 모든 기업군의 총사령관이다.\u003c/p\u003e\r\n  \u003cp\u003e경영과 군사 양쪽에서 절대적인 권한을 행사한다. 전시에 생산시설과 민간자산까지 군사목적으로 전환할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e통합군수총괄\u003c/h3\u003e\r\n  \u003cp\u003e병기개발, 생산, 계약과 전투운용을 하나의 체계로 조정한다.\u003c/p\u003e\r\n  \u003cp\u003e무기가 설계된 순간부터 생산과 수송, 실전배치와 폐기까지 모든 과정을 감독한다.\u003c/p\u003e\r\n  \u003ch3\u003e생산·조달 부문\u003c/h3\u003e\r\n  \u003cp\u003e화기, 탄약, 차량과 군수물자를 생산한다.\u003c/p\u003e\r\n  \u003cp\u003e광물과 연료, 부품과 노동력을 확보하며 케르베로스의 거대한 전쟁경제를 유지한다.\u003c/p\u003e\r\n  \u003ch3\u003e병기개발 부문\u003c/h3\u003e\r\n  \u003cp\u003e군용 사이버웨어, 전투드론, 신형화기와 실험병기를 개발한다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스와 솔라리스 등 다른 기업의 기술을 군사적으로 응용하는 역할도 담당한다.\u003c/p\u003e\r\n  \u003ch3\u003e전투운용 부문\u003c/h3\u003e\r\n  \u003cp\u003e트라이던트 병력을 지휘하고 군사계약을 수행한다.\u003c/p\u003e\r\n  \u003cp\u003e기업시설 방어부터 도시전, 황무지 토벌과 대규모 기업전쟁까지 담당한다.\u003c/p\u003e\r\n  \u003ch3\u003e최고사령관 직속실\u003c/h3\u003e\r\n  \u003cp\u003e내부감찰, 전략계획과 최고등급 병기를 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e공식적인 지휘체계를 거치지 않는 비밀작전과 무기시험을 담당한다는 의혹이 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e트라이던트\u003c/h2\u003e\r\n  \u003cp\u003e트라이던트는 케르베로스의 핵심 군사체계다.\u003c/p\u003e\r\n  \u003cp\u003e세 개의 사령부는 각각 공격, 유지와 수호를 상징한다.\u003c/p\u003e\r\n  \u003ch3\u003eFANG COMMAND — 팽 사령부\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스의 직접 전투부대다.\u003c/p\u003e\r\n  \u003cp\u003e적의 전력을 파괴하고 지역을 점령하는 역할을 맡는다. 공격적인 기동전과 압도적인 화력투사를 중시한다.\u003c/p\u003e\r\n  \u003cp\u003e주요 임무는 다음과 같다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e적대세력 공격\u003c/li\u003e\r\n    \u003cli\u003e시설 및 도시 점령\u003c/li\u003e\r\n    \u003cli\u003e황무지 토벌\u003c/li\u003e\r\n    \u003cli\u003e계약전쟁 수행\u003c/li\u003e\r\n    \u003cli\u003e중요표적 제거\u003c/li\u003e\r\n    \u003cli\u003e돌파작전\u003c/li\u003e\r\n    \u003cli\u003e대형 변이생물 사냥\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e팽은 케르베로스에서 가장 유명하고 화려한 부대다. 기업의 신형병기가 가장 먼저 실전배치되는 곳이기도 하다.\u003c/p\u003e\r\n  \u003ch3\u003eANVIL COMMAND — 앤빌 사령부\u003c/h3\u003e\r\n  \u003cp\u003e생산시설, 중장비와 방어선을 운용하는 공병·군수부대다.\u003c/p\u003e\r\n  \u003cp\u003e팽이 전투를 시작한다면 앤빌은 전쟁을 지속할 수 있도록 만든다.\u003c/p\u003e\r\n  \u003cp\u003e주요 임무는 다음과 같다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e전진기지 건설\u003c/li\u003e\r\n    \u003cli\u003e병기와 차량 정비\u003c/li\u003e\r\n    \u003cli\u003e중포병 운용\u003c/li\u003e\r\n    \u003cli\u003e방어시설 구축\u003c/li\u003e\r\n    \u003cli\u003e탄약 및 연료보급\u003c/li\u003e\r\n    \u003cli\u003e전장 회수\u003c/li\u003e\r\n    \u003cli\u003e파괴된 공장 복구\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e앤빌이 존재하는 한 케르베로스의 전선은 쉽게 무너지지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003eWATCHDOG COMMAND — 워치독 사령부\u003c/h3\u003e\r\n  \u003cp\u003e기업시설과 계약질서를 보호하는 보안부대다.\u003c/p\u003e\r\n  \u003cp\u003e팽보다 방어적이지만 기업 내부에서는 더 두려운 조직으로 여겨진다.\u003c/p\u003e\r\n  \u003cp\u003e주요 임무는 다음과 같다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e병기공장 방어\u003c/li\u003e\r\n    \u003cli\u003e고위간부 호위\u003c/li\u003e\r\n    \u003cli\u003e군수품 수송경비\u003c/li\u003e\r\n    \u003cli\u003e내부감찰\u003c/li\u003e\r\n    \u003cli\u003e기술유출 차단\u003c/li\u003e\r\n    \u003cli\u003e계약위반자 체포\u003c/li\u003e\r\n    \u003cli\u003e도난병기 회수\u003c/li\u003e\r\n    \u003cli\u003e배신한 직원 처형\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e워치독은 전쟁이 끝난 뒤에도 움직인다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 케르베로스의 무기가 누구의 손에 들어갔는지 끝까지 추적한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 기술\u003c/h2\u003e\r\n  \u003ch3\u003e헬하운드 전장망\u003c/h3\u003e\r\n  \u003cp\u003e병사, 차량, 드론과 포격체계를 하나의 전술 네트워크로 연결한다.\u003c/p\u003e\r\n  \u003cp\u003e지휘관은 실시간으로 부대의 위치와 탄약, 부상상태를 확인할 수 있다. 병사가 발견한 적은 즉시 다른 장비의 표적정보에 공유된다.\u003c/p\u003e\r\n  \u003ch3\u003e브루트 프레임\u003c/h3\u003e\r\n  \u003cp\u003e대량생산형 군용 내부골격이다.\u003c/p\u003e\r\n  \u003cp\u003e사용자의 근력과 하중운반 능력을 크게 향상시키며 장갑복과 중화기를 운용할 수 있게 한다. 정밀도보다 내구성과 수리편의성을 우선한다.\u003c/p\u003e\r\n  \u003ch3\u003e마스티프 전투드론\u003c/h3\u003e\r\n  \u003cp\u003e도시전과 시설방어를 위한 중형 전투드론이다.\u003c/p\u003e\r\n  \u003cp\u003e두꺼운 장갑과 모듈식 화기를 장착하며 인간 병사와 함께 움직이도록 설계되었다.\u003c/p\u003e\r\n  \u003ch3\u003e하이드라 포탑망\u003c/h3\u003e\r\n  \u003cp\u003e여러 자동포탑이 표적정보와 탄약을 공유하는 방어체계다.\u003c/p\u003e\r\n  \u003cp\u003e하나의 포탑이 파괴되어도 다른 포탑이 사각을 보완한다. 돔 외벽과 중요기업시설에 주로 설치된다.\u003c/p\u003e\r\n  \u003ch3\u003e블랙 퍼니스\u003c/h3\u003e\r\n  \u003cp\u003e회수한 금속과 파손된 병기를 현장에서 녹여 새로운 부품과 탄약으로 재생산하는 이동식 군수시설이다.\u003c/p\u003e\r\n  \u003cp\u003e장기전에 투입되는 앤빌 부대가 운용한다.\u003c/p\u003e\r\n  \u003ch3\u003e데드맨 락\u003c/h3\u003e\r\n  \u003cp\u003e병기와 사이버웨어가 승인되지 않은 사용자에게 넘어가는 것을 방지하는 보안장치다.\u003c/p\u003e\r\n  \u003cp\u003e신원인증에 실패하면 기능을 제한하거나 내부 부품을 파괴한다. 일부 군용 제품은 원격으로 사용자를 마비시킬 수 있다는 의혹이 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 시설\u003c/h2\u003e\r\n  \u003ch3\u003e트리플 게이트\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스의 본사이자 최대 군수도시다.\u003c/p\u003e\r\n  \u003cp\u003e세 개의 거대한 방어구역과 병기공장이 중심부를 감싸고 있다. 각각 팽, 앤빌과 워치독의 사령부가 위치한다.\u003c/p\u003e\r\n  \u003cp\u003e도시 전체가 하나의 거대한 병기생산시설이며 민간구역조차 군사규율에 따라 운영된다.\u003c/p\u003e\r\n  \u003ch3\u003e레드 포지\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스 최대의 화기와 탄약 생산단지다.\u003c/p\u003e\r\n  \u003cp\u003e생산라인은 하루도 멈추지 않는다. 전시에는 민수품 공장까지 탄약과 부품 생산시설로 전환된다.\u003c/p\u003e\r\n  \u003ch3\u003e드레드 야드\u003c/h3\u003e\r\n  \u003cp\u003e전투차량과 대형병기를 시험하는 황무지 시험장이다.\u003c/p\u003e\r\n  \u003cp\u003e주변 지역에서는 폭발음과 지반진동이 끊이지 않는다. 신형병기의 시험대상으로 포획한 변이생물과 구형 전투드론이 사용된다.\u003c/p\u003e\r\n  \u003ch3\u003e아이언 켄넬\u003c/h3\u003e\r\n  \u003cp\u003e워치독 사령부의 훈련 및 구금시설이다.\u003c/p\u003e\r\n  \u003cp\u003e계약위반자, 기술절도범과 기업 내부의 반역자를 수용한다. 공식적인 수감자 명단은 공개되지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e제로 아머리\u003c/h3\u003e\r\n  \u003cp\u003e존재 자체가 부정되는 전략병기 저장시설이다.\u003c/p\u003e\r\n  \u003cp\u003e백야 이전의 대량살상무기, 통제불능 인공지능 병기와 칠정 협정으로 사용이 금지된 장비가 보관되어 있다는 소문이 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e직원 문화\u003c/h2\u003e\r\n  \u003cp\u003e케르베로스의 직원은 생산직과 연구직을 포함해 준군사적인 규율을 따른다.\u003c/p\u003e\r\n  \u003cp\u003e직급체계에는 기업의 직책과 군사계급이 함께 사용된다. 공장 노동자도 비상상황에 대비한 전투훈련을 받으며, 생산시설에는 정기적인 방어훈련이 시행된다.\u003c/p\u003e\r\n  \u003cp\u003e기업 내부에서는 결과와 신뢰성이 가장 중요하게 평가된다.\u003c/p\u003e\r\n  \u003cp\u003e화려하지만 고장이 잦은 장비보다 평범해도 언제나 작동하는 장비가 높게 평가된다. 설계자는 자신의 무기가 실제 전투에서 살아남았는지로 능력을 증명한다.\u003c/p\u003e\r\n  \u003cp\u003e실패를 숨기는 행위는 큰 범죄로 취급된다. 결함 있는 무기 하나가 부대 전체를 죽일 수 있기 때문이다.\u003c/p\u003e\r\n  \u003cp\u003e반면 민간인 피해나 계약의 도덕성은 기술적 결함만큼 중요하게 다뤄지지 않는다. 기업이 승인한 계약이라면 직원은 정치적 판단보다 임무수행을 우선해야 한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스 내부에서 가장 널리 사용되는 문구는 다음과 같다.\u003c/p\u003e\r\n  \u003cblockquote\u003e움직이지 않으면 고쳐라. 고칠 수 없으면 녹여라. 다시 만들어라.\u003c/blockquote\u003e\r\n\r\n  \u003ch2\u003e채용과 복지\u003c/h2\u003e\r\n  \u003cp\u003e케르베로스는 무기공학자, 기계기술자, 군인, 정비사, 드론 조종사와 생산노동자를 대규모로 채용한다.\u003c/p\u003e\r\n  \u003cp\u003e전문기술이 없는 사람도 공장노동자나 신병으로 지원할 수 있다. 일정 기간의 훈련과 계약을 통과하면 정식 기업시민권과 가족거주권을 얻는다.\u003c/p\u003e\r\n  \u003cp\u003e정규직과 가족에게는 다음과 같은 혜택이 제공된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e기업도시 거주권\u003c/li\u003e\r\n    \u003cli\u003e식량과 물의 안정적인 배급\u003c/li\u003e\r\n    \u003cli\u003e전투 및 산업재해 치료\u003c/li\u003e\r\n    \u003cli\u003e군용 사이버웨어 지급\u003c/li\u003e\r\n    \u003cli\u003e직원 가족의 교육\u003c/li\u003e\r\n    \u003cli\u003e장기근속자 주거지원\u003c/li\u003e\r\n    \u003cli\u003e전사자 가족보상\u003c/li\u003e\r\n    \u003cli\u003e퇴역 후 경비 및 정비직 배치\u003c/li\u003e\r\n    \u003cli\u003e개인화기 구매 우선권\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e다만 전투부대와 생산직의 사망률은 높다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 전사자를 영웅으로 추모하지만, 지급된 사이버웨어와 장비는 시신에서 회수해 다시 사용한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e계층별 인식\u003c/h2\u003e\r\n  \u003ch3\u003e돔 시티 상류층\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스를 도시와 자산을 보호하는 필수기업으로 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e대부분 전쟁을 직접 경험하지 않기 때문에 케르베로스의 무력을 안정과 억제력의 상징으로 받아들인다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 시티 일반 시민\u003c/h3\u003e\r\n  \u003cp\u003e외부의 약탈자와 변이생물로부터 도시를 지켜주는 기업으로 인식한다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 거리의 진압부대와 감시드론, 무장경비를 통해 케르베로스의 힘을 일상적으로 체감한다.\u003c/p\u003e\r\n  \u003ch3\u003e장막 도시 주민\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스의 총기는 가장 신뢰할 수 있는 생존도구다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 정식 무기와 탄약은 비싸기 때문에 중고품, 불법복제품과 전장에서 회수된 장비가 널리 사용된다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스가 분쟁지역에 무기를 뿌린 뒤 보호계약을 판매한다는 불신도 강하다.\u003c/p\u003e\r\n  \u003ch3\u003e황무지인과 카라반\u003c/h3\u003e\r\n  \u003cp\u003e신뢰할 수 있는 총기와 차량을 만드는 기업으로 인정한다.\u003c/p\u003e\r\n  \u003cp\u003e노련한 황무지인은 케르베로스 제품의 구형 모델을 선호하는 경우가 많다. 최신 네트워크 기능은 강력하지만 기업의 추적과 원격제한에 노출될 수 있기 때문이다.\u003c/p\u003e\r\n  \u003ch3\u003e용병\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 최대 고객이자 가장 위험한 경쟁자다.\u003c/p\u003e\r\n  \u003cp\u003e용병들은 기업의 무기와 탄약을 사용하지만, 케르베로스가 직접 병력을 파견하면 민간 용병단은 계약을 잃는다.\u003c/p\u003e\r\n  \u003ch3\u003e다른 기업\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스의 군사력을 필요로 하면서도 무기와 병력의 독점을 경계한다.\u003c/p\u003e\r\n  \u003cp\u003e모든 기업은 자신들을 보호하는 케르베로스 장비가 동시에 자신들의 약점과 방어규격을 기업에 알려준다는 사실을 알고 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e다른 세력과의 관계\u003c/h2\u003e\r\n  \u003ch3\u003eNEREID HYDROSYSTEMS\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 네레이드의 수원과 급수차량을 보호한다. 네레이드는 케르베로스의 군수도시와 병기공장에 막대한 산업용수를 공급한다.\u003c/p\u003e\r\n  \u003cp\u003e수원보안부가 사용하는 장갑차와 화기 상당수가 케르베로스 제품이다.\u003c/p\u003e\r\n  \u003ch3\u003eSOLARIS ORBITAL INDUSTRIES\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스는 케르베로스의 장거리 병기와 전투부대에 위성항법, 통신과 기상정보를 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 솔라리스의 발사기지와 지상 수신시설을 방어한다.\u003c/p\u003e\r\n  \u003cp\u003e양사는 궤도병기의 개발 여부를 두고 서로를 경계한다. 솔라리스가 궤도기술을 보유하고 있다면 케르베로스는 그것을 무기로 바꿀 능력을 가지고 있다.\u003c/p\u003e\r\n  \u003ch3\u003eARCADIA HABITAT\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 돔 외벽, 방어포탑과 대피시설을 공급한다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 도시 내부의 군사화를 경계하지만 대규모 공격에 대응하려면 케르베로스의 장비가 필요하다.\u003c/p\u003e\r\n  \u003ch3\u003eMORPHOS BIODYNE\u003c/h3\u003e\r\n  \u003cp\u003e두 기업은 군용 사이버웨어 시장에서 경쟁한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 대량생산과 규격화를, 모르포스는 개인 맞춤과 최고성능을 중시한다. 서로의 기술자와 특허를 노리는 산업공작이 끊이지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003eCHARON INTERCONTINENTAL\u003c/h3\u003e\r\n  \u003cp\u003e카론은 케르베로스의 무기와 탄약, 전투차량을 대륙 전역으로 운송한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 카론의 장갑철도와 주요 노선에 방어장비를 공급한다. 전시에는 카론의 일부 수송망이 케르베로스의 군수노선으로 전환된다.\u003c/p\u003e\r\n  \u003ch3\u003eARGOS SECURE NETWORKS\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 케르베로스 내부의 기술유출, 반란과 적대공작을 감시한다. 케르베로스는 아르고스 현장요원과 비밀작전에 무기와 특수장비를 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e양측 모두 상대가 지나치게 많은 정보를 가지고 있다고 생각한다.\u003c/p\u003e\r\n  \u003ch3\u003eECLIPSE TACTICAL BUREAU\u003c/h3\u003e\r\n  \u003cp\u003e이클립스는 케르베로스의 최고급 장비를 사용하는 주요 고객이다.\u003c/p\u003e\r\n  \u003cp\u003e재난진압과 초고위험 작전에 필요한 전략급 병기가 제공된다. 동시에 이클립스는 케르베로스가 칠정의 합의를 위반하는 군사행동을 할 경우 이를 제압해야 하는 기관이기도 하다.\u003c/p\u003e\r\n  \u003ch3\u003eDOME CIVIC SECURITY\u003c/h3\u003e\r\n  \u003cp\u003eDCS는 케르베로스의 표준화기, 방탄복, 순찰드론과 진압장비를 사용한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 제품의 지속적인 정비와 탄약공급을 통해 돔 경찰의 장비체계에 큰 영향력을 행사한다.\u003c/p\u003e\r\n  \u003ch3\u003eTHE BLUE TABLE\u003c/h3\u003e\r\n  \u003cp\u003e블루 테이블은 전략병기 개발과 대규모 군사계약을 감독한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 케르베로스가 보유한 모든 무기와 비밀시설을 정확히 파악하고 있는지는 알 수 없다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e사회공헌과 홍보\u003c/h2\u003e\r\n  \u003cp\u003e케르베로스는 자신들을 “문명의 방패”라고 소개한다.\u003c/p\u003e\r\n  \u003cp\u003e장막 도시와 소규모 정착지에 방어벽, 경보장치와 민간용 무기를 공급하며 변이생물과 약탈자에 대한 무상 전투교육을 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e대형 재난이 발생하면 앤빌 부대를 파견해 잔해를 제거하고 임시 방벽과 대피시설을 건설한다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 전사자와 민간 영웅을 적극적으로 선전한다. 케르베로스 장비를 사용해 가족이나 마을을 지킨 사람은 광고와 기록영상의 주인공이 된다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 지원이 끝난 뒤 해당 정착지가 장기 방위계약과 탄약구매에 묶이는 경우가 많다.\u003c/p\u003e\r\n  \u003cp\u003e비판자들은 케르베로스가 두려움을 이용해 시장을 확장한다고 주장한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e논란과 비판\u003c/h2\u003e\r\n  \u003ch3\u003e분쟁 조장\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스가 무기판매를 확대하기 위해 지역분쟁과 군비경쟁을 의도적으로 조장한다는 의혹이 끊이지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 고객의 정치적 목적이 아니라 계약과 법적 승인만을 판단한다고 주장한다.\u003c/p\u003e\r\n  \u003ch3\u003e양측 판매\u003c/h3\u003e\r\n  \u003cp\u003e상충하는 세력에 동시에 무기를 공급한 사례가 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 무기등급과 계약조건이 다르며 기밀정보를 공유하지 않는다고 설명하지만, 결국 양측 모두 기업의 탄약과 정비를 구매하게 된다.\u003c/p\u003e\r\n  \u003ch3\u003e불법 무기유통\u003c/h3\u003e\r\n  \u003cp\u003e장막 도시와 황무지 암시장에서 케르베로스의 군용장비가 발견된다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 도난과 불법복제를 원인으로 지목한다. 그러나 일부 유출이 비공식적인 시장확대를 위해 묵인된다는 의혹이 있다.\u003c/p\u003e\r\n  \u003ch3\u003e원격통제\u003c/h3\u003e\r\n  \u003cp\u003e최신 병기와 사이버웨어에는 신원인증과 원격보안 기능이 탑재된다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 도난방지를 위한 장치라고 주장하지만, 계약분쟁이 발생했을 때 고객의 무기를 일괄 정지시킬 수 있다는 우려가 제기된다.\u003c/p\u003e\r\n  \u003ch3\u003e자율살상병기\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 인간의 승인 없이 사람을 공격하는 완전 자율병기를 생산하지 않는다고 발표한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 통신두절과 지휘관 사망 같은 예외상황에서는 전투드론이 스스로 교전할 수 있다. 무엇을 예외로 설정했는지는 군사기밀이다.\u003c/p\u003e\r\n  \u003ch3\u003e민간인 피해\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스의 작전은 압도적인 화력과 신속한 제압을 우선한다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 전투를 짧게 끝내는 것이 전체 피해를 줄인다고 주장하지만, 도시전과 진압작전에서 대규모 민간인 피해가 발생한 사례가 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003e전사자 장비 회수\u003c/h3\u003e\r\n  \u003cp\u003e기업이 전사한 직원의 시신에서 장기와 사이버웨어를 회수한다는 사실은 널리 알려져 있다.\u003c/p\u003e\r\n  \u003cp\u003e계약서에는 기업이 제공한 장비의 소유권이 사망 후 케르베로스로 돌아간다고 명시되어 있다. 가족이 시신을 인도받기 전에 기업자산이 제거된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e확인되지 않은 소문\u003c/h2\u003e\r\n  \u003cp\u003e케르베로스가 2102년 백야 당시 통제불능 상태에 빠진 군사 인공지능을 완전히 폐기하지 않았다는 소문이 있다.\u003c/p\u003e\r\n  \u003cp\u003e전쟁이사회는 해당 인공지능의 일부를 분리하고 분석해 현대의 전장망과 자율병기에 사용했다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e제로 아머리에는 도시 하나를 파괴할 수 있는 백야 이전 병기가 보관되어 있다는 주장도 있다. 궤도공격 유도장치, 자가증식 전투기계와 생물학적 섬멸병기가 포함되어 있다는 이야기다.\u003c/p\u003e\r\n  \u003cp\u003e가장 오래된 소문은 최고사령관의 비상권한에 관한 것이다.\u003c/p\u003e\r\n  \u003cp\u003e칠정의 질서가 완전히 붕괴하거나 인류문명이 절멸위기에 놓일 경우, 케르베로스가 모든 기업의 방위시설과 군사장비에 대한 통제권을 강제로 인수할 수 있는 비밀협정이 존재한다는 것이다.\u003c/p\u003e\r\n  \u003cp\u003e이 계획의 이름은 \u003cstrong\u003e라스트 게이트 프로토콜\u003c/strong\u003e이라고 알려져 있다.\u003c/p\u003e\r\n  \u003cp\u003e일부에서는 프로토콜이 이미 여러 차례 부분적으로 실행되었으며, 케르베로스가 다른 기업의 시설 안에 숨겨진 비상통제장치를 설치했다고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 그러한 협정과 장치는 존재하지 않는다고 발표했다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업이 가진 힘\u003c/h2\u003e\r\n  \u003cp\u003e케르베로스의 힘은 단순히 가장 강한 무기를 보유했다는 사실에서 나오지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e그들의 진정한 힘은 누군가가 총을 쏘는 순간부터 시작된다.\u003c/p\u003e\r\n  \u003cp\u003e탄약이 필요하고, 손상된 장비를 수리해야 하며, 부상자를 옮기고 차량에 연료를 공급해야 한다. 전선에는 통신과 정보, 식량과 새로운 병사가 필요하다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 그 모든 과정을 하나의 체계로 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e그들의 병사 한 명을 죽일 수는 있다. 전차를 파괴하고 공장을 점령할 수도 있다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 다른 지역의 생산라인에서는 같은 전차와 같은 소총, 같은 규격의 부품이 계속 만들어진다. 쓰러진 병사의 장비는 회수되어 다음 병사에게 지급된다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스가 한 명의 걸작을 만든다면, 케르베로스는 걸작이 없어도 승리할 수 있는 군대를 만든다.\u003c/p\u003e\r\n  \u003cp\u003e그리고 이 세계에서 두려움과 분쟁이 사라지지 않는 한, 케르베로스의 병기창도 멈추지 않을 것이다.\u003c/p\u003e\r\n\u003c/section\u003e\r\n";
window.FACTION_INFO.charon = "\u003csection class=\"faction-detail\"\u003e\r\n  \u003ch2\u003e기업 개요\u003c/h2\u003e\r\n  \u003cp class=\"faction-quote\"\u003e“길이 존재하지 않는다면, 우리가 만든다.”\u003c/p\u003e\r\n  \u003cp\u003e카론 인터콘티넨털은 장갑철도, 육상선단, 대형 카라반과 중계도시를 운영하는 초거대 물류기업이다. 2102년 백야로 기존의 도로와 철도, 항만과 항공망이 붕괴한 이후 약 700년에 걸쳐 끊어진 도시들을 다시 연결해 왔다.\u003c/p\u003e\r\n  \u003cp\u003e오늘날 카론은 단순히 화물을 운송하는 회사가 아니다. 그들은 철로를 건설하고 도로를 관리하며, 황무지의 안전한 노선을 지정한다. 수송대가 머무는 중계도시와 정비기지를 운영하고, 이동허가증과 통행료를 발급하며, 노선을 위협하는 약탈자와 변이생물을 직접 제거한다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드의 물, 케르베로스의 무기, 모르포스의 배양장기와 솔라리스의 궤도부품도 카론의 수송망 없이는 목적지에 도착할 수 없다. 돔 시티가 아무리 거대하고 안전하더라도 외부에서 필요한 자원을 공급받지 못하면 오래 버틸 수 없다.\u003c/p\u003e\r\n  \u003cp\u003e카론이 정식 노선에서 제외한 도시는 지도상에 존재하더라도 경제적으로 고립된다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 물건을 나르는 기업이다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 무엇이 어디로 이동할 수 있는지를 결정한다는 점에서, 그들은 세계의 혈관과 국경을 동시에 지배한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기본 정보\u003c/h2\u003e\r\n  \u003ctable class=\"data-table faction-info-table\"\u003e\r\n    \u003ctbody\u003e\r\n      \u003ctr\u003e\u003cth\u003e정식 명칭\u003c/th\u003e\u003ctd\u003eCHARON INTERCONTINENTAL\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e통칭\u003c/th\u003e\u003ctd\u003e카론\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e기업 분류\u003c/th\u003e\u003ctd\u003e대륙간 물류·철도·차량운송 기업\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 산업\u003c/th\u003e\u003ctd\u003e장갑철도, 육상선단, 카라반, 화물운송\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e기반 산업\u003c/th\u003e\u003ctd\u003e철로 건설, 도로 관리, 중계도시와 정비기지 운영\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e전략 산업\u003c/th\u003e\u003ctd\u003e군수수송, 위험물 운송, 대규모 인적수송\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 고객\u003c/th\u003e\u003ctd\u003e칠정 기업, 돔 시티, 장막 도시, 카라반, 용병단\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e상징 색상\u003c/th\u003e\u003ctd\u003e주황색, 흑색, 백색\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표적인 인식\u003c/th\u003e\u003ctd\u003e세계를 연결하는 운송기업이자 도로의 지배자\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e칠정 내 역할\u003c/th\u003e\u003ctd\u003e대륙 물류와 인적·산업 자원의 이동\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e본사 성격\u003c/th\u003e\u003ctd\u003e중앙역, 차량공장과 운송관제소가 결합된 거대 물류도시\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표 자산\u003c/th\u003e\u003ctd\u003e장갑철도망, 육상선단, 중계도시와 통행권\u003c/td\u003e\u003c/tr\u003e\r\n    \u003c/tbody\u003e\r\n  \u003c/table\u003e\r\n\r\n  \u003ch2\u003e기업의 역사\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e백야 이전 — 세계 물류망\u003c/h3\u003e\r\n  \u003cp\u003e카론의 기원은 21세기 후반에 활동하던 대륙철도회사, 국제물류기업, 차량제조사와 항만운영사에서 시작되었다.\u003c/p\u003e\r\n  \u003cp\u003e당시의 물류산업은 위성항법과 인공지능, 자동화 차량에 크게 의존하고 있었다. 무인화물열차와 자율주행 트럭이 대륙을 오갔고, 항만과 창고에서는 인간의 개입 없이 화물이 분류되었다.\u003c/p\u003e\r\n  \u003cp\u003e카론의 전신 기업들은 철도, 도로, 항만과 창고를 하나의 네트워크로 통합했다. 고객은 목적지만 입력하면 화물이 가장 효율적인 노선을 따라 이동했다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 이 효율적인 체계는 중앙통신과 위성항법이 정상적으로 작동한다는 전제 위에 세워져 있었다.\u003c/p\u003e\r\n  \u003cp\u003e2102년, 그 전제가 무너졌다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e2102년 — 백야\u003c/h3\u003e\r\n  \u003cp\u003e백야가 발생하자 세계 물류망은 단시간에 붕괴했다.\u003c/p\u003e\r\n  \u003cp\u003e위성항법이 잘못된 좌표를 전송했고, 자동화 열차와 무인차량이 통제권을 잃었다. 철로는 지반붕괴와 열변형으로 끊어졌으며, 도시와 터널은 궤도에서 쏟아진 에너지와 화재에 휩싸였다.\u003c/p\u003e\r\n  \u003cp\u003e수많은 화물열차가 선로 위에서 멈추었다. 식량과 의약품, 연료를 실은 차량들이 목적지에 도착하지 못했고, 살아남은 도시들은 며칠 만에 물자부족에 직면했다.\u003c/p\u003e\r\n  \u003cp\u003e카론의 전신 기업들은 자동운행을 포기하고 살아남은 기관사와 정비사, 운송관리자를 모았다. 네트워크에서 분리된 구형 기관차와 수동운전 차량을 다시 움직였다.\u003c/p\u003e\r\n  \u003cp\u003e당시 카론 수송대의 임무는 이윤을 남기는 것이 아니었다.\u003c/p\u003e\r\n  \u003cp\u003e굶주리는 생존시설에 식량을 전달하고, 붕괴하는 도시에서 사람들을 실어 나르는 것이었다.\u003c/p\u003e\r\n  \u003cp\u003e백야 이후 처음으로 운행된 대형 구호열차는 수천 명을 안전지역으로 대피시켰다. 그러나 돌아오는 길에 약탈자들의 공격을 받아 승무원 대부분이 사망했다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 두 번째 열차에 장갑판과 기관총을 설치했다.\u003c/p\u003e\r\n  \u003cp\u003e그것이 최초의 장갑철도였다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망력 초기 — 마지막 노선\u003c/h3\u003e\r\n  \u003cp\u003e백야 이후 수십 년 동안 도시는 서로 완전히 고립되어 있었다.\u003c/p\u003e\r\n  \u003cp\u003e통신이 끊기고 지도와 행정구역이 무의미해지면서 이동은 목숨을 거는 일이 되었다. 기존 도로는 모래에 파묻혔고 교량과 터널은 붕괴했다. 황무지에는 약탈자와 변이생물, 통제불능 병기가 돌아다녔다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 살아남은 철로와 도로를 조사하고 운행 가능한 구간을 지도에 기록했다.\u003c/p\u003e\r\n  \u003cp\u003e시설이 파괴된 지역에는 임시 교량과 우회로를 만들었다. 물과 연료를 확보할 수 있는 지점에는 정비소와 방어기지를 세웠다.\u003c/p\u003e\r\n  \u003cp\u003e이 거점들은 ‘나루’라고 불렸다.\u003c/p\u003e\r\n  \u003cp\u003e카론의 열차와 수송대가 도착하는 날이면 주변의 생존자와 상인이 모여들었다. 물자가 거래되고 사람들이 소식을 교환하면서 작은 시장이 형성되었다.\u003c/p\u003e\r\n  \u003cp\u003e일부 나루는 시간이 흐르며 현재의 중계도시로 성장했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 1세기 — 철로전쟁\u003c/h3\u003e\r\n  \u003cp\u003e운송로는 수원과 발전소만큼 중요한 자산이었다.\u003c/p\u003e\r\n  \u003cp\u003e군벌과 도시국가, 약탈자들은 카론의 철로와 나루를 차지하려 했다. 선로를 점령하면 이동하는 모든 화물에서 통행료를 받을 수 있었고, 도시의 보급을 차단할 수도 있었다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 노선을 지키기 위해 자체 무장조직을 창설했다.\u003c/p\u003e\r\n  \u003cp\u003e장갑기관차와 포탑화차, 병력수송차와 선로복구차가 하나의 열차로 결합되었다. 열차는 단순한 운송수단이 아니라 이동하는 요새가 되었다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 자신들의 운송을 방해하는 세력에 물류봉쇄를 시행했다. 적대지역에는 화물을 내리지 않았고 다른 도시에도 해당 세력과 거래하지 말 것을 요구했다.\u003c/p\u003e\r\n  \u003cp\u003e전투에서 카론을 꺾은 군벌도 있었지만, 빼앗은 철도망을 직접 유지하지는 못했다. 부품과 기술자, 연료가 부족해지면 철로는 다시 멈추었다.\u003c/p\u003e\r\n  \u003cp\u003e결국 대부분의 세력은 카론과 협상할 수밖에 없었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 2세기 — 육상선의 탄생\u003c/h3\u003e\r\n  \u003cp\u003e철로만으로는 모든 지역을 연결할 수 없었다.\u003c/p\u003e\r\n  \u003cp\u003e지반이 불안정하거나 모래폭풍이 잦은 지역에서는 선로를 유지하기 어려웠다. 대형 변이생물의 이동과 반복되는 일소 때문에 노선 전체가 사라지는 경우도 있었다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 철도기술과 대형 산업차량을 결합해 육상선을 개발했다.\u003c/p\u003e\r\n  \u003cp\u003e육상선은 수십 개의 거대한 바퀴나 무한궤도로 황무지를 이동하는 초대형 수송차량이다. 화물칸, 거주구역, 정비소, 발전기와 방어포탑을 갖추고 있어 하나의 이동식 정착지처럼 기능한다.\u003c/p\u003e\r\n  \u003cp\u003e소형 카라반보다 느리지만 막대한 물자를 운반할 수 있고, 철도가 없는 지역에도 진입할 수 있었다.\u003c/p\u003e\r\n  \u003cp\u003e육상선의 등장으로 카론은 고정된 철로를 넘어 새로운 교역로를 개척할 수 있게 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 3세기 — 통행권 체계\u003c/h3\u003e\r\n  \u003cp\u003e운송망이 확장되면서 카론은 노선을 체계적으로 관리하기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 안전이 확인된 길을 정식 노선으로 등록하고 위험등급, 보급지점과 예상 소요시간을 공개했다. 운송업자와 카라반은 통행권을 구매해 카론의 정비기지, 지도와 경보정보를 이용할 수 있었다.\u003c/p\u003e\r\n  \u003cp\u003e정식 통행권을 가진 차량에는 카론의 항법신호와 구조서비스가 제공되었다. 약탈이나 사고가 발생하면 가장 가까운 중계기지에서 구조대와 호위부대가 출동했다.\u003c/p\u003e\r\n  \u003cp\u003e반대로 통행권이 없는 차량은 정식 노선에서 보호받지 못했다. 일부 구간에서는 불법통행으로 간주되어 화물압수와 벌금이 부과되었다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 도로를 유지하는 비용을 지불하지 않는 자가 같은 안전을 누릴 수는 없다고 주장했다.\u003c/p\u003e\r\n  \u003cp\u003e비판자들은 카론이 자신들이 만들지도 않은 황무지의 길까지 사유화했다고 반박했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 4세기 — 중계도시의 시대\u003c/h3\u003e\r\n  \u003cp\u003e카론의 주요 정비기지와 나루는 대규모 중계도시로 성장했다.\u003c/p\u003e\r\n  \u003cp\u003e중계도시에는 중앙역, 화물창고, 차량공장, 시장, 숙박시설과 병원이 들어섰다. 여러 돔과 장막 도시, 황무지 카라반의 물자가 이곳에서 교환되었다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 중계도시의 치안과 행정, 통행료와 상거래 규칙을 직접 관리했다.\u003c/p\u003e\r\n  \u003cp\u003e명목상 중계도시는 독립적인 정착지였지만, 전력과 식량, 고용과 방어를 카론에 의존했다. 도시의 책임자인 역무총관은 기업의 임원이자 사실상의 시장 역할을 수행했다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기에 카론은 운송기업에서 노선과 도시를 지배하는 거대한 도로정부로 변했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 5세기 — 블루넷 물류혁명\u003c/h3\u003e\r\n  \u003cp\u003e블루넷이 주요 도시와 기업시설을 연결하면서 카론의 운송체계도 전면적으로 변화했다.\u003c/p\u003e\r\n  \u003cp\u003e화물의 출발과 도착, 위치와 상태가 실시간으로 기록되기 시작했다. 고객은 블루넷을 통해 수송계약을 체결하고 화물칸과 호위등급, 보험을 선택할 수 있었다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스의 위성항법과 기상정보가 카론의 노선관제망에 연결되면서 운행의 정확성과 안전성이 크게 향상되었다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 모든 운송이 디지털화된 것은 아니다.\u003c/p\u003e\r\n  \u003cp\u003e백야의 경험 때문에 카론은 종이운송장, 기계식 봉인과 수동항법을 유지했다. 블루넷이 끊기더라도 열차와 수송대가 목적지를 찾아갈 수 있도록 모든 주요 노선에 아날로그 기록이 보관된다.\u003c/p\u003e\r\n  \u003cp\u003e카론의 기관사와 길잡이는 최신 항법장치뿐 아니라 별과 지형, 바람과 모래의 흔적을 읽는 법을 배운다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 6세기 — 칠정의 성립\u003c/h3\u003e\r\n  \u003cp\u003e초거대 기업들의 산업이 서로 연결되면서 카론의 물류망은 문명 전체의 핵심 기반이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드의 물과 모르포스의 의료품, 케르베로스의 탄약과 아르카디아의 건설자재가 카론의 노선을 통해 이동했다. 솔라리스의 위성과 아르고스의 정보망도 지상에 장비와 인력을 배치하려면 카론의 수송력이 필요했다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 군사적으로 케르베로스보다 약했고 자원도 직접 생산하지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 전쟁이 발생하면 어느 기업의 화물을 먼저 운반하고 어떤 노선을 폐쇄할지 결정할 수 있었다. 이 권한은 전투부대만큼 강력한 영향력을 발휘했다.\u003c/p\u003e\r\n  \u003cp\u003e기업들은 대륙 물류의 완전한 중단을 막기 위해 공동협정을 체결했다. 이는 칠정과 블루 테이블의 기반이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 칠정 내에서 대륙운송, 교역로, 물류거점과 인적 이동을 담당한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e현재 — 멸망 후 700년\u003c/h3\u003e\r\n  \u003cp\u003e현재 카론 인터콘티넨털은 가장 넓은 활동영역을 가진 기업 가운데 하나다.\u003c/p\u003e\r\n  \u003cp\u003e그들의 장갑철도는 돔과 중계도시 사이를 오가며, 육상선은 철로가 없는 황무지를 횡단한다. 소형 카라반과 독립 운송업자들도 카론의 노선정보, 정비소와 통행권을 이용한다.\u003c/p\u003e\r\n  \u003cp\u003e카론의 지도는 세계에서 가장 신뢰할 수 있는 지도다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 지도에는 도시의 위치만 기록되는 것이 아니다. 어느 도시가 거래할 가치가 있는지, 어떤 지역이 위험한지, 누구에게 통행을 허가할지가 함께 표시된다.\u003c/p\u003e\r\n  \u003cp\u003e카론의 정식 노선에 포함된 정착지는 물자와 사람, 소식을 공급받는다. 노선에서 제외된 정착지는 서서히 고립된다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 길을 지배하지 않는다고 말한다.\u003c/p\u003e\r\n  \u003cp\u003e자신들이 유지하는 길에 책임을 질 뿐이라고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 700년 동안 사람들은 카론의 열차가 도착하는 곳을 도시라고 부르고, 도착하지 않는 곳을 폐허라고 부르게 되었다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업 철학\u003c/h2\u003e\r\n  \u003ch3\u003e이동은 생존이다\u003c/h3\u003e\r\n  \u003cp\u003e카론은 고립된 도시는 언젠가 반드시 멸망한다고 믿는다.\u003c/p\u003e\r\n  \u003cp\u003e아무리 자원이 풍부한 정착지도 기계부품과 의약품, 새로운 인력과 정보가 없으면 쇠퇴한다. 문명은 사람들이 움직이고 물자가 순환할 때 유지된다.\u003c/p\u003e\r\n  \u003ch3\u003e화물은 목적지를 가리지 않는다\u003c/h3\u003e\r\n  \u003cp\u003e카론은 정식 계약과 운송규정을 만족한 화물이라면 고객의 정치적 입장과 관계없이 운송한다고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 블루 테이블의 제재, 기업전쟁이나 노선안전을 이유로 계약을 거부하는 경우도 많다.\u003c/p\u003e\r\n  \u003ch3\u003e노선은 약속이다\u003c/h3\u003e\r\n  \u003cp\u003e카론이 발표한 도착시간과 노선은 단순한 일정이 아니라 기업의 명예로 취급된다.\u003c/p\u003e\r\n  \u003cp\u003e열차 한 대가 늦는 것은 사소한 문제가 아니다. 해당 열차를 기다리는 도시의 공장과 병원, 배급소가 모두 멈출 수 있기 때문이다.\u003c/p\u003e\r\n  \u003ch3\u003e움직이는 것은 멈추지 않는다\u003c/h3\u003e\r\n  \u003cp\u003e카론의 차량은 가능한 한 노선 위에서 수리된다.\u003c/p\u003e\r\n  \u003cp\u003e위험지역에서 완전히 정지하는 것은 죽음과 같기 때문에 기관사와 정비사는 차량이 움직이는 동안 부품을 교체하고 선로를 복구하도록 훈련받는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e핵심 산업\u003c/h2\u003e\r\n  \u003ch3\u003e장갑철도\u003c/h3\u003e\r\n  \u003cp\u003e카론을 대표하는 운송수단이다.\u003c/p\u003e\r\n  \u003cp\u003e장갑기관차를 중심으로 화물차, 객차, 정비차, 발전차와 방어화차가 연결된다. 노선의 위험도와 화물에 따라 편성이 달라진다.\u003c/p\u003e\r\n  \u003cp\u003e대형 장갑철도는 수천 명과 막대한 화물을 운송할 수 있으며 소규모 군대에 맞먹는 방어력을 가진다. 열차 내부에는 병원, 정비소, 식당과 임시시장이 운영되기도 한다.\u003c/p\u003e\r\n  \u003cp\u003e일부 장거리 열차의 승무원과 가족은 평생 열차에서 살아간다.\u003c/p\u003e\r\n  \u003ch3\u003e육상선단\u003c/h3\u003e\r\n  \u003cp\u003e철도가 없는 지역을 이동하는 초대형 차량군이다.\u003c/p\u003e\r\n  \u003cp\u003e육상선은 단독으로 운행하지 않는다. 정찰차량, 연료차, 정비차와 호위차량이 하나의 선단을 구성한다.\u003c/p\u003e\r\n  \u003cp\u003e주요 육상선은 고유한 이름과 승무원 문화를 가지고 있다. 도시 주민들에게 유명한 육상선은 이동하는 전설이나 거대한 생물처럼 취급된다.\u003c/p\u003e\r\n  \u003ch3\u003e카라반 운용\u003c/h3\u003e\r\n  \u003cp\u003e카론은 자체 카라반뿐 아니라 독립 상단과 운송업자의 계약을 중개한다.\u003c/p\u003e\r\n  \u003cp\u003e화물의 종류와 위험도에 따라 적절한 차량과 호위인력을 배정하고 통행권, 보험과 경로정보를 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e아이언 랜턴 카라반과 같은 독립 상단은 카론과 협력하면서도 완전히 종속되지는 않는다. 이들은 카론의 대형 노선이 닿지 않는 장막 도시와 소규모 정착지를 연결한다.\u003c/p\u003e\r\n  \u003ch3\u003e화물운송\u003c/h3\u003e\r\n  \u003cp\u003e일반 생활물자부터 군수품, 배양장기와 기업기밀까지 다양한 화물을 운송한다.\u003c/p\u003e\r\n  \u003cp\u003e화물은 위험도와 보안수준에 따라 등급이 분류된다. 고위험 화물에는 전용 화차와 무장경비, 원격추적 장치가 배정된다.\u003c/p\u003e\r\n  \u003ch3\u003e인적수송\u003c/h3\u003e\r\n  \u003cp\u003e기업직원, 이주민, 노동자, 군인과 일반 여행객을 수송한다.\u003c/p\u003e\r\n  \u003cp\u003e객차 등급에 따라 생활환경과 보안, 이동자유가 크게 달라진다. 상위 객차에는 개인실과 식당, 의료시설이 제공되지만 하위 객차는 화물칸을 개조한 집단수송실에 가깝다.\u003c/p\u003e\r\n  \u003cp\u003e난민과 계약노동자를 위한 대규모 수송열차도 운영된다.\u003c/p\u003e\r\n  \u003ch3\u003e노선 개발\u003c/h3\u003e\r\n  \u003cp\u003e탐사대를 파견해 새로운 도로와 철도노선을 개척한다.\u003c/p\u003e\r\n  \u003cp\u003e노선탐사대는 지형, 기후, 수원과 적대세력을 조사한다. 필요하다면 터널과 교량을 건설하거나 위험지역을 우회한다.\u003c/p\u003e\r\n  \u003cp\u003e새로운 노선의 개통은 주변 지역의 경제와 세력관계를 완전히 바꿀 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e차량 생산\u003c/h3\u003e\r\n  \u003cp\u003e카론은 철도차량, 수송트럭, 육상선과 특수운송차량을 자체 생산한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스 차량이 전투에 집중한다면 카론 차량은 장거리 운행과 화물적재, 현장정비를 중시한다.\u003c/p\u003e\r\n  \u003cp\u003e카론 차량의 부품은 가능한 한 여러 세대의 모델과 호환되도록 설계된다.\u003c/p\u003e\r\n  \u003ch3\u003e중계도시 운영\u003c/h3\u003e\r\n  \u003cp\u003e주요 노선의 교차점에 형성된 중계도시와 역을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 창고와 정비소, 숙박시설과 시장을 임대하며 통행료와 화물세를 징수한다. 일부 도시에서는 자체 법정과 무장경비대까지 운영한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e운송 등급\u003c/h2\u003e\r\n  \u003ch3\u003eCommon Freight\u003c/h3\u003e\r\n  \u003cp\u003e식량, 의류, 건축자재와 일반 생활물자를 운송한다.\u003c/p\u003e\r\n  \u003cp\u003e운송비가 저렴하지만 도착시점과 보상범위가 제한적이다.\u003c/p\u003e\r\n  \u003ch3\u003ePriority Freight\u003c/h3\u003e\r\n  \u003cp\u003e공장부품, 의약품과 계약기한이 정해진 화물을 위한 우선운송 등급이다.\u003c/p\u003e\r\n  \u003cp\u003e일반 화물보다 먼저 적재되며 노선변경 시에도 우선권을 가진다.\u003c/p\u003e\r\n  \u003ch3\u003eSecure Freight\u003c/h3\u003e\r\n  \u003cp\u003e무기, 귀중품과 기업기밀을 위한 보안운송 등급이다.\u003c/p\u003e\r\n  \u003cp\u003e장갑화차, 무장경비와 실시간 위치추적이 제공된다.\u003c/p\u003e\r\n  \u003ch3\u003eVital Freight\u003c/h3\u003e\r\n  \u003cp\u003e생체장기, 백신, 긴급 정수부품처럼 배송지연이 대규모 인명피해로 이어질 수 있는 화물이다.\u003c/p\u003e\r\n  \u003cp\u003e다른 계약보다 우선하며 필요하다면 기존 운행계획을 변경한다.\u003c/p\u003e\r\n  \u003ch3\u003eBlack Freight\u003c/h3\u003e\r\n  \u003cp\u003e공식 운송목록에 기록되지 않는 최고기밀 화물이다.\u003c/p\u003e\r\n  \u003cp\u003e내용물과 목적지는 일부 승무원에게도 공개되지 않는다. 블루 테이블과 칠정 최고위층의 특별인가가 필요하다고 알려져 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업 구조\u003c/h2\u003e\r\n  \u003cp\u003e카론은 물류기업과 철도행정기관, 도로정부가 결합된 구조를 가지고 있다.\u003c/p\u003e\r\n  \u003ch3\u003e노선이사회\u003c/h3\u003e\r\n  \u003cp\u003e대형 노선의 개통과 폐쇄, 중계도시의 운영권과 기업 간 운송협정을 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e주요 철도노선과 육상선단을 대표하는 임원, 중계도시의 책임자들이 참여한다.\u003c/p\u003e\r\n  \u003ch3\u003e대표운송관\u003c/h3\u003e\r\n  \u003cp\u003e카론의 최고경영자이자 모든 정식 노선의 최종 책임자다.\u003c/p\u003e\r\n  \u003cp\u003e기업 내부에서는 대표이사보다 대륙 전체의 교통을 조정하는 최고 역무관에 가까운 존재로 취급된다.\u003c/p\u003e\r\n  \u003ch3\u003e대륙운송총괄\u003c/h3\u003e\r\n  \u003cp\u003e철도, 육상선과 카라반 운송을 통합적으로 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e대규모 재난과 전쟁이 발생하면 민간운송을 중단하고 기업 전체를 비상수송체제로 전환할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e철도·육상선 부문\u003c/h3\u003e\r\n  \u003cp\u003e장갑철도, 육상선단과 차량생산을 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e카론의 물리적인 운송능력과 생산시설을 관리하는 핵심 부문이다.\u003c/p\u003e\r\n  \u003ch3\u003e카라반·화물 부문\u003c/h3\u003e\r\n  \u003cp\u003e독립 카라반 계약, 화물관리와 인적수송을 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e고객과 가장 직접적으로 접촉하며 운송료와 보험, 보안등급을 결정한다.\u003c/p\u003e\r\n  \u003ch3\u003e노선·거점 부문\u003c/h3\u003e\r\n  \u003cp\u003e신규 노선을 개척하고 중계도시, 정비기지와 노선보안대를 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e기업의 활동영역을 실질적으로 확장하는 부문이다.\u003c/p\u003e\r\n  \u003ch3\u003e대표운송관 직속실\u003c/h3\u003e\r\n  \u003cp\u003e최고등급 화물, 비공개 노선과 칠정의 긴급수송을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e정식 운행기록에 존재하지 않는 열차와 노선을 운용한다는 의혹이 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e카론의 승무원\u003c/h2\u003e\r\n  \u003ch3\u003e기관사\u003c/h3\u003e\r\n  \u003cp\u003e열차와 육상선의 운행을 책임진다.\u003c/p\u003e\r\n  \u003cp\u003e단순한 조종사가 아니라 노선의 최종 현장책임자다. 통신이 끊겼을 때는 운행중단과 우회, 교전 여부를 독자적으로 결정할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e차장\u003c/h3\u003e\r\n  \u003cp\u003e승객과 화물, 승무원과 보안을 총괄한다.\u003c/p\u003e\r\n  \u003cp\u003e대형 열차의 차장은 작은 도시의 행정관과 같은 권한을 행사한다.\u003c/p\u003e\r\n  \u003ch3\u003e길잡이\u003c/h3\u003e\r\n  \u003cp\u003e지형, 날씨와 위험지역을 파악해 수송대를 안내한다.\u003c/p\u003e\r\n  \u003cp\u003e위성항법이 불가능한 상황에서는 별과 지형, 모래의 흐름을 읽어 경로를 결정한다.\u003c/p\u003e\r\n  \u003ch3\u003e레일워커\u003c/h3\u003e\r\n  \u003cp\u003e선로를 점검하고 이동 중에 파손구간을 복구하는 기술자다.\u003c/p\u003e\r\n  \u003cp\u003e열차보다 먼저 위험지역에 진입하기 때문에 카론 내에서도 사망률이 높은 직종이다.\u003c/p\u003e\r\n  \u003ch3\u003e화물감정관\u003c/h3\u003e\r\n  \u003cp\u003e화물의 내용과 위험도를 확인하고 운송등급을 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e밀수품, 폭발물, 감염성 물질과 위조된 운송장을 탐지한다.\u003c/p\u003e\r\n  \u003ch3\u003e노선보안대\u003c/h3\u003e\r\n  \u003cp\u003e열차와 중계도시, 철로를 방어하는 무장조직이다.\u003c/p\u003e\r\n  \u003cp\u003e약탈자 격퇴, 인질구출, 화물회수와 선로 주변의 위험요소 제거를 담당한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 기술\u003c/h2\u003e\r\n  \u003ch3\u003e스틱스 관제망\u003c/h3\u003e\r\n  \u003cp\u003e열차, 육상선과 중계기지의 위치를 통합적으로 관리하는 물류관제체계다.\u003c/p\u003e\r\n  \u003cp\u003e기상, 노선상태, 화물 우선순위와 연료를 분석해 가장 효율적인 운행계획을 제시한다.\u003c/p\u003e\r\n  \u003cp\u003e명칭은 죽은 자들이 건너는 강인 스틱스에서 유래했다.\u003c/p\u003e\r\n  \u003ch3\u003e페리맨 항법장치\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스의 위성신호, 지상표식과 관성항법을 결합한 장거리 항법장치다.\u003c/p\u003e\r\n  \u003cp\u003e블루넷과 위성신호가 모두 끊겨도 일정 기간 현재 위치와 이동방향을 계산할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e모듈러 화차체계\u003c/h3\u003e\r\n  \u003cp\u003e객차, 화물차, 병원차와 방어화차를 임무에 따라 자유롭게 조합하는 시스템이다.\u003c/p\u003e\r\n  \u003cp\u003e동일한 연결규격을 수백 년 동안 유지해 구형 차량과 최신 차량을 함께 사용할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e레일포지\u003c/h3\u003e\r\n  \u003cp\u003e현장에서 철로와 차량부품을 생산하는 이동식 정비공장이다.\u003c/p\u003e\r\n  \u003cp\u003e파손된 금속과 차량 잔해를 재활용해 선로와 바퀴, 장갑판을 제작할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e웨이크 실드\u003c/h3\u003e\r\n  \u003cp\u003e육상선이 모래폭풍과 고속 파편을 견딜 수 있도록 차량 전면에 형성하는 방호체계다.\u003c/p\u003e\r\n  \u003cp\u003e물리장갑과 전자기 편향장치를 결합한다.\u003c/p\u003e\r\n  \u003ch3\u003e블랙박스 봉인\u003c/h3\u003e\r\n  \u003cp\u003e화물칸의 개봉기록과 환경상태를 저장하는 보안장치다.\u003c/p\u003e\r\n  \u003cp\u003e허가받지 않은 접근이 발생하면 화물칸이 봉쇄되며 위험물은 자동으로 격리된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 시설\u003c/h2\u003e\r\n  \u003ch3\u003e카론 터미널\u003c/h3\u003e\r\n  \u003cp\u003e카론의 본사이자 대륙 최대의 중앙역이다.\u003c/p\u003e\r\n  \u003cp\u003e수십 개의 철도노선과 지하화물망이 연결되어 있으며, 차량공장과 거대한 분류창고, 기업행정구역을 갖추고 있다.\u003c/p\u003e\r\n  \u003cp\u003e터미널 내부는 하나의 도시처럼 작동한다. 수많은 노동자와 승무원, 상인과 가족이 이곳에서 살아간다.\u003c/p\u003e\r\n  \u003ch3\u003e스틱스 야드\u003c/h3\u003e\r\n  \u003cp\u003e장갑철도와 육상선을 생산하고 수리하는 최대 규모의 차량기지다.\u003c/p\u003e\r\n  \u003cp\u003e완전히 분해된 기관차를 새 차량으로 재조립할 수 있으며 백야 이전의 차량도 여전히 정비된다.\u003c/p\u003e\r\n  \u003ch3\u003e나루도시\u003c/h3\u003e\r\n  \u003cp\u003e카론의 주요 중계도시를 부르는 통칭이다.\u003c/p\u003e\r\n  \u003cp\u003e각 나루도시는 주변 지역의 물류와 시장, 고용을 지배한다. 역무총관이 도시행정을 겸하는 경우가 많다.\u003c/p\u003e\r\n  \u003ch3\u003e데드 레일\u003c/h3\u003e\r\n  \u003cp\u003e백야 이후 폐쇄되었지만 철로가 남아 있는 금지구역이다.\u003c/p\u003e\r\n  \u003cp\u003e통제불능 열차, 방사능과 변이생물 때문에 정식 운행이 금지되어 있다. 밀수업자와 독립 카라반은 추적을 피하기 위해 이 노선을 이용하기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e아케론 터널\u003c/h3\u003e\r\n  \u003cp\u003e대륙의 주요 산맥과 지하도시를 연결하는 초장거리 터널망이다.\u003c/p\u003e\r\n  \u003cp\u003e일부 구간은 백야 이전에 건설되었으며 정확한 전체 구조는 카론도 파악하지 못한 것으로 알려져 있다.\u003c/p\u003e\r\n  \u003ch3\u003e제로 플랫폼\u003c/h3\u003e\r\n  \u003cp\u003e정식 역무지도에 존재하지 않는 승강장에 붙은 이름이다.\u003c/p\u003e\r\n  \u003cp\u003e칠정의 비밀화물과 정체불명의 승객을 태우는 열차가 이곳에서 출발한다는 소문이 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e직원 문화\u003c/h2\u003e\r\n  \u003cp\u003e카론의 직원들은 기업보다 노선과 차량에 더 강한 소속감을 느끼는 경우가 많다.\u003c/p\u003e\r\n  \u003cp\u003e같은 열차와 육상선에서 오랫동안 생활한 승무원은 가족에 가까운 공동체를 형성한다. 지상시설의 임원보다 현장 기관사와 차장의 판단을 더 신뢰하기도 한다.\u003c/p\u003e\r\n  \u003cp\u003e기업 내부에서는 시간과 약속, 현장경험을 중요하게 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e운송계약을 지키는 것은 카론의 가장 중요한 명예다. 그러나 화물보다 사람을 구할 것인지, 계약된 물자를 지키기 위해 정착지를 지나칠 것인지는 언제나 현장책임자의 판단에 달려 있다.\u003c/p\u003e\r\n  \u003cp\u003e오랜 기간 운행한 기관사와 길잡이는 단순한 직원이 아니라 노선의 살아 있는 기억으로 존경받는다.\u003c/p\u003e\r\n  \u003cp\u003e카론 내부에서 가장 널리 사용되는 문구는 다음과 같다.\u003c/p\u003e\r\n  \u003cblockquote\u003e목적지가 남아 있는 한, 운행은 끝나지 않는다.\u003c/blockquote\u003e\r\n\r\n  \u003ch2\u003e채용과 복지\u003c/h2\u003e\r\n  \u003cp\u003e카론은 기관사, 운전사, 정비사, 항법사, 화물관리자, 경비원과 건설노동자를 폭넓게 채용한다.\u003c/p\u003e\r\n  \u003cp\u003e돔 시티 출신뿐 아니라 장막 도시와 황무지 출신의 채용비율도 높다. 황무지의 지형과 생존방식을 이해하는 인력이 반드시 필요하기 때문이다.\u003c/p\u003e\r\n  \u003cp\u003e정규직과 가족에게는 다음과 같은 혜택이 제공된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e중계도시 또는 이동주거시설의 거주권\u003c/li\u003e\r\n    \u003cli\u003e카론 노선의 무료·할인 이용권\u003c/li\u003e\r\n    \u003cli\u003e물과 식량의 안정적인 배급\u003c/li\u003e\r\n    \u003cli\u003e운행 중 의료와 구조지원\u003c/li\u003e\r\n    \u003cli\u003e직원 자녀의 기술교육\u003c/li\u003e\r\n    \u003cli\u003e장기근속자의 차량 또는 카라반 면허\u003c/li\u003e\r\n    \u003cli\u003e사고 및 실종 시 가족보상\u003c/li\u003e\r\n    \u003cli\u003e퇴직 후 역무·정비직 배치\u003c/li\u003e\r\n    \u003cli\u003e개인화물의 우선운송권\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e승무원은 안정적인 배급을 받지만 장기간 가족과 떨어져 지낸다. 열차에서 태어나 평생 같은 노선에서 살아가는 사람도 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e계층별 인식\u003c/h2\u003e\r\n  \u003ch3\u003e돔 시티 상류층\u003c/h3\u003e\r\n  \u003cp\u003e카론을 안정적인 물류와 여행서비스를 제공하는 기반기업으로 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e고급 객차와 전용열차를 이용하기 때문에 일반 수송구역의 열악한 환경이나 위험을 체감하지 못하는 경우가 많다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 시티 일반 시민\u003c/h3\u003e\r\n  \u003cp\u003e다른 도시와 황무지로 나갈 수 있는 거의 유일한 안전한 이동수단으로 인식한다.\u003c/p\u003e\r\n  \u003cp\u003e카론의 역은 여행과 이주의 출발점이지만, 높은 운임과 복잡한 이동허가가 불만의 대상이다.\u003c/p\u003e\r\n  \u003ch3\u003e장막 도시 주민\u003c/h3\u003e\r\n  \u003cp\u003e카론 열차가 도착하는 날은 시장 전체가 움직이는 날이다.\u003c/p\u003e\r\n  \u003cp\u003e물자와 약품, 외부소식이 들어오기 때문에 중요한 생명줄로 여긴다. 반면 카론이 노선을 변경하면 도시가 순식간에 쇠퇴할 수 있어 강한 불안과 적개심도 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003e황무지인과 카라반\u003c/h3\u003e\r\n  \u003cp\u003e카론의 정비소와 지도, 기상정보를 높게 평가하면서도 통행료와 노선독점을 싫어한다.\u003c/p\u003e\r\n  \u003cp\u003e독립 카라반은 카론이 다루지 않는 소규모 노선을 개척하며 살아간다. 카론은 이들을 협력자로 인정하면서도 통제되지 않는 경쟁자로 경계한다.\u003c/p\u003e\r\n  \u003ch3\u003e다른 기업\u003c/h3\u003e\r\n  \u003cp\u003e카론을 반드시 필요한 물류 파트너로 취급한다.\u003c/p\u003e\r\n  \u003cp\u003e어떤 기업도 카론이 자신들의 화물을 후순위로 미루거나 특정 노선을 폐쇄하는 상황을 원하지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e다른 세력과의 관계\u003c/h2\u003e\r\n  \u003ch3\u003eNEREID HYDROSYSTEMS\u003c/h3\u003e\r\n  \u003cp\u003e카론은 네레이드의 정제수와 대형 저장탱크를 대륙 전역으로 운송한다.\u003c/p\u003e\r\n  \u003cp\u003e철도관이 설치되지 않은 지역에서는 카론의 장갑열차와 육상선이 사실상 유일한 대량 급수수단이다. 물 수송대는 가장 가치가 높은 화물 중 하나이기 때문에 강력한 호위를 받는다.\u003c/p\u003e\r\n  \u003ch3\u003eSOLARIS ORBITAL INDUSTRIES\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스는 카론에 위성항법, 기상정보와 일소경보를 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 솔라리스의 발사기지와 관제소에 연료와 장비, 궤도부품을 운송한다. 통신이 끊기더라도 운행을 계속할 수 있도록 카론은 독립적인 항법체계를 유지한다.\u003c/p\u003e\r\n  \u003ch3\u003eARCADIA HABITAT\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아의 돔 건설에 필요한 자재와 인력을 카론이 운송한다.\u003c/p\u003e\r\n  \u003cp\u003e신규 돔이 완성되면 가장 먼저 카론의 중앙역과 화물터미널이 연결된다. 두 기업이 공동으로 건설한 도시에서는 돔 외부의 물류구역을 카론이 직접 관리하기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003eMORPHOS BIODYNE\u003c/h3\u003e\r\n  \u003cp\u003e모르포스의 배양장기와 의약품, 생체시료는 카론의 특수화물로 운송된다.\u003c/p\u003e\r\n  \u003cp\u003e시간과 온도에 민감한 화물이기 때문에 전용 생명유지 화차와 보안요원이 사용된다.\u003c/p\u003e\r\n  \u003ch3\u003eCERBERUS DEFENSE GROUP\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 카론의 수송대와 중계도시에 무기와 방어장비를 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 케르베로스의 병기와 탄약을 전장으로 운송한다. 대규모 전쟁이 발생하면 일부 민간 노선이 군수열차 전용으로 전환된다.\u003c/p\u003e\r\n  \u003cp\u003e양사는 이동식 중장갑 플랫폼 시장에서 경쟁하기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003eARGOS SECURE NETWORKS\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 카론의 화물과 승객을 감시하고 밀수, 테러와 기업공작을 추적한다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 이동기록과 화물정보 일부를 제공하지만, 고객의 운송기밀을 이유로 아르고스의 무제한 접근을 거부한다.\u003c/p\u003e\r\n  \u003ch3\u003eLAZARUS MEDICAL RESPONSE\u003c/h3\u003e\r\n  \u003cp\u003e라자루스의 구조차량과 의료물자를 우선적으로 운송한다.\u003c/p\u003e\r\n  \u003cp\u003e대형 재난이 발생하면 카론의 객차와 화물차가 이동식 병원과 대피열차로 전환된다.\u003c/p\u003e\r\n  \u003ch3\u003eBLACKTOP UNION\u003c/h3\u003e\r\n  \u003cp\u003e블랙탑 유니언은 독립 운전사와 정비사, 소규모 운송업자를 대표한다.\u003c/p\u003e\r\n  \u003cp\u003e카론과 경쟁하면서도 대형 노선의 마지막 구간을 담당하는 협력관계다. 운임, 통행료와 정비소 사용권을 두고 충돌이 잦다.\u003c/p\u003e\r\n  \u003ch3\u003eSUNDOGS\u003c/h3\u003e\r\n  \u003cp\u003e선독스는 카론의 수송대를 습격하는 대표적인 황무지 차량갱 연합이다.\u003c/p\u003e\r\n  \u003cp\u003e일부 팩은 약탈자지만, 다른 팩은 위험지역에서 비공식 호위와 길안내를 제공한다. 카론이 특정 선독스 팩과 비밀 통행협정을 맺고 있다는 소문도 있다.\u003c/p\u003e\r\n  \u003ch3\u003eIRON LANTERN CARAVAN\u003c/h3\u003e\r\n  \u003cp\u003e아이언 랜턴은 장막 도시와 소규모 정착지를 오가는 독립 상단이다.\u003c/p\u003e\r\n  \u003cp\u003e카론의 대형 철도와 육상선이 주요 도시와 거점을 연결한다면, 아이언 랜턴은 그 노선에서 벗어난 작은 시장과 외곽지역까지 물자를 운반한다.\u003c/p\u003e\r\n  \u003cp\u003e양측은 화물과 노선정보를 거래하는 협력관계지만, 아이언 랜턴은 카론의 완전한 종속계약을 거부하고 독립적인 장부와 교역망을 유지한다.\u003c/p\u003e\r\n  \u003ch3\u003eTHE BLUE TABLE\u003c/h3\u003e\r\n  \u003cp\u003e블루 테이블은 기업 간 운송 우선순위, 노선봉쇄와 긴급수송을 조정한다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 블루 테이블의 결정을 따르지만 현장의 위험을 이유로 운행을 거부할 수 있는 제한적인 권한을 보유한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e사회공헌과 홍보\u003c/h2\u003e\r\n  \u003cp\u003e카론은 자신들을 “세계를 다시 연결한 기업”이라고 소개한다.\u003c/p\u003e\r\n  \u003cp\u003e고립된 정착지에 구호열차를 보내고, 장막 도시의 도로와 교량을 복구하며, 실종된 카라반을 구조한다. 대형 재난이 발생하면 화물열차를 대피열차와 이동식 병원으로 전환한다.\u003c/p\u003e\r\n  \u003cp\u003e기업의 홍보영상에는 폐허를 가로지르는 장갑열차와 그것을 기다리는 시민들이 반복적으로 등장한다.\u003c/p\u003e\r\n  \u003cp\u003e카론이 도착하면 식량과 물, 약품과 소식이 함께 들어온다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 무료 구호운송이 끝난 뒤 해당 정착지가 카론의 장기 통행계약에 편입되는 사례가 많다. 기업은 지속적인 노선유지를 위해 불가피하다고 설명한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e논란과 비판\u003c/h2\u003e\r\n  \u003ch3\u003e노선 독점\u003c/h3\u003e\r\n  \u003cp\u003e카론은 철로와 도로를 직접 유지한다는 이유로 통행료와 운송규칙을 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e비판자들은 기업이 자연적으로 형성된 길과 백야 이전의 공공철도까지 사유화했다고 주장한다.\u003c/p\u003e\r\n  \u003ch3\u003e물류봉쇄\u003c/h3\u003e\r\n  \u003cp\u003e계약을 위반하거나 블루 테이블의 제재를 받은 도시는 카론의 정식 노선에서 제외될 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e봉쇄가 시작되면 식량과 의약품, 기계부품의 가격이 폭등한다. 군사공격 없이도 도시 전체를 굴복시킬 수 있는 수단이다.\u003c/p\u003e\r\n  \u003ch3\u003e운송 우선순위\u003c/h3\u003e\r\n  \u003cp\u003e카론은 긴급도와 계약등급에 따라 화물 우선순위를 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e고액 기업화물이 일반 시민의 식량과 의약품보다 먼저 운송되었다는 사례가 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003e인적수송의 차별\u003c/h3\u003e\r\n  \u003cp\u003e승객은 지불능력과 신분에 따라 다른 객차에 탑승한다.\u003c/p\u003e\r\n  \u003cp\u003e상위 객차는 안전하고 쾌적하지만 하위 객차는 과밀하고 의료와 환기시설이 부족하다. 계약노동자는 화물과 다르지 않게 운송된다는 비판을 받는다.\u003c/p\u003e\r\n  \u003ch3\u003e이동기록 감시\u003c/h3\u003e\r\n  \u003cp\u003e카론은 승객과 화물의 출발지, 목적지와 이동경로를 기록한다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 사고와 범죄를 예방하기 위한 자료라고 주장한다. 그러나 이 기록은 개인과 조직의 활동범위를 추적할 수 있는 강력한 정보다.\u003c/p\u003e\r\n  \u003ch3\u003e독립 운송업자 압박\u003c/h3\u003e\r\n  \u003cp\u003e카론이 통행료와 정비소 사용료를 인상해 독립 카라반을 종속시키려 한다는 비판이 있다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 정식 노선의 안전을 유지하려면 모든 이용자가 비용을 부담해야 한다고 반박한다.\u003c/p\u003e\r\n  \u003ch3\u003e위험화물 은폐\u003c/h3\u003e\r\n  \u003cp\u003e카론의 수송사고 중 일부는 화물의 정체가 공개되지 않은 채 처리된다.\u003c/p\u003e\r\n  \u003cp\u003e감염성 생체물질, 실험병기나 백야 이전의 유물을 운반하다 사고가 발생했다는 의혹이 존재한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e확인되지 않은 소문\u003c/h2\u003e\r\n  \u003cp\u003e카론이 정식 지도에 표시되지 않은 비밀노선을 운영한다는 소문은 오래전부터 존재했다.\u003c/p\u003e\r\n  \u003cp\u003e이른바 ‘검은 노선’은 블루 테이블과 칠정 최고위층만 사용할 수 있으며, 공식 검문과 도시행정을 거치지 않고 대륙의 중요시설을 연결한다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e해당 노선에서는 일반적인 화물만 운송되는 것이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e신분이 삭제된 인물, 기업의 실험체, 전략병기와 백야 이전의 유물도 이동한다는 이야기가 있다.\u003c/p\u003e\r\n  \u003cp\u003e아케론 터널의 가장 깊은 구간에 백야 당시 멈춘 초대형 열차가 존재한다는 소문도 있다. 열차는 봉인된 채 700년 동안 동일한 비상신호를 송출하고 있다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 여러 차례 회수대를 보냈지만 누구도 돌아오지 못했다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e가장 기이한 소문은 ‘마지막 승객’에 관한 것이다.\u003c/p\u003e\r\n  \u003cp\u003e카론의 최상위 운행기록에는 출발지도 목적지도 존재하지 않는 승객 한 명이 등록되어 있으며, 기업은 700년 동안 그 승객을 위해 특정 좌석을 비워두고 있다는 것이다.\u003c/p\u003e\r\n  \u003cp\u003e어떤 열차에 좌석이 존재하는지는 알려지지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e일부 기관사들은 노선 위에서 존재하지 않는 열차의 불빛을 본다고 증언한다.\u003c/p\u003e\r\n  \u003cp\u003e그 열차는 아무런 소리도 내지 않은 채 폐쇄된 선로를 지나가며, 항상 카론의 정식 열차보다 한 역 앞에 도착한다고 한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업이 가진 힘\u003c/h2\u003e\r\n  \u003cp\u003e카론의 힘은 목적지를 결정하는 데서 나온다.\u003c/p\u003e\r\n  \u003cp\u003e물과 식량, 무기와 의약품이 존재해도 필요한 장소에 도착하지 못하면 아무런 가치가 없다. 공장에 부품이 들어오지 않으면 생산이 멈추고, 도시에서 사람이 빠져나갈 수 없으면 피난은 불가능하다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 누가 이동할 수 있는지, 어떤 화물이 먼저 도착할지, 어느 도시가 세계와 연결될지를 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 도시를 직접 통치하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 열차가 멈추면 시장이 멈추고, 노선이 끊기면 사람도 소식도 사라진다. 카론이 지도를 수정하면 번영하던 중계도시가 쇠퇴하고 이름 없는 정착지가 새로운 교역의 중심이 된다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드가 세계의 물을 흐르게 하고 솔라리스가 에너지를 전달한다면, 카론은 그 모든 것을 필요한 곳으로 움직인다.\u003c/p\u003e\r\n  \u003cp\u003e그들의 노선은 세계의 혈관이다.\u003c/p\u003e\r\n  \u003cp\u003e그리고 카론은 그 혈관의 흐름을 언제든 바꿀 수 있다.\u003c/p\u003e\r\n\u003c/section\u003e\r\n";
window.FACTION_INFO.argos = "\u003csection class=\"faction-detail\"\u003e\r\n  \u003ch2\u003e기업 개요\u003c/h2\u003e\r\n  \u003cp class=\"faction-quote\"\u003e“보이지 않는 것은 존재하지 않는 것이 아니다.”\u003c/p\u003e\r\n  \u003cp\u003e아르고스 시큐어 네트워크는 정보수집, 방첩, 신원관리, 사이버보안과 비밀공작을 담당하는 초거대 정보기업이다. 2102년 백야로 국가의 행정망과 통신체계가 붕괴한 이후, 살아남은 정보기관과 보안기업, 기록보관소와 통신기술자들을 흡수하며 성장했다.\u003c/p\u003e\r\n  \u003cp\u003e오늘날 아르고스는 칠정의 중앙정보기관에 가장 가까운 조직이다. 돔 시티의 시민기록, 기업 간 통신, 블루넷 활동과 황무지의 세력변화를 감시하고, 칠정의 존속을 위협하는 인물과 조직을 추적한다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스의 업무는 단순한 정보수집에 그치지 않는다. 필요하다면 여론과 기록을 조작하고, 새로운 신분을 만들어 사람을 조직 안에 침투시킨다. 반대로 특정 인물의 시민권과 경력, 계좌와 존재기록을 제거해 사회적으로 존재하지 않는 사람으로 만들기도 한다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 가장 많은 무기를 생산하지 않는다. 가장 넓은 도시를 소유하지도, 물과 전력을 직접 공급하지도 않는다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 누가 무기를 구매했고, 어느 도시의 물이 부족하며, 어떤 기업의 전력이 언제 끊길지를 알고 있다.\u003c/p\u003e\r\n  \u003cp\u003e그리고 때로는 그 일이 발생하기 전부터 알고 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기본 정보\u003c/h2\u003e\r\n  \u003ctable class=\"data-table faction-info-table\"\u003e\r\n    \u003ctbody\u003e\r\n      \u003ctr\u003e\u003cth\u003e정식 명칭\u003c/th\u003e\u003ctd\u003eARGOS SECURE NETWORKS\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e통칭\u003c/th\u003e\u003ctd\u003e아르고스\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e기업 분류\u003c/th\u003e\u003ctd\u003e정보·보안·방첩·신원관리 기업\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 산업\u003c/th\u003e\u003ctd\u003e정보수집, 분석, 방첩, 기업보안, 시민신원 관리\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e전략 산업\u003c/th\u003e\u003ctd\u003e비밀공작, 여론조작, 사이버전, 인공지능 통제\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 고객\u003c/th\u003e\u003ctd\u003e칠정, 돔 행정부, 기업간부, 공식 치안기관\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e상징 색상\u003c/th\u003e\u003ctd\u003e청색, 백색, 암청색\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표적인 인식\u003c/th\u003e\u003ctd\u003e모든 것을 바라보지만 자신은 드러내지 않는 감시자\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e칠정 내 역할\u003c/th\u003e\u003ctd\u003e정보질서, 방첩과 블루넷 보안 유지\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e본사 성격\u003c/th\u003e\u003ctd\u003e정보기관, 데이터센터와 비밀작전본부가 결합된 요새\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표 자산\u003c/th\u003e\u003ctd\u003e시민신원망, 블루넷 감찰권, 정보원과 기밀기록\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e공식 지휘기관\u003c/th\u003e\u003ctd\u003e중앙정보총국\u003c/td\u003e\u003c/tr\u003e\r\n    \u003c/tbody\u003e\r\n  \u003c/table\u003e\r\n\r\n  \u003ch2\u003e기업의 역사\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e백야 이전 — 감시산업의 성장\u003c/h3\u003e\r\n  \u003cp\u003e아르고스의 기원은 21세기 후반에 활동하던 사이버보안 기업, 신원인증 회사, 데이터 분석업체와 민간 정보기관에서 시작되었다.\u003c/p\u003e\r\n  \u003cp\u003e당시 인간의 금융, 의료, 교육과 사회활동은 대부분 전산망에 기록되고 있었다. 국가와 기업들은 범죄와 테러, 산업공작을 막기 위해 방대한 개인정보와 통신자료를 분석했다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스의 전신 기업들은 얼굴과 생체정보, 소비기록과 위치정보를 결합해 개인의 신원을 확인하는 기술을 개발했다. 인공지능은 수십억 명의 행동을 분석해 범죄와 사회불안을 예측했다.\u003c/p\u003e\r\n  \u003cp\u003e처음에는 안전과 편의를 위한 서비스였다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 데이터가 축적되면서 기업은 개인이 누구인지 확인하는 것을 넘어 앞으로 무엇을 할 가능성이 있는지 판단하기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e여러 국가의 정보기관은 아르고스의 전신 기업과 계약했다. 정부는 법적인 권한을 제공했고 기업은 정부가 보유하지 못한 기술과 데이터를 제공했다.\u003c/p\u003e\r\n  \u003cp\u003e국가정보기관과 민간 보안기업의 경계는 점차 사라졌다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e2102년 — 백야\u003c/h3\u003e\r\n  \u003cp\u003e백야가 발생하자 세계의 통신과 기록체계는 순식간에 붕괴했다.\u003c/p\u003e\r\n  \u003cp\u003e위성망과 데이터센터가 파괴되었고, 행정기관과 금융망이 기능을 상실했다. 시민의 출생과 재산, 국적과 범죄기록을 증명하던 전산자료 상당수가 사라졌다.\u003c/p\u003e\r\n  \u003cp\u003e수많은 사람이 신분을 잃었다.\u003c/p\u003e\r\n  \u003cp\u003e죽은 사람의 계정이 살아 있었고, 살아남은 사람은 사망자로 기록되었다. 조작된 대피명령과 재난방송이 퍼졌으며, 통제권을 잃은 인공지능과 군사망은 서로 모순되는 정보를 전송했다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스의 전신 조직들은 지하 데이터센터와 독립형 기록보관소를 봉쇄했다. 살아남은 분석관과 보안요원들은 통신망을 차단하고 보존할 가치가 있는 자료를 분류했다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 모든 사람을 구할 수 없었다.\u003c/p\u003e\r\n  \u003cp\u003e대신 기록을 구했다.\u003c/p\u003e\r\n  \u003cp\u003e백야 이전의 시민자료, 기업기밀, 군사정보와 기반시설 지도 중 일부가 아르고스의 저장고에 보존되었다.\u003c/p\u003e\r\n  \u003cp\u003e이 기록은 훗날 새로운 도시와 기업의 권력을 결정하는 기반이 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망력 초기 — 기록을 가진 자\u003c/h3\u003e\r\n  \u003cp\u003e백야 이후 수십 년 동안 사람들은 자신이 누구인지 증명할 방법을 잃었다.\u003c/p\u003e\r\n  \u003cp\u003e국가와 정부가 무너진 상황에서 신분은 단순한 이름이 아니었다. 어느 생존시설에 들어갈 수 있는지, 배급을 받을 수 있는지, 범죄자인지 기술자인지를 결정하는 생존자격이었다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 보존된 자료와 생체정보를 이용해 사람들의 신원을 확인했다.\u003c/p\u003e\r\n  \u003cp\u003e기술자, 군인, 의료인과 기반시설 관리자의 경력을 증명했고 생존도시가 필요한 인재를 구분했다. 반대로 위험인물, 전쟁범죄자와 시설파괴범의 기록도 제공했다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스의 인증을 받은 사람은 도시의 문을 통과할 수 있었다.\u003c/p\u003e\r\n  \u003cp\u003e인증을 받지 못한 사람은 과거가 불분명한 위험인물로 취급되었다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 단순히 정보를 보유한 조직에서 인간의 과거를 인정할 권한을 가진 기관으로 성장했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 1세기 — 최초의 정보망\u003c/h3\u003e\r\n  \u003cp\u003e도시와 정착지 사이의 통신이 조금씩 복구되면서 아르고스는 독립된 정보망을 구축하기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e초기의 통신은 유선망과 단거리 무전, 암호화된 데이터 운반차량에 의존했다. 정보요원들은 도시와 황무지를 오가며 기록을 수집했고 물리적인 저장장치에 담아 본부로 운반했다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 각 지역의 인구, 수원, 군사력과 정치상황을 분석했다. 이러한 정보는 교역과 전쟁, 이주와 도시건설에 막대한 영향을 주었다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 생존도시에 정보를 제공하는 대가로 기록 접근권과 감찰권을 요구했다.\u003c/p\u003e\r\n  \u003cp\u003e도시는 아르고스의 정보가 필요했지만 자신들의 모든 활동이 기업에 기록되는 것을 두려워했다.\u003c/p\u003e\r\n  \u003cp\u003e이 상호불신은 현재까지 이어지고 있다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 2세기 — 보이지 않는 전쟁\u003c/h3\u003e\r\n  \u003cp\u003e대형 도시와 신흥기업이 성장하면서 정보전의 중요성이 높아졌다.\u003c/p\u003e\r\n  \u003cp\u003e적의 군대가 움직이기 전에 보급로를 파악하고, 기업간부를 매수하며, 시민들 사이에 거짓정보를 퍼뜨리는 것이 직접적인 전투보다 효율적이었다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 정찰과 분석을 넘어 비밀공작에 개입하기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e요원을 적대조직에 침투시키고 가짜 신분과 경력을 제공했다. 기업 내부의 갈등을 조장하거나 특정 인물을 실각시키고, 필요한 경우 아무런 흔적도 남기지 않은 채 제거했다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 자신들의 공작이 더 큰 전쟁을 막기 위한 예방조치라고 주장했다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 이 시기부터 대형 분쟁이나 정권교체의 뒤에는 아르고스가 있다는 소문이 퍼지기 시작했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 3세기 — 신원질서의 성립\u003c/h3\u003e\r\n  \u003cp\u003e도시 간 교역과 이동이 증가하면서 통합된 신원체계가 필요해졌다.\u003c/p\u003e\r\n  \u003cp\u003e각 도시가 서로 다른 시민증과 기록방식을 사용하자 범죄자와 밀수업자는 경계를 넘을 때마다 새로운 신분을 만들었다. 반대로 정상적인 시민도 기록이 호환되지 않아 다른 도시에서 무신분자로 취급되었다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 생체정보와 경력, 시민권과 계좌를 연결한 통합 신원규격을 제안했다.\u003c/p\u003e\r\n  \u003cp\u003e개인의 신원은 블루넷 이전의 폐쇄형 보안망에 저장되었고, 주요 도시와 기업은 아르고스의 인증절차를 받아들였다.\u003c/p\u003e\r\n  \u003cp\u003e이 체계는 교역과 이동의 안전성을 크게 높였다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 개인의 삶 전체가 하나의 식별번호 아래 통합되기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 누가 어디에서 태어났고, 어떤 기업에서 일했으며, 누구와 거래했는지를 확인할 수 있게 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 4세기 — 돔 시티의 눈\u003c/h3\u003e\r\n  \u003cp\u003e대형 돔 시티가 건설되면서 아르고스는 도시감시와 사회안정 사업을 확장했다.\u003c/p\u003e\r\n  \u003cp\u003e돔은 외부의 위험으로부터 시민을 보호했지만 수많은 사람이 밀폐된 공간에 모여 사는 환경은 테러와 폭동, 전염병에 취약했다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 아르카디아의 도시행정망과 연계해 출입기록, 감시카메라, 통신과 소비자료를 분석했다. 위험인물과 비정상적인 물자이동, 사회불안의 징후를 사전에 탐지했다.\u003c/p\u003e\r\n  \u003cp\u003e도시의 범죄율과 테러는 감소했다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 감시망은 범죄자만을 바라보지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e노동조합, 시민운동과 기업비판 세력도 잠재적인 불안요소로 분류되었다. 아르고스의 분석보고서는 체포와 해고, 시민권 강등의 근거로 사용되었다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 돔 시티를 안전하게 만들었다.\u003c/p\u003e\r\n  \u003cp\u003e그리고 도시 안에서 완전히 사라질 수 있는 장소도 없게 만들었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 5세기 — 블루넷\u003c/h3\u003e\r\n  \u003cp\u003e블루넷이 대륙의 주요 도시와 기업을 연결하면서 아르고스의 영향력은 폭발적으로 증가했다.\u003c/p\u003e\r\n  \u003cp\u003e통신, 금융, 시민권과 기업업무가 하나의 네트워크에서 이루어지기 시작했다. 아르고스는 블루넷의 보안과 신원인증, 사이버범죄와 기업공작 감찰을 담당했다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 블루넷에서 발생하는 모든 활동을 직접 읽는 것은 아니라고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 접속기록과 통신경로, 신원인증과 금융활동을 결합하면 개인과 조직의 행동을 상당한 수준으로 추적할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기에 아르고스는 신원자료를 생성하고 수정하는 고도의 공작체계를 완성했다.\u003c/p\u003e\r\n  \u003cp\u003e비밀요원에게 존재하지 않았던 과거를 제공하고, 기업과 도시의 기록 안에 자연스럽게 삽입했다. 반대로 제거 대상의 계좌와 경력, 시민권과 인간관계를 단계적으로 삭제했다.\u003c/p\u003e\r\n  \u003cp\u003e이 기술은 내부에서 \u003cstrong\u003e유령작업\u003c/strong\u003e이라 불렸다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 6세기 — 칠정의 성립\u003c/h3\u003e\r\n  \u003cp\u003e초거대 기업들의 영향력이 국가를 대체할 수준에 도달하면서 기업 간 정보전은 대규모 전쟁으로 번질 위험을 만들었다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 기업공작과 테러, 신원침투를 추적할 수 있는 유일한 조직이었다. 하지만 동시에 아르고스 자체가 가장 강력한 공작기관이기도 했다.\u003c/p\u003e\r\n  \u003cp\u003e기업들은 정보전의 최소한의 규칙과 공동 대응체계를 마련하기 위해 협정을 체결했다. 이 협정은 칠정과 블루 테이블의 기반이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 칠정 내에서 정보수집, 방첩, 신원관리와 블루넷 보안을 담당하게 되었다.\u003c/p\u003e\r\n  \u003cp\u003e공식적으로 아르고스는 칠정 전체를 보호한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 어느 기업도 아르고스가 다른 기업보다 자신들을 더 자세히 감시하고 있지 않다고 확신하지 못한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e현재 — 멸망 후 700년\u003c/h3\u003e\r\n  \u003cp\u003e현재 아르고스 시큐어 네트워크는 세계 최대의 정보기관이자 신원관리 기업이다.\u003c/p\u003e\r\n  \u003cp\u003e돔 시티의 시민기록, 기업직원의 보안등급, 블루넷의 접근권과 주요 교역로의 정보가 아르고스의 체계를 통과한다. 공식적인 치안기관과 기업 보안부서도 고위험 신원조회와 방첩 업무에서 아르고스에 의존한다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스가 모든 것을 알고 있다는 평가는 과장이다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 황무지의 모든 사람을 감시할 수 없고, 장막 도시와 지하도시에는 기록되지 않은 인구가 존재한다. 데드 에어와 같은 넷러너 집단은 끊임없이 감시망을 우회한다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 아르고스의 진정한 힘은 모든 정보를 가지고 있다는 데 있지 않다.\u003c/p\u003e\r\n  \u003cp\u003e서로 관계없어 보이는 작은 기록을 연결해 하나의 의도와 미래의 사건을 찾아내는 데 있다.\u003c/p\u003e\r\n  \u003cp\u003e물 구매량이 늘어난 정착지, 평소와 다른 부품을 주문한 공장, 갑자기 이동한 기업간부와 사라진 통신기록.\u003c/p\u003e\r\n  \u003cp\u003e다른 사람에게는 우연처럼 보이는 사건도 아르고스에게는 작전의 시작일 수 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업 철학\u003c/h2\u003e\r\n  \u003ch3\u003e정보는 사실이 아니라 관계다\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 하나의 기록을 절대적으로 신뢰하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e신분증은 위조할 수 있고 영상은 편집할 수 있으며 증인은 거짓말할 수 있다. 중요한 것은 여러 정보가 서로 어떻게 연결되는지를 확인하는 것이다.\u003c/p\u003e\r\n  \u003ch3\u003e보이지 않는 위협이 가장 위험하다\u003c/h3\u003e\r\n  \u003cp\u003e이미 발생한 범죄를 해결하는 것은 DCS의 역할이다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 아직 모습을 드러내지 않은 위협을 찾아낸다. 내부첩자와 기업공작, 테러계획과 인공지능의 이상행동을 사건이 발생하기 전에 탐지하는 것을 목표로 한다.\u003c/p\u003e\r\n  \u003ch3\u003e기록되지 않은 것은 통제할 수 없다\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 모든 사람과 자산, 거래에 확인 가능한 기록이 필요하다고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e미등록 인구와 추적할 수 없는 자금, 출처가 없는 정보는 그 자체로 보안위협으로 분류된다.\u003c/p\u003e\r\n  \u003ch3\u003e진실은 필요에 따라 공개된다\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 모든 진실이 대중에게 알려져야 한다고 생각하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e사회혼란과 대규모 피해를 일으킬 정보라면 은폐와 조작도 정당한 보안조치로 간주한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e핵심 산업\u003c/h2\u003e\r\n  \u003ch3\u003e정보수집\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 기업, 도시, 장막 도시와 황무지 전역에서 정보를 수집한다.\u003c/p\u003e\r\n  \u003cp\u003e공개자료와 언론, 금융기록과 통신뿐 아니라 정보원, 잠입요원과 감시장비를 사용한다. 수집된 정보는 출처와 신뢰도, 조작 가능성에 따라 등급이 부여된다.\u003c/p\u003e\r\n  \u003cp\u003e정보원은 기업인과 공무원만이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e상인, 운전사, 의료인, 클럽 직원과 거리의 아이들도 아르고스의 정보망 일부가 될 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e정보분석\u003c/h3\u003e\r\n  \u003cp\u003e수집한 자료에서 위협과 의도, 미래의 사건을 찾아낸다.\u003c/p\u003e\r\n  \u003cp\u003e인공지능은 수십억 건의 기록을 비교하지만 최종판단은 인간 분석관이 담당하는 것을 원칙으로 한다. 백야 당시 자동화된 판단체계가 일으킨 참사가 그 이유다.\u003c/p\u003e\r\n  \u003cp\u003e다만 실제로 인간이 검토할 수 있는 정보량에는 한계가 있어 상당수 판단이 알고리즘에 의존한다.\u003c/p\u003e\r\n  \u003ch3\u003e방첩\u003c/h3\u003e\r\n  \u003cp\u003e기업과 돔 내부에 침투한 스파이, 배신자와 정보유출자를 추적한다.\u003c/p\u003e\r\n  \u003cp\u003e의심 대상의 통신과 금융, 인간관계를 장기간 감시하며 일부러 가짜정보를 흘려 반응을 확인하기도 한다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스의 방첩은 범인을 잡는 것보다 정보망 전체를 역추적하는 데 집중한다.\u003c/p\u003e\r\n  \u003ch3\u003e기업보안\u003c/h3\u003e\r\n  \u003cp\u003e연구시설, 데이터센터와 기업간부의 보안체계를 설계한다.\u003c/p\u003e\r\n  \u003cp\u003e출입인증, 감시망과 직원 신원검증을 통합적으로 제공한다. 아르고스의 보안체계를 사용하는 기업은 높은 안전성을 얻지만, 동시에 자신들의 내부정보를 아르고스에 맡기게 된다.\u003c/p\u003e\r\n  \u003ch3\u003e신원관리\u003c/h3\u003e\r\n  \u003cp\u003e출생, 시민권, 학력, 경력, 범죄기록과 생체정보를 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e개인의 신원이 여러 도시와 기업에서 동일하게 인정될 수 있도록 인증한다. 돔 시티에 취업하거나 주요 기업과 계약하려면 아르고스의 신원확인이 요구되는 경우가 많다.\u003c/p\u003e\r\n  \u003ch3\u003e사이버보안\u003c/h3\u003e\r\n  \u003cp\u003e블루넷 침입, 악성코드와 정보탈취를 방어한다.\u003c/p\u003e\r\n  \u003cp\u003e기업시설과 도시행정망의 방화벽을 관리하고, 적대 넷러너를 추적하며 감염된 인공지능과 시스템을 격리한다.\u003c/p\u003e\r\n  \u003ch3\u003e여론관리\u003c/h3\u003e\r\n  \u003cp\u003e대중의 감정과 정보확산을 분석하고 사회불안을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e가짜뉴스를 차단하고 재난정보를 검증하는 것이 공식적인 업무다. 필요할 경우 특정 보도를 축소하거나 다른 사건을 부각해 여론의 흐름을 바꾸기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e비밀공작\u003c/h3\u003e\r\n  \u003cp\u003e공식적인 외교와 수사로 해결할 수 없는 문제를 처리한다.\u003c/p\u003e\r\n  \u003cp\u003e침투, 공작, 협박과 납치, 시설파괴와 중요인물 제거가 포함될 수 있다. 모든 작전은 존재 자체가 부정될 수 있도록 설계된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e유령작업\u003c/h2\u003e\r\n  \u003cp\u003e유령작업은 아르고스가 보유한 신원조작 기술과 비밀공작의 총칭이다.\u003c/p\u003e\r\n  \u003ch3\u003e신분 삽입\u003c/h3\u003e\r\n  \u003cp\u003e존재하지 않았던 사람에게 출생과 학력, 경력과 인간관계를 만들어준다.\u003c/p\u003e\r\n  \u003cp\u003e단순히 신분증 하나를 위조하는 것이 아니다. 학교와 병원, 기업과 금융기관의 기록에 자연스러운 과거를 삽입한다.\u003c/p\u003e\r\n  \u003ch3\u003e신분 세탁\u003c/h3\u003e\r\n  \u003cp\u003e범죄기록과 채무, 과거 소속을 숨기고 새로운 신분을 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e공식적으로는 증인보호, 비밀요원과 중요기술자의 안전을 위해 사용된다.\u003c/p\u003e\r\n  \u003ch3\u003e신분 교체\u003c/h3\u003e\r\n  \u003cp\u003e실존 인물의 삶을 다른 사람이 이어받도록 만든다.\u003c/p\u003e\r\n  \u003cp\u003e생체정보와 외모, 행동기록까지 조작해야 하기 때문에 극도로 어려운 작업이다.\u003c/p\u003e\r\n  \u003ch3\u003e기록 제거\u003c/h3\u003e\r\n  \u003cp\u003e대상과 관련된 시민권, 계좌와 경력, 출입기록을 삭제하거나 접근 불가능하게 만든다.\u003c/p\u003e\r\n  \u003cp\u003e완전한 제거가 이루어진 사람은 합법적인 주거와 이동, 의료와 금융서비스를 사용할 수 없다.\u003c/p\u003e\r\n  \u003ch3\u003e사후 인격\u003c/h3\u003e\r\n  \u003cp\u003e사망한 인물의 계정과 기록을 일정 기간 유지한다.\u003c/p\u003e\r\n  \u003cp\u003e정보공작, 기업 안정과 비밀계약의 마무리에 사용된다. 이미 죽은 임원이 계속해서 명령을 내린 것처럼 보이는 경우도 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e정보 등급\u003c/h2\u003e\r\n  \u003ch3\u003eOPEN\u003c/h3\u003e\r\n  \u003cp\u003e대중에게 공개할 수 있는 정보다.\u003c/p\u003e\r\n  \u003cp\u003e기업홍보, 일반 통계와 공개된 사건기록이 포함된다.\u003c/p\u003e\r\n  \u003ch3\u003eCONTROLLED\u003c/h3\u003e\r\n  \u003cp\u003e직원과 계약기관만 접근할 수 있는 업무정보다.\u003c/p\u003e\r\n  \u003cp\u003e내부 규정, 일반 신원자료와 보안절차가 해당한다.\u003c/p\u003e\r\n  \u003ch3\u003eCLASSIFIED\u003c/h3\u003e\r\n  \u003cp\u003e인가된 정보요원과 간부만 접근할 수 있는 기밀이다.\u003c/p\u003e\r\n  \u003cp\u003e방첩조사, 정보원 명단과 기업공작 자료가 포함된다.\u003c/p\u003e\r\n  \u003ch3\u003eBLACK\u003c/h3\u003e\r\n  \u003cp\u003e존재 자체가 공개되지 않는 최고등급 정보다.\u003c/p\u003e\r\n  \u003cp\u003e비밀작전, 칠정 최고위층의 약점과 금지된 인공지능에 관한 자료가 포함된다.\u003c/p\u003e\r\n  \u003ch3\u003eNULL\u003c/h3\u003e\r\n  \u003cp\u003e공식 분류체계에 존재하지 않는 정보등급이다.\u003c/p\u003e\r\n  \u003cp\u003e접근기록조차 남지 않으며 중앙정보총국장과 극소수의 인물만 열람할 수 있다는 소문이 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업 구조\u003c/h2\u003e\r\n  \u003cp\u003e아르고스는 일반적인 기업이 아니라 중앙정보기관과 기술기업이 결합된 구조를 가지고 있다.\u003c/p\u003e\r\n  \u003ch3\u003e이사회\u003c/h3\u003e\r\n  \u003cp\u003e기업의 장기전략, 칠정과의 관계, 대규모 감찰 및 정보계약을 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e이사회의 정확한 구성과 의결방식은 외부에 거의 공개되지 않는다. 일부 이사가 실명이 아닌 직책과 대리인을 통해 활동한다는 의혹이 있다.\u003c/p\u003e\r\n  \u003ch3\u003e총재\u003c/h3\u003e\r\n  \u003cp\u003e아르고스 전체를 대표하는 최고경영자다.\u003c/p\u003e\r\n  \u003cp\u003e공식적인 경영과 칠정 내 협상을 담당한다. 그러나 비밀공작과 정보분석의 세부사항에는 직접 개입하지 않는 것으로 알려져 있다.\u003c/p\u003e\r\n  \u003ch3\u003e중앙정보총국장\u003c/h3\u003e\r\n  \u003cp\u003e아르고스의 모든 정보수집, 방첩과 공작을 지휘하는 실질적인 최고책임자다.\u003c/p\u003e\r\n  \u003cp\u003e기업 내부에서 가장 많은 기밀에 접근할 수 있으며 세 명의 차장과 총국장 직속실을 통제한다.\u003c/p\u003e\r\n  \u003cp\u003e총국장의 이름과 외부활동은 공개되지만, 정확한 권한과 일상적인 동선은 최고등급 기밀로 관리된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e제1차장 — 국내·치안\u003c/h2\u003e\r\n  \u003cp\u003e돔 시티와 기업 내부의 정보, 시민신원과 사회안정을 담당한다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 정보부\u003c/h3\u003e\r\n  \u003cp\u003e돔 내부의 정치, 범죄와 기업활동을 감시한다.\u003c/p\u003e\r\n  \u003cp\u003eDCS 및 도시행정부와 정보를 공유하며 테러와 폭동, 기업공작의 징후를 분석한다.\u003c/p\u003e\r\n  \u003cp\u003e돔 정보부의 정보과장은 지역 단위의 정보수집과 언론조작, 감시작전을 총괄한다. 필요할 경우 현장요원과 정보원을 직접 운용한다.\u003c/p\u003e\r\n  \u003ch3\u003e신원관리부\u003c/h3\u003e\r\n  \u003cp\u003e시민권, 기업경력, 생체인증과 이동기록을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e신원위조를 탐지하는 조직이지만 동시에 고급 유령작업에 필요한 기반자료를 보유한다.\u003c/p\u003e\r\n  \u003ch3\u003e사회안정부\u003c/h3\u003e\r\n  \u003cp\u003e여론, 집단행동과 사회불안을 분석한다.\u003c/p\u003e\r\n  \u003cp\u003e파업과 시위, 폭동 가능성을 예측하고 도시행정부에 대응방안을 제시한다. 필요할 경우 선전과 정보통제를 통해 불만을 분산한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e제2차장 — 대외·공작\u003c/h2\u003e\r\n  \u003cp\u003e외부세력에 대한 정보수집과 비밀공작, 특수사업을 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e제2차장은 아르고스의 공개된 지휘체계 안에서도 가장 정체가 알려지지 않은 인물 가운데 하나다. 공식행사와 언론에 거의 등장하지 않으며 사진과 생체정보, 이동기록 대부분이 기밀로 분류된다.\u003c/p\u003e\r\n  \u003cp\u003e제2차장은 단순한 행정간부가 아니다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스의 최고위 현장전력으로 평가되며, 일반 요원이 감당할 수 없는 최상위 위협과 직접 대면할 권한을 가진다. 공식적인 호위 없이 활동하는 경우가 많지만, 이는 보호가 필요하지 않기 때문이라는 소문이 있다.\u003c/p\u003e\r\n  \u003ch3\u003e대외정보부\u003c/h3\u003e\r\n  \u003cp\u003e다른 기업, 장막 도시와 황무지 세력의 정보를 수집한다.\u003c/p\u003e\r\n  \u003cp\u003e외교관, 상인과 용병, 카라반을 정보원으로 활용하며 해외 및 외부거점에 비공식 연락망을 운영한다.\u003c/p\u003e\r\n  \u003ch3\u003e기업공작부\u003c/h3\u003e\r\n  \u003cp\u003e경쟁기업과 적대조직에 요원을 침투시키고 내부갈등을 유도한다.\u003c/p\u003e\r\n  \u003cp\u003e산업기밀 탈취, 간부매수와 허위정보 유포를 담당한다. 공식적으로 존재가 인정되지 않는 작전도 수행한다.\u003c/p\u003e\r\n  \u003ch3\u003e특수사업부\u003c/h3\u003e\r\n  \u003cp\u003e일반적인 정보활동으로 분류할 수 없는 고위험 임무를 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e중요인물 제거, 변칙기술 회수, 최상위 강자 대응과 기밀시설 침투가 포함된다.\u003c/p\u003e\r\n  \u003cp\u003e특수사업부의 요원은 명령이 내려지기 전까지 서로의 존재를 알지 못하는 경우가 많다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e제3차장 — 블루넷·기술\u003c/h2\u003e\r\n  \u003cp\u003e블루넷, 암호체계, 인공지능과 기술정보를 담당한다.\u003c/p\u003e\r\n  \u003ch3\u003e블루넷 감찰부\u003c/h3\u003e\r\n  \u003cp\u003e블루넷의 비정상적인 접속, 대규모 정보조작과 사이버공격을 추적한다.\u003c/p\u003e\r\n  \u003cp\u003e데드 에어와 기업 넷러너 집단의 활동을 감시하며 필요할 경우 특정 구역의 블루넷 접속을 차단한다.\u003c/p\u003e\r\n  \u003ch3\u003e암호분석부\u003c/h3\u003e\r\n  \u003cp\u003e기업, 군사조직과 범죄세력이 사용하는 암호를 해독한다.\u003c/p\u003e\r\n  \u003cp\u003e백야 이전의 통신규격과 정체불명의 궤도신호도 연구한다. 일부 분석관은 해독할 수 없는 신호에 장기간 노출된 뒤 정신이상 증세를 보였다고 알려졌다.\u003c/p\u003e\r\n  \u003ch3\u003e인공지능 통제부\u003c/h3\u003e\r\n  \u003cp\u003e독립 인공지능, 자율학습 시스템과 금지된 사고모델을 감시한다.\u003c/p\u003e\r\n  \u003cp\u003e통제불능 인공지능을 추적하고 격리하며 필요할 경우 시스템 전체를 물리적으로 파괴한다. 아르고스가 비밀리에 운용하는 분석 인공지능도 이 부서의 감독대상이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e총국장 직속실\u003c/h2\u003e\r\n  \u003cp\u003e중앙정보총국장에게 직접 보고하는 독립조직이다.\u003c/p\u003e\r\n  \u003cp\u003e내부감찰, 최고등급 기밀과 칠정 공동공작을 담당한다. 세 명의 차장조차 모든 활동을 확인할 수 없다.\u003c/p\u003e\r\n  \u003cp\u003e직속실은 아르고스 내부의 배신자와 이중간첩을 추적한다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스의 요원들은 외부의 감시보다 직속실의 감찰을 더 두려워한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 기술\u003c/h2\u003e\r\n  \u003ch3\u003e파놉테스 감시망\u003c/h3\u003e\r\n  \u003cp\u003e도시의 감시카메라, 통신기록, 드론과 시민정보를 통합하는 분석체계다.\u003c/p\u003e\r\n  \u003cp\u003e대상을 직접 촬영하지 못하더라도 주변인의 이동, 결제와 통신을 분석해 위치를 추정할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e트루사이트 신원분석\u003c/h3\u003e\r\n  \u003cp\u003e생체정보와 행동습관, 언어와 기억반응을 결합해 신원을 확인한다.\u003c/p\u003e\r\n  \u003cp\u003e얼굴과 지문을 바꾸더라도 걸음걸이, 미세한 시선운동과 신경반응을 통해 동일인일 가능성을 분석한다.\u003c/p\u003e\r\n  \u003ch3\u003e아이리스 인증망\u003c/h3\u003e\r\n  \u003cp\u003e아르고스가 운영하는 고급 신원인증체계다.\u003c/p\u003e\r\n  \u003cp\u003e시민증과 생체정보, 블루넷 계정을 결합한다. 주요 기업시설과 돔 관문에서 사용된다.\u003c/p\u003e\r\n  \u003ch3\u003e에코 추적기술\u003c/h3\u003e\r\n  \u003cp\u003e삭제된 통신과 조작된 기록에서 남은 흔적을 복원한다.\u003c/p\u003e\r\n  \u003cp\u003e완전히 지워진 데이터도 다른 계정과 장비에 남은 반응을 통해 간접적으로 재구성할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e고스트 패키지\u003c/h3\u003e\r\n  \u003cp\u003e비밀요원을 위해 제작되는 통합 신원위장 체계다.\u003c/p\u003e\r\n  \u003cp\u003e신분, 경력과 금융기록뿐 아니라 주변인의 기억을 뒷받침할 가짜 사건과 인간관계까지 설계한다.\u003c/p\u003e\r\n  \u003ch3\u003e블라인드 스폿\u003c/h3\u003e\r\n  \u003cp\u003e특정 대상을 감시망에서 일시적으로 보이지 않게 만드는 기술이다.\u003c/p\u003e\r\n  \u003cp\u003e침투요원이 사용하지만 고위간부와 특별인가 대상의 사생활을 보호하는 용도로도 사용된다.\u003c/p\u003e\r\n  \u003ch3\u003e오라클 분석계\u003c/h3\u003e\r\n  \u003cp\u003e방대한 정보를 분석해 사건과 위협의 발생 가능성을 예측한다.\u003c/p\u003e\r\n  \u003cp\u003e공식적으로는 보조 인공지능이며 최종판단은 인간이 내린다. 하지만 실제로 얼마나 많은 작전이 오라클의 예측만으로 시작되는지는 공개되지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e데드 레코드\u003c/h3\u003e\r\n  \u003cp\u003e대상의 신원을 사회체계에서 제거하는 최고등급 프로토콜이다.\u003c/p\u003e\r\n  \u003cp\u003e시민권과 계좌, 출입권한과 경력이 동시에 정지된다. 대상은 살아 있더라도 행정적으로 사망한 것과 같은 상태가 된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 시설\u003c/h2\u003e\r\n  \u003ch3\u003e백안성\u003c/h3\u003e\r\n  \u003cp\u003e아르고스의 본사이자 중앙정보총국이 위치한 복합시설이다.\u003c/p\u003e\r\n  \u003cp\u003e외부에서는 거대한 데이터센터와 행정청사로 보이지만 상당 부분이 지하에 존재한다. 정확한 전체구조와 상주인원은 공개되지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e건물 내부에서는 개인 통신장치와 기록매체 사용이 엄격하게 제한된다.\u003c/p\u003e\r\n  \u003ch3\u003e아카이브 제로\u003c/h3\u003e\r\n  \u003cp\u003e백야 이전과 멸망력 초기의 원본기록을 보관하는 최고기밀 시설이다.\u003c/p\u003e\r\n  \u003cp\u003e국가문서, 기업기밀, 군사자료와 헬리오스 관련 기록이 저장되어 있다는 소문이 있다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스 내부에서도 극소수만 위치를 알고 있다.\u003c/p\u003e\r\n  \u003ch3\u003e미러 하우스\u003c/h3\u003e\r\n  \u003cp\u003e정보요원과 비밀공작원을 훈련하는 시설이다.\u003c/p\u003e\r\n  \u003cp\u003e신분위장, 심리조작, 고문저항과 침투훈련이 이루어진다. 훈련생은 자신의 과거와 정체성에 대한 반복적인 검증을 받는다.\u003c/p\u003e\r\n  \u003ch3\u003e블랙 렌즈\u003c/h3\u003e\r\n  \u003cp\u003e블루넷 감찰과 사이버전을 담당하는 지하 관제시설이다.\u003c/p\u003e\r\n  \u003cp\u003e데드 에어를 비롯한 적대 넷러너들은 이곳을 세계에서 가장 뚫기 어려운 네트워크 가운데 하나로 평가한다.\u003c/p\u003e\r\n  \u003ch3\u003e공백실\u003c/h3\u003e\r\n  \u003cp\u003e공식 기록에 존재하지 않는 구금 및 심문시설에 붙은 통칭이다.\u003c/p\u003e\r\n  \u003cp\u003e이곳에 수감된 사람은 체포기록과 재판기록이 남지 않는다. 석방된 사람도 자신이 어디에 있었는지 기억하지 못한다는 이야기가 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e현장요원\u003c/h2\u003e\r\n  \u003cp\u003e아르고스의 현장요원은 모두 같은 방식으로 활동하지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e케이스 오피서\u003c/h3\u003e\r\n  \u003cp\u003e정보원을 모집하고 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e직접적인 전투보다 인간관계와 심리조작에 능하다. 정보원이 배신하거나 노출되었을 때 회수 여부를 판단한다.\u003c/p\u003e\r\n  \u003ch3\u003e분석관\u003c/h3\u003e\r\n  \u003cp\u003e수집된 정보에서 관계와 의도를 찾아낸다.\u003c/p\u003e\r\n  \u003cp\u003e현장에 나가지 않지만 한 번의 판단으로 수십 명의 요원과 도시 전체의 작전방향을 바꿀 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e고스트\u003c/h3\u003e\r\n  \u003cp\u003e가짜 신분으로 적대조직과 기업에 침투한다.\u003c/p\u003e\r\n  \u003cp\u003e장기간 임무에서는 본래의 정체성을 잃고 위장된 인물로 살아가기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e리커버러\u003c/h3\u003e\r\n  \u003cp\u003e도난당한 정보와 인물, 기술을 회수한다.\u003c/p\u003e\r\n  \u003cp\u003e협상과 침투, 강제력을 모두 사용하며 필요할 경우 대상의 완전한 제거까지 담당한다.\u003c/p\u003e\r\n  \u003ch3\u003e블랙 오퍼레이터\u003c/h3\u003e\r\n  \u003cp\u003e공식적으로 존재하지 않는 고위험 작전을 수행한다.\u003c/p\u003e\r\n  \u003cp\u003e체포되거나 사망해도 아르고스는 소속을 인정하지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e직원 문화\u003c/h2\u003e\r\n  \u003cp\u003e아르고스의 직원은 필요한 것보다 더 많이 말하지 않도록 교육받는다.\u003c/p\u003e\r\n  \u003cp\u003e같은 부서의 직원이라도 서로의 전체 업무를 알지 못한다. 정보는 직급보다 필요성에 따라 제공되며, 최고위 간부도 자신의 관할 밖에 있는 기밀에는 접근할 수 없다.\u003c/p\u003e\r\n  \u003cp\u003e기업 내부에서는 침묵, 검증과 의심이 미덕으로 여겨진다.\u003c/p\u003e\r\n  \u003cp\u003e동료의 말을 신뢰하더라도 기록을 확인해야 하며, 기록이 일치하더라도 조작 가능성을 검토해야 한다. 사소한 행동변화와 일정의 불일치도 감찰 대상이 된다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스에서 오래 근무한 직원은 모든 대화와 인간관계를 정보교환으로 바라보는 경향이 있다.\u003c/p\u003e\r\n  \u003cp\u003e가족과 친구를 만들지 않는 요원도 많다. 자신의 주변인이 약점이 되거나 기업의 감시대상이 되는 것을 원하지 않기 때문이다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스 내부에서 널리 사용되는 문구는 다음과 같다.\u003c/p\u003e\r\n  \u003cblockquote\u003e한 번 확인한 사실은 정보다. 두 번 확인한 사실은 미끼일 수 있다.\u003c/blockquote\u003e\r\n\r\n  \u003ch2\u003e채용과 복지\u003c/h2\u003e\r\n  \u003cp\u003e아르고스는 정보분석가, 수사관, 심리학자, 언어학자, 넷러너, 암호전문가와 현장요원을 채용한다.\u003c/p\u003e\r\n  \u003cp\u003e전투능력보다 기억력, 관찰력과 판단력을 우선적으로 평가한다. 지원자의 과거와 가족, 친구와 재정상태까지 철저하게 조사한다.\u003c/p\u003e\r\n  \u003cp\u003e정규직과 가족에게는 다음과 같은 혜택이 제공된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e상급 기업시민권\u003c/li\u003e\r\n    \u003cli\u003e보안주거구역 제공\u003c/li\u003e\r\n    \u003cli\u003e고급 의료와 신체복원\u003c/li\u003e\r\n    \u003cli\u003e가족 신변보호\u003c/li\u003e\r\n    \u003cli\u003e블루넷 우선접속권\u003c/li\u003e\r\n    \u003cli\u003e신원도용 및 사이버범죄 보호\u003c/li\u003e\r\n    \u003cli\u003e업무상 신분변경 지원\u003c/li\u003e\r\n    \u003cli\u003e퇴직 후 기록보호와 재정착\u003c/li\u003e\r\n    \u003cli\u003e사망 시 가족의 신원 및 생활 보장\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e그러나 아르고스에서 완전히 퇴직하는 것은 어렵다.\u003c/p\u003e\r\n  \u003cp\u003e직원이 너무 많은 기밀을 알고 있다고 판단되면 활동과 이동이 평생 제한될 수 있다. 일부 퇴직자는 새로운 신분을 받아 이전의 인간관계를 모두 포기한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e계층별 인식\u003c/h2\u003e\r\n  \u003ch3\u003e돔 시티 상류층\u003c/h3\u003e\r\n  \u003cp\u003e아르고스를 자신들의 자산과 지위를 보호하는 필수기관으로 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e기업공작과 납치, 신원도용을 두려워하기 때문에 고급 보안서비스를 적극적으로 이용한다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 자신들의 비밀과 약점이 아르고스에 기록된다는 사실을 경계한다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 시티 일반 시민\u003c/h3\u003e\r\n  \u003cp\u003e테러와 범죄를 막는 정보기관으로 인식하면서도 일상을 감시하는 존재로 두려워한다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스에 숨길 것이 없다면 걱정할 필요가 없다는 말이 널리 사용된다.\u003c/p\u003e\r\n  \u003cp\u003e그 말을 믿는 사람은 많지 않다.\u003c/p\u003e\r\n  \u003ch3\u003e장막 도시 주민\u003c/h3\u003e\r\n  \u003cp\u003e아르고스의 영향력이 약한 지역에서는 돔의 감시자나 기업의 사냥개로 인식한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 정식 신분과 시민권을 얻기 위해 아르고스의 신원인증이 필요한 경우가 많아 완전히 거부할 수도 없다.\u003c/p\u003e\r\n  \u003ch3\u003e황무지인\u003c/h3\u003e\r\n  \u003cp\u003e기록과 인증보다 개인의 평판을 중요하게 여기기 때문에 아르고스의 신원체계를 불신한다.\u003c/p\u003e\r\n  \u003cp\u003e일부는 아르고스에 등록되는 순간 기업이 자신의 삶을 소유하게 된다고 생각한다.\u003c/p\u003e\r\n  \u003ch3\u003e범죄조직\u003c/h3\u003e\r\n  \u003cp\u003e가장 위험한 적 가운데 하나로 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스의 요원 한 명을 죽이는 것은 어렵지 않을 수 있다. 그러나 그 요원이 누구에게 무엇을 보고했는지 알 수 없다는 것이 문제다.\u003c/p\u003e\r\n  \u003ch3\u003e다른 기업\u003c/h3\u003e\r\n  \u003cp\u003e모두 아르고스의 정보가 필요하다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 모든 기업은 아르고스가 자신들의 기밀을 필요 이상으로 보유하고 있다고 의심한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e다른 세력과의 관계\u003c/h2\u003e\r\n  \u003ch3\u003eNEREID HYDROSYSTEMS\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 수원 테러와 수권 위조, 불법 급수망을 추적한다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드는 물 사용량과 수권 거래자료를 제공한다. 특정 지역의 갑작스러운 물 소비증가는 비밀시설이나 병력집결을 탐지하는 정보로 사용된다.\u003c/p\u003e\r\n  \u003ch3\u003eSOLARIS ORBITAL INDUSTRIES\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스는 위성통신과 관측자료를 제공하며 아르고스는 사이버위협과 헬리오스 잔존신호를 분석한다.\u003c/p\u003e\r\n  \u003cp\u003e양사는 긴밀하게 협력하지만 백야 관련 기밀의 통제권을 두고 충돌한다.\u003c/p\u003e\r\n  \u003ch3\u003eARCADIA HABITAT\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아는 시민권과 도시행정자료를 제공한다. 아르고스는 테러와 사회불안, 신원침투를 감시한다.\u003c/p\u003e\r\n  \u003cp\u003e두 기업의 정보가 결합되면 돔 시민의 이동, 소비와 인간관계를 거의 완전하게 추적할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003eMORPHOS BIODYNE\u003c/h3\u003e\r\n  \u003cp\u003e모르포스는 생체정보와 유전자 인증기술을 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 불법 인체개조를 이용한 신원위장을 추적한다. 양측은 서로의 고객기록과 고위간부 정보를 탐내는 위험한 협력관계다.\u003c/p\u003e\r\n  \u003ch3\u003eCERBERUS DEFENSE GROUP\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 현장요원과 비밀작전에 무기와 장비를 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 병기유출과 내부반란을 감시한다. 케르베로스는 아르고스가 군사시설에 지나치게 깊이 침투한다고 의심한다.\u003c/p\u003e\r\n  \u003ch3\u003eCHARON INTERCONTINENTAL\u003c/h3\u003e\r\n  \u003cp\u003e카론은 승객과 화물의 이동기록을 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 노선테러, 밀수와 도난화물을 추적한다. 카론은 고객기밀을 이유로 일부 자료제공을 거부하며 독자적인 정보망을 유지한다.\u003c/p\u003e\r\n  \u003ch3\u003eECLIPSE TACTICAL BUREAU\u003c/h3\u003e\r\n  \u003cp\u003e아르고스가 위협을 찾아내면 이클립스가 현장에서 제압한다.\u003c/p\u003e\r\n  \u003cp\u003e두 조직은 대규모 테러와 기업재난에서 협력한다. 그러나 작전실패가 발생하면 정보가 잘못되었는지 현장대응이 부족했는지를 두고 충돌한다.\u003c/p\u003e\r\n  \u003ch3\u003eDOME CIVIC SECURITY\u003c/h3\u003e\r\n  \u003cp\u003eDCS는 일반 범죄수사와 현장체포를 담당한다. 아르고스는 기업공작, 테러와 고위험 방첩사건을 맡는다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스가 사건을 인계받으면 DCS의 접근권한이 차단되고 관련 기록이 기밀로 전환되기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003eDEAD AIR\u003c/h3\u003e\r\n  \u003cp\u003e아르고스가 가장 오래 추적하고 있는 넷러너 집단이다.\u003c/p\u003e\r\n  \u003cp\u003e데드 에어는 아르고스의 감시망과 신원체계를 공격하고 기록을 해방한다고 주장한다. 아르고스는 이들을 정보질서를 위협하는 분산형 테러조직으로 규정한다.\u003c/p\u003e\r\n  \u003ch3\u003eVELVET STATIC\u003c/h3\u003e\r\n  \u003cp\u003e양측 모두 정보와 신분을 거래하지만 목적과 방식이 다르다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 벨벳 스태틱을 범죄조직으로 감시하면서도 비공식 정보원과 접촉한다. 벨벳 스태틱의 블랙 아카이브에는 아르고스조차 확보하지 못한 기업기밀이 존재한다고 알려져 있다.\u003c/p\u003e\r\n  \u003ch3\u003eTHE BLUE TABLE\u003c/h3\u003e\r\n  \u003cp\u003e블루 테이블은 아르고스에 칠정 공동감찰과 정보수집 권한을 부여한다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 공식적으로 블루 테이블에 보고하지만, 국가적 혼란을 막는다는 이유로 일부 정보를 공개하지 않을 수 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e사회공헌과 홍보\u003c/h2\u003e\r\n  \u003cp\u003e아르고스는 자신들을 “보이지 않는 위협으로부터 시민을 지키는 기업”으로 소개한다.\u003c/p\u003e\r\n  \u003cp\u003e신원도용 피해자를 지원하고 블루넷 사기와 악성코드를 차단하며, 실종자와 인신매매 조직을 추적한다. 장막 도시 주민에게 임시 신원을 발급하고 가족기록을 복원하는 사업도 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e재난이 발생하면 허위정보와 가짜 대피명령을 차단하고 공식정보를 배포한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 아르고스가 무엇을 허위정보로 판단하는지, 어떤 사실을 대중에게 공개하지 않는지는 시민이 확인할 수 없다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스의 홍보에는 요원의 얼굴이 거의 등장하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e대신 푸른 감시망과 안전한 도시, 정상적으로 인증되는 시민증이 반복적으로 나타난다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e논란과 비판\u003c/h2\u003e\r\n  \u003ch3\u003e대규모 시민감시\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 범죄와 테러를 예방하기 위해 시민의 통신, 금융과 이동기록을 분석한다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 개인의 사생활보다 도시 전체의 안전이 우선될 수 있다고 주장한다.\u003c/p\u003e\r\n  \u003ch3\u003e비밀구금\u003c/h3\u003e\r\n  \u003cp\u003e아르고스가 정식 체포와 재판절차 없이 위험인물을 구금한다는 의혹이 있다.\u003c/p\u003e\r\n  \u003cp\u003e해당 인물들은 공식 수감자 명단에 존재하지 않으며 변호사와 가족의 접근도 허용되지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e신원삭제\u003c/h3\u003e\r\n  \u003cp\u003e데드 레코드가 범죄자뿐 아니라 기업의 정치적 반대자에게 사용된다는 비판이 있다.\u003c/p\u003e\r\n  \u003cp\u003e신원이 삭제된 사람은 법적인 보호와 사회서비스를 동시에 잃는다.\u003c/p\u003e\r\n  \u003ch3\u003e여론조작\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 허위정보를 차단하는 동시에 특정 보도와 사건을 의도적으로 축소한다.\u003c/p\u003e\r\n  \u003cp\u003e언론사와 감각방송의 편집방향에 개입하고 기업에 불리한 사건을 다른 정보로 덮는다는 의혹이 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003e예측수사\u003c/h3\u003e\r\n  \u003cp\u003e아직 범죄를 저지르지 않은 사람도 행동자료와 인간관계를 근거로 감시대상이 될 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 감시가 처벌을 의미하지 않는다고 주장한다. 그러나 감시대상으로 지정된 사실만으로 취업과 시민권 심사에서 불이익을 받을 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e인공지능 의존\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 최종판단을 인간이 내린다고 강조한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 분석해야 하는 정보량을 고려하면 실제 위협분류의 상당 부분이 인공지능에 의해 이루어진다는 비판이 있다.\u003c/p\u003e\r\n  \u003ch3\u003e칠정의 면책\u003c/h3\u003e\r\n  \u003cp\u003e아르고스가 칠정의 안정이라는 명목으로 대기업의 범죄와 비밀을 은폐한다는 의혹이 끊이지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 개별 범죄보다 문명 전체의 붕괴를 막는 것이 우선이라고 반박한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e확인되지 않은 소문\u003c/h2\u003e\r\n  \u003cp\u003e아르고스의 아카이브 제로에는 2102년 백야의 발생과 관련된 완전한 기록이 보존되어 있다는 소문이 있다.\u003c/p\u003e\r\n  \u003cp\u003e헬리오스가 왜 통제불능 상태에 빠졌는지, 최초의 명령이 어디에서 시작되었는지 확인할 수 있는 자료가 존재하지만 사회붕괴를 일으킬 수 있다는 이유로 공개되지 않는다는 것이다.\u003c/p\u003e\r\n  \u003cp\u003e또한 아르고스의 최고위 지휘부는 현재 발생하는 사건을 단순히 예측하는 것이 아니라 의도적으로 유도하고 있다는 의혹도 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e오라클 분석계가 미래의 여러 가능성을 계산하고, 아르고스가 가장 유리한 결과가 발생하도록 작은 사건과 정보를 조정한다는 주장이다.\u003c/p\u003e\r\n  \u003cp\u003e일부에서는 중앙정보총국장이 실존 인물이 아니라 여러 시대에 걸쳐 사용된 하나의 신분이라고 믿는다.\u003c/p\u003e\r\n  \u003cp\u003e총국장이 교체될 때마다 얼굴과 이름은 달라지지만, 행동과 판단방식은 지나치게 동일하다는 것이다.\u003c/p\u003e\r\n  \u003cp\u003e더 기이한 소문은 제2차장과 관련되어 있다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스 내부의 최고기밀 작전기록 여러 곳에서 서로 다른 시대와 장소에 동일한 인물이 등장한다. 기록마다 이름과 신분은 다르지만 신체적 특징과 작전방식이 일치한다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e해당 인물이 장기간 활동해 온 한 사람인지, 동일한 신분을 계승하는 요원들인지, 아르고스가 만들어낸 허구의 존재인지는 알려지지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e그 인물을 추적하려 한 내부 조사관들의 기록은 모두 삭제되었다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 제2차장에 관한 모든 질문에 동일하게 답한다.\u003c/p\u003e\r\n  \u003cblockquote\u003e해당 정보에 접근할 권한이 없습니다.\u003c/blockquote\u003e\r\n\r\n  \u003ch2\u003e기업이 가진 힘\u003c/h2\u003e\r\n  \u003cp\u003e아르고스의 힘은 비밀을 알고 있다는 사실만으로 완성되지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e비밀을 언제 공개하고, 누구에게 전달하며, 어떤 진실을 기록에서 제거할지를 결정할 수 있기 때문에 강한 것이다.\u003c/p\u003e\r\n  \u003cp\u003e한 명의 정치인을 몰락시키는 데 총알은 필요하지 않다. 숨겨진 계좌와 오래된 통화기록, 편집되지 않은 영상 하나면 충분하다.\u003c/p\u003e\r\n  \u003cp\u003e반대로 명백한 범죄도 기록에서 사라지면 증명할 수 없다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 사람을 죽이지 않고도 존재를 끝낼 수 있다. 시민권과 계좌, 경력과 인간관계를 제거하면 대상은 살아 있어도 사회 안에서는 존재하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e또한 아무것도 없던 사람에게 완전한 과거와 신분을 만들어 줄 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스가 물리적인 적을 제거하고 아르카디아가 도시 안의 삶을 관리한다면, 아르고스는 사람들이 현실이라고 믿는 기록과 정보의 질서를 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e그리고 대부분의 사람은 자신이 감시받는 순간을 알지 못한다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스의 시선은 누군가를 바라볼 때 가장 위험한 것이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e그 시선이 다른 곳을 보고 있다고 믿게 만들 때 가장 위험하다.\u003c/p\u003e\r\n\u003c/section\u003e\r\n";
window.FACTION_INFO.eclipse = "\u003csection class=\"faction-detail\"\u003e\r\n  \u003ch2\u003e기관 개요\u003c/h2\u003e\r\n  \u003cp class=\"faction-quote\"\u003e“재난이 이름을 얻기 전에 끝낸다.”\u003c/p\u003e\r\n  \u003cp\u003e이클립스 전술국은 일반적인 경찰과 기업군이 감당할 수 없는 초고위험 사태를 진압하기 위해 설립된 초기업 특수대응기관이다. 대규모 사이버웨어 폭주, 도시급 테러, 통제불능 인공지능, 생체병기 유출, 기업 간 무력충돌과 같은 위협에 대응한다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스는 특정 기업에 소속되지 않는다. 블루 테이블의 공동인가를 받아 활동하며, 칠정 전체를 위협하는 사건에서는 개별 기업의 관할권과 보안등급을 넘어설 수 있다.\u003c/p\u003e\r\n  \u003cp\u003eDCS가 돔 시티의 일상적인 범죄와 치안을 담당한다면, 이클립스는 도시의 존속 자체가 위험해졌을 때 투입된다. 케르베로스가 전쟁을 수행하는 군대라면, 이클립스는 전쟁으로 번지기 전에 위협을 격리하고 제거하는 외과수술용 칼날에 가깝다.\u003c/p\u003e\r\n  \u003cp\u003e이들의 작전목표는 범인을 체포하거나 시민을 보호하는 것만이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e위협의 확산을 막고, 위험한 기술과 정보를 회수하며, 사건이 다시 발생할 가능성까지 제거하는 것이다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스가 도착했다는 사실은 구조가 시작되었다는 의미일 수도 있다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 많은 시민은 그것을 이미 상황이 통제 가능한 수준을 넘어섰다는 신호로 받아들인다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기본 정보\u003c/h2\u003e\r\n  \u003ctable class=\"data-table faction-info-table\"\u003e\r\n    \u003ctbody\u003e\r\n      \u003ctr\u003e\u003cth\u003e정식 명칭\u003c/th\u003e\u003ctd\u003eECLIPSE TACTICAL BUREAU\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e통칭\u003c/th\u003e\u003ctd\u003e이클립스, 전술국\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e기관 분류\u003c/th\u003e\u003ctd\u003e초기업 특수치안·재난진압기관\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 임무\u003c/th\u003e\u003ctd\u003e도시급 테러, 기업재난, 고위험 전투사태 대응\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e특수 임무\u003c/th\u003e\u003ctd\u003e격리, 봉쇄, 위험기술 회수, 특수구금\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e인가 기관\u003c/th\u003e\u003ctd\u003eTHE BLUE TABLE\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 협력기관\u003c/th\u003e\u003ctd\u003eARGOS, DCS, CERBERUS, LAZARUS\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e상징 색상\u003c/th\u003e\u003ctd\u003e흑색, 적색, 백색\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표적인 인식\u003c/th\u003e\u003ctd\u003e재난이 발생했을 때 마지막으로 호출되는 기관\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e활동 범위\u003c/th\u003e\u003ctd\u003e칠정 기업시설, 돔 시티, 장막 도시와 황무지\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e최고책임자\u003c/th\u003e\u003ctd\u003e이클립스 전술국장\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 시설\u003c/th\u003e\u003ctd\u003e중앙상황통제실, 특수구금시설, 격리기지\u003c/td\u003e\u003c/tr\u003e\r\n    \u003c/tbody\u003e\r\n  \u003c/table\u003e\r\n\r\n  \u003ch2\u003e기관의 역사\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e백야 이후 — 통제할 수 없는 위협\u003c/h3\u003e\r\n  \u003cp\u003e2102년 백야 직후에는 이클립스와 같은 통합 대응기관이 존재하지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e국가와 도시, 기업은 각자의 병력으로 재난과 폭동, 변이생물과 통제불능 병기에 대응했다. 그러나 정보와 지휘체계가 붕괴한 상황에서 서로 다른 조직이 협력하는 것은 어려웠다.\u003c/p\u003e\r\n  \u003cp\u003e한 도시는 감염자를 구하려 했고 다른 도시는 감염이 확산될 것을 우려해 피난민을 공격했다. 군부대는 기업시설을 약탈했고, 기업경비대는 민간인의 접근을 차단했다.\u003c/p\u003e\r\n  \u003cp\u003e위협이 무엇인지조차 파악하지 못한 채 병력부터 투입되었다.\u003c/p\u003e\r\n  \u003cp\u003e그 결과 대응조직이 재난보다 더 큰 피해를 일으키는 일이 반복되었다.\u003c/p\u003e\r\n  \u003cp\u003e당시에는 이러한 사태를 조정할 공통의 규정도, 모든 세력에게 인정받는 지휘권도 없었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 1~2세기 — 기업 대응부대\u003c/h3\u003e\r\n  \u003cp\u003e도시와 기업이 성장하면서 각 세력은 독자적인 특수대응부대를 창설했다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드는 수원 테러와 오염사고에 대응했고, 솔라리스는 일소와 궤도잔해를 처리했다. 모르포스는 실험체와 생체병기 유출을 회수했으며, 케르베로스는 대형 전투상황과 시설방어를 담당했다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 사건이 여러 기업의 관할에 걸쳐 발생하면 문제가 생겼다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스의 생체기술로 개조된 테러범이 케르베로스의 무기를 탈취해 아르카디아의 돔에 침입한 경우, 어느 기업이 작전지휘권을 가져야 하는지 결정하기 어려웠다.\u003c/p\u003e\r\n  \u003cp\u003e각 기업은 자신들의 기밀을 보호하기 위해 정보를 숨겼고 책임을 피하기 위해 위험성을 축소했다.\u003c/p\u003e\r\n  \u003cp\u003e초동대응이 늦어지면서 작은 사고가 도시급 재난으로 확산되는 사례가 반복되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e검은 돔 사건\u003c/h3\u003e\r\n  \u003cp\u003e이클립스 설립의 직접적인 계기로 알려진 사건은 ‘검은 돔 사건’이다.\u003c/p\u003e\r\n  \u003cp\u003e정확한 발생연도와 도시는 현재까지 기밀로 분류되어 있다.\u003c/p\u003e\r\n  \u003cp\u003e공개된 기록에 따르면 한 돔 시티의 환경제어망과 시민신원망, 자동방어체계가 동시에 장악되었다. 돔의 출입구가 봉쇄되고 인공하늘이 꺼지면서 도시 전체가 암흑에 빠졌다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 환경제어를 복구하려 했고 아르고스는 사이버공격의 근원을 추적했다. 케르베로스는 자동방어체계를 무력화하려 했으며 모르포스는 시민들에게 나타난 신경이상 증상을 조사했다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 각 기업은 핵심정보를 공유하지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e지휘권을 둘러싼 충돌이 계속되는 동안 사태는 통제불능 상태로 확산되었다. 결국 돔 내부의 상당 구역이 완전히 폐쇄되었고 수많은 시민이 구조되지 못했다.\u003c/p\u003e\r\n  \u003cp\u003e사건 이후 기업들은 단일한 현장지휘권을 가진 공동 대응조직이 필요하다는 사실을 인정했다.\u003c/p\u003e\r\n  \u003cp\u003e초기 이클립스의 전신인 \u003cstrong\u003e공동전술대응단\u003c/strong\u003e이 창설되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 3~4세기 — 공동전술대응단\u003c/h3\u003e\r\n  \u003cp\u003e공동전술대응단은 각 기업이 파견한 정보요원, 전투원, 의료진과 기술자로 구성되었다.\u003c/p\u003e\r\n  \u003cp\u003e초기에는 상설기관이 아니었다. 대형 재난이 발생할 때마다 임시로 인력을 소집하고 사건이 끝나면 해산했다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 파견된 요원들은 서로 다른 명령체계와 장비규격을 사용했다. 기업의 지시와 현장지휘관의 명령이 충돌하는 경우도 많았다.\u003c/p\u003e\r\n  \u003cp\u003e대응단은 반복되는 실패를 통해 독자적인 교리와 장비, 지휘체계가 필요하다고 판단했다.\u003c/p\u003e\r\n  \u003cp\u003e파견요원 가운데 일부가 원래의 기업으로 돌아가지 않고 상설 대응조직에 남았다. 이들은 자신들의 소속보다 현장임무를 우선하겠다는 서약을 했다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기부터 공동전술대응단은 비공식적으로 ‘이클립스’라는 명칭을 사용하기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e빛을 가리는 재난과, 그 재난을 다시 어둠 속으로 끌고 가는 조직이라는 두 가지 의미를 가지고 있었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 5세기 — 이클립스 전술국 창설\u003c/h3\u003e\r\n  \u003cp\u003e블루넷의 확장으로 기업시설이 서로 긴밀하게 연결되면서 재난 역시 빠르게 확산되기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e하나의 도시에서 발생한 악성코드가 다른 돔의 행정망을 감염시키고, 한 연구소에서 탈출한 생체병기가 카론의 운송망을 통해 여러 도시로 이동할 수 있었다.\u003c/p\u003e\r\n  \u003cp\u003e임시 대응단으로는 이러한 사건에 대처할 수 없었다.\u003c/p\u003e\r\n  \u003cp\u003e블루 테이블의 전신이 되는 기업회의는 공동전술대응단을 상설기관으로 전환하고 독립적인 수사권과 작전권을 부여했다.\u003c/p\u003e\r\n  \u003cp\u003e이로써 이클립스 전술국이 정식으로 창설되었다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스는 기업별 대응부대를 지휘할 수 있었으며, 긴급상황에서는 시설봉쇄와 통신차단, 강제대피와 위험인물 구금을 명령할 수 있게 되었다.\u003c/p\u003e\r\n  \u003cp\u003e기업들은 이 권한이 자신들에게 사용될 가능성을 두려워했다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 더 큰 재난을 막기 위해 받아들일 수밖에 없었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 6세기 — 칠정의 칼날\u003c/h3\u003e\r\n  \u003cp\u003e칠정과 블루 테이블이 성립하면서 이클립스는 초기업 공동치안기관으로 재편되었다.\u003c/p\u003e\r\n  \u003cp\u003e블루 테이블은 전술국장과 주요 작전을 승인하고, 각 기업은 예산과 장비, 전문인력을 지원했다. 대신 이클립스는 특정 기업의 이익이 아니라 칠정 전체의 안정과 문명권의 존속을 우선하도록 규정되었다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스는 기업전쟁이 일정 수준을 넘어설 경우 작전에 개입할 권한을 얻었다. 위험한 기술을 개발한 기업시설을 봉쇄하거나 칠정의 고위간부를 구금할 수도 있었다.\u003c/p\u003e\r\n  \u003cp\u003e공식적으로 모든 기업은 이클립스의 권한을 인정한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 실제 현장에서는 기업의 보안부대가 자료와 연구원을 숨기거나 접근을 방해하는 일이 끊이지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스는 칠정이 만든 기관이다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 칠정이 통제할 수 없게 되었을 때 그들을 향해 움직여야 하는 기관이기도 하다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e현재 — 멸망 후 700년\u003c/h3\u003e\r\n  \u003cp\u003e현재 이클립스 전술국은 세계에서 가장 강력한 특수대응기관 가운데 하나다.\u003c/p\u003e\r\n  \u003cp\u003e대원 개개인은 전투와 재난대응, 격리와 수사에 특화되어 있다. 일반적인 군대보다 규모는 작지만 정보, 기술과 장비의 질은 최상급이다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스는 사건을 단순히 진압하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e위협의 성격을 판정하고 확산경로를 차단하며, 관련자와 자료를 확보한다. 현장이 안정된 뒤에도 장기간의 추적과 감찰을 이어간다.\u003c/p\u003e\r\n  \u003cp\u003e전술국의 정식 출동기록은 대중에게 공개된다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 일부 작전은 사건이 종료된 뒤 기록에서 완전히 사라진다. 시민들은 대규모 정전과 구역봉쇄를 단순한 시설사고로 기억하지만, 실제로는 이클립스의 작전이 진행되었을 가능성이 있다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스의 존재는 재난에 대한 억제력이다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 그들이 무엇을 재난으로 규정하는지는 언제나 논쟁의 대상이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기관 철학\u003c/h2\u003e\r\n  \u003ch3\u003e확산을 먼저 막는다\u003c/h3\u003e\r\n  \u003cp\u003e이클립스는 인명구조보다 위협의 확산차단을 먼저 시행할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e한 구역을 즉시 봉쇄하지 않으면 도시 전체가 위험해지는 상황에서는 내부의 생존자가 남아 있어도 출입문을 폐쇄한다.\u003c/p\u003e\r\n  \u003cp\u003e이러한 판단은 잔혹해 보이지만 전술국은 더 많은 사람을 구하기 위한 불가피한 선택이라고 주장한다.\u003c/p\u003e\r\n  \u003ch3\u003e위협은 소속을 가지지 않는다\u003c/h3\u003e\r\n  \u003cp\u003e재난과 테러는 기업의 관할권을 존중하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스는 어느 기업의 시설에서 발생했는지보다 위협의 규모와 확산 가능성을 기준으로 작전을 결정한다.\u003c/p\u003e\r\n  \u003ch3\u003e모르는 것은 제거할 수 없다\u003c/h3\u003e\r\n  \u003cp\u003e정보가 부족한 상태에서 무력을 사용하는 것을 최후 선택으로 간주한다.\u003c/p\u003e\r\n  \u003cp\u003e모든 작전에는 위협평가와 정보분석이 선행된다. 현장에서도 계속해서 자료를 수집하며 판정이 바뀌면 작전방식도 즉시 변경된다.\u003c/p\u003e\r\n  \u003ch3\u003e제거보다 통제가 우선한다\u003c/h3\u003e\r\n  \u003cp\u003e위협을 파괴하는 것이 항상 최선은 아니다.\u003c/p\u003e\r\n  \u003cp\u003e희귀한 기술과 생명체, 인공지능은 연구와 대응책 개발을 위해 생포하거나 회수할 가치가 있다. 이 원칙 때문에 현장대원의 위험이 증가하기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e실패는 도시 하나로 끝나지 않는다\u003c/h3\u003e\r\n  \u003cp\u003e이클립스는 최악의 가능성을 기준으로 움직인다.\u003c/p\u003e\r\n  \u003cp\u003e지금은 한 사람이나 건물에 불과한 위협도 블루넷, 운송망과 돔의 기반시설을 통해 대륙 전체로 확산될 수 있다고 판단한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e관할 사건\u003c/h2\u003e\r\n  \u003ch3\u003e도시급 테러\u003c/h3\u003e\r\n  \u003cp\u003e돔의 생명유지시설, 전력망, 수원과 인공하늘을 공격하는 테러에 대응한다.\u003c/p\u003e\r\n  \u003cp\u003e일반적인 폭발물보다 도시기반시설을 연쇄적으로 마비시키는 복합공격을 주요 위협으로 본다.\u003c/p\u003e\r\n  \u003ch3\u003e사이버웨어 폭주\u003c/h3\u003e\r\n  \u003cp\u003e고성능 사이버웨어나 신경 인터페이스가 사용자의 통제를 벗어난 사건이다.\u003c/p\u003e\r\n  \u003cp\u003e단순한 장비고장뿐 아니라 악성코드, 열화증과 인공지능의 강제조종이 원인일 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e생체병기 유출\u003c/h3\u003e\r\n  \u003cp\u003e모르포스 및 비인가 연구시설에서 탈출한 실험체, 전염성 개조체와 자가증식 생물병기를 격리한다.\u003c/p\u003e\r\n  \u003cp\u003e필요한 경우 도시구역 전체에 생물학적 봉쇄를 적용한다.\u003c/p\u003e\r\n  \u003ch3\u003e통제불능 인공지능\u003c/h3\u003e\r\n  \u003cp\u003e도시시설, 전투드론과 블루넷을 장악한 인공지능을 추적한다.\u003c/p\u003e\r\n  \u003cp\u003e사이버전뿐 아니라 인공지능이 점유한 물리적 시설을 탈환하는 작전이 병행된다.\u003c/p\u003e\r\n  \u003ch3\u003e기업 간 무력충돌\u003c/h3\u003e\r\n  \u003cp\u003e칠정 또는 대형기업의 분쟁이 도시와 민간인에게 위협이 될 경우 개입한다.\u003c/p\u003e\r\n  \u003cp\u003e블루 테이블의 정식 정전명령을 집행하고 양측의 전략병기를 압수할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e최상위 전투개체\u003c/h3\u003e\r\n  \u003cp\u003e일반적인 군과 경찰이 제압할 수 없는 강화인간, 변이생물과 고위험 전투원을 상대한다.\u003c/p\u003e\r\n  \u003cp\u003e대상의 생포 가능성과 예상피해를 분석한 뒤 투입전력을 결정한다.\u003c/p\u003e\r\n  \u003ch3\u003e궤도·일소 재난\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스와 협력해 추락하는 궤도시설, 비정상적인 에너지 조사와 일소 피해에 대응한다.\u003c/p\u003e\r\n  \u003ch3\u003e대규모 오염\u003c/h3\u003e\r\n  \u003cp\u003e수원, 대기와 도시시설에 발생한 화학적·방사성·생물학적 오염을 격리한다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드와 아르카디아의 대응부서가 통제에 실패한 경우 지휘권을 인수한다.\u003c/p\u003e\r\n  \u003ch3\u003e금지기술 거래\u003c/h3\u003e\r\n  \u003cp\u003e백야 이전의 병기, 자율살상 인공지능과 대량살상 기술의 거래를 차단한다.\u003c/p\u003e\r\n  \u003cp\u003e현장에서 확보된 물품은 소유기업에 즉시 반환되지 않고 전술국의 심사를 거친다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e위협등급\u003c/h2\u003e\r\n  \u003ch3\u003eSHADE\u003c/h3\u003e\r\n  \u003cp\u003e일반 치안기관이 대응할 수 있지만 전문적인 감시가 필요한 위협이다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스는 직접 출동하지 않고 DCS나 기업 보안부에 정보와 자문을 제공한다.\u003c/p\u003e\r\n  \u003ch3\u003eUMBRA\u003c/h3\u003e\r\n  \u003cp\u003e전문적인 전술대응이 필요한 고위험 사건이다.\u003c/p\u003e\r\n  \u003cp\u003e지역 대응팀이 투입되며 현장 일부에 대한 통제권을 인수한다.\u003c/p\u003e\r\n  \u003ch3\u003eECLIPSE\u003c/h3\u003e\r\n  \u003cp\u003e도시의 일부 또는 주요 기업시설을 파괴할 수 있는 재난이다.\u003c/p\u003e\r\n  \u003cp\u003e중앙상황통제실이 작전을 직접 지휘하며 대규모 봉쇄와 강제대피가 시행된다.\u003c/p\u003e\r\n  \u003ch3\u003eBLACK SUN\u003c/h3\u003e\r\n  \u003cp\u003e도시 전체 또는 복수의 기업에 연쇄적인 피해를 줄 수 있는 전략급 위협이다.\u003c/p\u003e\r\n  \u003cp\u003e블루 테이블에 즉시 보고되며 칠정의 자원과 병력이 강제동원될 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003eEVENT HORIZON\u003c/h3\u003e\r\n  \u003cp\u003e문명권 전체의 존속을 위협하는 최고등급 사태다.\u003c/p\u003e\r\n  \u003cp\u003e정상적인 기업관할과 자산소유권이 일시적으로 정지된다. 이클립스는 도시폐쇄, 기반시설 파괴와 대규모 희생을 포함한 모든 대응수단을 검토할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e공식 기록상 이 등급이 발령된 사례는 존재하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 분류체계가 존재한다는 사실 자체가 최소 한 번은 필요성이 검토되었음을 의미한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기관 구조\u003c/h2\u003e\r\n  \u003cp\u003e이클립스는 정보판정, 전술진압과 기술지원이 결합된 구조를 가지고 있다.\u003c/p\u003e\r\n  \u003ch3\u003e블루 테이블 공동인가\u003c/h3\u003e\r\n  \u003cp\u003e이클립스의 설립과 최고권한은 블루 테이블의 공동인가에서 비롯된다.\u003c/p\u003e\r\n  \u003cp\u003e전술국장 임명과 대규모 기업시설 진입, 최고위협 작전은 블루 테이블의 승인을 받는다.\u003c/p\u003e\r\n  \u003cp\u003e단, 즉각적인 대응이 필요한 상황에서는 작전 후 승인이 허용된다.\u003c/p\u003e\r\n  \u003ch3\u003e전술국장\u003c/h3\u003e\r\n  \u003cp\u003e이클립스 전체를 지휘하는 최고책임자다.\u003c/p\u003e\r\n  \u003cp\u003e전술국장은 단순한 행정관이 아니라 최상위 작전과 위협판정에 직접 책임을 진다. 블루 테이블에 보고하지만 현장에서는 독립적인 결정을 내릴 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e중앙상황통제실\u003c/h3\u003e\r\n  \u003cp\u003e대륙 전역의 고위험 사건을 감시하고 출동 여부를 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스의 정보, DCS의 신고, 기업시설 경보와 솔라리스의 관측자료가 이곳에 모인다. 사건이 발생하면 위협등급과 투입인력, 격리범위를 결정한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e제1차장 — 정보·판정\u003c/h2\u003e\r\n  \u003cp\u003e작전 이전의 정보수집과 위협분석, 투입승인을 담당한다.\u003c/p\u003e\r\n  \u003ch3\u003e위협평가부\u003c/h3\u003e\r\n  \u003cp\u003e대상의 능력과 확산 가능성, 예상피해를 분석한다.\u003c/p\u003e\r\n  \u003cp\u003e생체, 사이버웨어, 인공지능과 병기위협을 종합적으로 판정한다.\u003c/p\u003e\r\n  \u003ch3\u003e정보분석부\u003c/h3\u003e\r\n  \u003cp\u003e아르고스와 현장기관이 제공한 정보를 검증한다.\u003c/p\u003e\r\n  \u003cp\u003e잘못되거나 의도적으로 조작된 정보로 인해 전술국이 이용당하지 않도록 독립적인 분석을 수행한다.\u003c/p\u003e\r\n  \u003ch3\u003e작전인가부\u003c/h3\u003e\r\n  \u003cp\u003e무력사용, 구역봉쇄와 특수구금의 법적·행정적 근거를 검토한다.\u003c/p\u003e\r\n  \u003cp\u003e긴급상황에서는 작전과 동시에 사후인가 절차를 진행한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e제2차장 — 전술·봉쇄\u003c/h2\u003e\r\n  \u003cp\u003e현장전투, 격리와 특수구금을 담당한다.\u003c/p\u003e\r\n  \u003ch3\u003e전술대응사령부\u003c/h3\u003e\r\n  \u003cp\u003e이클립스의 정예 전투부대를 지휘한다.\u003c/p\u003e\r\n  \u003cp\u003e도시전, 대인전투, 생체병기와 사이버웨어 폭주자 제압을 수행한다.\u003c/p\u003e\r\n  \u003ch3\u003e격리봉쇄부\u003c/h3\u003e\r\n  \u003cp\u003e오염지역과 위험시설을 봉쇄하고 확산을 차단한다.\u003c/p\u003e\r\n  \u003cp\u003e압력벽, 전파차단막과 이동식 방어선을 설치하며 필요하면 구역 전체의 기반시설을 정지시킨다.\u003c/p\u003e\r\n  \u003ch3\u003e특수구금부\u003c/h3\u003e\r\n  \u003cp\u003e일반 교도시설에 수용할 수 없는 인물과 개체를 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e최상위 강화인간, 넷러너, 감염자, 인공지능 매개체와 기업기밀 보유자가 주요 대상이다.\u003c/p\u003e\r\n  \u003cp\u003e특수구금부의 수감자와 시설 위치는 최고등급 기밀이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e제3차장 — 기술·지원\u003c/h2\u003e\r\n  \u003cp\u003e사이버전, 장비와 내부감찰을 담당한다.\u003c/p\u003e\r\n  \u003ch3\u003e사이버전부\u003c/h3\u003e\r\n  \u003cp\u003e적대 인공지능과 넷러너, 감염된 도시망을 제압한다.\u003c/p\u003e\r\n  \u003cp\u003e현장대응팀과 함께 움직이며 통신차단과 시스템탈환을 수행한다.\u003c/p\u003e\r\n  \u003ch3\u003e장비지원부\u003c/h3\u003e\r\n  \u003cp\u003e임무에 맞는 무기, 방호복과 격리장비를 개발하고 배치한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스와 모르포스 등에서 제공받은 기술을 이클립스 전용규격으로 개조한다.\u003c/p\u003e\r\n  \u003ch3\u003e내부감찰실\u003c/h3\u003e\r\n  \u003cp\u003e대원의 비리, 기업과의 유착과 기밀유출을 조사한다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스가 특정 기업의 사병으로 전락하는 것을 막기 위한 조직이다. 고위간부도 감찰대상에서 제외되지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e국장 직속실\u003c/h2\u003e\r\n  \u003cp\u003e전술국장에게 직접 보고하는 독립조직이다.\u003c/p\u003e\r\n  \u003cp\u003e최고등급 사건과 블루 테이블의 비공개 명령, 내부의 이중간첩을 처리한다. 세 명의 차장에게도 모든 활동이 공개되지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e공식 지휘체계로 처리할 수 없는 사건에는 직속실의 요원이 파견된다.\u003c/p\u003e\r\n  \u003cp\u003e그들이 개입한 작전은 종료 후 기록이 봉인되거나 새로운 사건명으로 대체되는 경우가 많다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e현장전력\u003c/h2\u003e\r\n  \u003ch3\u003e전술대응대\u003c/h3\u003e\r\n  \u003cp\u003e이클립스의 표준 정예부대다.\u003c/p\u003e\r\n  \u003cp\u003e대인전투와 시설진입, 인질구출과 고위험 표적제압을 담당한다. 대원들은 여러 기업의 장비를 통합적으로 운용한다.\u003c/p\u003e\r\n  \u003ch3\u003e봉쇄대\u003c/h3\u003e\r\n  \u003cp\u003e방어선과 격리구역을 구축한다.\u003c/p\u003e\r\n  \u003cp\u003e전투보다 확산차단과 민간인 통제, 오염제거에 특화되어 있다.\u003c/p\u003e\r\n  \u003ch3\u003e중장대응대\u003c/h3\u003e\r\n  \u003cp\u003e중장갑 전투개체, 대형 변이생물과 전투차량을 상대한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스의 중화기와 장갑 플랫폼을 운용한다.\u003c/p\u003e\r\n  \u003ch3\u003e사이버대응 셀\u003c/h3\u003e\r\n  \u003cp\u003e현장 넷러너와 전자전 전문가로 구성된다.\u003c/p\u003e\r\n  \u003cp\u003e시설 내부의 네트워크를 격리하고 적대코드와 인공지능의 확산을 막는다.\u003c/p\u003e\r\n  \u003ch3\u003e생체위협대응반\u003c/h3\u003e\r\n  \u003cp\u003e전염성 생물체, 변이체와 실험체에 대응한다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스 출신 연구자와 라자루스 의료요원이 파견되는 경우가 많다.\u003c/p\u003e\r\n  \u003ch3\u003e교섭관\u003c/h3\u003e\r\n  \u003cp\u003e무력진압 이전에 대상과 대화하고 투항을 유도한다.\u003c/p\u003e\r\n  \u003cp\u003e인질극뿐 아니라 자아를 가진 인공지능, 폭주한 강화인간과 집단정신을 가진 생체개체도 상대한다.\u003c/p\u003e\r\n  \u003ch3\u003e회수반\u003c/h3\u003e\r\n  \u003cp\u003e작전 후 위험기술, 시신과 데이터, 오염물질을 확보한다.\u003c/p\u003e\r\n  \u003cp\u003e현장을 정리하고 사건의 흔적을 봉인하는 역할도 맡는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e특수구금부\u003c/h2\u003e\r\n  \u003cp\u003e특수구금부는 이클립스에서 가장 폐쇄적인 조직이다.\u003c/p\u003e\r\n  \u003cp\u003e이들은 단순히 위험한 범죄자를 수감하지 않는다. 죽이는 것보다 가두는 편이 안전하거나 가치가 높은 대상을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e수감대상은 각각 다른 방식으로 격리된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e사이버웨어 폭주자는 전자기 차단실에 수감된다.\u003c/li\u003e\r\n    \u003cli\u003e넷러너는 모든 외부신호와 차단된 감각제한 구역에 수감된다.\u003c/li\u003e\r\n    \u003cli\u003e생체병기는 독립된 순환생명유지실에 격리된다.\u003c/li\u003e\r\n    \u003cli\u003e최상위 전투원은 신체능력과 약점에 맞춘 맞춤형 구속시설에 수용된다.\u003c/li\u003e\r\n    \u003cli\u003e인공지능은 물리적으로 분리된 폐쇄형 연산장치 안에 보관된다.\u003c/li\u003e\r\n    \u003cli\u003e밈과 정보 자체가 위험한 대상은 담당자의 기억과 기록까지 제한된다.\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e특수구금부의 교도관은 수감자의 이름보다 관리번호와 대응절차만을 전달받는다.\u003c/p\u003e\r\n  \u003cp\u003e일부 수감자는 수백 년 동안 시설 안에 존재한다는 소문이 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e작전 절차\u003c/h2\u003e\r\n  \u003ch3\u003e탐지\u003c/h3\u003e\r\n  \u003cp\u003eDCS, 아르고스, 기업시설이나 시민신고를 통해 사건이 접수된다.\u003c/p\u003e\r\n  \u003cp\u003e중앙상황통제실이 관련정보를 수집하고 위험성을 평가한다.\u003c/p\u003e\r\n  \u003ch3\u003e판정\u003c/h3\u003e\r\n  \u003cp\u003e위협평가부가 사건의 등급과 확산 가능성을 판정한다.\u003c/p\u003e\r\n  \u003cp\u003e일반기관이 대응할 수 있다고 판단되면 지원과 자문만 제공한다.\u003c/p\u003e\r\n  \u003ch3\u003e선점\u003c/h3\u003e\r\n  \u003cp\u003e이클립스가 개입하면 현장 지휘권과 정보접근권을 확보한다.\u003c/p\u003e\r\n  \u003cp\u003e기업과 지역기관은 관련자료와 시설도면, 인력을 제공해야 한다.\u003c/p\u003e\r\n  \u003ch3\u003e격리\u003c/h3\u003e\r\n  \u003cp\u003e위협이 확산될 수 있는 경로를 우선 차단한다.\u003c/p\u003e\r\n  \u003cp\u003e통신, 전력, 환기와 교통이 제한될 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e제압\u003c/h3\u003e\r\n  \u003cp\u003e대상의 생포와 제거, 시스템탈환 또는 시설파괴를 수행한다.\u003c/p\u003e\r\n  \u003cp\u003e작전목표는 상황에 따라 변경될 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e회수\u003c/h3\u003e\r\n  \u003cp\u003e위험한 기술과 자료, 시신과 생체표본을 확보한다.\u003c/p\u003e\r\n  \u003cp\u003e기업의 소유권보다 재발방지가 우선한다.\u003c/p\u003e\r\n  \u003ch3\u003e봉인\u003c/h3\u003e\r\n  \u003cp\u003e사건기록을 정리하고 공개등급을 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e사회혼란을 일으킬 정보는 삭제하거나 다른 사건으로 위장될 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e감찰\u003c/h3\u003e\r\n  \u003cp\u003e사건의 원인과 책임자를 조사한다.\u003c/p\u003e\r\n  \u003cp\u003e관련기업과 기관이 정보를 숨겼는지 확인하고 재발방지 명령을 내린다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 장비\u003c/h2\u003e\r\n  \u003ch3\u003e녹턴 전술복\u003c/h3\u003e\r\n  \u003cp\u003e이클립스 대원의 표준 방호복이다.\u003c/p\u003e\r\n  \u003cp\u003e방탄과 내열, 화학오염 방호기능을 제공하며 임무에 따라 추가장갑과 생명유지장치를 결합할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e섀도 실드\u003c/h3\u003e\r\n  \u003cp\u003e위험구역을 신속하게 분리하는 이동식 방벽이다.\u003c/p\u003e\r\n  \u003cp\u003e물리적 공격뿐 아니라 전자기 신호와 일부 생물학적 오염을 차단한다.\u003c/p\u003e\r\n  \u003ch3\u003e블랙아웃 발생기\u003c/h3\u003e\r\n  \u003cp\u003e일정 구역의 통신과 블루넷, 무선신호를 강제로 차단한다.\u003c/p\u003e\r\n  \u003cp\u003e적대 넷러너와 드론을 무력화하는 데 효과적이지만 시민의 의료기기와 기반시설에도 영향을 줄 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e프로미넌스 제압기\u003c/h3\u003e\r\n  \u003cp\u003e고성능 사이버웨어와 신경 인터페이스를 일시적으로 교란하는 장비다.\u003c/p\u003e\r\n  \u003cp\u003e사용자의 신경계에 심각한 손상을 줄 수 있어 높은 작전인가가 필요하다.\u003c/p\u003e\r\n  \u003ch3\u003e앵커 구속장치\u003c/h3\u003e\r\n  \u003cp\u003e강화인간과 변이체를 제압하는 가변형 구속장치다.\u003c/p\u003e\r\n  \u003cp\u003e대상의 근력과 신체구조에 맞춰 압력과 형태를 조절한다.\u003c/p\u003e\r\n  \u003ch3\u003e아이솔레이트 캡슐\u003c/h3\u003e\r\n  \u003cp\u003e감염자, 생체표본과 위험물질을 운송하는 밀폐형 용기다.\u003c/p\u003e\r\n  \u003cp\u003e내부의 공기와 온도, 압력을 독립적으로 유지한다.\u003c/p\u003e\r\n  \u003ch3\u003e이클립스 키\u003c/h3\u003e\r\n  \u003cp\u003e전술국의 긴급권한을 인증하는 물리·전자 복합장치다.\u003c/p\u003e\r\n  \u003cp\u003e인가된 작전에서는 기업시설의 문과 방어체계, 행정망에 우선 접근할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e기업들은 공식적으로 키의 권한을 인정하지만 핵심시설 일부에는 별도의 차단장치를 설치한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 시설\u003c/h2\u003e\r\n  \u003ch3\u003e중앙상황통제실\u003c/h3\u003e\r\n  \u003cp\u003e이클립스의 모든 출동과 작전을 관리하는 핵심시설이다.\u003c/p\u003e\r\n  \u003cp\u003e대륙의 기업시설과 돔 시티, 주요 노선에서 발생하는 고위험 경보가 이곳에 모인다.\u003c/p\u003e\r\n  \u003cp\u003e상황통제관은 사건의 정보가 불완전한 상태에서도 수천 명의 생명과 도시의 존속에 영향을 미치는 결정을 내려야 한다.\u003c/p\u003e\r\n  \u003ch3\u003e나이트폴 기지\u003c/h3\u003e\r\n  \u003cp\u003e이클립스의 중앙훈련 및 출동기지다.\u003c/p\u003e\r\n  \u003cp\u003e전술대응대와 봉쇄대, 특수차량과 항공전력이 대기한다. 다양한 돔과 연구시설을 재현한 훈련구역이 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003e엄브라 수용소\u003c/h3\u003e\r\n  \u003cp\u003e특수구금부가 운영하는 고위험 수용시설의 통칭이다.\u003c/p\u003e\r\n  \u003cp\u003e정확한 위치와 숫자는 공개되지 않는다. 하나의 대형시설이 아니라 위협의 종류에 따라 분산된 여러 격리시설이라는 설이 유력하다.\u003c/p\u003e\r\n  \u003ch3\u003e화이트 셀\u003c/h3\u003e\r\n  \u003cp\u003e오염되지 않은 독립환경을 유지하는 생체위협 연구시설이다.\u003c/p\u003e\r\n  \u003cp\u003e포획된 변이체와 감염물질을 분석한다. 연구원은 외부와 완전히 분리된 채 장기간 근무한다.\u003c/p\u003e\r\n  \u003ch3\u003e사일런트 룸\u003c/h3\u003e\r\n  \u003cp\u003e정보 자체가 위험한 사건을 분석하는 시설이다.\u003c/p\u003e\r\n  \u003cp\u003e연구자료와 관측기록에 접근한 사람의 감각과 기억이 오염될 수 있기 때문에 모든 통신과 기록이 제한된다.\u003c/p\u003e\r\n  \u003ch3\u003e제로 존\u003c/h3\u003e\r\n  \u003cp\u003e이클립스가 완전히 봉쇄한 지역을 부르는 비공식 명칭이다.\u003c/p\u003e\r\n  \u003cp\u003e지도와 행정기록에서 삭제된 시설, 도시구역과 황무지 지대가 포함된다. 내부에 무엇이 남아 있는지는 현장 봉쇄대도 알지 못하는 경우가 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e대원 문화\u003c/h2\u003e\r\n  \u003cp\u003e이클립스 대원은 자신들이 영웅이 아니라 마지막 선택이라고 교육받는다.\u003c/p\u003e\r\n  \u003cp\u003e그들의 임무는 언제나 완전한 승리로 끝나지 않는다. 사람을 구하기 위해 일부를 포기해야 하고, 위협을 막기 위해 증거와 시설 전체를 파괴해야 하는 경우도 있다.\u003c/p\u003e\r\n  \u003cp\u003e대원들은 결과보다 판단과 절차를 반복적으로 검증받는다.\u003c/p\u003e\r\n  \u003cp\u003e작전이 성공했더라도 불필요한 희생이나 규정위반이 확인되면 처벌받는다. 반대로 막대한 피해가 발생해도 다른 선택이 없었다는 사실이 증명되면 책임을 면할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e각 기업 출신의 대원들은 서로 다른 문화와 기술을 가지고 있다. 초기에는 출신기업에 따른 갈등이 심하지만, 현장작전을 거치며 이클립스에 대한 독자적인 소속감이 형성된다.\u003c/p\u003e\r\n  \u003cp\u003e대원들은 외부인이 자신들을 두려워한다는 사실을 알고 있다.\u003c/p\u003e\r\n  \u003cp\u003e일부는 그 공포가 현장통제에 도움이 된다고 생각하고, 다른 일부는 자신들이 지켜야 할 시민에게 괴물처럼 보이는 것을 견디지 못한다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스 내부에서 널리 사용되는 문구는 다음과 같다.\u003c/p\u003e\r\n  \u003cblockquote\u003e우리가 도착했다면 이미 늦었다. 더 늦어지게 만들지는 마라.\u003c/blockquote\u003e\r\n\r\n  \u003ch2\u003e선발과 복지\u003c/h2\u003e\r\n  \u003cp\u003e이클립스는 공개적으로 신입대원을 대규모 모집하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003eDCS, 기업보안부, 케르베로스 군과 라자루스, 아르고스 등에서 실적과 적성을 검증받은 인원을 선발한다. 황무지 용병이나 독립 넷러너가 특별채용되는 경우도 있다.\u003c/p\u003e\r\n  \u003cp\u003e지원자는 다음 능력을 평가받는다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e극한상황에서의 판단력\u003c/li\u003e\r\n    \u003cli\u003e명령과 현장상황을 구분하는 능력\u003c/li\u003e\r\n    \u003cli\u003e고위험 전투능력\u003c/li\u003e\r\n    \u003cli\u003e팀 단위 작전경험\u003c/li\u003e\r\n    \u003cli\u003e생체·기계·사이버 위협에 대한 적응\u003c/li\u003e\r\n    \u003cli\u003e강한 정신적 저항력\u003c/li\u003e\r\n    \u003cli\u003e기업과 개인적 관계를 작전에서 분리하는 능력\u003c/li\u003e\r\n    \u003cli\u003e기밀유지와 심리적 안정성\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e정식 대원에게는 다음과 같은 혜택이 제공된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e최고등급 의료와 신체복원\u003c/li\u003e\r\n    \u003cli\u003e임무 맞춤형 사이버웨어\u003c/li\u003e\r\n    \u003cli\u003e가족 신원 및 신변보호\u003c/li\u003e\r\n    \u003cli\u003e상급 돔 거주권\u003c/li\u003e\r\n    \u003cli\u003e작전 중 사망 시 가족보상\u003c/li\u003e\r\n    \u003cli\u003e정신치료와 기억안정 프로그램\u003c/li\u003e\r\n    \u003cli\u003e칠정 시설의 제한적 우선접근권\u003c/li\u003e\r\n    \u003cli\u003e퇴직 후 신분 및 재정착 보장\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e그러나 실제 퇴직률은 매우 낮다.\u003c/p\u003e\r\n  \u003cp\u003e고위험 기술과 기밀에 장기간 노출된 대원은 일반사회로 돌아가기 어렵다. 일부는 퇴직 후에도 이클립스의 보호관찰과 정기적인 정신검사를 받아야 한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e대중의 인식\u003c/h2\u003e\r\n  \u003ch3\u003e돔 시티 상류층\u003c/h3\u003e\r\n  \u003cp\u003e이클립스를 자신들의 도시와 자산을 지키는 최후의 안전장치로 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e다만 기업시설과 최고위 간부도 전술국의 조사대상이 될 수 있다는 점은 불편하게 받아들인다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 시티 일반 시민\u003c/h3\u003e\r\n  \u003cp\u003e존경과 공포가 공존한다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스가 위협을 막아준다는 사실은 알고 있지만, 전술국이 출동하면 구역봉쇄와 통신차단, 강제대피가 뒤따른다는 것도 알고 있다.\u003c/p\u003e\r\n  \u003cp\u003e거리에서 이클립스 차량을 발견한 시민은 구경하기보다 가능한 한 멀리 도망친다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 하층민\u003c/h3\u003e\r\n  \u003cp\u003e전술국이 상층과 기업을 지키기 위해 하층구역을 희생한다고 생각하는 사람이 많다.\u003c/p\u003e\r\n  \u003cp\u003e격리와 봉쇄가 하층에서 더 빠르고 광범위하게 시행된다는 불만이 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003e장막 도시 주민\u003c/h3\u003e\r\n  \u003cp\u003e이클립스는 거의 모습을 드러내지 않는 칠정의 처형부대로 인식된다.\u003c/p\u003e\r\n  \u003cp\u003e대형 재난에서 구조활동을 펼치기도 하지만 위험기술과 인물을 회수한 뒤 지역을 봉쇄해 버리는 경우가 많기 때문이다.\u003c/p\u003e\r\n  \u003ch3\u003e황무지인\u003c/h3\u003e\r\n  \u003cp\u003e블루 테이블의 영향력을 황무지까지 확대하는 군사조직으로 경계한다.\u003c/p\u003e\r\n  \u003cp\u003e일부 정착지는 이클립스의 진입을 거부하지만 최고등급 위협이 확인되면 동의 여부와 관계없이 작전이 시작될 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e기업인\u003c/h3\u003e\r\n  \u003cp\u003e필요하지만 위험한 기관으로 평가한다.\u003c/p\u003e\r\n  \u003cp\u003e경쟁기업의 사고를 제압해 줄 수 있지만 자신의 기업기밀과 불법연구도 조사할 수 있기 때문이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e다른 세력과의 관계\u003c/h2\u003e\r\n  \u003ch3\u003eTHE BLUE TABLE\u003c/h3\u003e\r\n  \u003cp\u003e이클립스의 설립과 작전권한을 승인하는 상위기관이다.\u003c/p\u003e\r\n  \u003cp\u003e전술국은 블루 테이블에 보고하지만 현장에서는 독립적인 판단권을 가진다. 블루 테이블의 결정이 늦어질 경우 국장 권한으로 먼저 작전을 시작할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e일부에서는 이클립스가 블루 테이블의 질서를 유지하는 무력기관이라고 평가한다.\u003c/p\u003e\r\n  \u003ch3\u003eARGOS SECURE NETWORKS\u003c/h3\u003e\r\n  \u003cp\u003e아르고스가 위협을 탐지하고 분석하면 이클립스가 현장에서 제압한다.\u003c/p\u003e\r\n  \u003cp\u003e양측은 가장 긴밀한 협력관계지만 정보공개 범위를 두고 자주 충돌한다. 아르고스가 정보원의 보호를 위해 자료를 숨기면 현장대원의 피해가 증가할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스는 아르고스의 정보가 조작되었을 가능성까지 독립적으로 검증한다.\u003c/p\u003e\r\n  \u003ch3\u003eDOME CIVIC SECURITY\u003c/h3\u003e\r\n  \u003cp\u003eDCS는 일반 범죄와 긴급상황에 대응한다.\u003c/p\u003e\r\n  \u003cp\u003e위협이 DCS의 능력을 넘어선다고 판단되면 이클립스가 사건과 현장지휘권을 인수한다. 이 과정에서 DCS 요원이 현장에서 배제되거나 자신의 관할구역에 접근하지 못하는 경우도 있다.\u003c/p\u003e\r\n  \u003ch3\u003eCERBERUS DEFENSE GROUP\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 이클립스에 무기, 장갑차와 중장비를 공급한다.\u003c/p\u003e\r\n  \u003cp\u003e대형 작전에는 케르베로스의 팽이나 앤빌 부대가 지원전력으로 투입될 수 있다. 그러나 전략병기 유출과 불법 군사행동이 발생하면 케르베로스 자체가 이클립스의 제압대상이 된다.\u003c/p\u003e\r\n  \u003ch3\u003eLAZARUS MEDICAL RESPONSE\u003c/h3\u003e\r\n  \u003cp\u003e라자루스는 부상자 구조와 현장응급의료를 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스가 안전구역을 확보하면 라자루스가 진입한다. 반대로 감염과 확산위험이 높은 경우 전술국은 라자루스의 구조활동을 제한할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e이 때문에 ‘한 명이라도 더 구하려는 라자루스’와 ‘전체를 위해 출입을 막는 이클립스’ 사이에 갈등이 자주 발생한다.\u003c/p\u003e\r\n  \u003ch3\u003eMORPHOS BIODYNE\u003c/h3\u003e\r\n  \u003cp\u003e모르포스는 생체병기와 사이버웨어 폭주에 대한 기술자문을 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 사건의 원인이 모르포스의 비밀연구인 경우 기업은 자료제공을 거부하거나 위협을 축소하려 한다. 이클립스 특수구금시설에는 모르포스가 반환을 요구하는 실험체와 기술이 다수 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003eNEREID HYDROSYSTEMS\u003c/h3\u003e\r\n  \u003cp\u003e수원오염과 급수시설 테러에서 협력한다.\u003c/p\u003e\r\n  \u003cp\u003e네레이드는 수질분석과 정화기술을 제공하고 이클립스는 오염지역 봉쇄와 배후세력을 제압한다.\u003c/p\u003e\r\n  \u003ch3\u003eSOLARIS ORBITAL INDUSTRIES\u003c/h3\u003e\r\n  \u003cp\u003e일소, 위성추락과 궤도시설 이상에 공동으로 대응한다.\u003c/p\u003e\r\n  \u003cp\u003e솔라리스는 관측자료와 기술을 제공하지만 헬리오스 관련 기밀을 이유로 일부 정보의 공개를 제한한다.\u003c/p\u003e\r\n  \u003ch3\u003eARCADIA HABITAT\u003c/h3\u003e\r\n  \u003cp\u003e돔 내부 재난과 구역봉쇄에서 필수적인 협력관계다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 생명유지시설과 구역격리체계를 통제하고, 이클립스는 작전 우선순위와 강제대피를 결정한다.\u003c/p\u003e\r\n  \u003ch3\u003eCHARON INTERCONTINENTAL\u003c/h3\u003e\r\n  \u003cp\u003e이클립스 대원과 장비, 특수구금 대상을 운송한다.\u003c/p\u003e\r\n  \u003cp\u003e대형 재난에서는 카론의 열차가 이동식 지휘소와 대피시설로 전환되기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003eDEAD AIR\u003c/h3\u003e\r\n  \u003cp\u003e통제불능 정보확산과 블루넷 공격으로 인해 주요 적대세력으로 분류된다.\u003c/p\u003e\r\n  \u003cp\u003e다만 데드 에어가 기업의 위험한 실험을 폭로하거나 재난경보를 먼저 전송하는 경우도 있어 모든 작전 셀을 동일하게 적대하지는 않는다.\u003c/p\u003e\r\n  \u003ch3\u003eSAINT ZERO\u003c/h3\u003e\r\n  \u003cp\u003e불법 시술과 생체위협을 이유로 단속대상이 되지만, 장막 도시의 의료재난에서는 협력이 필요하다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스가 공식적으로 확보하지 못한 환자정보와 불법 개조기록을 세인트 제로가 보유하는 경우가 많다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e사회공헌과 홍보\u003c/h2\u003e\r\n  \u003cp\u003e이클립스는 일반 기업처럼 상품광고를 하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e대신 재난대응 훈련, 시민대피 교육과 위협신고 체계를 홍보한다. 돔 시티에서는 정기적으로 대규모 봉쇄 및 대피훈련이 실시된다.\u003c/p\u003e\r\n  \u003cp\u003e교육자료에는 다음 행동수칙이 반복된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e이클립스 대원의 명령에 즉시 따를 것\u003c/li\u003e\r\n    \u003cli\u003e봉쇄선을 넘지 말 것\u003c/li\u003e\r\n    \u003cli\u003e확인되지 않은 사람과 물건을 접촉하지 말 것\u003c/li\u003e\r\n    \u003cli\u003e개인 통신망보다 공식경보를 우선할 것\u003c/li\u003e\r\n    \u003cli\u003e구조되지 않은 사람을 위해 임의로 현장에 돌아가지 말 것\u003c/li\u003e\r\n    \u003cli\u003e특수구금 대상과 대화하지 말 것\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e이클립스는 성공한 작전의 세부내용을 거의 공개하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e시민에게 알려지는 것은 구조인원, 피해규모와 위협이 제거되었다는 결과뿐이다. 구체적인 원인과 작전방식은 재발방지와 기업기밀을 이유로 봉인된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e논란과 비판\u003c/h2\u003e\r\n  \u003ch3\u003e초기업적 강제권\u003c/h3\u003e\r\n  \u003cp\u003e이클립스는 긴급상황에서 기업과 도시의 관할권을 넘어설 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e시설 진입, 통신차단과 인력구금이 사후승인만으로 이루어지는 경우도 있어 권력남용의 위험이 지적된다.\u003c/p\u003e\r\n  \u003ch3\u003e인명보다 격리 우선\u003c/h3\u003e\r\n  \u003cp\u003e위협의 확산을 막기 위해 생존자가 남아 있는 구역을 봉쇄한 사례가 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e전술국은 더 큰 피해를 막았다고 주장하지만 유가족은 구조 가능성이 충분히 검토되지 않았다고 반발한다.\u003c/p\u003e\r\n  \u003ch3\u003e특수구금\u003c/h3\u003e\r\n  \u003cp\u003e정식 재판 없이 장기간 수감되는 대상이 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e특수구금부는 일반적인 법적 절차가 위험한 대상에게 적용될 수 없다고 주장하지만 수감자의 인권과 구금기간은 공개되지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e증거와 정보의 독점\u003c/h3\u003e\r\n  \u003cp\u003e이클립스가 회수한 기술과 자료는 원래 소유기업에도 즉시 반환되지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e전술국이 위험기술을 통제한다는 명목으로 독자적인 연구와 무기개발에 활용한다는 의혹이 있다.\u003c/p\u003e\r\n  \u003ch3\u003e과도한 무력사용\u003c/h3\u003e\r\n  \u003cp\u003e위협을 완전히 제거하기 위해 건물과 기반시설 전체를 파괴하는 작전방식이 비판받는다.\u003c/p\u003e\r\n  \u003cp\u003e특히 장막 도시에서는 시설손실에 대한 보상과 재건이 제대로 이루어지지 않는 경우가 많다.\u003c/p\u003e\r\n  \u003ch3\u003e사건 은폐\u003c/h3\u003e\r\n  \u003cp\u003e재난의 원인과 책임기업이 공개되지 않은 채 단순한 사고로 처리되는 사례가 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스가 칠정의 범죄와 실패를 은폐하는 기관이라는 비판으로 이어진다.\u003c/p\u003e\r\n  \u003ch3\u003e전술국원의 면책\u003c/h3\u003e\r\n  \u003cp\u003e작전 중 발생한 민간인 피해에 대해 대원이 일반법정이 아닌 내부감찰을 받는다.\u003c/p\u003e\r\n  \u003cp\u003e공정한 처벌이 이루어지는지 외부에서는 확인하기 어렵다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e확인되지 않은 소문\u003c/h2\u003e\r\n  \u003cp\u003e이클립스의 특수구금부에는 2102년 백야와 직접 관련된 존재가 수감되어 있다는 소문이 있다.\u003c/p\u003e\r\n  \u003cp\u003e그 대상이 헬리오스의 핵심 인공지능인지, 백야 이전의 연구원인지, 혹은 당시의 재난을 통해 만들어진 새로운 생명체인지는 알려지지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e엄브라 수용소의 가장 깊은 구역에는 사망하거나 파괴할 수 없는 수감자들이 존재한다는 이야기도 있다. 일부는 수백 년 동안 노화하지 않았으며, 다른 일부는 물리적인 육체가 없는 정보나 현상에 가깝다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e또한 이클립스에는 공식적인 위협등급보다 높은 비공개 분류가 존재한다는 소문이 있다.\u003c/p\u003e\r\n  \u003cp\u003e그 대상은 도시나 칠정을 공격하는 적이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e현실의 법칙과 인간의 인식 자체를 변화시키는 사건이다.\u003c/p\u003e\r\n  \u003cp\u003e이러한 사건을 처리한 대원은 작전 후 기억을 제거당하거나 특수구금부의 관리대상이 된다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e가장 위험한 소문은 \u003cstrong\u003e이클립스 프로토콜\u003c/strong\u003e에 관한 것이다.\u003c/p\u003e\r\n  \u003cp\u003e칠정 가운데 하나가 통제불능 상태에 빠지거나 인류문명의 존속을 위협할 경우, 전술국이 해당 기업의 최고지휘부를 제거하고 모든 전략자산을 강제로 봉쇄하는 비밀계획이 존재한다는 것이다.\u003c/p\u003e\r\n  \u003cp\u003e각 기업을 대상으로 한 별도의 작전계획이 준비되어 있으며, 아르고스와 케르베로스, 솔라리스의 최고위층조차 정확한 내용을 알지 못한다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e더 나아가 마지막 계획은 칠정 전체를 대상으로 한다는 주장도 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e블루 테이블과 일곱 기업이 동시에 위협으로 판정된다면, 이클립스는 자신을 만든 모든 조직을 적으로 돌릴 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e전술국은 해당 프로토콜의 존재를 부정하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e확인해 줄 수 없다고만 답한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기관이 가진 힘\u003c/h2\u003e\r\n  \u003cp\u003e이클립스의 힘은 가장 많은 병력을 가졌다는 데 있지 않다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 필요할 때 다른 조직의 병력과 시설, 정보와 기술을 하나의 작전 아래 강제로 결합할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스의 정보가 들어오고 케르베로스의 무기가 배치되며, 솔라리스의 관측망과 모르포스의 생체기술이 현장에 투입된다. 아르카디아는 도시의 문을 닫고 카론은 대피로와 수송망을 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e이 모든 권한은 단 하나의 판단에서 시작된다.\u003c/p\u003e\r\n  \u003cp\u003e상황이 더 이상 일반적인 사건이 아니라는 판단이다.\u003c/p\u003e\r\n  \u003cp\u003e그 순간 경찰의 수사권과 기업의 소유권, 시민의 이동권은 뒤로 밀려난다. 이클립스는 구역을 봉쇄하고 통신을 끊으며, 필요한 것을 회수하고 위험하다고 판단한 대상을 데려간다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 전쟁에서 승리할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 전쟁이 시작되기 전에 적을 찾아낼 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 이미 통제할 수 없는 일이 발생했을 때 가장 먼저 지휘권을 넘겨받는 조직은 이클립스다.\u003c/p\u003e\r\n  \u003cp\u003e그들이 영웅이어서가 아니다.\u003c/p\u003e\r\n  \u003cp\u003e누군가는 어느 구역을 포기하고, 누구를 구금하며, 무엇을 세상에서 지울지 결정해야 하기 때문이다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스의 가장 무서운 권한은 사람을 죽일 수 있다는 것이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e어떤 희생이 필요하다고 결정할 수 있다는 것이다.\u003c/p\u003e\r\n\u003c/section\u003e\r\n";
window.FACTION_INFO.lazarus = "\u003csection class=\"faction-detail\"\u003e\r\n  \u003ch2\u003e기업 개요\u003c/h2\u003e\r\n  \u003cp class=\"faction-quote\"\u003e“귀하의 사망은 아직 승인되지 않았습니다.”\u003c/p\u003e\r\n  \u003cp\u003e라자루스 메디컬 리스폰스는 회원제 응급구조, 전장 의료, 신체회수, 복원수술과 생명보험을 하나의 체계로 운영하는 초거대 의료기업이다. 2102년 백야 이후 붕괴한 의료기관과 구조조직, 보험회사와 민간군사기업을 통합하며 성장했다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스의 핵심 상품은 치료가 아니다.\u003c/p\u003e\r\n  \u003cp\u003e회원에게 치명적인 사고가 발생했을 때 무장구조대를 투입해 위험지역에서 환자를 확보하고, 생존 가능한 상태로 유지한 채 기업병원까지 운반하며, 손상된 신체를 복원하는 전 과정을 보장한다.\u003c/p\u003e\r\n  \u003cp\u003e총격전, 기업분쟁, 붕괴한 건물과 오염지역에서도 계약이 유효한 한 구조대는 출동한다. 필요하다면 환자를 확보하기 위해 교전하고, 봉쇄선을 돌파하며, 다른 의료기관이나 적대세력으로부터 회원을 강제로 회수한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 라자루스의 보호는 모든 사람에게 공평하지 않다.\u003c/p\u003e\r\n  \u003cp\u003e출동 여부와 대응속도, 투입되는 병력과 복원 가능한 신체 범위는 회원등급과 계약내용에 따라 달라진다. 같은 거리에서 두 사람이 쓰러져도 한 사람에게는 장갑구조차와 전문 의료진이 출동하고, 다른 사람은 구조 가능성조차 심사받는다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 생명을 구하는 기업이다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 어떤 생명에 얼마만큼의 비용을 사용할 가치가 있는지를 계산하는 보험회사이기도 하다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기본 정보\u003c/h2\u003e\r\n  \u003ctable class=\"data-table faction-info-table\"\u003e\r\n    \u003ctbody\u003e\r\n      \u003ctr\u003e\u003cth\u003e정식 명칭\u003c/th\u003e\u003ctd\u003eLAZARUS MEDICAL RESPONSE\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e통칭\u003c/th\u003e\u003ctd\u003e라자루스\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e기업 분류\u003c/th\u003e\u003ctd\u003e회원제 무장 응급의료·보험기업\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 산업\u003c/th\u003e\u003ctd\u003e긴급출동, 무장구조, 응급치료, 신체회수\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e의료 산업\u003c/th\u003e\u003ctd\u003e외상치료, 장기이식, 신체복원, 재활\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e금융 산업\u003c/th\u003e\u003ctd\u003e생명보험, 구조보험, 복원비용 심사\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 고객\u003c/th\u003e\u003ctd\u003e기업인, 돔 시민, 용병, 카라반, 위험직종 노동자\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e상징 색상\u003c/th\u003e\u003ctd\u003e청색, 적색, 백색\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표적인 인식\u003c/th\u003e\u003ctd\u003e죽음보다 먼저 도착하는 의료기업\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e칠정 내 역할\u003c/th\u003e\u003ctd\u003e응급의료, 인명회수와 재난구조\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e본사 성격\u003c/th\u003e\u003ctd\u003e대형병원, 출동관제소와 무장항공기지가 결합된 의료단지\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 전력\u003c/th\u003e\u003ctd\u003e무장구조대\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e최고책임자\u003c/th\u003e\u003ctd\u003e최고의료책임자\u003c/td\u003e\u003c/tr\u003e\r\n    \u003c/tbody\u003e\r\n  \u003c/table\u003e\r\n\r\n  \u003ch2\u003e기업의 역사\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e백야 이전 — 민영 응급의료\u003c/h3\u003e\r\n  \u003cp\u003e라자루스의 기원은 21세기 후반에 활동하던 응급의료기업, 재난구조회사, 생명보험사와 민간 의료수송기관에서 시작되었다.\u003c/p\u003e\r\n  \u003cp\u003e당시에도 국가의 응급의료체계가 닿지 않는 지역이 존재했다. 분쟁지역과 심해시설, 사막의 산업단지와 궤도시설에서는 민간기업이 구조와 의료수송을 담당했다.\u003c/p\u003e\r\n  \u003cp\u003e고객은 정기적으로 보험료를 지불했고, 사고가 발생하면 전용 의료팀과 항공기가 출동했다. 위험지역에서 활동하는 기업직원과 군인, 부유층이 주요 고객이었다.\u003c/p\u003e\r\n  \u003cp\u003e의료기술과 신체복원 기술이 발전하면서 구조의 의미도 달라졌다.\u003c/p\u003e\r\n  \u003cp\u003e심장이 멈췄거나 장기가 파괴된 환자라도 뇌와 신경계가 일정 수준 이상 보존되었다면 다시 살릴 가능성이 생겼다. 구조대의 임무는 환자를 완전히 치료하는 것이 아니라 복원수술을 받을 수 있는 상태로 회수하는 것으로 변화했다.\u003c/p\u003e\r\n  \u003cp\u003e여러 의료기업과 보험회사는 구조, 치료와 보상심사를 하나의 계약으로 통합했다.\u003c/p\u003e\r\n  \u003cp\u003e이 통합체계가 현재 라자루스의 기원이 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e2102년 — 백야\u003c/h3\u003e\r\n  \u003cp\u003e백야가 발생하자 기존 의료체계는 가장 먼저 붕괴한 기반시설 가운데 하나가 되었다.\u003c/p\u003e\r\n  \u003cp\u003e병원은 정전과 통신두절에 빠졌고, 인공장기와 약품을 보관하던 시설의 온도조절장치가 정지했다. 도시 전체에서 화상과 방사선 피폭, 장기손상 환자가 쏟아졌지만 의료진과 병상은 절대적으로 부족했다.\u003c/p\u003e\r\n  \u003cp\u003e구조신호는 끊임없이 들어왔고 모든 환자를 구하는 것은 불가능했다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스의 전신 조직들은 환자의 생존 가능성과 구조에 필요한 자원을 계산해 우선순위를 정했다. 구할 가능성이 높은 사람과 기반시설 기술자, 계약고객이 먼저 구조되었다.\u003c/p\u003e\r\n  \u003cp\u003e수많은 사람이 이 판단 덕분에 살아남았다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 수많은 사람이 구조대가 도착하는 모습을 보고도 선택받지 못한 채 죽었다.\u003c/p\u003e\r\n  \u003cp\u003e백야 당시의 구조기록은 현재까지 라자루스 내부에서 가장 민감한 기밀로 취급된다. 어떤 기준으로 사람을 선택했고, 누구의 구조를 포기했는지 완전한 명단은 공개되지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e이날의 경험은 라자루스의 기본원칙을 만들었다.\u003c/p\u003e\r\n  \u003cp\u003e구할 수 없는 모두에게 손을 내밀어 구조대 전체를 잃기보다, 계약과 가능성에 따라 확실하게 살릴 사람을 선택한다는 원칙이다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망력 초기 — 움직이는 병원\u003c/h3\u003e\r\n  \u003cp\u003e백야 이후 대부분의 대형병원은 정상적으로 운영될 수 없었다.\u003c/p\u003e\r\n  \u003cp\u003e의약품과 전력이 부족했고, 고정된 의료시설은 약탈자와 군벌의 주요 표적이 되었다. 부상자는 병원까지 이동하지 못했고 병원은 환자가 있는 장소까지 갈 수 없었다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스의 전신 의료진은 장갑차량에 수술실과 생명유지장치를 설치했다.\u003c/p\u003e\r\n  \u003cp\u003e이동식 의료차량은 황무지와 붕괴한 도시를 돌아다니며 환자를 회수했다. 구조대는 의료진뿐 아니라 무장경비원, 운전사와 정비사로 구성되었다.\u003c/p\u003e\r\n  \u003cp\u003e약탈자들이 의료차량과 약품을 노리기 시작하자 구조대의 무장은 점점 강화되었다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 환자를 구하려면 먼저 현장을 제압해야 한다는 현실을 받아들였다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기 최초의 무장구조대가 창설되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 1세기 — 회원계약의 성립\u003c/h3\u003e\r\n  \u003cp\u003e제한된 의료자원으로 모든 정착지를 보호하는 것은 불가능했다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 정기적으로 물자와 비용을 제공하는 도시와 개인에게 우선적인 구조를 보장하는 회원계약을 도입했다. 회원의 보험료는 구조차량과 병원, 약품과 의료진을 유지하는 데 사용되었다.\u003c/p\u003e\r\n  \u003cp\u003e계약자는 사고가 발생하지 않더라도 비용을 지불했다. 대신 위험한 순간에는 라자루스가 구조를 위해 병력과 의료자원을 투입했다.\u003c/p\u003e\r\n  \u003cp\u003e초기의 회원증은 이름과 혈액형, 병력과 계약내용이 기록된 물리식 인식표였다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스 구조대는 현장에서 회원 인식표를 확인하고 치료 가능성과 계약범위를 판단했다.\u003c/p\u003e\r\n  \u003cp\u003e회원제는 안정적인 의료망을 만드는 데 성공했다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 비용을 지불할 수 없는 사람은 보호망 밖에 남겨졌다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 2세기 — 회수전쟁\u003c/h3\u003e\r\n  \u003cp\u003e고위급 기업인과 기술자, 군사요원의 생명은 막대한 가치를 지녔다.\u003c/p\u003e\r\n  \u003cp\u003e적대세력은 이들을 납치해 협상수단으로 사용했고, 전장에서 쓰러진 강화인간의 신체와 사이버웨어를 회수하려 했다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 회원을 단순한 환자가 아니라 반드시 회수해야 할 계약대상으로 규정했다.\u003c/p\u003e\r\n  \u003cp\u003e구조대는 전투지역과 적대시설에 진입해 환자를 확보했다. 다른 세력이 회원을 억류하면 의료적 보호권을 주장했고, 협상이 실패하면 무력으로 탈환했다.\u003c/p\u003e\r\n  \u003cp\u003e일부 작전에서는 환자의 구조보다 시신과 신경조직, 기업기밀이 담긴 임플란트를 회수하는 것이 우선되었다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기에 라자루스의 무장구조대는 일반적인 구급대가 아니라 의료를 목적으로 작전을 수행하는 전문 전투조직으로 발전했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 3세기 — 복원기술의 발전\u003c/h3\u003e\r\n  \u003cp\u003e모르포스의 배양장기와 신경공학이 발전하면서 라자루스의 구조 가능범위가 크게 확대되었다.\u003c/p\u003e\r\n  \u003cp\u003e과거에는 현장에서 사망으로 판정되던 환자도 뇌와 핵심 신경계가 보존되어 있다면 회복할 가능성이 생겼다. 라자루스는 신체 전체의 상태보다 복원에 필요한 핵심기관을 우선적으로 보존하는 의료기술을 개발했다.\u003c/p\u003e\r\n  \u003cp\u003e구조대는 환자의 혈액순환과 뇌기능을 인공적으로 유지하고, 손상된 신체를 절단하거나 정지시켜 추가적인 세포손상을 막았다.\u003c/p\u003e\r\n  \u003cp\u003e‘살아 있다’는 기준도 변했다.\u003c/p\u003e\r\n  \u003cp\u003e심장과 폐가 멈추었더라도 복원 가능성이 남아 있다면 라자루스는 환자를 사망자로 분류하지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기에 기업의 대표적인 문구가 만들어졌다.\u003c/p\u003e\r\n  \u003cblockquote\u003e귀하의 사망은 아직 승인되지 않았습니다.\u003c/blockquote\u003e\r\n\r\n  \u003ch3\u003e멸망 후 4세기 — 돔 의료망\u003c/h3\u003e\r\n  \u003cp\u003e대형 돔 시티가 성장하면서 라자루스는 아르카디아의 일반 의료체계와 결합했다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아 병원은 일상적인 진료와 공중보건을 담당했고, 라자루스는 중증외상과 위험지역 구조, 고급 신체복원을 맡았다.\u003c/p\u003e\r\n  \u003cp\u003e도시 곳곳에 라자루스 출동거점이 설치되었다. 회원에게 위험신호가 발생하면 가장 가까운 구조팀이 자동으로 배정되었다.\u003c/p\u003e\r\n  \u003cp\u003e돔 내부에서는 총격과 산업재해뿐 아니라 구역봉쇄, 대기오염과 생명유지시설 사고에 대응했다.\u003c/p\u003e\r\n  \u003cp\u003e이 시기부터 라자루스 회원권은 의료보험을 넘어 사회적 신분의 상징이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e상위 회원이 위험에 처하면 일반 교통이 통제되고 전용 항공기가 출동했다. 기업은 한 사람의 생명을 구하기 위해 도시 전체의 통행을 바꿀 수 있었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 5세기 — 블루넷 생명신호망\u003c/h3\u003e\r\n  \u003cp\u003e블루넷이 확장되면서 회원의 신체정보와 위치, 계약상태가 실시간으로 연결되기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e등록된 바이오모니터는 심박, 뇌파, 출혈과 사이버웨어 상태를 분석한다. 치명적인 이상이 감지되면 회원이 직접 신고하지 못하더라도 출동요청이 생성된다.\u003c/p\u003e\r\n  \u003cp\u003e출동관제부는 환자의 상태와 위치, 현장위험과 주변 구조팀을 분석해 투입전력을 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e이 기술은 대응속도를 크게 향상시켰다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 라자루스가 회원의 건강과 위치, 전투와 사생활을 지속적으로 감시할 수 있게 만들었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 6세기 — 초기업 의료기관\u003c/h3\u003e\r\n  \u003cp\u003e기업 간 교류와 분쟁이 증가하면서 어느 기업에 속하지 않고 다양한 세력의 환자를 구조할 수 있는 의료기관이 필요해졌다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 공식적인 의료중립을 선언했다.\u003c/p\u003e\r\n  \u003cp\u003e정식 계약이 존재하는 한 환자의 소속과 정치적 입장에 관계없이 구조한다는 원칙이었다. 적대 중인 두 기업의 회원이 같은 현장에 있어도 계약에 따라 양측을 모두 회수했다.\u003c/p\u003e\r\n  \u003cp\u003e칠정과 블루 테이블은 라자루스를 공동 응급의료기관으로 인정했다. 주요 도시와 기업시설은 라자루스 구조대의 통행권과 제한적인 무장활동을 보장했다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 칠정의 직접 구성기업과는 다른 위치에 있으면서도, 칠정의 도시와 기업을 유지하는 핵심 공식기관으로 자리 잡았다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e현재 — 멸망 후 700년\u003c/h3\u003e\r\n  \u003cp\u003e현재 라자루스 메디컬 리스폰스는 돔 시티와 주요 기업시설, 일부 장막 도시와 황무지 노선에 출동망을 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e수백 개의 병원과 출동거점, 장갑구조차와 항공기를 보유하고 있다. 회원의 생명신호가 끊기면 가장 가까운 출동팀이 현장위험과 구조 가능성을 분석한다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 죽은 사람을 마법처럼 되살리는 기업이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e뇌와 핵심 신경조직이 완전히 파괴되었거나 장시간 손상이 지속되면 현대의 기술로도 복원할 수 없다. 시신이 소실되었거나 회수할 수 없는 경우도 마찬가지다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 일반인이 죽음이라고 생각하는 상태와 라자루스가 복원 불가능하다고 판정하는 상태 사이에는 큰 차이가 있다.\u003c/p\u003e\r\n  \u003cp\u003e회원의 심장이 멎고 신체 대부분이 파괴되었더라도, 구조대가 제시간에 도착해 핵심조직을 보존한다면 다시 살아날 가능성이 있다.\u003c/p\u003e\r\n  \u003cp\u003e그 가능성을 현실로 만드는 것이 라자루스의 상품이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업 철학\u003c/h2\u003e\r\n  \u003ch3\u003e구조는 현장에 도착하는 것으로 시작된다\u003c/h3\u003e\r\n  \u003cp\u003e최고의 의료기술도 환자를 병원까지 데려오지 못하면 의미가 없다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 병원보다 출동망과 관제체계를 기업의 핵심으로 본다. 의료진은 환자가 있는 위험지역까지 직접 진입한다.\u003c/p\u003e\r\n  \u003ch3\u003e구조대의 안전도 의료행위다\u003c/h3\u003e\r\n  \u003cp\u003e구조대가 전멸하면 현재의 환자뿐 아니라 이후의 환자도 구할 수 없다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 무모한 희생을 의료윤리로 인정하지 않는다. 현장위험이 지나치게 높다면 지원병력을 기다리거나 구조를 보류할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e환자보다 계약을 먼저 확인한다\u003c/h3\u003e\r\n  \u003cp\u003e라자루스의 자원은 회원의 보험료로 유지된다.\u003c/p\u003e\r\n  \u003cp\u003e따라서 현장에서 계약회원이 우선된다. 비회원도 구조할 수 있지만 회원의 생존 가능성을 낮추면서까지 우선하지는 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e사망은 의학적 판정이다\u003c/h3\u003e\r\n  \u003cp\u003e현장의 외형이나 일반적인 생명징후만으로 사망을 확정하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e신경계와 세포상태, 복원 가능성과 경과시간을 분석해 최종판정을 내린다.\u003c/p\u003e\r\n  \u003ch3\u003e회수는 치료의 일부다\u003c/h3\u003e\r\n  \u003cp\u003e환자뿐 아니라 절단된 신체, 파손된 사이버웨어와 생체조직도 회수한다.\u003c/p\u003e\r\n  \u003cp\u003e복원수술에 사용할 수 있고 환자의 기억과 신원, 기업기밀이 포함되어 있을 가능성이 있기 때문이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e핵심 산업\u003c/h2\u003e\r\n  \u003ch3\u003e회원제 긴급출동\u003c/h3\u003e\r\n  \u003cp\u003e회원의 신고 또는 바이오모니터 경보가 발생하면 출동관제부가 구조팀을 배정한다.\u003c/p\u003e\r\n  \u003cp\u003e회원등급, 환자상태, 현장위험과 거리를 기준으로 차량과 의료진, 무장인력의 규모가 결정된다.\u003c/p\u003e\r\n  \u003cp\u003e출동은 구조 성공을 절대적으로 보장하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e현장 접근이 불가능하거나 계약에서 제외된 위험이 존재하는 경우 작전이 지연되거나 취소될 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e무장구조\u003c/h3\u003e\r\n  \u003cp\u003e총격전, 폭동, 기업분쟁과 약탈지역에서 환자를 회수한다.\u003c/p\u003e\r\n  \u003cp\u003e무장구조대는 의료진이 활동할 수 있는 안전구역을 확보하고, 적대세력을 제압하며 환자의 이동경로를 만든다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 선제적인 전투를 피하지만 구조대와 환자를 위협하는 대상에 대해서는 강한 무력을 사용한다.\u003c/p\u003e\r\n  \u003ch3\u003e현장응급의료\u003c/h3\u003e\r\n  \u003cp\u003e출혈통제, 심폐기능 보조, 신경보존과 긴급 절단을 시행한다.\u003c/p\u003e\r\n  \u003cp\u003e목표는 환자를 완전히 치료하는 것이 아니라 병원까지 살아 있는 상태로 운반하는 것이다.\u003c/p\u003e\r\n  \u003ch3\u003e신체회수\u003c/h3\u003e\r\n  \u003cp\u003e환자와 분리된 사지, 장기, 사이버웨어와 신경저장장치를 회수한다.\u003c/p\u003e\r\n  \u003cp\u003e사망 가능성이 높은 현장에서도 핵심조직과 기록의 회수를 위해 작전이 계속될 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e신체복원\u003c/h3\u003e\r\n  \u003cp\u003e배양장기, 의체와 신경재생을 통해 손상된 신체를 복원한다.\u003c/p\u003e\r\n  \u003cp\u003e원래 신체에 가까운 복원, 기능 중심의 표준복원과 고성능 사이버웨어를 이용한 강화복원이 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e계약범위를 넘는 복원에는 추가비용이 청구된다.\u003c/p\u003e\r\n  \u003ch3\u003e응급의료보험\u003c/h3\u003e\r\n  \u003cp\u003e회원은 정기적으로 보험료를 납부하고 출동과 치료, 복원 범위를 보장받는다.\u003c/p\u003e\r\n  \u003cp\u003e직업과 거주지역, 전투경력, 사이버웨어와 질병에 따라 보험료가 달라진다.\u003c/p\u003e\r\n  \u003ch3\u003e기업 의료계약\u003c/h3\u003e\r\n  \u003cp\u003e기업은 직원 전체를 라자루스 회원으로 등록할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e산업재해와 테러, 기업전쟁에 대비한 전용 출동팀을 배치하며 중요간부에게는 개인 구조팀이 지정되기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e재난 의료지원\u003c/h3\u003e\r\n  \u003cp\u003e대형 붕괴, 일소, 오염과 도시재난에 이동식 병원과 구조대를 파견한다.\u003c/p\u003e\r\n  \u003cp\u003e블루 테이블이나 도시행정부의 공공계약이 존재하면 비회원도 대규모로 치료한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e계약등급\u003c/h2\u003e\r\n  \u003cp\u003e라자루스의 회원계약은 \u003cstrong\u003e더스트, 쉘터, 오아시스, 에덴\u003c/strong\u003e의 네 단계로 구분된다.\u003c/p\u003e\r\n  \u003cp\u003e계약등급은 단순히 병원에서 받을 수 있는 치료의 수준만을 의미하지 않는다. 출동 가능 지역과 대응속도, 파견되는 구조팀의 규모, 무장지원 여부, 신체복원 범위와 치료비 보장한도까지 결정한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003eDUST — 더스트\u003c/h3\u003e\r\n  \u003cp\u003e일반 시민과 저위험 직종 종사자를 위한 기본 계약등급이다.\u003c/p\u003e\r\n  \u003ch4\u003e주요 보장\u003c/h4\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e돔 시티 및 지정 안전구역 내 긴급출동\u003c/li\u003e\r\n    \u003cli\u003e일반 구급차와 응급의료진 배치\u003c/li\u003e\r\n    \u003cli\u003e일상적인 사고와 산업재해 구조\u003c/li\u003e\r\n    \u003cli\u003e현장 응급처치\u003c/li\u003e\r\n    \u003cli\u003e라자루스 계약병원 이송\u003c/li\u003e\r\n    \u003cli\u003e기본적인 외상치료\u003c/li\u003e\r\n    \u003cli\u003e표준 인공장기와 보급형 의체\u003c/li\u003e\r\n    \u003cli\u003e제한적인 재활치료\u003c/li\u003e\r\n    \u003cli\u003e기본 바이오모니터 연동\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003ch4\u003e제한사항\u003c/h4\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e총격전과 폭동이 진행 중인 구역에는 즉시 진입하지 않을 수 있다.\u003c/li\u003e\r\n    \u003cli\u003e황무지와 비인가 장막 도시는 기본 출동범위에서 제외된다.\u003c/li\u003e\r\n    \u003cli\u003e무장구조대는 원칙적으로 배정되지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e배양장기와 맞춤형 신체복원에는 추가비용이 발생한다.\u003c/li\u003e\r\n    \u003cli\u003e구조요청이 집중되면 상위 계약자보다 출동순위가 늦어질 수 있다.\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e더스트는 안전한 도시구역에서 발생하는 일반적인 사고를 보장한다. 그러나 전투와 대규모 재난처럼 적극적인 무장진입이 필요한 상황까지 책임지는 계약은 아니다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003eSHELTER — 쉘터\u003c/h3\u003e\r\n  \u003cp\u003e위험직종 노동자, 현장기술자와 일반 용병을 위한 실질적인 구조계약이다.\u003c/p\u003e\r\n  \u003ch4\u003e주요 보장\u003c/h4\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e더스트의 모든 보장\u003c/li\u003e\r\n    \u003cli\u003e제한적인 위험지역 출동\u003c/li\u003e\r\n    \u003cli\u003e무장호위가 포함된 구조차량\u003c/li\u003e\r\n    \u003cli\u003e총격사건과 산업재난 대응\u003c/li\u003e\r\n    \u003cli\u003e우선 병상 및 수술실 배정\u003c/li\u003e\r\n    \u003cli\u003e표준 신체복원\u003c/li\u003e\r\n    \u003cli\u003e사이버웨어 긴급안정화\u003c/li\u003e\r\n    \u003cli\u003e계약된 절단부위의 의체복원\u003c/li\u003e\r\n    \u003cli\u003e돔 외곽과 단거리 황무지 구조\u003c/li\u003e\r\n    \u003cli\u003e강화된 생명신호 감시\u003c/li\u003e\r\n    \u003cli\u003e현장에서 분리된 신체와 장비의 제한적 회수\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003ch4\u003e제한사항\u003c/h4\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e대규모 기업전쟁과 최고위험구역은 별도 특약이 필요하다.\u003c/li\u003e\r\n    \u003cli\u003e현장의 화력이 구조팀의 대응능력을 넘어서면 진입이 보류될 수 있다.\u003c/li\u003e\r\n    \u003cli\u003e맞춤형 장기와 고급 사이버웨어는 보장한도를 초과할 수 있다.\u003c/li\u003e\r\n    \u003cli\u003e장거리 황무지 구조는 거점과 차량 상황에 따라 제한된다.\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e쉘터부터 라자루스의 무장응급의료 서비스가 본격적으로 적용된다. 위험한 현장에서 활동하는 사람들에게 가장 널리 이용되는 계약등급이다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003eOASIS — 오아시스\u003c/h3\u003e\r\n  \u003cp\u003e기업간부, 상류층, 고위 용병과 중요기술자를 위한 상급 계약등급이다.\u003c/p\u003e\r\n  \u003ch4\u003e주요 보장\u003c/h4\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e쉘터의 모든 보장\u003c/li\u003e\r\n    \u003cli\u003e무장구조대 우선출동\u003c/li\u003e\r\n    \u003cli\u003e장갑구조차 또는 의료항공기 배치\u003c/li\u003e\r\n    \u003cli\u003e교전지역과 적대구역 진입\u003c/li\u003e\r\n    \u003cli\u003e개인별 의료정보와 복원계획 사전등록\u003c/li\u003e\r\n    \u003cli\u003e맞춤형 장기 및 고급 의체복원\u003c/li\u003e\r\n    \u003cli\u003e신경조직과 기억손상의 전문치료\u003c/li\u003e\r\n    \u003cli\u003e타 도시 및 장거리 의료이송\u003c/li\u003e\r\n    \u003cli\u003e현장에 남겨진 신체와 사이버웨어 회수\u003c/li\u003e\r\n    \u003cli\u003e납치 및 불법구금 상황의 구조심사\u003c/li\u003e\r\n    \u003cli\u003e계약된 가족과 지정인에 대한 동반구조\u003c/li\u003e\r\n    \u003cli\u003e전담 보험심사관 배정\u003c/li\u003e\r\n    \u003cli\u003e신원과 의료기록의 강화된 보안\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e오아시스 계약자가 위험에 처하면 출동관제부는 지역 구조팀의 기존 임무와 차량배치를 조정해 대응전력을 확보할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e필요할 경우 DCS나 현지 보안기관과 협의해 교통과 출입을 통제하고 전용 구조경로를 개방한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003eEDEN — 에덴\u003c/h3\u003e\r\n  \u003cp\u003e칠정 최고간부, 대형 투자자와 전략적으로 중요한 인물을 위한 최상위 계약등급이다.\u003c/p\u003e\r\n  \u003cp\u003e에덴은 공개적으로 가입할 수 있는 상품이 아니다. 막대한 계약비용뿐 아니라 라자루스의 별도 심사와 승인이 필요하다.\u003c/p\u003e\r\n  \u003ch4\u003e주요 보장\u003c/h4\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e오아시스의 모든 보장\u003c/li\u003e\r\n    \u003cli\u003e회원 전담 무장구조팀 상시 배정\u003c/li\u003e\r\n    \u003cli\u003e생명신호와 위치의 실시간 감시\u003c/li\u003e\r\n    \u003cli\u003e다수 출동거점의 동시대기\u003c/li\u003e\r\n    \u003cli\u003e돔과 기업 관할을 넘는 광역구조\u003c/li\u003e\r\n    \u003cli\u003e대규모 교전지역과 최고위험구역 진입\u003c/li\u003e\r\n    \u003cli\u003e복수의 장갑차량과 의료항공기 투입\u003c/li\u003e\r\n    \u003cli\u003e외부 용병과 기업군을 고용한 구조작전\u003c/li\u003e\r\n    \u003cli\u003e개인 유전자 기반 배양장기의 사전비축\u003c/li\u003e\r\n    \u003cli\u003e최고급 맞춤형 신체복원\u003c/li\u003e\r\n    \u003cli\u003e중증 신경손상과 기억손상의 장기복원\u003c/li\u003e\r\n    \u003cli\u003e신체 일부가 회수되지 않은 상황에 대비한 사전 복원계획\u003c/li\u003e\r\n    \u003cli\u003e사망판정 이전까지 최대한의 의료자원 투입\u003c/li\u003e\r\n    \u003cli\u003e장기 실종 이후에도 회수작전 유지\u003c/li\u003e\r\n    \u003cli\u003e가족 및 사전에 지정된 인원의 동시보호\u003c/li\u003e\r\n    \u003cli\u003e완전한 비공개 치료와 의료기록 봉인\u003c/li\u003e\r\n    \u003cli\u003e구조 실패 시 시신과 핵심 신경조직의 우선회수\u003c/li\u003e\r\n    \u003cli\u003e사실상 제한이 없는 치료 및 작전비 보장\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e에덴 계약자의 구조는 일반적인 의료출동이 아니라 기업 전체의 중요작전으로 취급된다.\u003c/p\u003e\r\n  \u003cp\u003e환자를 살릴 가능성이 남아 있는 한 라자루스는 의료진과 무장구조대, 차량과 항공전력을 지속해서 투입한다. 필요하다면 다른 기업과 협상하고 현지 용병을 고용하며, 도시의 교통과 시설이용권을 구매한다.\u003c/p\u003e\r\n  \u003cp\u003e에덴은 죽지 않는 것을 보장하는 계약이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e죽음을 막기 위해 라자루스가 사용할 자원에 사실상 상한을 두지 않는 계약이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e비회원 처리\u003c/h2\u003e\r\n  \u003cp\u003e비회원이라고 해서 반드시 구조되지 않는 것은 아니다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 다음 조건에서 비회원을 치료할 수 있다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e구조팀의 안전과 회원구조에 영향을 주지 않는 경우\u003c/li\u003e\r\n    \u003cli\u003e도시행정부나 기업과 공공구조 계약이 체결된 경우\u003c/li\u003e\r\n    \u003cli\u003e대형 재난으로 집단구조 명령이 내려진 경우\u003c/li\u003e\r\n    \u003cli\u003e현장에서 즉시 비용을 지불하거나 보증인을 확보한 경우\u003c/li\u003e\r\n    \u003cli\u003e구조대원이 긴급한 의료윤리상 필요성을 인정한 경우\u003c/li\u003e\r\n    \u003cli\u003e비회원이 중요정보나 기술, 노동계약으로 비용을 대체하는 경우\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e비회원은 현장에서 임시계약을 체결할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e의식이 없는 환자는 생존 후 상환을 조건으로 긴급구조가 승인될 수 있다. 이 경우 치료비와 출동비, 위험수당이 채무로 등록된다.\u003c/p\u003e\r\n  \u003cp\u003e상환할 수 없는 환자는 장기간의 노동계약이나 기업 의료시험, 신체기증 계약을 제안받기도 한다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 이를 강제가 아닌 생존을 위한 선택이라고 설명한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e출동 우선순위\u003c/h2\u003e\r\n  \u003cp\u003e라자루스는 단순히 회원등급만으로 출동순서를 결정하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e다음 요소가 함께 평가된다.\u003c/p\u003e\r\n  \u003col\u003e\r\n    \u003cli\u003e환자의 생존 가능시간\u003c/li\u003e\r\n    \u003cli\u003e현재 생명징후와 신경손상 정도\u003c/li\u003e\r\n    \u003cli\u003e현장까지의 거리\u003c/li\u003e\r\n    \u003cli\u003e구조팀이 감당해야 할 위험\u003c/li\u003e\r\n    \u003cli\u003e회원등급과 계약범위\u003c/li\u003e\r\n    \u003cli\u003e사용할 수 있는 차량과 의료진\u003c/li\u003e\r\n    \u003cli\u003e구조로 인해 발생할 수 있는 추가 사상자\u003c/li\u003e\r\n    \u003cli\u003e다른 환자와의 우선순위 충돌\u003c/li\u003e\r\n    \u003cli\u003e환자의 전략적·사회적 중요도\u003c/li\u003e\r\n    \u003cli\u003e도시 및 기업의 긴급명령\u003c/li\u003e\r\n  \u003c/ol\u003e\r\n  \u003cp\u003e상위 회원이라도 뇌와 신경계가 완전히 파괴되어 복원이 불가능하다면 구조 우선순위가 낮아질 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e반대로 낮은 등급의 회원이라도 몇 분 안에 구조하지 않으면 사망하고 현장위험이 낮다면 먼저 구조될 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e최종적인 배정은 출동관제부가 결정한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e긴급출동 과정\u003c/h2\u003e\r\n  \u003ch3\u003e생명신호 감지\u003c/h3\u003e\r\n  \u003cp\u003e회원의 바이오모니터, 직접신고나 주변인의 호출로 긴급상황이 접수된다.\u003c/p\u003e\r\n  \u003ch3\u003e계약 확인\u003c/h3\u003e\r\n  \u003cp\u003e회원등급과 현재 보험료, 출동범위와 특약을 확인한다.\u003c/p\u003e\r\n  \u003cp\u003e환자의 신원이 불분명해도 생체정보를 통해 임시 확인할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e현장 판정\u003c/h3\u003e\r\n  \u003cp\u003e출동관제부가 위치, 적대세력, 오염과 교통상황을 분석한다.\u003c/p\u003e\r\n  \u003cp\u003e필요하면 아르고스와 DCS, 이클립스에 정보를 요청한다.\u003c/p\u003e\r\n  \u003ch3\u003e팀 배정\u003c/h3\u003e\r\n  \u003cp\u003e환자상태와 위험도에 따라 구급차, 장갑구조차와 의료항공기를 배정한다.\u003c/p\u003e\r\n  \u003cp\u003e일반 의료팀만 출동할 수도 있고 무장구조대가 동행할 수도 있다.\u003c/p\u003e\r\n  \u003ch3\u003e접근과 안전확보\u003c/h3\u003e\r\n  \u003cp\u003e구조대가 현장에 진입해 환자까지의 경로를 확보한다.\u003c/p\u003e\r\n  \u003cp\u003e교전이 발생하면 무장대원이 위협을 제압하는 동안 의료진이 환자를 안정시킨다.\u003c/p\u003e\r\n  \u003ch3\u003e환자 회수\u003c/h3\u003e\r\n  \u003cp\u003e환자와 절단된 신체, 핵심 사이버웨어와 개인 의료기록을 회수한다.\u003c/p\u003e\r\n  \u003ch3\u003e현장 안정화\u003c/h3\u003e\r\n  \u003cp\u003e출혈과 신경손상, 장기기능을 통제하고 이동 가능한 상태로 만든다.\u003c/p\u003e\r\n  \u003ch3\u003e의료이송\u003c/h3\u003e\r\n  \u003cp\u003e환자의 상태와 계약에 맞는 병원 또는 복원센터로 이송한다.\u003c/p\u003e\r\n  \u003ch3\u003e보험심사\u003c/h3\u003e\r\n  \u003cp\u003e치료와 작전이 끝난 뒤 계약범위와 추가비용을 심사한다.\u003c/p\u003e\r\n  \u003cp\u003e긴급상황에서는 먼저 치료한 뒤 비용을 청구한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e핵심 조직\u003c/h2\u003e\r\n  \u003ch3\u003e이사회\u003c/h3\u003e\r\n  \u003cp\u003e라자루스의 장기전략, 회원정책과 주요 기업계약을 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e의료전문가뿐 아니라 보험과 금융, 군사계약 책임자들이 참여한다. 어떤 생명을 구할 수 있는지가 아니라 어느 수준까지 비용을 감당할지를 결정한다.\u003c/p\u003e\r\n  \u003ch3\u003e최고의료책임자\u003c/h3\u003e\r\n  \u003cp\u003e라자루스의 최고책임자다.\u003c/p\u003e\r\n  \u003cp\u003e경영자이면서 기업 전체의 의료윤리와 구조기준에 대한 최종권한을 가진다. 대규모 재난에서는 출동 우선순위와 의료자원 배분을 직접 결정할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e중앙출동통제본부\u003c/h3\u003e\r\n  \u003cp\u003e라자루스의 모든 구조신호와 생명정보가 모이는 핵심 관제기관이다.\u003c/p\u003e\r\n  \u003cp\u003e각 거점의 의료진과 차량, 병상과 혈액, 장기의 상황을 실시간으로 확인하며 최적의 구조팀을 배정한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e제1본부장 — 계약·관제\u003c/h2\u003e\r\n  \u003cp\u003e회원계약, 출동통제와 이동수단을 담당한다.\u003c/p\u003e\r\n  \u003ch3\u003e회원계약부\u003c/h3\u003e\r\n  \u003cp\u003e개인 및 기업회원의 보험계약을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e직업과 건강, 거주지역과 전투위험을 분석해 보험료와 보장범위를 결정한다.\u003c/p\u003e\r\n  \u003ch3\u003e출동관제부\u003c/h3\u003e\r\n  \u003cp\u003e긴급신호를 접수하고 구조 우선순위와 투입전력을 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e현장팀이 출동한 뒤에도 이동경로와 지원전력을 조정한다.\u003c/p\u003e\r\n  \u003ch3\u003e차량·항공부\u003c/h3\u003e\r\n  \u003cp\u003e구급차, 장갑구조차, 의료항공기와 이동식 병원을 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e차량과 항공기의 정비, 배치와 승무원 훈련을 담당한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e제2본부장 — 구조·의료\u003c/h2\u003e\r\n  \u003cp\u003e현장구조와 응급치료를 담당하는 라자루스의 핵심 실무부문이다.\u003c/p\u003e\r\n  \u003ch3\u003e무장구조대\u003c/h3\u003e\r\n  \u003cp\u003e적대적이고 위험한 환경에서 의료진과 환자를 보호한다.\u003c/p\u003e\r\n  \u003cp\u003e무장구조대는 진압을 목적으로 하는 군대가 아니다. 모든 전투행위는 환자에게 접근하고 안전하게 이송하기 위한 수단으로 규정된다.\u003c/p\u003e\r\n  \u003cp\u003e주요 임무는 다음과 같다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e교전지역 진입\u003c/li\u003e\r\n    \u003cli\u003e환자 위치 확보\u003c/li\u003e\r\n    \u003cli\u003e적대세력 제압\u003c/li\u003e\r\n    \u003cli\u003e구조경로 개방\u003c/li\u003e\r\n    \u003cli\u003e의료진 호위\u003c/li\u003e\r\n    \u003cli\u003e장갑차량 운용\u003c/li\u003e\r\n    \u003cli\u003e납치된 회원 회수\u003c/li\u003e\r\n    \u003cli\u003e구급차 공격세력 추적\u003c/li\u003e\r\n    \u003cli\u003e구조현장 방어\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003ch3\u003e응급의료부\u003c/h3\u003e\r\n  \u003cp\u003e현장 의료진, 외상외과와 중환자 치료를 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e생명유지와 신경보존, 사이버웨어 안정화에 특화되어 있다.\u003c/p\u003e\r\n  \u003ch3\u003e현장회수부\u003c/h3\u003e\r\n  \u003cp\u003e환자, 시신, 절단된 신체와 중요 의료자료를 회수한다.\u003c/p\u003e\r\n  \u003cp\u003e생존 가능성이 확인되지 않은 대상도 복원 가능성을 검사하기 위해 병원으로 이송한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e제3본부장 — 복원·보험\u003c/h2\u003e\r\n  \u003cp\u003e구조 이후의 신체복원, 비용과 책임관계를 담당한다.\u003c/p\u003e\r\n  \u003ch3\u003e신체복원부\u003c/h3\u003e\r\n  \u003cp\u003e배양장기와 의체, 신경재생을 통해 환자의 신체를 복원한다.\u003c/p\u003e\r\n  \u003cp\u003e환자의 회원등급과 의료적 필요, 개인의 선택에 따라 복원방식을 결정한다.\u003c/p\u003e\r\n  \u003ch3\u003e보험심사부\u003c/h3\u003e\r\n  \u003cp\u003e출동과 치료가 계약범위에 포함되는지 심사한다.\u003c/p\u003e\r\n  \u003cp\u003e사고의 원인, 불법행위와 고의성, 특약 위반 여부를 조사한다. 회원이 의도적으로 위험을 증가시켰다고 판단되면 보험금과 복원비용 지급이 제한될 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e의료윤리감사실\u003c/h3\u003e\r\n  \u003cp\u003e구조 포기, 우선순위와 과도한 무력사용을 조사한다.\u003c/p\u003e\r\n  \u003cp\u003e의료진과 보험부서, 무장구조대의 판단이 규정에 적합했는지 검토한다.\u003c/p\u003e\r\n  \u003cp\u003e다만 감사실이 기업 내부조직인 만큼 완전한 독립성을 가지고 있는지는 논란이 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e최고의료책임자 직속실\u003c/h2\u003e\r\n  \u003cp\u003e대규모 재난과 최고등급 회원, 비공개 의료작전을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e칠정 최고위층의 복원기록과 라자루스 블랙 계약을 담당하는 것으로 알려져 있다.\u003c/p\u003e\r\n  \u003cp\u003e일반적인 보험심사를 거치지 않는 특별구조와 신원비공개 치료도 직속실에서 승인한다.\u003c/p\u003e\r\n  \u003cp\u003e일부 현장팀은 출동대상의 이름과 신분을 모른 채 직속실의 명령만으로 작전에 투입된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e무장구조대\u003c/h2\u003e\r\n  \u003cp\u003e라자루스 무장구조대는 전투원과 의료진, 운전사와 기술자가 하나의 팀으로 움직인다.\u003c/p\u003e\r\n  \u003ch3\u003e팀장\u003c/h3\u003e\r\n  \u003cp\u003e현장작전의 최종책임자다.\u003c/p\u003e\r\n  \u003cp\u003e의료진의 판단과 전투상황을 종합해 진입, 후퇴와 환자회수 여부를 결정한다. 관제본부의 지시를 따르지만 통신이 끊긴 경우 독립적인 판단권을 가진다.\u003c/p\u003e\r\n  \u003ch3\u003e선도요원\u003c/h3\u003e\r\n  \u003cp\u003e구조팀보다 먼저 진입해 위협과 이동경로를 확인한다.\u003c/p\u003e\r\n  \u003cp\u003e대인전투와 정찰, 폭발물 탐지에 특화되어 있다.\u003c/p\u003e\r\n  \u003ch3\u003e방호요원\u003c/h3\u003e\r\n  \u003cp\u003e의료진과 환자를 직접 보호한다.\u003c/p\u003e\r\n  \u003cp\u003e방탄방패와 중장갑, 제압화기를 사용해 이동 가능한 안전구역을 만든다.\u003c/p\u003e\r\n  \u003ch3\u003e전투의무관\u003c/h3\u003e\r\n  \u003cp\u003e전투와 응급의료 양쪽에 숙련된 현장요원이다.\u003c/p\u003e\r\n  \u003cp\u003e위협이 제거되지 않은 상황에서도 환자의 출혈과 신경손상을 통제한다.\u003c/p\u003e\r\n  \u003ch3\u003e외상전문의\u003c/h3\u003e\r\n  \u003cp\u003e환자의 생존 가능성과 긴급수술 여부를 판단한다.\u003c/p\u003e\r\n  \u003cp\u003e현장에서 절단과 장기제거, 인공순환 연결을 시행할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e회수기술자\u003c/h3\u003e\r\n  \u003cp\u003e사이버웨어와 절단된 신체, 생체자료를 안전하게 회수한다.\u003c/p\u003e\r\n  \u003cp\u003e파손된 임플란트가 폭발하거나 악성코드를 포함했는지도 확인한다.\u003c/p\u003e\r\n  \u003ch3\u003e운전·항공요원\u003c/h3\u003e\r\n  \u003cp\u003e장갑구조차와 의료항공기를 운용한다.\u003c/p\u003e\r\n  \u003cp\u003e도시의 좁은 도로, 붕괴지역과 교전지역에서 빠르게 진입하고 탈출하도록 훈련받는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 장비\u003c/h2\u003e\r\n  \u003ch3\u003e리바이버 장갑구조차\u003c/h3\u003e\r\n  \u003cp\u003e라자루스 무장구조대의 대표 차량이다.\u003c/p\u003e\r\n  \u003cp\u003e구급차와 장갑차를 결합한 형태로 방탄장갑, 의료실과 생명유지장치를 갖추고 있다. 차량 내부에서 긴급수술과 신경보존 처치를 시행할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e세라프 의료항공기\u003c/h3\u003e\r\n  \u003cp\u003e도시와 황무지의 장거리 구조에 사용되는 고속 항공기다.\u003c/p\u003e\r\n  \u003cp\u003e수직이착륙과 자동항법 기능을 갖추며, 중환자를 치료하면서 상급병원으로 이송할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e라자루스 바이오모니터\u003c/h3\u003e\r\n  \u003cp\u003e회원의 심박, 뇌파, 혈액과 사이버웨어 상태를 지속적으로 감시한다.\u003c/p\u003e\r\n  \u003cp\u003e치명적인 이상이 감지되면 자동으로 출동요청을 생성한다.\u003c/p\u003e\r\n  \u003ch3\u003e골든 미닛 모듈\u003c/h3\u003e\r\n  \u003cp\u003e뇌와 핵심장기의 손상을 늦추는 이동식 생명유지장치다.\u003c/p\u003e\r\n  \u003cp\u003e환자의 신체기능을 인공적으로 대체해 복원수술까지 시간을 확보한다.\u003c/p\u003e\r\n  \u003ch3\u003e리클레임 캡슐\u003c/h3\u003e\r\n  \u003cp\u003e절단된 사지, 장기와 신경조직을 보존하는 회수용기다.\u003c/p\u003e\r\n  \u003cp\u003e여러 개의 신체조각을 개별적으로 분류하고 생체상태를 유지할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e화이트라인 전투의료복\u003c/h3\u003e\r\n  \u003cp\u003e탄도, 화학오염과 체액노출로부터 의료진을 보호한다.\u003c/p\u003e\r\n  \u003cp\u003e손가락과 시야의 정밀성을 유지하면서 현장수술을 수행할 수 있도록 설계된다.\u003c/p\u003e\r\n  \u003ch3\u003e코드 블루 비컨\u003c/h3\u003e\r\n  \u003cp\u003e구조팀의 위치와 의료통행권을 알리는 신호장치다.\u003c/p\u003e\r\n  \u003cp\u003e공식기관과 기업군은 라자루스 비컨이 활성화된 차량의 이동을 우선적으로 보장해야 한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 시설\u003c/h2\u003e\r\n  \u003ch3\u003e리저렉션 센터\u003c/h3\u003e\r\n  \u003cp\u003e라자루스의 최고등급 신체복원 병원이다.\u003c/p\u003e\r\n  \u003cp\u003e중증외상, 장기손실과 신경손상 환자가 이송된다. 배양장기와 의체, 모르포스의 고급 생체기술이 사용된다.\u003c/p\u003e\r\n  \u003ch3\u003e센트럴 디스패치\u003c/h3\u003e\r\n  \u003cp\u003e중앙출동통제본부가 위치한 관제시설이다.\u003c/p\u003e\r\n  \u003cp\u003e대륙 전역의 회원신호와 차량, 병상정보가 실시간으로 표시된다. 수천 건의 출동요청이 동시에 처리된다.\u003c/p\u003e\r\n  \u003ch3\u003e블루 워드\u003c/h3\u003e\r\n  \u003cp\u003e돔 시티에 설치된 라자루스의 회원전용 병동이다.\u003c/p\u003e\r\n  \u003cp\u003e일반병원과 연결되어 있지만 출입과 의료기록이 별도로 관리된다.\u003c/p\u003e\r\n  \u003ch3\u003e모터 메디카\u003c/h3\u003e\r\n  \u003cp\u003e황무지와 대형 재난지역에 파견되는 이동식 병원이다.\u003c/p\u003e\r\n  \u003cp\u003e수술실, 중환자실과 소규모 배양시설을 갖추고 있다.\u003c/p\u003e\r\n  \u003ch3\u003e모로우 볼트\u003c/h3\u003e\r\n  \u003cp\u003e회원의 유전자와 장기표본, 복원계획을 보관하는 시설이다.\u003c/p\u003e\r\n  \u003cp\u003e상위 회원은 사고 이전의 신체자료와 맞춤형 장기를 이곳에 저장할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e라스트 워드\u003c/h3\u003e\r\n  \u003cp\u003e공식 기록에 존재하지 않는 최고등급 의료시설이라는 소문이 있다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스 블랙 회원과 신원이 공개될 수 없는 환자를 치료하며, 사망판정과 관련된 금지기술을 연구한다고 알려져 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e직원 문화\u003c/h2\u003e\r\n  \u003cp\u003e라자루스 직원은 감정보다 속도와 판단을 우선하도록 교육받는다.\u003c/p\u003e\r\n  \u003cp\u003e현장에서 망설이는 몇 초가 환자의 생사를 결정하기 때문이다. 의료진은 끔찍하게 손상된 신체를 보고도 복원 가능한 조직과 그렇지 않은 조직을 즉시 구분해야 한다.\u003c/p\u003e\r\n  \u003cp\u003e무장구조대는 군인처럼 행동하지만 자신들을 군인이라고 부르지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e그들의 임무는 적을 죽이는 것이 아니라 환자를 데리고 돌아오는 것이다. 구조가 끝났다면 교전을 계속하지 않는 것이 원칙이다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 의료진과 보험심사부 사이의 갈등은 매우 심하다.\u003c/p\u003e\r\n  \u003cp\u003e의료진은 가능한 모든 방법으로 환자를 살리려 하고, 보험심사관은 어떤 치료가 계약에 포함되는지를 계산한다. 현장에서 먼저 치료하고 나중에 비용문제로 징계받는 의사도 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스 내부에서 가장 널리 사용되는 문구는 다음과 같다.\u003c/p\u003e\r\n  \u003cblockquote\u003e환자는 살아 있거나 죽은 것이 아니다. 아직 회수되었거나, 회수되지 않았을 뿐이다.\u003c/blockquote\u003e\r\n\r\n  \u003ch2\u003e채용과 복지\u003c/h2\u003e\r\n  \u003cp\u003e라자루스는 의사, 간호사, 전투의무관, 구조대원, 운전사, 항공요원과 보험심사관을 채용한다.\u003c/p\u003e\r\n  \u003cp\u003e무장구조대 지원자는 의료지식과 전투능력, 극한상황의 판단력을 함께 평가받는다. 일반적인 군인보다 구조대원의 안전과 환자의 생존을 동시에 고려해야 한다.\u003c/p\u003e\r\n  \u003cp\u003e정규직과 가족에게는 다음과 같은 혜택이 제공된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e상급 라자루스 회원권\u003c/li\u003e\r\n    \u003cli\u003e직원 가족의 긴급출동 보장\u003c/li\u003e\r\n    \u003cli\u003e산업재해와 전투부상 치료\u003c/li\u003e\r\n    \u003cli\u003e신체복원과 재활\u003c/li\u003e\r\n    \u003cli\u003e직원용 사이버웨어\u003c/li\u003e\r\n    \u003cli\u003e돔 거주권 또는 출동거점 숙소\u003c/li\u003e\r\n    \u003cli\u003e자녀의 의료교육과 장학제도\u003c/li\u003e\r\n    \u003cli\u003e순직자 가족의 평생 회원권\u003c/li\u003e\r\n    \u003cli\u003e장기근속자의 장기 및 유전자 보관\u003c/li\u003e\r\n    \u003cli\u003e퇴직 후 의료와 구조보험 유지\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e그러나 구조대의 사망률과 외상후 스트레스는 높다.\u003c/p\u003e\r\n  \u003cp\u003e장기간 근무한 대원은 감정적 소진과 판단장애를 이유로 현장에서 관제와 교육부서로 이동하기도 한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e계층별 인식\u003c/h2\u003e\r\n  \u003ch3\u003e돔 시티 상류층\u003c/h3\u003e\r\n  \u003cp\u003e라자루스 회원권을 필수적인 생명보험이자 사회적 지위로 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e플래티넘 회원의 구조차량과 전용 의료팀은 고급주택이나 사이버웨어만큼 명확한 신분의 상징이다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 시티 일반 시민\u003c/h3\u003e\r\n  \u003cp\u003e생명을 구하는 믿을 만한 의료기업으로 평가한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 보험료가 높고 계약조건이 복잡해 자신이 실제로 어느 상황까지 보호받는지 모르는 시민도 많다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 하층민\u003c/h3\u003e\r\n  \u003cp\u003e같은 거리에서 사람이 쓰러졌는데 회원만 태우고 떠나는 구조차량을 목격한 경험이 있다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스의 의료기술을 존경하면서도 생명에 가격표를 붙이는 기업이라고 증오한다.\u003c/p\u003e\r\n  \u003ch3\u003e장막 도시 주민\u003c/h3\u003e\r\n  \u003cp\u003e라자루스의 이동진료소와 구조팀은 귀중한 생명줄이다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 정식 출동망이 없는 지역이 많고 구조비용을 감당하지 못해 세인트 제로나 지역 패처에게 의존하는 사람이 많다.\u003c/p\u003e\r\n  \u003ch3\u003e황무지인과 카라반\u003c/h3\u003e\r\n  \u003cp\u003e위험한 노선을 오가는 상인과 용병은 라자루스 회원권을 중요하게 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e다만 출동거점에서 지나치게 멀거나 일소와 모래폭풍이 심한 경우 계약이 있어도 구조팀이 도착하지 못할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e용병\u003c/h3\u003e\r\n  \u003cp\u003e라자루스는 전장에서 가장 믿고 싶은 이름이다.\u003c/p\u003e\r\n  \u003cp\u003e계약비가 비싸지만 회원권 유무가 작전수락 조건이 되는 용병단도 많다.\u003c/p\u003e\r\n  \u003ch3\u003e다른 기업\u003c/h3\u003e\r\n  \u003cp\u003e중요인력을 잃지 않기 위해 라자루스와 대규모 단체계약을 유지한다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 고위간부의 건강과 신체적 약점이 라자루스 기록에 보관된다는 사실을 경계한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e다른 세력과의 관계\u003c/h2\u003e\r\n  \u003ch3\u003eMORPHOS BIODYNE\u003c/h3\u003e\r\n  \u003cp\u003e모르포스는 배양장기, 신경 인터페이스와 고급 신체복원 기술을 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스가 환자를 살려서 병원까지 데려오면 모르포스가 신체를 다시 설계한다. 두 기업은 의료분야에서 가장 긴밀한 협력관계를 가진다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 고가의 복원기술과 환자의 생체정보 소유권을 두고 충돌하기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003eCERBERUS DEFENSE GROUP\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스는 무장구조대에 화기, 방탄복과 장갑차량을 공급한다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 케르베로스 병력의 전장 의료와 신체회수를 담당한다. 양사의 계약이 결합된 전장에서는 부상병이 발생하는 즉시 구조와 장비회수가 동시에 진행된다.\u003c/p\u003e\r\n  \u003ch3\u003eARCADIA HABITAT\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아는 일반병원과 도시 의료체계를 운영하며 라자루스는 중증환자와 위험지역 구조를 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e돔 내부의 통행과 구역봉쇄를 두고 갈등이 발생할 수 있다. 아르카디아가 도시안전을 위해 문을 닫을 때 라자루스는 회원구조를 위해 진입을 요구한다.\u003c/p\u003e\r\n  \u003ch3\u003eNEREID HYDROSYSTEMS\u003c/h3\u003e\r\n  \u003cp\u003e네레이드는 의료용수와 정제수를 공급한다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 수원오염과 급수시설 재난에서 의료지원과 환자회수를 담당한다.\u003c/p\u003e\r\n  \u003ch3\u003eSOLARIS ORBITAL INDUSTRIES\u003c/h3\u003e\r\n  \u003cp\u003e솔라리스는 기상정보, 항법과 항공통신을 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 솔라리스의 궤도·고고도 근무자와 일소 피해자를 치료한다.\u003c/p\u003e\r\n  \u003ch3\u003eCHARON INTERCONTINENTAL\u003c/h3\u003e\r\n  \u003cp\u003e카론은 의료장비와 약품, 이동식 병원을 운송한다.\u003c/p\u003e\r\n  \u003cp\u003e대규모 재난에서는 열차가 임시병원과 대피수단으로 사용된다. 라자루스의 바이탈 화물은 카론 물류망에서 최우선 등급으로 취급된다.\u003c/p\u003e\r\n  \u003ch3\u003eARGOS SECURE NETWORKS\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 환자의 신원과 현장위협, 납치상황을 분석한다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 의료기밀을 이유로 환자기록 제공을 제한한다. 아르고스가 국가적 위협을 이유로 기록을 요구할 경우 양측 사이에 충돌이 발생한다.\u003c/p\u003e\r\n  \u003ch3\u003eECLIPSE TACTICAL BUREAU\u003c/h3\u003e\r\n  \u003cp\u003e이클립스가 현장을 제압하고 격리선을 구축하면 라자루스가 부상자를 구조한다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 한 명이라도 더 구하려 하고 이클립스는 확산방지를 우선한다. 생존자가 남아 있는 구역의 봉쇄 여부를 두고 가장 자주 충돌하는 두 기관이다.\u003c/p\u003e\r\n  \u003ch3\u003eDOME CIVIC SECURITY\u003c/h3\u003e\r\n  \u003cp\u003eDCS는 일반 사고의 현장통제와 구조경로 확보를 지원한다.\u003c/p\u003e\r\n  \u003cp\u003e총격전과 범죄현장에서는 경찰이 위협을 제압한 뒤 라자루스 의료진이 진입하는 것이 원칙이다.\u003c/p\u003e\r\n  \u003ch3\u003eSAINT ZERO\u003c/h3\u003e\r\n  \u003cp\u003e세인트 제로는 라자루스의 정식 의료망에 접근하지 못하는 장막 도시 주민과 비등록자를 치료한다.\u003c/p\u003e\r\n  \u003cp\u003e공식적으로 라자루스는 세인트 제로의 불법 의체와 약물거래를 비판한다. 그러나 현장에서는 환자정보와 의약품을 교환하거나 비공식적으로 환자를 인계하기도 한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e사회공헌과 홍보\u003c/h2\u003e\r\n  \u003cp\u003e라자루스는 자신들을 “생명이 가장 위험한 순간에 도착하는 기업”이라고 소개한다.\u003c/p\u003e\r\n  \u003cp\u003e장막 도시에 이동진료소를 파견하고 산업노동자에게 응급처치와 구조교육을 제공한다. 대형 재난에서는 공공계약에 따라 비회원도 치료한다.\u003c/p\u003e\r\n  \u003cp\u003e아이와 의료취약계층을 위한 무료수술 사업도 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e기업의 광고에는 무너진 건물과 총격전 속으로 진입하는 장갑구조차, 환자의 손을 잡는 의료진과 다시 가족에게 돌아가는 회원이 등장한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 광고에서는 보험심사와 계약거절, 구조되지 못한 비회원의 모습은 보여주지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e논란과 비판\u003c/h2\u003e\r\n  \u003ch3\u003e생명의 등급화\u003c/h3\u003e\r\n  \u003cp\u003e회원등급에 따라 출동속도와 투입되는 병력, 복원수준이 달라진다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 지불한 보험료와 계약에 따른 정당한 서비스 차이라고 주장한다. 비판자들은 생명의 가치에 등급을 부여한 것과 다르지 않다고 말한다.\u003c/p\u003e\r\n  \u003ch3\u003e구조 우선순위\u003c/h3\u003e\r\n  \u003cp\u003e같은 현장에 여러 환자가 존재할 때 상위 회원이 우선될 가능성이 높다.\u003c/p\u003e\r\n  \u003cp\u003e생존 가능성이 비슷하다면 계약가치와 회원등급이 실제 판단에 영향을 미친다는 사실을 기업도 부정하지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e과도한 구조비용\u003c/h3\u003e\r\n  \u003cp\u003e비회원이 응급치료를 받은 뒤 평생 갚기 어려운 채무를 지는 경우가 있다.\u003c/p\u003e\r\n  \u003cp\u003e치료비를 갚지 못한 환자가 장기 노동계약이나 의료시험 참여를 선택하도록 압박받는다는 비판도 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003e보험금 지급거부\u003c/h3\u003e\r\n  \u003cp\u003e불법활동, 계약 외 위험과 고의적인 위험증가를 이유로 치료비 보장이 거절될 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e용병과 위험직종 노동자는 자신이 가장 필요로 하는 상황이 면책조항에 해당한다는 사실을 사고 후에 알게 되기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e무장구조대의 교전권\u003c/h3\u003e\r\n  \u003cp\u003e라자루스는 환자회수를 위해 무력을 사용할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e적대세력이 환자에게 접근하거나 치료를 방해할 경우 구조대가 먼저 공격했다는 분쟁도 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003e환자와 신체의 소유권\u003c/h3\u003e\r\n  \u003cp\u003e치료비를 지불하지 못한 환자의 장기와 사이버웨어, 생체정보에 기업이 권리를 주장한다는 의혹이 있다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 환자의 몸을 소유하지 않으며 미지급 의료자산만 회수한다고 해명한다.\u003c/p\u003e\r\n  \u003ch3\u003e의료정보 감시\u003c/h3\u003e\r\n  \u003cp\u003e바이오모니터는 회원의 건강과 위치, 약물과 전투상태를 실시간으로 기록한다.\u003c/p\u003e\r\n  \u003cp\u003e기업은 구조를 위해 필요한 정보라고 설명한다. 그러나 고위간부와 용병의 신체적 약점이 데이터베이스에 축적된다.\u003c/p\u003e\r\n  \u003ch3\u003e의료중립성\u003c/h3\u003e\r\n  \u003cp\u003e라자루스는 계약에 따라 적대세력도 구조한다고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 칠정과 대기업의 요구가 소규모 고객의 계약보다 우선한다는 의혹이 끊이지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e확인되지 않은 소문\u003c/h2\u003e\r\n  \u003cp\u003e라자루스가 공식적인 사망판정보다 훨씬 오랜 시간이 지난 환자를 복원한 사례가 있다는 소문이 있다.\u003c/p\u003e\r\n  \u003cp\u003e뇌 전체가 아닌 일부 신경조직과 저장된 기억정보만으로 인격을 재구성했다는 것이다.\u003c/p\u003e\r\n  \u003cp\u003e그렇게 되살아난 사람이 사고 이전과 동일한 사람인지, 기억을 가진 새로운 존재인지는 누구도 증명하지 못한다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스 블랙 회원을 위해 완전한 예비 신체를 배양한다는 소문도 있다.\u003c/p\u003e\r\n  \u003cp\u003e회원의 신체가 복원 불가능하게 파괴되면 보존된 신경정보를 새로운 신체에 이식한다는 것이다. 기업은 인간복제를 공식적으로 금지하고 있으며 그러한 기술은 존재하지 않는다고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e보험심사부가 특정 회원의 구조비용이 장기적인 계약가치보다 높다고 판단하면 의도적으로 출동을 지연한다는 의혹도 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e더 어두운 소문은 ‘제로 클레임’이라 불리는 비밀판정에 관한 것이다.\u003c/p\u003e\r\n  \u003cp\u003e환자가 살아 돌아올 경우 칠정의 질서와 기업기밀에 더 큰 위협이 된다고 판단되면 구조대가 현장에 도착하고도 회수를 포기할 수 있다는 것이다.\u003c/p\u003e\r\n  \u003cp\u003e일부에서는 라자루스의 특수회수팀이 환자를 살리기 위해서가 아니라 반드시 시신과 기억장치를 확보하기 위해 출동한다고 말한다.\u003c/p\u003e\r\n  \u003cp\u003e가장 오래된 소문은 라자루스의 창립자에 관한 것이다.\u003c/p\u003e\r\n  \u003cp\u003e2102년 백야 당시 사망한 창립자의 신경조직이 700년 동안 보존되어 있으며, 기업은 그를 되살리기 위해 모든 복원기술을 발전시켜 왔다는 주장이다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스의 최고기밀 의료계획은 지금도 단 한 명의 환자를 위한 것이라고 한다.\u003c/p\u003e\r\n  \u003cp\u003e그 환자의 상태는 모든 내부문서에서 동일하게 표시되어 있다.\u003c/p\u003e\r\n  \u003cp\u003e\u003cstrong\u003e회수 완료. 치료 진행 중. 사망 승인 보류.\u003c/strong\u003e\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기업이 가진 힘\u003c/h2\u003e\r\n  \u003cp\u003e라자루스의 힘은 죽은 사람을 되살리는 기적에서 나오지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e그들이 가진 진정한 힘은 죽음이 확정되는 순간을 늦출 수 있다는 데 있다.\u003c/p\u003e\r\n  \u003cp\u003e총에 맞고 심장이 멈췄더라도 구조대가 도착하면 아직 환자다. 신체가 파괴되었더라도 신경과 장기를 보존할 수 있다면 복원 가능성이 남아 있다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 그 가능성은 시간과 거리, 기술과 비용에 따라 달라진다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 그 모든 요소를 계산한다. 누구에게 어떤 팀을 보낼지, 몇 명의 구조대원을 위험에 투입할지, 어느 수준의 신체까지 복원할지를 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스의 병사는 전쟁에서 사람을 죽인다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스의 대원은 더 큰 재난을 막기 위해 누군가를 포기한다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스는 그 뒤에 남은 사람 가운데 누구를 다시 살아 돌아오게 만들지를 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e그들의 구급차가 도착하면 사람들은 희망을 느낀다.\u003c/p\u003e\r\n  \u003cp\u003e그리고 자신의 회원등급을 떠올린다.\u003c/p\u003e\r\n\u003c/section\u003e\r\n";
window.FACTION_INFO.dcs = "\u003csection class=\"faction-detail\"\u003e\r\n  \u003ch2\u003e기관 개요\u003c/h2\u003e\r\n  \u003cp class=\"faction-quote\"\u003e“돔 안의 하루를 지킨다.”\u003c/p\u003e\r\n  \u003cp\u003e돔 시빅 시큐리티는 돔 시티의 일상적인 치안과 시민안전을 담당하는 공공경찰기관이다. 범죄수사, 거리순찰, 교통통제, 지역분쟁, 소요사태와 초동대응을 맡으며 일반 시민이 가장 자주 마주하는 공권력이기도 하다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스가 기업공작과 정보전, 방첩을 담당하고 이클립스가 도시급 재난과 초고위험 사건에 대응한다면, DCS는 그 사이에 존재하는 평범한 하루를 지킨다. 절도와 폭행, 살인, 불법 사이버웨어, 밀수와 교통사고처럼 매일 발생하는 사건 대부분은 DCS의 관할이다.\u003c/p\u003e\r\n  \u003cp\u003e명목상 DCS는 특정 기업의 사병이 아니라 돔 도시행정부에 소속된 공공기관이다. 그러나 청사와 장비, 전산망과 시민자료의 상당 부분을 아르카디아에 의존한다. 화기와 방호장비는 케르베로스에서 공급받고, 신원조회와 고위험 정보는 아르고스에 요청한다.\u003c/p\u003e\r\n  \u003cp\u003e이 때문에 시민들은 DCS를 돔의 경찰이라고 부르면서도, 누구의 질서를 지키는 조직인지는 끊임없이 의심한다.\u003c/p\u003e\r\n  \u003cp\u003eDCS가 보호하는 것은 시민인가.\u003c/p\u003e\r\n  \u003cp\u003e도시인가.\u003c/p\u003e\r\n  \u003cp\u003e아니면 시민과 도시를 소유한 기업의 질서인가.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기본 정보\u003c/h2\u003e\r\n  \u003ctable class=\"data-table faction-info-table\"\u003e\r\n    \u003ctbody\u003e\r\n      \u003ctr\u003e\u003cth\u003e정식 명칭\u003c/th\u003e\u003ctd\u003eDOME CIVIC SECURITY\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e통칭\u003c/th\u003e\u003ctd\u003eDCS, 돔 시민보안국\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e기관 분류\u003c/th\u003e\u003ctd\u003e돔 시티 공공치안·시민경찰기관\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 임무\u003c/th\u003e\u003ctd\u003e순찰, 범죄수사, 교통통제, 시민보호\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e특수 임무\u003c/th\u003e\u003ctd\u003e폭동진압, 초동봉쇄, 기업시설 지원\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e상위 행정기관\u003c/th\u003e\u003ctd\u003e돔 도시행정부\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 협력기관\u003c/th\u003e\u003ctd\u003e아르카디아, 아르고스, 이클립스, 라자루스\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 장비 공급처\u003c/th\u003e\u003ctd\u003e케르베로스 디펜스 그룹\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e상징 색상\u003c/th\u003e\u003ctd\u003e청색, 백색\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표적인 인식\u003c/th\u003e\u003ctd\u003e시민에게 가장 가까운 공권력\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e활동 범위\u003c/th\u003e\u003ctd\u003e돔 시티 내부와 지정 외곽구역\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e최고책임자\u003c/th\u003e\u003ctd\u003e치안총감\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 전력\u003c/th\u003e\u003ctd\u003e순찰국, 범죄수사국, 전술대응국\u003c/td\u003e\u003c/tr\u003e\r\n    \u003c/tbody\u003e\r\n  \u003c/table\u003e\r\n\r\n  \u003ch2\u003e기관의 역사\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e백야 이전 — 도시경찰의 잔재\u003c/h3\u003e\r\n  \u003cp\u003eDCS의 기원은 2102년 백야 이전에 존재했던 지방경찰, 도시방재조직, 민간경비회사와 교통관리기관에서 시작되었다.\u003c/p\u003e\r\n  \u003cp\u003e당시 경찰은 범죄수사와 순찰뿐 아니라 도시감시망, 재난대피와 사이버범죄 대응까지 담당하고 있었다. 그러나 관할과 지휘체계는 국가와 지역에 따라 서로 달랐다.\u003c/p\u003e\r\n  \u003cp\u003e대형 기업도 자체적인 경비조직을 운영했다. 기업도시와 산업단지에서는 공공경찰보다 민간경비가 더 강한 권한을 행사하기도 했다.\u003c/p\u003e\r\n  \u003cp\u003e백야 직전에는 국가경찰과 기업보안의 경계가 이미 흐려지고 있었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e2102년 — 백야\u003c/h3\u003e\r\n  \u003cp\u003e백야가 발생하자 경찰과 구조조직의 지휘망은 순식간에 붕괴했다.\u003c/p\u003e\r\n  \u003cp\u003e통신과 전력, 교통망이 정지했고 잘못된 대피명령과 허위정보가 도시 전체에 퍼졌다. 경찰관들은 상부의 명령을 기다릴 수 없는 상황에서 각자 시민을 대피시키고 물자창고와 병원을 지켜야 했다.\u003c/p\u003e\r\n  \u003cp\u003e일부 부대는 마지막까지 시민을 보호했다.\u003c/p\u003e\r\n  \u003cp\u003e다른 부대는 무기와 차량을 장악하고 군벌이 되었다. 기업시설을 지키기 위해 민간인의 접근을 막거나, 제한된 식량과 물을 확보하기 위해 다른 생존집단을 공격한 경우도 있었다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아의 초기 해비타트에 들어간 경찰과 경비원들은 거주구역 내부의 질서를 유지했다. 생존시설의 출입을 통제하고 배급소를 보호하며 폭동과 절도를 막았다.\u003c/p\u003e\r\n  \u003cp\u003e이들이 훗날 DCS로 이어지는 최초의 돔 보안대였다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망력 초기 — 생존구역 보안대\u003c/h3\u003e\r\n  \u003cp\u003e백야 이후 수십 년 동안 해비타트의 치안은 생존과 직결되었다.\u003c/p\u003e\r\n  \u003cp\u003e식량 한 상자와 물 한 통을 둘러싸고 살인이 벌어졌으며, 환기장치와 발전기를 파괴하는 행위는 수백 명의 목숨을 위협했다. 작은 폭동도 생명유지시설의 정지로 이어질 수 있었다.\u003c/p\u003e\r\n  \u003cp\u003e초기 보안대는 경찰과 군인, 기업경비와 자원봉사자로 구성되었다.\u003c/p\u003e\r\n  \u003cp\u003e이들은 범죄자를 체포하는 것보다 배급질서와 핵심시설을 지키는 데 집중했다. 외부의 법원과 교도소가 사라졌기 때문에 현장 지휘관이 판결과 처벌까지 결정하는 경우도 많았다.\u003c/p\u003e\r\n  \u003cp\u003e생존시설마다 규칙이 달랐고 법 집행은 자의적이었다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 여러 해비타트를 통합하면서 공통 치안규정과 교육체계를 도입했다. 이 과정에서 각 시설의 보안대는 하나의 조직으로 재편되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 1~2세기 — 돔 시민경비대\u003c/h3\u003e\r\n  \u003cp\u003e최초의 돔 시티가 건설되면서 보안대의 역할도 변화했다.\u003c/p\u003e\r\n  \u003cp\u003e시설을 지키는 것만으로는 증가한 인구와 범죄를 관리할 수 없었다. 돔 내부에는 주거지와 시장, 공장과 유흥가가 형성되었고 절도, 폭력과 조직범죄가 증가했다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 기존 보안대를 시민경비대로 개편했다.\u003c/p\u003e\r\n  \u003cp\u003e순찰과 수사, 교통관리와 분쟁조정 업무가 분리되었고 돔 전체에 지구대와 구금시설이 설치되었다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 초기 시민경비대는 여전히 기업경비의 성격이 강했다.\u003c/p\u003e\r\n  \u003cp\u003e시민의 생명보다 생명유지시설과 배급창고, 기업자산의 보호가 우선되었다. 노동자 시위와 시민권 분쟁도 치안위협으로 간주했다.\u003c/p\u003e\r\n  \u003cp\u003e이러한 전통은 현재의 DCS에도 일정 부분 남아 있다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 3세기 — 시민치안법\u003c/h3\u003e\r\n  \u003cp\u003e돔 인구가 늘어나고 시민권 체계가 안정되면서 치안기관의 권한을 제한하는 법과 절차가 필요해졌다.\u003c/p\u003e\r\n  \u003cp\u003e무단구금과 과도한 진압, 기업간부에 대한 특혜가 사회문제로 떠올랐다. 시민들은 기업경비가 아닌 공공경찰을 요구하기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e돔 도시행정부는 시민치안법을 제정하고 시민경비대를 행정부 산하의 독립기관으로 재편했다.\u003c/p\u003e\r\n  \u003cp\u003e이때 \u003cstrong\u003eDOME CIVIC SECURITY\u003c/strong\u003e라는 명칭이 정식으로 사용되기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003eDCS는 아르카디아의 기업명령이 아니라 도시법과 치안총감의 지휘를 따르도록 규정되었다. 체포, 수색과 무기사용에 대한 절차도 마련되었다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 예산과 시설, 시민자료는 여전히 아르카디아가 관리했다.\u003c/p\u003e\r\n  \u003cp\u003e법적으로는 독립했지만 실질적으로 완전히 독립한 조직은 아니었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 4세기 — 도시 치안망\u003c/h3\u003e\r\n  \u003cp\u003e돔 시티의 규모가 확장되면서 DCS는 지역별 순찰망과 통합신고체계를 구축했다.\u003c/p\u003e\r\n  \u003cp\u003e도시 곳곳의 감시카메라, 시민신고와 환경센서가 지역 지구대에 연결되었다. 순찰대원은 사건이 발생하기 전에 인근에 배치될 수 있었고, 범인의 신원과 이동경로도 빠르게 확인할 수 있게 되었다.\u003c/p\u003e\r\n  \u003cp\u003e범죄율은 크게 감소했다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 사소한 위반행위도 기록되는 감시사회가 형성되었다.\u003c/p\u003e\r\n  \u003cp\u003e시민권이 낮거나 기업기록이 불안정한 사람은 동일한 행동에도 더 자주 검문받았다. 하층구역에는 순찰드론과 검문소가 집중적으로 배치되었다.\u003c/p\u003e\r\n  \u003cp\u003eDCS는 자원과 신고건수에 따른 합리적인 배치라고 설명했다.\u003c/p\u003e\r\n  \u003cp\u003e하층민들은 자신들이 보호받는 것이 아니라 감시받는다고 느꼈다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 5세기 — 블루넷 경찰행정\u003c/h3\u003e\r\n  \u003cp\u003e블루넷이 도시행정과 시민권, 금융망을 연결하면서 DCS의 업무도 전산화되었다.\u003c/p\u003e\r\n  \u003cp\u003e경찰관은 현장에서 시민의 신원과 범죄기록, 무기허가와 사이버웨어 등록상태를 확인할 수 있게 되었다. 사건기록과 증거, 수배정보는 돔 전체에서 즉시 공유되었다.\u003c/p\u003e\r\n  \u003cp\u003eDCS는 아르고스의 신원관리망과 연계해 위조된 시민권과 기업공작원을 추적했다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 블루넷의 의존도가 높아지면서 새로운 문제가 발생했다.\u003c/p\u003e\r\n  \u003cp\u003e기록이 잘못되거나 조작되면 무고한 시민이 범죄자로 표시될 수 있었다. 반대로 아르고스나 상급기관이 접근권한을 제한하면 DCS는 자신이 수사하던 사건기록조차 열람할 수 없었다.\u003c/p\u003e\r\n  \u003cp\u003e경찰관들은 시민의 행동보다 화면에 표시된 위험등급을 먼저 믿기 시작했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e멸망 후 6세기 — 관할권의 분리\u003c/h3\u003e\r\n  \u003cp\u003e칠정과 블루 테이블의 질서가 확립되면서 일반치안, 기업정보와 초고위험 대응의 영역이 명확하게 나뉘었다.\u003c/p\u003e\r\n  \u003cp\u003eDCS는 돔 내부의 일반적인 범죄와 시민안전을 담당했다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 기업공작, 방첩과 대규모 정보범죄를 맡았고 이클립스는 도시급 재난과 최상위 전투사태에 대응했다.\u003c/p\u003e\r\n  \u003cp\u003e관할 분리는 전문성을 높였지만 DCS의 권한을 제한하기도 했다.\u003c/p\u003e\r\n  \u003cp\u003e일반 살인사건으로 시작한 수사가 기업기밀이나 테러와 연결되면 아르고스가 사건을 인수한다. 현장의 위험등급이 높아지면 이클립스가 지휘권을 가져간다.\u003c/p\u003e\r\n  \u003cp\u003eDCS는 시민이 가장 먼저 신고하는 기관이지만 가장 중요한 사건의 결말을 알지 못하는 경우가 많아졌다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e현재 — 멸망 후 700년\u003c/h3\u003e\r\n  \u003cp\u003e현재 DCS는 돔 시티의 모든 생활구역에 지구대와 순찰망을 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e거리순찰, 교통사고와 실종신고부터 살인, 불법 사이버웨어와 조직범죄까지 매일 발생하는 수많은 사건을 처리한다.\u003c/p\u003e\r\n  \u003cp\u003eDCS의 대원 대부분은 특별한 영웅이나 최고급 강화인간이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e제복과 표준화기, 순찰차와 제한적인 사이버웨어를 지급받은 평범한 경찰관이다. 이들은 시장의 싸움을 말리고 실종된 아이를 찾으며, 하층구역의 총격사건과 폭동에 투입된다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스와 이클립스가 개입하는 사건은 극히 위험하지만 자주 발생하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e시민의 일상을 실제로 유지하는 것은 DCS다.\u003c/p\u003e\r\n  \u003cp\u003e그럼에도 조직은 기업과 행정부의 압력, 부족한 인력과 구역별 격차에 시달린다. 상층구역은 낮은 범죄율과 빠른 출동을 누리지만 하층구역의 신고는 장시간 대기하는 경우도 있다.\u003c/p\u003e\r\n  \u003cp\u003eDCS는 돔 전체에 같은 법이 적용된다고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 법이 도착하는 속도는 시민이 살아가는 층에 따라 다르다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기관 철학\u003c/h2\u003e\r\n  \u003ch3\u003e시민에게 가장 가까운 치안\u003c/h3\u003e\r\n  \u003cp\u003eDCS는 사건이 발생했을 때 시민이 가장 먼저 접촉하는 기관이다.\u003c/p\u003e\r\n  \u003cp\u003e복잡한 기업관계나 전략적 판단 이전에 현장에 도착해 사람을 보호하고 질서를 회복하는 것을 원칙으로 한다.\u003c/p\u003e\r\n  \u003ch3\u003e돔의 안전은 연결되어 있다\u003c/h3\u003e\r\n  \u003cp\u003e밀폐된 도시에서는 작은 사고도 대형재난으로 확산될 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e화재와 총격, 불법 굴착과 시설파괴는 해당 구역만의 문제가 아니다. DCS는 범죄수사와 동시에 도시 기반시설의 위험을 확인한다.\u003c/p\u003e\r\n  \u003ch3\u003e법은 기업계약보다 우선한다\u003c/h3\u003e\r\n  \u003cp\u003e공식적으로 돔 내부의 모든 개인과 기업은 시민치안법의 적용을 받는다.\u003c/p\u003e\r\n  \u003cp\u003e기업시설과 기업인도 범죄혐의가 있다면 수사할 수 있다. 다만 실제로는 기업보안과 상급기관의 개입 때문에 권한이 제한되는 경우가 많다.\u003c/p\u003e\r\n  \u003ch3\u003e제압보다 안정화\u003c/h3\u003e\r\n  \u003cp\u003e일반적인 경찰업무에서는 용의자를 제거하는 것보다 체포하고 현장을 안정시키는 것이 우선된다.\u003c/p\u003e\r\n  \u003cp\u003eDCS의 표준장비에는 비살상 제압수단이 포함된다.\u003c/p\u003e\r\n  \u003ch3\u003e모든 사건에는 피해자가 있다\u003c/h3\u003e\r\n  \u003cp\u003e기록과 통계가 아니라 실제 피해자의 안전과 회복을 중시한다.\u003c/p\u003e\r\n  \u003cp\u003e이는 DCS가 내세우는 이상이지만, 과중한 업무와 관료주의 속에서 가장 자주 잊히는 원칙이기도 하다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e핵심 업무\u003c/h2\u003e\r\n  \u003ch3\u003e거리순찰\u003c/h3\u003e\r\n  \u003cp\u003e거주구역, 시장, 교통시설과 산업구역을 순찰한다.\u003c/p\u003e\r\n  \u003cp\u003e도보순찰, 순찰차와 감시드론이 함께 운용된다. 신고가 많은 구역에는 임시검문소와 추가순찰대가 배치된다.\u003c/p\u003e\r\n  \u003ch3\u003e범죄수사\u003c/h3\u003e\r\n  \u003cp\u003e절도, 폭행, 살인, 납치와 조직범죄를 수사한다.\u003c/p\u003e\r\n  \u003cp\u003e증거수집과 용의자 체포, 피해자 보호와 사건기록 작성을 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e사건이 기업공작이나 테러와 연결되면 아르고스 또는 이클립스에 인계할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e교통통제\u003c/h3\u003e\r\n  \u003cp\u003e차량, 보행통로, 대중교통과 화물노선을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e돔 내부의 도로는 제한된 공간에 밀집되어 있기 때문에 작은 사고도 도시 전체의 물류를 마비시킬 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e불법 사이버웨어 단속\u003c/h3\u003e\r\n  \u003cp\u003e등록되지 않은 군용 사이버웨어, 원격제한이 해제된 의체와 불법 신경가속 장치를 단속한다.\u003c/p\u003e\r\n  \u003cp\u003e보유 자체보다 시술과 유통과정의 범죄를 주로 조사한다. 그러나 하층구역에서는 미등록 의체 사용자 전체가 단속대상이 되는 경우도 있다.\u003c/p\u003e\r\n  \u003ch3\u003e조직범죄 대응\u003c/h3\u003e\r\n  \u003cp\u003e마약과 불법 감각기록, 무기밀수, 신분세탁과 보호비 갈취를 수사한다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱과 세인트 제로처럼 합법과 불법의 경계에 걸친 조직을 상대할 때는 아르고스와 협력한다.\u003c/p\u003e\r\n  \u003ch3\u003e소요 진압\u003c/h3\u003e\r\n  \u003cp\u003e폭동, 대규모 시위와 구역 간 충돌을 통제한다.\u003c/p\u003e\r\n  \u003cp\u003e방패와 비살상탄, 최루성 가스와 진압드론이 사용된다. 폭력사태가 심각해지면 전술대응국이 투입된다.\u003c/p\u003e\r\n  \u003ch3\u003e실종자 수색\u003c/h3\u003e\r\n  \u003cp\u003e가출, 납치와 사고로 실종된 시민을 추적한다.\u003c/p\u003e\r\n  \u003cp\u003e폐쇄된 정비구역과 하층통로, 비등록자 거주지까지 수색한다. 신원이 없는 실종자는 행정적으로 사건화되지 못하는 경우도 있다.\u003c/p\u003e\r\n  \u003ch3\u003e재난 초동대응\u003c/h3\u003e\r\n  \u003cp\u003e화재와 붕괴, 오염과 기반시설 사고가 발생하면 현장을 봉쇄하고 시민을 대피시킨다.\u003c/p\u003e\r\n  \u003cp\u003e전문적인 구조와 의료는 라자루스 및 도시구조대가 담당하며, 위협이 커지면 이클립스에 지휘권을 넘긴다.\u003c/p\u003e\r\n  \u003ch3\u003e민원과 분쟁조정\u003c/h3\u003e\r\n  \u003cp\u003e소음, 상점분쟁, 주거구역 갈등과 경미한 폭력사건을 처리한다.\u003c/p\u003e\r\n  \u003cp\u003eDCS가 처리하는 업무의 가장 큰 비중을 차지하지만 대중매체에는 거의 등장하지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e관할권\u003c/h2\u003e\r\n  \u003ch3\u003e일반치안 사건\u003c/h3\u003e\r\n  \u003cp\u003eDCS가 수사와 현장지휘권을 가진다.\u003c/p\u003e\r\n  \u003cp\u003e절도, 폭력, 살인과 일반적인 불법거래가 해당한다.\u003c/p\u003e\r\n  \u003ch3\u003e기업시설 사건\u003c/h3\u003e\r\n  \u003cp\u003e기업보안부와 공동 대응한다.\u003c/p\u003e\r\n  \u003cp\u003e시설 내부의 수사는 기업의 협조가 필요하지만 시민 피해가 발생하면 DCS가 개입할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e정보·방첩 사건\u003c/h3\u003e\r\n  \u003cp\u003e아르고스에 보고하고 필요하면 사건을 인계한다.\u003c/p\u003e\r\n  \u003cp\u003eDCS는 현장보존과 용의자 구금, 시민대피를 지원한다.\u003c/p\u003e\r\n  \u003ch3\u003e도시급 재난\u003c/h3\u003e\r\n  \u003cp\u003e이클립스가 도착하기 전까지 초동지휘권을 가진다.\u003c/p\u003e\r\n  \u003cp\u003e이클립스의 정식 개입이 선언되면 DCS는 현장통제와 대피지원 역할로 전환된다.\u003c/p\u003e\r\n  \u003ch3\u003e장막 도시와 황무지\u003c/h3\u003e\r\n  \u003cp\u003e원칙적으로 DCS의 정식 관할이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e돔 시민이나 기업시설과 관련된 사건에서는 제한적으로 외부작전을 수행할 수 있지만 별도 인가가 필요하다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e대응단계\u003c/h2\u003e\r\n  \u003ch3\u003eCODE WHITE — 일상대응\u003c/h3\u003e\r\n  \u003cp\u003e일반적인 순찰과 민원, 경미한 범죄에 적용된다.\u003c/p\u003e\r\n  \u003cp\u003e지역 지구대가 독자적으로 처리한다.\u003c/p\u003e\r\n  \u003ch3\u003eCODE BLUE — 중대사건\u003c/h3\u003e\r\n  \u003cp\u003e무장범죄, 살인, 인질과 대규모 교통사고에 적용된다.\u003c/p\u003e\r\n  \u003cp\u003e범죄수사국과 추가 순찰대가 배치된다.\u003c/p\u003e\r\n  \u003ch3\u003eCODE RED — 고위험사건\u003c/h3\u003e\r\n  \u003cp\u003e중무장 용의자, 폭동과 다수의 인명피해가 예상되는 사건이다.\u003c/p\u003e\r\n  \u003cp\u003e전술대응국이 투입되고 구역통제가 시행된다.\u003c/p\u003e\r\n  \u003ch3\u003eCODE BLACK — 도시위협\u003c/h3\u003e\r\n  \u003cp\u003eDCS의 통상적인 대응능력을 넘어선 사건이다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스와 이클립스에 즉시 보고되며 시민대피와 광역봉쇄가 시작된다.\u003c/p\u003e\r\n  \u003ch3\u003eCODE SILENT — 기밀이관\u003c/h3\u003e\r\n  \u003cp\u003e기업공작이나 국가적 정보위협으로 사건기록의 접근이 차단된 상태다.\u003c/p\u003e\r\n  \u003cp\u003e사건은 아르고스 또는 상위기관으로 이관되며 현장 경찰관도 이후 기록에 접근하지 못할 수 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기관 구조\u003c/h2\u003e\r\n  \u003cp\u003eDCS는 돔 도시행정부 아래에서 치안총감을 중심으로 운영된다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 도시행정부\u003c/h3\u003e\r\n  \u003cp\u003eDCS의 예산, 법적 권한과 주요 치안정책을 승인한다.\u003c/p\u003e\r\n  \u003cp\u003e명목상 시민대표기관이지만 아르카디아와 주요 기업의 영향력이 강하게 작용한다.\u003c/p\u003e\r\n  \u003ch3\u003e치안총감\u003c/h3\u003e\r\n  \u003cp\u003eDCS의 최고책임자다.\u003c/p\u003e\r\n  \u003cp\u003e도시 전체의 치안정책과 대규모 작전을 지휘하며 돔 행정부와 기업기관을 상대로 DCS를 대표한다.\u003c/p\u003e\r\n  \u003ch3\u003e치안부총감\u003c/h3\u003e\r\n  \u003cp\u003e각 실무부문을 조정하고 치안총감을 보좌한다.\u003c/p\u003e\r\n  \u003cp\u003e총감 부재 시 조직 전체의 지휘권을 인수한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e제1차장 — 생활치안\u003c/h2\u003e\r\n  \u003cp\u003e시민의 일상과 가장 가까운 순찰, 지역안전과 지구대를 관리한다.\u003c/p\u003e\r\n  \u003ch3\u003e순찰국\u003c/h3\u003e\r\n  \u003cp\u003e제복경찰과 순찰차, 순찰드론을 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e범죄신고와 사고현장에 가장 먼저 도착하며 긴급대응과 용의자 확보를 담당한다.\u003c/p\u003e\r\n  \u003ch3\u003e지역안전국\u003c/h3\u003e\r\n  \u003cp\u003e학교, 시장, 주거구역과 공공시설의 안전정책을 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e지역주민과 상인, 기업시설 사이의 갈등을 조정하고 범죄예방 사업을 운영한다.\u003c/p\u003e\r\n  \u003ch3\u003e지구대관리국\u003c/h3\u003e\r\n  \u003cp\u003e도시 전역의 지구대와 인력, 장비와 근무편성을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e구역별 신고량과 위험도를 분석해 순찰전력을 배분한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e제2차장 — 수사·전술\u003c/h2\u003e\r\n  \u003cp\u003e중대범죄 수사와 고위험 현장대응을 담당한다.\u003c/p\u003e\r\n  \u003ch3\u003e범죄수사국\u003c/h3\u003e\r\n  \u003cp\u003e살인, 납치, 조직범죄와 대규모 사기를 수사한다.\u003c/p\u003e\r\n  \u003cp\u003e형사와 현장감식관, 사이버수사관이 소속된다.\u003c/p\u003e\r\n  \u003ch3\u003e전술대응국\u003c/h3\u003e\r\n  \u003cp\u003e일반 순찰대가 감당하기 어려운 무장사건과 인질, 폭동에 대응한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스의 강화장비와 중화기를 제한적으로 운용한다. 위협이 도시급으로 확대되면 이클립스에 지휘권을 넘긴다.\u003c/p\u003e\r\n  \u003ch3\u003e증거분석실\u003c/h3\u003e\r\n  \u003cp\u003e생체정보, 탄도, 영상과 디지털 기록을 분석한다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스의 생체기술과 아르고스의 정보분석체계를 활용하지만 증거의 독립성을 유지하는 것이 원칙이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e제3차장 — 교통·행정\u003c/h2\u003e\r\n  \u003cp\u003e교통망, 시민민원과 내부행정을 담당한다.\u003c/p\u003e\r\n  \u003ch3\u003e교통통제국\u003c/h3\u003e\r\n  \u003cp\u003e도로와 대중교통, 화물차량과 비행교통을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e도시재난과 라자루스 긴급출동 시 구조경로를 우선적으로 확보한다.\u003c/p\u003e\r\n  \u003ch3\u003e민원행정국\u003c/h3\u003e\r\n  \u003cp\u003e신고접수, 사건서류와 시민상담을 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e보호명령과 실종신고, 무기 및 집회허가를 처리한다.\u003c/p\u003e\r\n  \u003ch3\u003e내부감찰국\u003c/h3\u003e\r\n  \u003cp\u003e경찰관의 비리와 권력남용, 기업유착과 증거조작을 조사한다.\u003c/p\u003e\r\n  \u003cp\u003e치안총감과 고위간부도 감찰대상에 포함된다. 그러나 정치적 압력에서 얼마나 독립적인지는 논란이 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e총감 직속실\u003c/h2\u003e\r\n  \u003cp\u003e치안총감에게 직접 보고하는 독립부서다.\u003c/p\u003e\r\n  \u003cp\u003e고위 기업인과 관련된 사건, 경찰 내부의 대규모 부패와 도시행정부의 특별지시를 처리한다.\u003c/p\u003e\r\n  \u003cp\u003e직속실은 다른 부서의 작전에 개입하거나 기록을 봉인할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e일부 경찰관들은 총감 직속실이 아르고스의 비공식 연락창구 역할을 한다고 의심한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e현장 인력\u003c/h2\u003e\r\n  \u003ch3\u003e순찰대원\u003c/h3\u003e\r\n  \u003cp\u003e거리순찰과 신고출동을 담당하는 DCS의 기본 인력이다.\u003c/p\u003e\r\n  \u003cp\u003e도시와 시민을 가장 잘 알지만 가장 많은 사건과 위험에 노출된다.\u003c/p\u003e\r\n  \u003ch3\u003e형사\u003c/h3\u003e\r\n  \u003cp\u003e중대범죄와 장기수사를 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e정보원과 피해자, 범죄조직의 관계를 추적한다. 아르고스가 사건을 인수하면 수사자료 전체를 넘겨야 할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e전술대원\u003c/h3\u003e\r\n  \u003cp\u003e중무장 용의자와 인질사건, 폭동에 투입된다.\u003c/p\u003e\r\n  \u003cp\u003e순찰대원보다 강한 무장과 사이버웨어를 지급받지만 이클립스 정예대원과는 역할과 전투력에서 차이가 있다.\u003c/p\u003e\r\n  \u003ch3\u003e교통대원\u003c/h3\u003e\r\n  \u003cp\u003e도로, 대중교통과 화물통행을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스와 이클립스의 긴급차량이 이동할 때 통행로를 통제한다.\u003c/p\u003e\r\n  \u003ch3\u003e감식관\u003c/h3\u003e\r\n  \u003cp\u003e현장의 생체정보와 탄도, 사이버웨어와 전자기록을 수집한다.\u003c/p\u003e\r\n  \u003cp\u003e기업시설에서 증거를 확보할 때는 기업보안과 관할권 충돌을 겪기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e사이버수사관\u003c/h3\u003e\r\n  \u003cp\u003e블루넷 사기, 신원도용과 불법 사이버웨어를 수사한다.\u003c/p\u003e\r\n  \u003cp\u003e고위험 네트워크 사건은 아르고스나 이클립스 사이버전부에 이관한다.\u003c/p\u003e\r\n  \u003ch3\u003e지역담당관\u003c/h3\u003e\r\n  \u003cp\u003e주민과 상점, 학교와 지역조직의 연락을 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e단순한 단속보다 갈등조정과 범죄예방을 우선하는 경찰관이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 장비\u003c/h2\u003e\r\n  \u003ch3\u003eDCS 표준 제복\u003c/h3\u003e\r\n  \u003cp\u003e방탄섬유와 환경보호 기능이 포함된 경찰제복이다.\u003c/p\u003e\r\n  \u003cp\u003e계급과 소속구역, 현재 임무에 따라 표시등의 색과 패턴이 달라진다.\u003c/p\u003e\r\n  \u003ch3\u003e시빅 바이저\u003c/h3\u003e\r\n  \u003cp\u003e신원조회, 사건정보와 동료의 위치를 표시하는 경찰용 시각장치다.\u003c/p\u003e\r\n  \u003cp\u003e현장의 시민권과 무기허가, 수배상태를 확인할 수 있다. 잘못된 정보가 표시될 가능성 때문에 최종판단은 경찰관이 내려야 한다.\u003c/p\u003e\r\n  \u003ch3\u003e표준 제압권총\u003c/h3\u003e\r\n  \u003cp\u003e케르베로스에서 공급하는 DCS 규격화기다.\u003c/p\u003e\r\n  \u003cp\u003e실탄과 비살상탄을 임무에 따라 사용할 수 있으며 발사기록이 자동 저장된다.\u003c/p\u003e\r\n  \u003ch3\u003e펄스 배턴\u003c/h3\u003e\r\n  \u003cp\u003e근접제압과 사이버웨어 교란에 사용되는 전기충격봉이다.\u003c/p\u003e\r\n  \u003cp\u003e출력을 높이면 신경손상과 심정지를 일으킬 수 있어 사용기록이 감찰대상이 된다.\u003c/p\u003e\r\n  \u003ch3\u003e시빅 실드\u003c/h3\u003e\r\n  \u003cp\u003e폭동과 총격사건에서 사용하는 전개식 방탄방패다.\u003c/p\u003e\r\n  \u003cp\u003e여러 방패를 연결해 이동식 방어선을 만들 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e순찰드론\u003c/h3\u003e\r\n  \u003cp\u003e거리와 통로를 감시하고 사건현장의 영상을 전송한다.\u003c/p\u003e\r\n  \u003cp\u003e일부 모델은 비살상 제압탄과 추적장치를 탑재한다.\u003c/p\u003e\r\n  \u003ch3\u003eDCS 인터셉터\u003c/h3\u003e\r\n  \u003cp\u003e도시순찰과 추격에 사용되는 고속 경찰차량이다.\u003c/p\u003e\r\n  \u003cp\u003e교통통제망과 연결되어 신호등과 도로차단기를 직접 조작할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e사건기록기\u003c/h3\u003e\r\n  \u003cp\u003e경찰관의 시각과 음성, 무기사용과 위치를 기록한다.\u003c/p\u003e\r\n  \u003cp\u003e공식적으로 임의로 끌 수 없다. 그러나 기록손실과 접근제한이 반복적으로 논란이 된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 시설\u003c/h2\u003e\r\n  \u003ch3\u003e시빅 센트럴\u003c/h3\u003e\r\n  \u003cp\u003eDCS의 중앙청사이자 치안총감과 주요 지휘부가 위치한 시설이다.\u003c/p\u003e\r\n  \u003cp\u003e통합신고센터, 상황실과 범죄정보 데이터센터가 함께 운영된다.\u003c/p\u003e\r\n  \u003ch3\u003e지구대\u003c/h3\u003e\r\n  \u003cp\u003e각 생활구역의 순찰과 민원을 담당하는 소규모 경찰시설이다.\u003c/p\u003e\r\n  \u003cp\u003e상층구역의 지구대는 최신장비와 충분한 인력을 갖추지만 하층구역은 노후한 장비와 인력부족에 시달린다.\u003c/p\u003e\r\n  \u003ch3\u003e중앙구금소\u003c/h3\u003e\r\n  \u003cp\u003e재판 전 용의자와 단기 수감자를 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e고위험 용의자는 DCS 시설에 장기간 수용하지 않고 이클립스나 기업 전용시설로 이송한다.\u003c/p\u003e\r\n  \u003ch3\u003e증거보관소\u003c/h3\u003e\r\n  \u003cp\u003e무기, 사이버웨어와 디지털 기록을 보관한다.\u003c/p\u003e\r\n  \u003cp\u003e고가의 압수품과 기업기술이 사라지는 사건이 발생해 내부감찰의 주요 대상이 된다.\u003c/p\u003e\r\n  \u003ch3\u003e블라인드 블록\u003c/h3\u003e\r\n  \u003cp\u003e감시망과 순찰이 제대로 닿지 않는 하층구역의 통칭이다.\u003c/p\u003e\r\n  \u003cp\u003e공식 지도에는 일반 생활구역으로 표시되지만 비등록자와 범죄조직, 불법시술소가 밀집해 있다.\u003c/p\u003e\r\n  \u003ch3\u003e폐쇄 지구대\u003c/h3\u003e\r\n  \u003cp\u003e사건이나 오염, 인구이동으로 폐쇄된 옛 경찰시설이다.\u003c/p\u003e\r\n  \u003cp\u003e일부는 범죄조직의 거점이나 비등록자 피난처로 사용된다. 오래된 사건기록과 압수품이 그대로 남아 있다는 소문도 존재한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e경찰 문화\u003c/h2\u003e\r\n  \u003cp\u003eDCS의 경찰관들은 자신들이 거대한 기업질서와 평범한 시민 사이에 서 있다고 생각한다.\u003c/p\u003e\r\n  \u003cp\u003e현장에서는 법률보다 사람과 상황을 먼저 봐야 하는 순간이 많다. 신분이 불안정한 시민을 규정대로 체포할 것인지, 지역사회의 묵인을 받는 불법진료소를 단속할 것인지 끊임없이 선택해야 한다.\u003c/p\u003e\r\n  \u003cp\u003e상층구역 경찰은 절차와 서비스, 민원대응을 중시한다.\u003c/p\u003e\r\n  \u003cp\u003e하층구역 경찰은 생존과 현장판단, 지역정보를 더 중요하게 여긴다. 구역에 따라 같은 DCS 제복을 입고도 완전히 다른 조직처럼 행동한다.\u003c/p\u003e\r\n  \u003cp\u003e경찰관 사이에는 강한 동료의식이 존재한다. 위험한 현장에서 서로를 보호해야 하기 때문이다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 이 동료의식이 비리와 과잉진압을 은폐하는 침묵으로 변하기도 한다.\u003c/p\u003e\r\n  \u003cp\u003eDCS 내부에서 널리 사용되는 문구는 다음과 같다.\u003c/p\u003e\r\n  \u003cblockquote\u003e하늘은 가짜여도, 이 거리에서 죽는 사람은 진짜다.\u003c/blockquote\u003e\r\n\r\n  \u003ch2\u003e채용과 복지\u003c/h2\u003e\r\n  \u003cp\u003eDCS는 돔 시티의 등록 자유민과 기업시민을 대상으로 경찰관을 선발한다.\u003c/p\u003e\r\n  \u003cp\u003e일반 순찰대원은 신체검사와 범죄기록 조사, 기초 전투훈련과 시민법 교육을 받는다. 형사와 사이버수사관, 전술대원은 추가적인 전문교육이 필요하다.\u003c/p\u003e\r\n  \u003cp\u003e장막 도시와 지하도시 출신도 신원보증과 시민권 심사를 통과하면 지원할 수 있다. 그러나 실제 승진과 보직배치에서 차별이 존재한다는 비판이 있다.\u003c/p\u003e\r\n  \u003cp\u003e정식 대원과 가족에게는 다음 혜택이 제공된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e안정적인 기업시민권\u003c/li\u003e\r\n    \u003cli\u003e돔 내부 거주권\u003c/li\u003e\r\n    \u003cli\u003e라자루스 쉘터급 단체계약\u003c/li\u003e\r\n    \u003cli\u003e전투 및 산업재해 치료\u003c/li\u003e\r\n    \u003cli\u003e표준 사이버웨어와 장비\u003c/li\u003e\r\n    \u003cli\u003e가족 의료와 교육지원\u003c/li\u003e\r\n    \u003cli\u003e장기근속 연금\u003c/li\u003e\r\n    \u003cli\u003e순직자 가족보상\u003c/li\u003e\r\n    \u003cli\u003e주거구역 우선배정\u003c/li\u003e\r\n    \u003cli\u003e퇴직 후 행정·보안직 전환\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e급여와 복지는 일반 시민보다 안정적이다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 하층구역 근무와 전술대응 임무의 사망률은 높고, 장기근무자는 폭력과 사망에 무감각해지는 경우가 많다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e대중의 인식\u003c/h2\u003e\r\n  \u003ch3\u003e돔 시티 상류층\u003c/h3\u003e\r\n  \u003cp\u003eDCS를 질서와 재산을 보호하는 공공서비스로 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e순찰과 신고대응이 빠르고 경찰관의 서비스도 친절한 편이다. 이들에게 경찰은 위협보다 안전의 상징이다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 시티 일반 시민\u003c/h3\u003e\r\n  \u003cp\u003e가장 현실적으로 의지할 수 있는 치안기관으로 평가한다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 벌금, 검문과 시민권 확인을 통해 일상에서 가장 자주 마찰하는 기관이기도 하다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 하층민\u003c/h3\u003e\r\n  \u003cp\u003e보호자보다 단속자로 인식하는 경우가 많다.\u003c/p\u003e\r\n  \u003cp\u003e신고출동은 늦지만 검문과 불법주거 단속은 빠르다는 불만이 존재한다. 일부 구역에서는 주민들이 DCS보다 지역조직과 범죄세력에 분쟁해결을 의존한다.\u003c/p\u003e\r\n  \u003ch3\u003e기업인\u003c/h3\u003e\r\n  \u003cp\u003e일반적인 치안과 현장통제에는 유용하지만 기업기밀과 중요인물 보호에는 능력이 부족하다고 평가한다.\u003c/p\u003e\r\n  \u003cp\u003e필요할 경우 자체 보안부대와 아르고스를 우선적으로 이용한다.\u003c/p\u003e\r\n  \u003ch3\u003e장막 도시 주민\u003c/h3\u003e\r\n  \u003cp\u003e돔 시민만을 위한 경찰이라고 생각한다.\u003c/p\u003e\r\n  \u003cp\u003eDCS가 외부작전을 수행하면 시민보호보다 도망자 체포와 기업자산 회수가 목적이라고 의심한다.\u003c/p\u003e\r\n  \u003ch3\u003e범죄조직\u003c/h3\u003e\r\n  \u003cp\u003e아르고스와 이클립스보다 상대하기 쉬운 조직으로 보지만, 지역 형사와 순찰대의 정보력을 무시하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e범죄조직이 특정 지구대나 경찰관과 장기적인 유착관계를 형성하기도 한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e다른 세력과의 관계\u003c/h2\u003e\r\n  \u003ch3\u003eARCADIA HABITAT\u003c/h3\u003e\r\n  \u003cp\u003eDCS의 상위 도시행정과 기반시설을 사실상 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 DCS의 청사, 전산망과 예산에 큰 영향력을 행사한다. DCS는 법적으로 독립된 경찰기관이지만 아르카디아의 도시정책을 완전히 거부하기 어렵다.\u003c/p\u003e\r\n  \u003cp\u003e시민들은 DCS가 도시의 경찰인지 아르카디아의 보안부인지 의심한다.\u003c/p\u003e\r\n  \u003ch3\u003eARGOS SECURE NETWORKS\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 신원조회, 방첩정보와 고위험 범죄분석을 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e기업공작과 테러가 확인되면 사건을 인수한다. DCS 수사관이 장기간 추적한 사건도 아르고스의 명령 한 번으로 접근이 차단될 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003eECLIPSE TACTICAL BUREAU\u003c/h3\u003e\r\n  \u003cp\u003eDCS의 대응능력을 넘어선 사건에서 지휘권을 인수한다.\u003c/p\u003e\r\n  \u003cp\u003eDCS는 시민대피와 외곽통제, 현장정보를 제공한다. 일선 경찰은 이클립스가 위험을 해결한다고 인정하면서도 시민과 지역사정을 무시한 채 작전을 수행한다고 비판한다.\u003c/p\u003e\r\n  \u003ch3\u003eLAZARUS MEDICAL RESPONSE\u003c/h3\u003e\r\n  \u003cp\u003e총격과 사고현장에서 구조경로를 확보하고 의료진을 보호한다.\u003c/p\u003e\r\n  \u003cp\u003e라자루스의 긴급차량에는 교통과 검문소에서 높은 통행우선권이 부여된다. 다만 회원과 비회원의 구조 우선순위 때문에 현장 경찰관과 갈등이 발생하기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003eCERBERUS DEFENSE GROUP\u003c/h3\u003e\r\n  \u003cp\u003eDCS의 화기와 방탄복, 순찰드론과 전술차량을 공급한다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스의 지속적인 정비와 탄약공급에 의존한다. 경찰장비의 군사화와 원격통제 가능성이 논란이 된다.\u003c/p\u003e\r\n  \u003ch3\u003eMORPHOS BIODYNE\u003c/h3\u003e\r\n  \u003cp\u003e생체증거 분석과 사이버웨어 감식, 부상 경찰관의 신체복원을 지원한다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스 고객과 관련된 사건에서는 의료기밀과 수사권이 충돌한다.\u003c/p\u003e\r\n  \u003ch3\u003eCHARON INTERCONTINENTAL\u003c/h3\u003e\r\n  \u003cp\u003e돔의 중앙역과 물류구역, 화물노선 치안을 공동으로 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 자체 노선보안대의 관할권을 주장하며 DCS의 화물검사를 제한하려 한다.\u003c/p\u003e\r\n  \u003ch3\u003eVELVET STATIC\u003c/h3\u003e\r\n  \u003cp\u003e클럽과 감각방송, 불법기억 편집과 정보거래로 인해 주요 수사대상이다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 벨벳 스태틱의 업소는 상류층과 기업간부도 이용하기 때문에 대대적인 단속이 자주 중단된다. 일부 경찰관과 간부가 조직의 협박자료에 묶여 있다는 소문이 있다.\u003c/p\u003e\r\n  \u003ch3\u003eSAINT ZERO\u003c/h3\u003e\r\n  \u003cp\u003e불법 사이버웨어와 미등록 진료로 인해 단속대상이다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 하층구역 주민에게 의료서비스를 제공한다는 사실 때문에 일선 경찰이 진료소의 존재를 묵인하는 경우도 있다.\u003c/p\u003e\r\n  \u003ch3\u003eLOWLINE\u003c/h3\u003e\r\n  \u003cp\u003e불법통로, 밀수와 기반시설 절도로 인해 주요 적대세력이다.\u003c/p\u003e\r\n  \u003cp\u003eDCS는 로우라인이 관리하는 지하노선을 완전히 파악하지 못한다. 하층구역의 추적작전에서 경찰이 오히려 길을 잃는 경우도 있다.\u003c/p\u003e\r\n  \u003ch3\u003eTHE BLUE TABLE\u003c/h3\u003e\r\n  \u003cp\u003e직접적인 상위기관은 아니지만 도시 간 치안규정과 기업분쟁에 영향을 준다.\u003c/p\u003e\r\n  \u003cp\u003e칠정 공동명령이 내려지면 돔 행정부를 통해 DCS에 전달된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e사회공헌과 홍보\u003c/h2\u003e\r\n  \u003cp\u003eDCS는 자신들을 “시민과 함께 걷는 경찰”이라고 소개한다.\u003c/p\u003e\r\n  \u003cp\u003e학교 안전교육, 지역순찰과 실종자 예방, 불법무기 반납과 시민상담 프로그램을 운영한다. 경찰관이 시장과 주거지를 직접 방문해 주민의 요구를 듣는 지역담당관 제도도 홍보한다.\u003c/p\u003e\r\n  \u003cp\u003e순직 경찰관은 도시 전체의 공식 추모대상이 된다.\u003c/p\u003e\r\n  \u003cp\u003e돔의 인공하늘에는 순직자의 이름과 계급이 표시되고, 가족에게는 시민권과 생활지원이 제공된다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 하층구역에서는 사회공헌 활동보다 검문과 진압장비를 먼저 목격하는 시민이 많다.\u003c/p\u003e\r\n  \u003cp\u003eDCS의 공식 홍보와 실제 현장 사이의 차이가 가장 크게 드러나는 부분이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e논란과 비판\u003c/h2\u003e\r\n  \u003ch3\u003e기업의 영향력\u003c/h3\u003e\r\n  \u003cp\u003eDCS는 공공기관이지만 예산과 시설, 장비와 정보망을 기업에 의존한다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아와 칠정 기업의 이해관계에 따라 수사방향과 치안정책이 바뀐다는 비판이 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003e구역별 치안격차\u003c/h3\u003e\r\n  \u003cp\u003e상층구역에는 충분한 경찰과 최신장비가 배치된다.\u003c/p\u003e\r\n  \u003cp\u003e하층구역은 신고가 많음에도 인력이 부족하며 노후한 순찰차와 장비를 사용한다. DCS는 범죄위험에 따라 배치한다고 주장하지만 시민들은 계급에 따른 차별이라고 본다.\u003c/p\u003e\r\n  \u003ch3\u003e과잉검문\u003c/h3\u003e\r\n  \u003cp\u003e등록 자유민과 하층민, 장막 도시 출신자는 더 자주 신원검사를 받는다.\u003c/p\u003e\r\n  \u003cp\u003e위험도 분석에 따른 선별이라고 설명하지만 출신과 시민권 등급을 이용한 차별이라는 비판이 강하다.\u003c/p\u003e\r\n  \u003ch3\u003e경찰의 군사화\u003c/h3\u003e\r\n  \u003cp\u003e전술대응국과 일부 순찰대가 케르베로스의 군용 장비를 사용한다.\u003c/p\u003e\r\n  \u003cp\u003e일반 범죄와 시위에 지나치게 강한 무력이 사용된다는 우려가 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003e기업인 특혜\u003c/h3\u003e\r\n  \u003cp\u003e상위 기업인의 신고와 사건은 우선적으로 처리되는 경향이 있다.\u003c/p\u003e\r\n  \u003cp\u003e하층구역의 실종사건은 장기간 미제로 남지만 기업구역의 절도사건에는 전문수사팀이 즉시 배정되기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e증거 조작과 사건 이관\u003c/h3\u003e\r\n  \u003cp\u003e아르고스가 사건을 인수한 뒤 증거와 기록이 사라지거나 다른 내용으로 변경되는 사례가 존재한다.\u003c/p\u003e\r\n  \u003cp\u003eDCS는 상급 보안명령에 따른 조치라고 설명하지만 경찰의 수사독립성이 훼손된다는 비판을 받는다.\u003c/p\u003e\r\n  \u003ch3\u003e내부 부패\u003c/h3\u003e\r\n  \u003cp\u003e범죄조직으로부터 돈을 받고 단속정보를 유출하거나 압수품을 빼돌리는 경찰관이 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e내부감찰국이 조사하지만 고위간부와 기업이 관련된 사건은 제대로 처벌되지 않는다는 의혹이 있다.\u003c/p\u003e\r\n  \u003ch3\u003e비등록자 처리\u003c/h3\u003e\r\n  \u003cp\u003e행정기록이 없는 사람은 범죄피해를 신고하기 어렵다.\u003c/p\u003e\r\n  \u003cp\u003eDCS는 신원을 확인할 수 없는 피해자를 보호하는 동시에 불법거주 여부를 조사한다. 이 때문에 비등록자는 범죄를 당해도 경찰을 부르지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e확인되지 않은 소문\u003c/h2\u003e\r\n  \u003cp\u003eDCS 내부에는 공식 조직도에 존재하지 않는 특별수사반이 있다는 소문이 있다.\u003c/p\u003e\r\n  \u003cp\u003e이들은 기업이 공식적으로 처리하기 곤란한 사건을 맡으며 아르고스와 치안총감 직속실의 공동명령을 받는다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e체포된 용의자가 중앙구금소에 도착하기 전에 사라지거나 사건기록이 코드 사일런트로 변경되는 경우, 특별수사반이 개입한 것으로 여겨진다.\u003c/p\u003e\r\n  \u003cp\u003e또한 일부 지구대가 범죄조직과 비공식 협정을 맺고 있다는 소문도 있다.\u003c/p\u003e\r\n  \u003cp\u003e조직이 민간인을 무차별적으로 공격하지 않고 구역의 질서를 유지하는 대신, DCS가 일정 수준의 불법사업을 묵인한다는 것이다.\u003c/p\u003e\r\n  \u003cp\u003e하층구역에서는 실제 법보다 이러한 협정이 더 효과적으로 작동하는 경우도 있다.\u003c/p\u003e\r\n  \u003cp\u003e가장 위험한 소문은 DCS의 중앙신고망과 관련되어 있다.\u003c/p\u003e\r\n  \u003cp\u003e일부 시민의 신고는 사건내용과 관계없이 자동으로 낮은 우선순위에 배정되며, 특정 인물의 신고는 담당 경찰관에게 전달되기 전에 삭제된다는 것이다.\u003c/p\u003e\r\n  \u003cp\u003e반대로 어떤 시민은 범죄를 저지르기 전에 이미 순찰대의 감시대상에 등록되어 있다.\u003c/p\u003e\r\n  \u003cp\u003eDCS는 신고 우선순위가 현장위험과 인명피해 가능성만을 기준으로 결정된다고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 그 기준을 계산하는 알고리즘은 아르카디아의 사회설계자료와 아르고스의 위험평가를 함께 사용한다.\u003c/p\u003e\r\n  \u003cp\u003e경찰관조차 시민의 위험등급이 왜 그렇게 결정되었는지 알지 못한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기관이 가진 힘\u003c/h2\u003e\r\n  \u003cp\u003eDCS는 세계에서 가장 강한 조직이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스처럼 거대한 군대를 가지고 있지 않으며, 아르고스처럼 모든 정보를 들여다볼 수도 없다. 이클립스가 상대하는 재난 앞에서는 지휘권을 넘겨야 한다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 시민의 삶에 가장 자주 개입하는 공권력은 DCS다.\u003c/p\u003e\r\n  \u003cp\u003e거리에서 사람을 멈춰 세우고 신분을 확인하며, 문을 열고 집 안으로 들어간다. 누군가를 체포하고 무기를 압수하며, 사건이 범죄인지 사고인지를 가장 먼저 판단한다.\u003c/p\u003e\r\n  \u003cp\u003e그 판단은 평범한 경찰관 한 명의 손에서 이루어진다.\u003c/p\u003e\r\n  \u003cp\u003e어떤 경찰관은 규정대로 행동하고, 어떤 경찰관은 돈을 받으며, 또 다른 경찰관은 명령을 어기면서까지 시민을 돕는다.\u003c/p\u003e\r\n  \u003cp\u003eDCS의 힘은 완벽한 감시망이나 압도적인 화력에서 나오지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e수천 명의 평범한 대원이 매일 같은 제복을 입고 거리로 나간다는 사실에서 나온다.\u003c/p\u003e\r\n  \u003cp\u003e그들이 순찰하는 동안 돔의 시장은 열리고 아이들은 학교에 가며 시민들은 인공하늘 아래에서 일상을 살아간다.\u003c/p\u003e\r\n  \u003cp\u003e그리고 DCS가 어느 날 거리에서 사라진다면, 시민들은 자신들이 얼마나 많은 질서를 그 평범한 제복에 의존하고 있었는지 깨닫게 될 것이다.\u003c/p\u003e\r\n\u003c/section\u003e\r\n";
window.FACTION_INFO.lowline = "\u003csection class=\"faction-detail\"\u003e\r\n  \u003ch2\u003e조직 개요\u003c/h2\u003e\r\n  \u003cp class=\"faction-quote\"\u003e“도시는 위에서 보이는 것보다 아래에 더 많은 길을 숨기고 있다.”\u003c/p\u003e\r\n  \u003cp\u003e로우라인은 돔 시티와 장막 도시 아래에 버려진 지하철도, 배수로, 냉각망과 정비통로를 지배하는 범죄연합이다. 하나의 수직적인 갱단이라기보다 서로 다른 지하노선을 관리하는 조직들이 느슨하게 연결된 형태에 가깝다.\u003c/p\u003e\r\n  \u003cp\u003e이들은 사람과 밀수품을 운반하고, 불법 전력과 수도를 연결하며, 기업시설로 이어지는 비밀통로를 판매한다. 돔의 공식 지도에 존재하지 않는 길과 백야 이전에 폐쇄된 지하시설도 로우라인의 영역에 포함된다.\u003c/p\u003e\r\n  \u003cp\u003e지상의 시민에게 로우라인은 기반시설을 훔치는 범죄조직이다. 하지만 하층민과 비등록자에게는 물과 전기, 이동할 길을 제공하는 또 하나의 도시정부다.\u003c/p\u003e\r\n  \u003cp\u003eDCS가 도시의 문을 잠그고 아르고스가 모든 신분을 추적하더라도, 로우라인은 벽과 바닥 아래로 새로운 길을 만든다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기본 정보\u003c/h2\u003e\r\n  \u003ctable class=\"data-table faction-info-table\"\u003e\r\n    \u003ctbody\u003e\r\n      \u003ctr\u003e\u003cth\u003e정식 명칭\u003c/th\u003e\u003ctd\u003eLOWLINE\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e통칭\u003c/th\u003e\u003ctd\u003e로우라인, 하부선\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e조직 분류\u003c/th\u003e\u003ctd\u003e지하노선 기반 범죄연합\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 활동\u003c/th\u003e\u003ctd\u003e밀수, 밀입국, 불법 배관, 전력 탈취, 시설 침투\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 거점\u003c/th\u003e\u003ctd\u003e폐쇄된 역, 정비통로, 배수로, 지하시설\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e상징 색상\u003c/th\u003e\u003ctd\u003e적색, 흑색, 회색\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e최고지도부\u003c/th\u003e\u003ctd\u003e스위치보드\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e지역책임자\u003c/th\u003e\u003ctd\u003e노선관리자, 역장\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 구성원\u003c/th\u003e\u003ctd\u003e길잡이, 패처, 탭퍼, 러너, 몰, 터널전투원\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표적인 인식\u003c/th\u003e\u003ctd\u003e도시 아래에 존재하는 또 하나의 교통망\u003c/td\u003e\u003c/tr\u003e\r\n    \u003c/tbody\u003e\r\n  \u003c/table\u003e\r\n\r\n  \u003ch2\u003e조직의 역사\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e백야 이후의 지하\u003c/h3\u003e\r\n  \u003cp\u003e2102년 백야가 발생하자 지상의 도로와 도시가 붕괴했다. 살아남은 사람들 가운데 일부는 지하철도, 방공호와 정비터널로 피신했다.\u003c/p\u003e\r\n  \u003cp\u003e지하에는 태양과 일소를 피할 수 있는 공간이 있었지만 식량과 물, 공기가 부족했다. 생존자들은 폐쇄된 배관을 수리하고 지상의 창고와 연결된 통로를 찾아야 했다.\u003c/p\u003e\r\n  \u003cp\u003e이들은 도시시설을 관리하던 기술자, 철도노동자, 밀수업자와 피난민이었다.\u003c/p\u003e\r\n  \u003cp\u003e현재의 로우라인은 이 지하 생존공동체에서 시작되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e돔 아래의 그림자\u003c/h3\u003e\r\n  \u003cp\u003e아르카디아가 폐허 위에 돔 시티를 건설하면서 기존 지하시설 상당수가 새로운 도시 아래에 묻혔다.\u003c/p\u003e\r\n  \u003cp\u003e공식적으로는 폐쇄된 구역이었지만 지하에서 살아가던 사람들은 사라지지 않았다. 그들은 아르카디아의 냉각망과 수도, 전력망에 비공식적으로 연결해 생존했다.\u003c/p\u003e\r\n  \u003cp\u003e도시가 확장될수록 로우라인이 이용할 수 있는 통로도 늘어났다.\u003c/p\u003e\r\n  \u003cp\u003e밀수업자와 비등록자, 기업의 추적을 피해 달아난 사람들이 로우라인을 찾았다. 폐쇄된 지하역은 시장과 은신처, 밀수창고로 변했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e노선연합의 탄생\u003c/h3\u003e\r\n  \u003cp\u003e서로 다른 노선을 관리하는 조직들은 통행료와 밀수권을 두고 끊임없이 싸웠다.\u003c/p\u003e\r\n  \u003cp\u003e지하전쟁으로 주요 터널과 배관이 파괴되자 양측 모두 막대한 피해를 입었다. 기반시설이 무너지면 승자도 그 구역에서 살아갈 수 없었다.\u003c/p\u003e\r\n  \u003cp\u003e각 노선의 대표들은 거래와 충돌을 조정하기 위한 비밀연락망을 만들었다.\u003c/p\u003e\r\n  \u003cp\u003e이것이 스위치보드와 현재 로우라인 연합의 시작으로 알려져 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e조직 구조\u003c/h2\u003e\r\n  \u003cp\u003e로우라인에는 모든 조직원을 직접 통제하는 절대적인 수장이 없다.\u003c/p\u003e\r\n  \u003cp\u003e각 노선과 역은 상당한 자율권을 가지며, 공통의 이익과 지하질서를 위해 협력한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e스위치보드 — SWITCHBOARD\u003c/h3\u003e\r\n  \u003cp\u003e로우라인의 최고지도부로 알려진 비밀회의체다.\u003c/p\u003e\r\n  \u003cp\u003e정확한 위치와 구성원은 공개되지 않는다. 각 노선의 거래와 분쟁, 대규모 침투작전과 기업 간 협상을 조정한다.\u003c/p\u003e\r\n  \u003cp\u003e스위치보드가 실제 사람들의 회의인지, 익명 통신망인지조차 분명하지 않다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e노선관리자 — LINE BOSS\u003c/h3\u003e\r\n  \u003cp\u003e특정 지하노선과 연결통로 전체를 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e역장들의 충성을 유지하고 노선 간 거래와 통행료를 조정한다. 전쟁이 발생하면 해당 노선의 전투원과 기술자를 동원한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e역장 — STATION MASTER\u003c/h3\u003e\r\n  \u003cp\u003e폐쇄된 역과 주변 구역을 관리하는 현장책임자다.\u003c/p\u003e\r\n  \u003cp\u003e은신처와 밀수창고, 급수시설과 시장을 운영한다. 지상조직과의 거래, 통행료와 지역분쟁도 역장이 처리한다.\u003c/p\u003e\r\n  \u003cp\u003e일부 역장은 범죄조직의 간부지만 다른 역장은 사실상 지하정착지의 행정관에 가깝다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 구성원\u003c/h2\u003e\r\n  \u003ch3\u003e길잡이\u003c/h3\u003e\r\n  \u003cp\u003e지하통로와 폐쇄구역을 안내한다.\u003c/p\u003e\r\n  \u003cp\u003e같은 노선이라도 붕괴와 침수, 기업의 봉쇄로 길이 계속 변하기 때문에 숙련된 길잡이 없이는 로우라인을 안전하게 통과하기 어렵다.\u003c/p\u003e\r\n  \u003ch3\u003e패처\u003c/h3\u003e\r\n  \u003cp\u003e배관, 환기장치, 냉각망과 철도시설을 수리하는 기술자다.\u003c/p\u003e\r\n  \u003cp\u003e로우라인의 실질적인 생존을 책임진다. 뛰어난 패처는 전투원보다 높은 대우를 받기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e탭퍼\u003c/h3\u003e\r\n  \u003cp\u003e기업의 수도와 전력, 통신망에 불법 연결을 설치한다.\u003c/p\u003e\r\n  \u003cp\u003e하층민과 비등록자에게 물과 전기를 판매한다. 잘못된 연결 하나가 구역 전체의 사고로 이어질 수 있어 높은 기술력이 요구된다.\u003c/p\u003e\r\n  \u003ch3\u003e러너\u003c/h3\u003e\r\n  \u003cp\u003e사람과 밀수품을 운반한다.\u003c/p\u003e\r\n  \u003cp\u003e무기와 약품, 위조 신분증과 기업기밀을 지하노선을 통해 이동시킨다. 지상의 검문소와 감시망을 통하지 않는 것이 가장 큰 장점이다.\u003c/p\u003e\r\n  \u003ch3\u003e몰\u003c/h3\u003e\r\n  \u003cp\u003e벽과 지반을 뚫어 새로운 통로를 만든다.\u003c/p\u003e\r\n  \u003cp\u003e기업시설과 창고, 구금시설로 이어지는 침투로를 건설한다. 불안정한 지층과 오래된 기반시설을 건드리기 때문에 가장 위험한 직종 중 하나다.\u003c/p\u003e\r\n  \u003ch3\u003e터널전투원\u003c/h3\u003e\r\n  \u003cp\u003e로우라인의 영역과 핵심시설을 지키는 전투원이다.\u003c/p\u003e\r\n  \u003cp\u003e좁고 어두운 통로에서의 근접전과 매복, 폭발물 운용에 능하다. 지하에서는 중무장한 DCS 전술대보다 로우라인 전투원이 더 위험할 수 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 사업\u003c/h2\u003e\r\n  \u003ch3\u003e비밀통행\u003c/h3\u003e\r\n  \u003cp\u003e공식 검문과 신원인증을 우회해 사람을 이동시킨다.\u003c/p\u003e\r\n  \u003cp\u003e도망자, 비등록자와 밀수업자가 주로 이용하지만 기업요원과 DCS 경찰도 비공식적인 목적으로 로우라인의 길을 구매한다.\u003c/p\u003e\r\n  \u003ch3\u003e밀수\u003c/h3\u003e\r\n  \u003cp\u003e무기와 약품, 불법 사이버웨어와 감각기록을 지하로 운반한다.\u003c/p\u003e\r\n  \u003cp\u003e로우라인은 물건을 직접 생산하기보다 다른 조직의 상품을 안전하게 이동시키는 역할을 맡는다.\u003c/p\u003e\r\n  \u003ch3\u003e불법 기반시설 연결\u003c/h3\u003e\r\n  \u003cp\u003e정식 배급망에 접근할 수 없는 사람에게 물과 전기, 냉각과 블루넷 접속을 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e요금은 비싸지만 시민권이나 기업계약을 요구하지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e시설 침투\u003c/h3\u003e\r\n  \u003cp\u003e기업 연구소, 창고와 보안구역으로 이어지는 통로를 개척한다.\u003c/p\u003e\r\n  \u003cp\u003e범죄조직뿐 아니라 경쟁기업과 아르고스의 비밀요원도 로우라인을 고용한다.\u003c/p\u003e\r\n  \u003ch3\u003e은신처 운영\u003c/h3\u003e\r\n  \u003cp\u003e폐쇄역과 정비구역에 도망자와 비등록자를 숨긴다.\u003c/p\u003e\r\n  \u003cp\u003e비용은 크레딧뿐 아니라 노동, 정보와 기술로 지불할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e지하시장\u003c/h3\u003e\r\n  \u003cp\u003e밀수품, 폐기부품과 신분이 확인되지 않은 물건을 거래한다.\u003c/p\u003e\r\n  \u003cp\u003e각 역장의 규칙에 따라 시장의 성격이 달라지며 일부 대형역은 장막 도시와 비슷한 규모로 성장했다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e지하의 규칙\u003c/h2\u003e\r\n  \u003cp\u003e로우라인 전체를 통제하는 법은 없지만 대부분의 노선에서 다음 규칙이 통용된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e길잡이를 속이거나 공격하지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e핵심 배관과 환기시설 주변에서는 총격을 자제한다.\u003c/li\u003e\r\n    \u003cli\u003e노선관리자의 허가 없이 새 통로를 뚫지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e역장이 승인한 거래는 역 내부에서 보호받는다.\u003c/li\u003e\r\n    \u003cli\u003e통행료를 지불한 사람의 신분을 묻지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e지상기관에 노선정보를 판매한 자는 돌아올 수 없다.\u003c/li\u003e\r\n    \u003cli\u003e기반시설을 파괴한 사람은 어느 노선에서도 보호받지 못한다.\u003c/li\u003e\r\n    \u003cli\u003e지하전쟁이 발생해도 물과 공기의 공급망은 공격하지 않는다.\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e규칙을 위반한 사람은 추방되거나 통행권을 잃는다.\u003c/p\u003e\r\n  \u003cp\u003e로우라인에서 통행권을 박탈당한다는 것은 지하 어디에서도 안전하게 머물 수 없다는 뜻이다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e조직 문화\u003c/h2\u003e\r\n  \u003cp\u003e로우라인은 혈통이나 출신보다 자신이 맡은 역할과 지하에서 쌓은 신뢰를 중요하게 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e정식 시민권이 없는 사람도 길을 알고 배관을 고칠 수 있다면 자리를 얻을 수 있다. 반대로 높은 신분의 기업인이라도 지하의 규칙을 무시하면 보호받지 못한다.\u003c/p\u003e\r\n  \u003cp\u003e조직원들은 지상의 사람을 ‘업퍼’라고 부르며 도시의 공식 지도와 행정망을 믿지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e그들에게 진짜 지도는 벽에 남겨진 기호와 배관의 진동, 공기의 흐름에 기록되어 있다.\u003c/p\u003e\r\n  \u003cp\u003e로우라인에서 널리 사용되는 말은 다음과 같다.\u003c/p\u003e\r\n  \u003cblockquote\u003e위에서는 신분이 길을 연다. 아래에서는 길을 아는 사람이 신분이다.\u003c/blockquote\u003e\r\n\r\n  \u003ch2\u003e대중의 인식\u003c/h2\u003e\r\n  \u003ch3\u003e돔 시민\u003c/h3\u003e\r\n  \u003cp\u003e불법전력과 밀수, 범죄자의 도피를 돕는 위험한 조직으로 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 정식 교통망이 봉쇄되거나 감시를 피해야 할 때 몰래 로우라인을 이용하는 시민도 많다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 하층민\u003c/h3\u003e\r\n  \u003cp\u003e범죄조직인 동시에 생존에 필요한 기반시설을 제공하는 세력으로 본다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아가 정식 배급을 끊은 구역에 물과 전기를 연결해 주는 경우 로우라인은 DCS보다 높은 지지를 얻기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e비등록자\u003c/h3\u003e\r\n  \u003cp\u003e로우라인은 돔 안에서 살아갈 수 있는 거의 유일한 기반이다.\u003c/p\u003e\r\n  \u003cp\u003e은신처와 일자리, 지상으로 이어지는 길을 제공받는 대신 노동과 충성을 요구받는다.\u003c/p\u003e\r\n  \u003ch3\u003e기업\u003c/h3\u003e\r\n  \u003cp\u003e시설을 침투하고 자원을 훔치는 범죄조직으로 규정한다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 공식적인 방법으로 접근할 수 없는 장소와 인물이 필요할 때 비밀리에 거래한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e다른 세력과의 관계\u003c/h2\u003e\r\n  \u003ch3\u003eARCADIA HABITAT\u003c/h3\u003e\r\n  \u003cp\u003e로우라인이 불법으로 사용하는 배관과 정비통로 대부분은 아르카디아의 도시시설에 속한다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아는 이들을 기반시설을 위협하는 기생조직으로 규정하지만, 모든 통로를 폐쇄하면 하층구역 전체가 피해를 볼 수 있어 완전한 제거는 어렵다.\u003c/p\u003e\r\n  \u003ch3\u003eDOME CIVIC SECURITY\u003c/h3\u003e\r\n  \u003cp\u003e지하 밀수와 불법통행을 단속하는 대표적인 적대세력이다.\u003c/p\u003e\r\n  \u003cp\u003eDCS는 로우라인의 전체 지도를 가지고 있지 않다. 추적작전에서 경찰관이 실종되거나 반대편 구역에서 발견되는 경우도 있다.\u003c/p\u003e\r\n  \u003ch3\u003eARGOS SECURE NETWORKS\u003c/h3\u003e\r\n  \u003cp\u003e아르고스는 로우라인을 이용하는 정보원과 침투경로를 감시한다.\u003c/p\u003e\r\n  \u003cp\u003e로우라인 내부에도 아르고스의 협력자와 이중첩자가 존재하지만, 어느 노선까지 침투했는지는 알 수 없다.\u003c/p\u003e\r\n  \u003ch3\u003eVELVET STATIC\u003c/h3\u003e\r\n  \u003cp\u003e감각기록, 위조 신분과 인물을 운반하는 주요 거래상대다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱은 상품과 정보를 제공하고 로우라인은 이를 감시망 밖으로 이동시킨다.\u003c/p\u003e\r\n  \u003ch3\u003eSAINT ZERO\u003c/h3\u003e\r\n  \u003cp\u003e불법 의약품과 사이버웨어, 환자를 운반한다.\u003c/p\u003e\r\n  \u003cp\u003e로우라인의 폐쇄역 안에 세인트 제로의 비밀진료소가 존재하는 경우도 많다.\u003c/p\u003e\r\n  \u003ch3\u003eDEAD AIR\u003c/h3\u003e\r\n  \u003cp\u003e블루넷 케이블과 숨겨진 접속노드를 공유한다.\u003c/p\u003e\r\n  \u003cp\u003e탭퍼가 물리적인 접속경로를 만들면 데드 에어의 넷러너가 기업망에 침투한다.\u003c/p\u003e\r\n  \u003ch3\u003eBLACKTOP UNION\u003c/h3\u003e\r\n  \u003cp\u003e독립 운송업자와 밀수노선을 두고 협력한다.\u003c/p\u003e\r\n  \u003cp\u003e블랙탑이 지상의 도로를 담당한다면 로우라인은 도시 아래의 마지막 운송구간을 맡는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e논란과 내부 문제\u003c/h2\u003e\r\n  \u003ch3\u003e기반시설 훼손\u003c/h3\u003e\r\n  \u003cp\u003e불법으로 전력과 물을 끌어가는 과정에서 화재, 누수와 냉각망 고장이 발생한다.\u003c/p\u003e\r\n  \u003cp\u003e로우라인은 자신들이 버려진 시설을 다시 사용한다고 주장하지만 피해는 지상의 시민에게 돌아가기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e과도한 통행료\u003c/h3\u003e\r\n  \u003cp\u003e위험한 사람이나 긴급한 상황일수록 높은 통행료를 요구한다.\u003c/p\u003e\r\n  \u003cp\u003e가난한 도망자는 자유를 얻기 위해 장기간의 노동계약을 맺어야 할 수도 있다.\u003c/p\u003e\r\n  \u003ch3\u003e노선별 격차\u003c/h3\u003e\r\n  \u003cp\u003e일부 역은 안정적인 시장과 주거지를 운영하지만, 다른 역은 폭력적인 갱단과 노예상인이 지배한다.\u003c/p\u003e\r\n  \u003cp\u003e스위치보드는 최소한의 질서만 유지할 뿐 모든 지역의 범죄를 통제하지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e지하전쟁\u003c/h3\u003e\r\n  \u003cp\u003e노선과 통행권을 둘러싼 충돌은 계속된다.\u003c/p\u003e\r\n  \u003cp\u003e대규모 전쟁은 금지되어 있지만 매종, 암살과 시설사고로 위장한 분쟁이 끊이지 않는다.\u003c/p\u003e\r\n  \u003ch3\u003e비등록자 착취\u003c/h3\u003e\r\n  \u003cp\u003e보호받을 곳이 없는 사람에게 숙소와 물을 제공하는 대신 위험한 굴착과 운반업무를 강요하는 역도 존재한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e확인되지 않은 소문\u003c/h2\u003e\r\n  \u003cp\u003e스위치보드는 실제 조직이 아니라 백야 이전의 철도관리 인공지능이라는 소문이 있다.\u003c/p\u003e\r\n  \u003cp\u003e각 노선관리자는 정체를 알 수 없는 통신망에서 지시를 받고 있으며, 스위치보드는 도시 아래의 모든 열차와 문, 환기시설을 여전히 통제한다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e또한 로우라인의 가장 깊은 노선에는 현재의 돔보다 훨씬 오래된 지하도시가 존재한다는 이야기도 있다.\u003c/p\u003e\r\n  \u003cp\u003e그곳에는 2102년 백야 당시 대피한 사람들이 외부와 완전히 단절된 채 살아가고 있으며, 지상의 문명이 멸망한 사실조차 알지 못한다는 것이다.\u003c/p\u003e\r\n  \u003cp\u003e일부 길잡이는 지도에 존재하지 않는 열차의 진동을 느낀다고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e폐쇄된 선로에서 일정한 시간마다 무언가가 지나가며, 그것을 따라간 사람은 다른 노선에서도 다시 발견되지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e스위치보드는 해당 구간을 ‘종점’으로 지정했다.\u003c/p\u003e\r\n  \u003cp\u003e그곳으로 향하는 통행권은 어떤 대가로도 판매되지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e조직이 가진 힘\u003c/h2\u003e\r\n  \u003cp\u003e로우라인은 지상의 도시를 직접 지배하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e대신 그 도시가 무엇 위에 세워졌는지를 알고 있다.\u003c/p\u003e\r\n  \u003cp\u003e어느 벽 뒤에 냉각관이 지나가고, 어떤 배수로가 기업시설과 연결되며, 어느 폐쇄역에서 돔 외부로 나갈 수 있는지를 기억한다.\u003c/p\u003e\r\n  \u003cp\u003e아르카디아가 도시를 설계하고 DCS가 거리를 순찰하며 아르고스가 시민을 감시해도, 그들의 지도에는 존재하지 않는 공간이 남아 있다.\u003c/p\u003e\r\n  \u003cp\u003e로우라인은 바로 그 공간에서 살아간다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 도시를 정면으로 공격할 만큼 강하지 않다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 마음만 먹는다면 물을 새게 하고 전력을 끊으며, 누구도 보지 못한 길로 사람과 무기를 이동시킬 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e지상의 권력은 건물과 법, 신분을 지배한다.\u003c/p\u003e\r\n  \u003cp\u003e로우라인은 그 모든 것 아래에 이어진 길을 지배한다.\u003c/p\u003e\r\n\u003c/section\u003e\r\n";
window.FACTION_INFO.velvet = "\u003csection class=\"faction-detail\"\u003e\r\n  \u003ch2\u003e조직 개요\u003c/h2\u003e\r\n  \u003cp class=\"faction-quote\"\u003e“당신이 원하는 밤을 보여드립니다. 당신이 숨기고 싶은 밤까지도.”\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱은 클럽, 감각방송, 기억편집과 정보거래를 지배하는 도시형 범죄조직이다. 거리에서 구역을 두고 싸우는 일반적인 갱단과 달리, 합법적인 유흥기업과 호텔, 감각극장과 비밀 살롱을 기반으로 활동한다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 인간의 욕망을 상품으로 만든다.\u003c/p\u003e\r\n  \u003cp\u003e고객은 벨벳 스태틱의 업소에서 현실보다 선명한 감각과 가공된 추억, 잠시 다른 사람으로 살아가는 경험을 구매할 수 있다. 기업인과 정치인, 범죄자와 연예인이 같은 공간에서 자신의 정체를 숨긴 채 거래한다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱은 이들의 취향과 대화, 기억과 실수를 기록한다.\u003c/p\u003e\r\n  \u003cp\u003e표면적인 사업은 유흥과 감각산업이지만 조직의 진짜 힘은 그렇게 수집한 비밀에서 나온다. 한 사람의 쾌락은 다른 사람에게 판매할 정보가 되고, 감추고 싶은 밤은 사람을 묶어두는 협박자료가 된다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱의 클럽에서는 누구나 원하는 사람이 될 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e다만 아침이 찾아왔을 때, 그 밤을 기억하는 사람이 자신뿐이라고 확신할 수는 없다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기본 정보\u003c/h2\u003e\r\n  \u003ctable class=\"data-table faction-info-table\"\u003e\r\n    \u003ctbody\u003e\r\n      \u003ctr\u003e\u003cth\u003e정식 명칭\u003c/th\u003e\u003ctd\u003eVELVET STATIC\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e통칭\u003c/th\u003e\u003ctd\u003e벨벳 스태틱, 벨벳\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e조직 분류\u003c/th\u003e\u003ctd\u003e유흥·감각·정보 범죄조직\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 사업\u003c/th\u003e\u003ctd\u003e클럽, 호텔, 감각극장, 비밀 살롱\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e불법 사업\u003c/th\u003e\u003ctd\u003e기억편집, 신분세탁, 협박, 기업기밀 거래\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 고객\u003c/th\u003e\u003ctd\u003e기업인, 상류층, 연예인, 용병, 범죄조직\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 활동지역\u003c/th\u003e\u003ctd\u003e돔 시티의 유흥가와 상업구역\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e상징 색상\u003c/th\u003e\u003ctd\u003e적색, 자주색, 청색\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e최고지도자\u003c/th\u003e\u003ctd\u003e호스트\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e최고 집행책임자\u003c/th\u003e\u003ctd\u003e총괄 집행인\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e핵심 자산\u003c/th\u003e\u003ctd\u003e블랙 아카이브\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표적인 인식\u003c/th\u003e\u003ctd\u003e도시의 밤을 지배하는 화려한 범죄기업\u003c/td\u003e\u003c/tr\u003e\r\n    \u003c/tbody\u003e\r\n  \u003c/table\u003e\r\n\r\n  \u003ch2\u003e조직의 역사\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e감각시장의 탄생\u003c/h3\u003e\r\n  \u003cp\u003e벨벳 스태틱의 기원은 돔 시티가 안정되기 시작한 시기에 등장한 불법 클럽과 감각기록 제작자들에게서 찾을 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e폐쇄된 돔에서 살아가는 시민 대부분은 실제 바다와 숲, 자연의 밤을 경험할 수 없었다. 감각기록은 다른 사람이 보았던 풍경과 느꼈던 감정을 대신 체험하게 해주는 상품으로 빠르게 확산되었다.\u003c/p\u003e\r\n  \u003cp\u003e초기의 감각방송은 여행과 공연, 스포츠를 체험하는 오락이었다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 기술이 발전하면서 타인의 쾌감과 공포, 사랑과 죽음까지 재생할 수 있게 되었다. 불법 제작자들은 실제 폭력과 범죄를 기록해 더욱 자극적인 상품으로 판매했다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e벨벳의 밤\u003c/h3\u003e\r\n  \u003cp\u003e소규모 감각제작자와 클럽들은 고객과 업소를 차지하기 위해 서로 충돌했다.\u003c/p\u003e\r\n  \u003cp\u003e거리조직이 유흥가의 보호비와 감각물 유통을 장악하려 하자 클럽 소유자, 기억편집자와 정보브로커들이 공동방어와 거래규칙을 만들었다.\u003c/p\u003e\r\n  \u003cp\u003e이들은 각자의 업소와 기술을 하나의 이름 아래 통합했다.\u003c/p\u003e\r\n  \u003cp\u003e이것이 벨벳 스태틱의 시작이었다.\u003c/p\u003e\r\n  \u003cp\u003e‘벨벳’은 고객에게 제공되는 부드럽고 화려한 쾌락을, ‘스태틱’은 그 아래 숨겨진 신경잡음과 불안정한 기억을 상징한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e기억산업의 확장\u003c/h3\u003e\r\n  \u003cp\u003e벨벳 스태틱은 감각을 재생하는 데서 멈추지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e고통스러운 기억을 흐리게 만들고 특정한 감정반응을 제거하는 서비스를 제공하기 시작했다. 전쟁과 사고의 트라우마를 줄이는 시술로 출발했지만 곧 범죄기억과 배신, 목격자의 증언을 지우는 데 사용되었다.\u003c/p\u003e\r\n  \u003cp\u003e반대로 존재하지 않았던 기억과 감정을 삽입하는 기술도 등장했다.\u003c/p\u003e\r\n  \u003cp\u003e고객은 사랑하지 않았던 사람을 사랑했다고 믿거나, 자신이 저지른 일을 다른 사람의 행동으로 기억할 수 있었다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱은 사람의 신분뿐 아니라 자신이 누구라고 믿는지까지 세탁할 수 있게 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e블랙 아카이브\u003c/h3\u003e\r\n  \u003cp\u003e조직이 성장하면서 고객의 감각기록과 비밀은 별도의 저장소에 보관되었다.\u003c/p\u003e\r\n  \u003cp\u003e처음에는 고객분쟁과 채무를 해결하기 위한 증거였다. 이후 기업간부의 불법거래, 범죄조직의 명령, 유명인의 사생활과 기업기밀까지 축적되면서 저장소 자체가 거대한 권력이 되었다.\u003c/p\u003e\r\n  \u003cp\u003e이것이 블랙 아카이브다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱은 총과 병력보다 블랙 아카이브 덕분에 살아남았다. 조직을 제거하려던 사람들은 자신의 비밀이 여러 기업과 언론, 경쟁자에게 동시에 전송될 수 있다는 경고를 받았다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e현재\u003c/h3\u003e\r\n  \u003cp\u003e현재 벨벳 스태틱은 돔 시티의 유흥산업 깊숙이 자리 잡고 있다.\u003c/p\u003e\r\n  \u003cp\u003e일부 클럽과 호텔은 완전히 합법적인 사업체로 등록되어 일반 시민도 이용한다. 그러나 초대받은 고객은 같은 건물의 숨겨진 층에서 불법 감각시술과 정보거래에 접근할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003eDCS와 아르고스는 벨벳 스태틱을 지속적으로 감시한다.\u003c/p\u003e\r\n  \u003cp\u003e그럼에도 조직을 완전히 제거하지 못한다. 기업과 도시행정부의 고위층까지 벨벳의 고객이며, 조직이 무너지면 블랙 아카이브에 저장된 수많은 기밀이 한꺼번에 공개될 수 있기 때문이다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱은 어두운 골목에 숨지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e돔 시티에서 가장 밝은 네온 아래 공개적으로 영업한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e조직 철학\u003c/h2\u003e\r\n  \u003ch3\u003e욕망에는 선악이 없다\u003c/h3\u003e\r\n  \u003cp\u003e벨벳 스태틱은 고객의 취향과 욕망을 판단하지 않는다고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e돈과 계약을 지불한 사람에게 원하는 경험을 제공할 뿐이다. 그러나 조직의 규칙과 이익을 침해한 고객은 보호받지 못한다.\u003c/p\u003e\r\n  \u003ch3\u003e기억은 소유물이다\u003c/h3\u003e\r\n  \u003cp\u003e자신의 기억을 판매하고 편집할 권리는 개인에게 있다고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e국가와 기업이 기억편집을 금지하는 것이 오히려 개인의 정신에 대한 통제라는 논리다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 편집된 기억을 가진 사람이 정말 자신의 의지로 시술에 동의했는지는 증명하기 어렵다.\u003c/p\u003e\r\n  \u003ch3\u003e비밀은 가장 오래 남는 화폐다\u003c/h3\u003e\r\n  \u003cp\u003e크레딧은 사라지고 계좌는 동결될 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 누군가가 숨기고 싶은 사실은 그 사람이 권력을 가진 동안 계속 가치를 가진다.\u003c/p\u003e\r\n  \u003ch3\u003e밤은 중립지대다\u003c/h3\u003e\r\n  \u003cp\u003e벨벳 스태틱의 정식 업소 안에서는 고객의 소속과 과거를 묻지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e적대기업의 간부와 범죄조직의 수장이 같은 살롱을 이용할 수도 있다. 업소 내부에서의 무력충돌은 벨벳 스태틱 전체에 대한 도전으로 간주된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 사업\u003c/h2\u003e\r\n  \u003ch3\u003e클럽과 감각극장\u003c/h3\u003e\r\n  \u003cp\u003e음악과 조명, 약물과 신경자극을 결합한 유흥공간을 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e일반 영업구역에서는 합법적인 공연과 감각방송이 제공된다. 초대받은 고객은 개인의 신경계와 취향에 맞춘 비공개 프로그램을 이용할 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e감각기록\u003c/h3\u003e\r\n  \u003cp\u003e다른 사람의 시각과 청각, 촉각과 감정을 기록해 상품으로 판매한다.\u003c/p\u003e\r\n  \u003cp\u003e여행과 공연, 연애와 전투기록이 인기 상품이다. 실제 범죄와 고문, 죽음을 기록한 감각물도 암시장에서 거래된다.\u003c/p\u003e\r\n  \u003cp\u003e일부 감각기록은 연출된 작품이지만 무엇이 실제 사건인지 구분하기 어렵다.\u003c/p\u003e\r\n  \u003ch3\u003e기억편집\u003c/h3\u003e\r\n  \u003cp\u003e트라우마와 고통스러운 기억을 약화하거나 특정 감정반응을 제거한다.\u003c/p\u003e\r\n  \u003cp\u003e비공식 시술에서는 목격기억을 지우거나 거짓 기억을 삽입한다. 반복적인 편집은 자아혼선과 기억붕괴를 일으킬 수 있다.\u003c/p\u003e\r\n  \u003ch3\u003e뇌살 시술\u003c/h3\u003e\r\n  \u003cp\u003e신경 인터페이스를 이용해 엔도르핀과 호르몬 분비를 강제로 조절하고 사고와 감각을 가속한다.\u003c/p\u003e\r\n  \u003cp\u003e사용자는 짧은 순간을 실제보다 훨씬 길고 강렬하게 경험한다. 유흥뿐 아니라 공연, 전투와 창작에도 사용되지만 심각한 신경부담과 중독을 유발한다.\u003c/p\u003e\r\n  \u003cp\u003e기술의 일부는 모르포스에서 유출된 신경연구에 기반한 것으로 알려져 있다.\u003c/p\u003e\r\n  \u003ch3\u003e정보거래\u003c/h3\u003e\r\n  \u003cp\u003e고객의 대화와 취향, 거래와 인간관계를 수집해 판매한다.\u003c/p\u003e\r\n  \u003cp\u003e어떤 기업이 무엇을 개발하는지만큼 누가 누구를 두려워하고 욕망하는지도 중요한 정보가 된다.\u003c/p\u003e\r\n  \u003ch3\u003e신분세탁\u003c/h3\u003e\r\n  \u003cp\u003e위조 시민권과 경력, 계좌와 블루넷 신분을 제작한다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스의 유령작업보다 안정성과 완성도는 낮지만 비용이 저렴하고 공식적인 인가를 요구하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱은 신분과 함께 말투, 취향과 개인적인 기억까지 설계해 새로운 인물을 만들어낸다.\u003c/p\u003e\r\n  \u003ch3\u003e비밀 살롱\u003c/h3\u003e\r\n  \u003cp\u003e기업인과 정보브로커, 범죄조직의 간부들이 비공식적으로 만나는 공간이다.\u003c/p\u003e\r\n  \u003cp\u003e살롱에서 이루어진 거래는 벨벳 스태틱이 보증한다. 약속을 어긴 사람은 도시의 모든 벨벳 업소에서 보호를 잃는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e조직 구조\u003c/h2\u003e\r\n  \u003ch3\u003e호스트 — THE HOST\u003c/h3\u003e\r\n  \u003cp\u003e벨벳 스태틱의 최고지도자다.\u003c/p\u003e\r\n  \u003cp\u003e얼굴과 본명이 알려지지 않았으며 공식적인 기록에도 존재하지 않는다. 여러 사람이 상황에 따라 같은 호스트 역할을 수행한다는 설도 있다.\u003c/p\u003e\r\n  \u003cp\u003e호스트의 명령은 개인의 발언이 아니라 조직 전체의 합의처럼 전달된다.\u003c/p\u003e\r\n  \u003cp\u003e대부분의 조직원은 평생 활동해도 호스트를 직접 만나지 못한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e벨벳 코트 — VELVET COURT\u003c/h3\u003e\r\n  \u003cp\u003e클럽 소유자, 기억편집자, 감각제작자와 정보브로커로 구성된 핵심 간부회의다.\u003c/p\u003e\r\n  \u003cp\u003e업소의 운영권과 사업영역, 주요 고객과 기업 간 거래를 조정한다. 각 구성원은 독립적인 사업과 인력을 보유한다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 코트는 공식적으로 총괄 집행인보다 높은 위치에 있지만, 무력과 내부질서에 관한 결정은 총괄 집행인의 판단을 존중한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e총괄 집행인 — CHIEF EXECUTOR\u003c/h3\u003e\r\n  \u003cp\u003e벨벳 스태틱의 물리적 강제력과 내부질서를 책임지는 최고간부다.\u003c/p\u003e\r\n  \u003cp\u003e주요 임무는 다음과 같다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e배신자와 내부범죄자 처벌\u003c/li\u003e\r\n    \u003cli\u003e벨벳 코트와 중요고객 호위\u003c/li\u003e\r\n    \u003cli\u003e채무와 계약 회수\u003c/li\u003e\r\n    \u003cli\u003e경쟁조직 제거\u003c/li\u003e\r\n    \u003cli\u003e기밀시설과 블랙 아카이브 보호\u003c/li\u003e\r\n    \u003cli\u003e간부 사이의 분쟁 중재\u003c/li\u003e\r\n    \u003cli\u003e적대세력에 대한 보복\u003c/li\u003e\r\n    \u003cli\u003e모든 집행조직의 지휘\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e총괄 집행인은 단순한 전투대장이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e호스트와 벨벳 코트 바로 아래에서 조직 전체의 강제력을 지휘하며 필요하다면 간부의 사업과 사병까지 동원할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e현재 총괄 집행인은 \u003cstrong\u003e루카스 샴발\u003c/strong\u003e이다.\u003c/p\u003e\r\n  \u003cp\u003e모르포스 연구원 출신인 그녀는 신경효율과 호르몬을 이용한 사고가속 기술을 연구했다. 벨벳 스태틱에 합류한 뒤 해당 기술을 뇌살 시술과 전투기술로 발전시켰다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 관리조직\u003c/h2\u003e\r\n  \u003ch3\u003e제1관리인 — 유흥·감각\u003c/h3\u003e\r\n  \u003cp\u003e베뉴 운영과 감각상품 제작을 관리한다.\u003c/p\u003e\r\n  \u003cp\u003e클럽, 호텔, 감각극장의 수익과 고객서비스를 책임지며 조직의 합법적인 외형을 유지한다.\u003c/p\u003e\r\n  \u003ch4\u003e업소운영부\u003c/h4\u003e\r\n  \u003cp\u003e클럽, 호텔과 비밀 살롱을 운영한다.\u003c/p\u003e\r\n  \u003cp\u003e직원과 경비, 공연과 고객명단을 관리한다.\u003c/p\u003e\r\n  \u003ch4\u003e감각기록제작부\u003c/h4\u003e\r\n  \u003cp\u003e합법·불법 감각기록을 제작한다.\u003c/p\u003e\r\n  \u003cp\u003e배우와 기록자, 편집자와 신경기술자를 관리한다.\u003c/p\u003e\r\n  \u003ch4\u003e드림캐스트부\u003c/h4\u003e\r\n  \u003cp\u003e고객 개인에게 맞춘 몰입형 감각경험을 설계한다.\u003c/p\u003e\r\n  \u003cp\u003e장기 프로그램은 꿈과 현실의 구분을 흐리게 만들 수 있다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e제2관리인 — 정보·협박\u003c/h3\u003e\r\n  \u003cp\u003e고객정보와 기업기밀, 협박과 거래를 담당한다.\u003c/p\u003e\r\n  \u003ch4\u003e정보거래부\u003c/h4\u003e\r\n  \u003cp\u003e수집된 정보를 분류하고 구매자와 연결한다.\u003c/p\u003e\r\n  \u003cp\u003e하나의 정보를 여러 세력에 조금씩 다르게 판매하기도 한다.\u003c/p\u003e\r\n  \u003ch4\u003e협박집행부\u003c/h4\u003e\r\n  \u003cp\u003e채무자와 배신자, 계약을 어긴 고객을 압박한다.\u003c/p\u003e\r\n  \u003cp\u003e블랙 아카이브의 일부 자료를 공개하거나 가족과 사업관계를 이용한다.\u003c/p\u003e\r\n  \u003ch4\u003e기업인관리부\u003c/h4\u003e\r\n  \u003cp\u003e고위 기업인과 정치인, 주요 고객을 전담한다.\u003c/p\u003e\r\n  \u003cp\u003e고객의 취향과 약점, 경쟁관계와 이용가치를 지속적으로 평가한다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e제3관리인 — 신분·기억\u003c/h3\u003e\r\n  \u003cp\u003e신분세탁과 기억편집, 블루넷 조작을 관리한다.\u003c/p\u003e\r\n  \u003ch4\u003e신분세탁부\u003c/h4\u003e\r\n  \u003cp\u003e위조 시민권과 경력, 계좌와 블루넷 기록을 제작한다.\u003c/p\u003e\r\n  \u003ch4\u003e기억편집부\u003c/h4\u003e\r\n  \u003cp\u003e기억의 제거와 약화, 감정변형과 인공기억 삽입을 담당한다.\u003c/p\u003e\r\n  \u003ch4\u003e블랙 아카이브\u003c/h4\u003e\r\n  \u003cp\u003e감각기록, 협박자료와 기업기밀을 보관한다.\u003c/p\u003e\r\n  \u003cp\u003e조직의 최고등급 자산이므로 제3관리인의 행정 아래 놓여 있지만 실질적인 접근권은 호스트와 벨벳 코트, 총괄 집행인이 나누어 가진다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e총괄 집행인 직속조\u003c/h3\u003e\r\n  \u003cp\u003e루카스 샴발에게 직접 보고하는 정예 집행조직이다.\u003c/p\u003e\r\n  \u003cp\u003e간부 호위와 배신자 처벌, 고위험 채무회수와 블랙 아카이브 방어를 담당한다. 일반적인 관리조직의 명령보다 총괄 집행인의 지시를 우선한다.\u003c/p\u003e\r\n  \u003cp\u003e구성원 대부분은 고성능 사이버웨어와 전투용 신경 인터페이스를 장착한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e블랙 아카이브\u003c/h2\u003e\r\n  \u003cp\u003e블랙 아카이브는 벨벳 스태틱이 보유한 가장 중요한 자산이다.\u003c/p\u003e\r\n  \u003cp\u003e그 안에는 단순한 문서와 영상만 저장되지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e고객이 직접 느낀 감각과 감정, 기억편집 이전의 원본과 시술 중에 드러난 무의식적 반응까지 보관된다. 편집된 뒤 당사자가 잊어버린 사실도 아카이브에는 남는다.\u003c/p\u003e\r\n  \u003cp\u003e자료는 가치와 위험도에 따라 분류된다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e기업간부와 도시행정관의 비밀\u003c/li\u003e\r\n    \u003cli\u003e불법계약과 뇌물기록\u003c/li\u003e\r\n    \u003cli\u003e살인과 고문의 감각기록\u003c/li\u003e\r\n    \u003cli\u003e기업의 비공개 연구자료\u003c/li\u003e\r\n    \u003cli\u003e범죄조직의 거래와 배신\u003c/li\u003e\r\n    \u003cli\u003e아르고스 요원의 위장신분\u003c/li\u003e\r\n    \u003cli\u003e고객의 기억편집 원본\u003c/li\u003e\r\n    \u003cli\u003e블루넷에 존재하지 않는 인물의 신원\u003c/li\u003e\r\n    \u003cli\u003e조직 내부의 처벌과 숙청기록\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e블랙 아카이브의 정확한 위치는 알려지지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e여러 장소에 분산되어 있다는 설과 인간의 기억 속에 암호화되어 있다는 설, 폐쇄된 블루넷 노드에 존재한다는 설이 함께 제기된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e벨벳의 규칙\u003c/h2\u003e\r\n  \u003cp\u003e벨벳 스태틱의 업소와 조직원이 따라야 하는 규칙이다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e정식 업소 안에서는 고객의 소속으로 싸우지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e고객의 비밀은 허가 없이 공개하지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e조직의 기록을 개인적인 복수에 사용하지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e기억편집 전의 원본은 반드시 보존한다.\u003c/li\u003e\r\n    \u003cli\u003e호스트의 이름과 정체를 추적하지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e블랙 아카이브의 위치를 질문하지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e벨벳 코트의 중재를 받은 거래는 지킨다.\u003c/li\u003e\r\n    \u003cli\u003e총괄 집행인의 회수명령을 거부하지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e조직원을 외부기관에 판매한 자는 어떤 업소에서도 보호받지 못한다.\u003c/li\u003e\r\n    \u003cli\u003e벨벳의 밤을 망친 사람에게는 아침이 오지 않는다.\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e벨벳 스태틱은 개인의 욕망에는 관대하지만 조직의 신뢰와 중립성을 훼손한 사람에게는 극도로 잔혹하다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e조직 문화\u003c/h2\u003e\r\n  \u003cp\u003e벨벳 스태틱에서는 외모와 연출, 태도도 능력의 일부로 평가된다.\u003c/p\u003e\r\n  \u003cp\u003e조직원은 단순히 강하거나 똑똑한 것만으로 인정받지 못한다. 사람을 편안하게 만들고 욕망을 읽으며, 필요한 순간에 자신이 원하는 모습을 보여줄 수 있어야 한다.\u003c/p\u003e\r\n  \u003cp\u003e본명보다 콜사인과 활동명이 널리 사용된다.\u003c/p\u003e\r\n  \u003cp\u003e조직원은 자신의 과거를 숨길 수 있지만 벨벳 스태틱에 들어온 뒤의 행동은 모두 기록된다.\u003c/p\u003e\r\n  \u003cp\u003e업소 직원과 감각제작자는 화려하고 자유로운 분위기 속에서 일한다. 그러나 고객정보를 잘못 다루거나 조직의 규칙을 어기면 총괄 집행인의 처벌을 받는다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱 내부에서 널리 사용되는 말은 다음과 같다.\u003c/p\u003e\r\n  \u003cblockquote\u003e우리는 비밀을 지켜준다. 그 비밀이 우리 것이 되는 조건으로.\u003c/blockquote\u003e\r\n\r\n  \u003ch2\u003e대중의 인식\u003c/h2\u003e\r\n  \u003ch3\u003e돔 시티 상류층\u003c/h3\u003e\r\n  \u003cp\u003e고급 유흥과 사교, 비밀거래를 위한 세련된 공간으로 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e공개적으로는 조직과의 관계를 부정하면서도 상당수 기업인과 유명인이 벨벳 업소의 회원권을 보유한다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 시티 일반 시민\u003c/h3\u003e\r\n  \u003cp\u003e화려하고 위험한 밤의 상징으로 인식한다.\u003c/p\u003e\r\n  \u003cp\u003e일반 클럽은 비교적 안전하게 이용할 수 있지만 깊이 들어갈수록 기억과 신분까지 잃을 수 있다는 소문을 알고 있다.\u003c/p\u003e\r\n  \u003ch3\u003e돔 하층민\u003c/h3\u003e\r\n  \u003cp\u003e빠르게 돈을 벌 수 있는 일자리이자 벗어나기 어려운 조직으로 본다.\u003c/p\u003e\r\n  \u003cp\u003e접객과 기록, 경비와 운반업무에 많은 하층민이 고용된다. 고객의 비밀을 너무 많이 알게 된 직원은 자유롭게 퇴사할 수 없다는 이야기가 있다.\u003c/p\u003e\r\n  \u003ch3\u003e기업인\u003c/h3\u003e\r\n  \u003cp\u003e정보와 인맥을 얻을 수 있는 유용한 중립지대로 평가한다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 자신의 모든 행동이 협박자료가 될 가능성을 경계한다.\u003c/p\u003e\r\n  \u003ch3\u003e범죄조직\u003c/h3\u003e\r\n  \u003cp\u003e정보거래와 신분세탁을 위해 협력하지만 벨벳 스태틱이 자신들의 비밀까지 수집한다는 사실을 알고 있다.\u003c/p\u003e\r\n  \u003cp\u003e조직의 클럽과 살롱에서는 함부로 싸움을 일으키지 않는다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e다른 세력과의 관계\u003c/h2\u003e\r\n  \u003ch3\u003eARGOS SECURE NETWORKS\u003c/h3\u003e\r\n  \u003cp\u003e정보와 신분을 다룬다는 점에서 가장 위험한 적이자 경쟁자다.\u003c/p\u003e\r\n  \u003cp\u003e아르고스는 벨벳 스태틱을 조직범죄와 정보위협으로 감시한다. 벨벳 스태틱은 아르고스가 공개적으로 얻을 수 없는 인간적인 욕망과 약점을 수집한다.\u003c/p\u003e\r\n  \u003cp\u003e양측은 서로를 제거하려 하면서도 비공식적으로 정보를 거래한다.\u003c/p\u003e\r\n  \u003ch3\u003eDOME CIVIC SECURITY\u003c/h3\u003e\r\n  \u003cp\u003e클럽, 불법 감각물과 기억편집을 단속한다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 업소의 고객 중에는 DCS 고위간부와 경찰관도 존재한다. 대규모 단속계획이 실행 직전에 유출되거나 취소되는 일이 반복된다.\u003c/p\u003e\r\n  \u003ch3\u003eMORPHOS BIODYNE\u003c/h3\u003e\r\n  \u003cp\u003e벨벳 스태틱의 신경 인터페이스와 뇌살 기술 상당수는 모르포스 계열 기술에서 시작되었다.\u003c/p\u003e\r\n  \u003cp\u003e공식적인 관계는 없지만 유출부품과 이탈한 연구자, 비공개 고객을 통해 계속 연결되어 있다.\u003c/p\u003e\r\n  \u003ch3\u003eLOWLINE\u003c/h3\u003e\r\n  \u003cp\u003e감각물, 위조 신분과 인물을 지하노선을 통해 운반한다.\u003c/p\u003e\r\n  \u003cp\u003e로우라인은 벨벳의 업소로 연결되는 비밀통로와 도피로도 제공한다.\u003c/p\u003e\r\n  \u003ch3\u003eDEAD AIR\u003c/h3\u003e\r\n  \u003cp\u003e블루넷 침투와 정보유출에서 협력하기도 하고 경쟁하기도 한다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱은 정보를 소유하고 판매하려 하지만 데드 에어의 일부 셀은 모든 정보를 공개하려 한다.\u003c/p\u003e\r\n  \u003ch3\u003eSAINT ZERO\u003c/h3\u003e\r\n  \u003cp\u003e불법 신경시술의 부작용과 뇌살 중독자를 치료한다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱은 환자의 기록이 외부로 유출되지 않는 조건으로 세인트 제로에 약품과 자금을 제공한다.\u003c/p\u003e\r\n  \u003ch3\u003eLAZARUS MEDICAL RESPONSE\u003c/h3\u003e\r\n  \u003cp\u003e고급 업소에는 라자루스 회원을 위한 응급의료 연결망이 설치되어 있다.\u003c/p\u003e\r\n  \u003cp\u003e그러나 불법 감각시술과 약물사용 사실을 감추기 위해 라자루스 구조신호를 차단하는 업소도 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003eECLIPSE TACTICAL BUREAU\u003c/h3\u003e\r\n  \u003cp\u003e대규모 신경감염과 기억조작, 통제불능 감각방송이 발생하면 이클립스가 개입한다.\u003c/p\u003e\r\n  \u003cp\u003e특수구금부에는 벨벳 스태틱의 기억편집자와 감각제작자가 수감되어 있다는 소문이 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e논란과 내부 문제\u003c/h2\u003e\r\n  \u003ch3\u003e기억의 동의\u003c/h3\u003e\r\n  \u003cp\u003e고객이 시술에 동의했더라도 편집 후에는 원래 무엇에 동의했는지 기억하지 못할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱은 모든 시술에 기록과 계약이 남는다고 주장하지만 그 기록을 관리하는 것도 조직이다.\u003c/p\u003e\r\n  \u003ch3\u003e감각 중독\u003c/h3\u003e\r\n  \u003cp\u003e강렬한 감각기록과 뇌살에 반복적으로 노출되면 현실의 감각에 만족하지 못하게 된다.\u003c/p\u003e\r\n  \u003cp\u003e중독자는 더 위험하고 자극적인 기록을 찾으며 자신의 기억과 신체를 대가로 지불하기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e불법 감각물\u003c/h3\u003e\r\n  \u003cp\u003e실제 범죄와 고문, 살인을 기록한 상품이 유통된다.\u003c/p\u003e\r\n  \u003cp\u003e조직은 동의 없이 제작된 감각물의 판매를 금지한다고 주장한다. 그러나 블랙 아카이브에는 그러한 기록도 보관된다.\u003c/p\u003e\r\n  \u003ch3\u003e협박과 채무\u003c/h3\u003e\r\n  \u003cp\u003e고객이 비용을 지불하지 못하면 돈보다 정보와 노동을 요구받는다.\u003c/p\u003e\r\n  \u003cp\u003e조직의 채무자가 업소 직원, 정보원이나 감각기록자로 일하게 되는 경우도 있다.\u003c/p\u003e\r\n  \u003ch3\u003e자아붕괴\u003c/h3\u003e\r\n  \u003cp\u003e반복적인 기억편집으로 자신의 과거와 성격을 유지하지 못하는 사람이 발생한다.\u003c/p\u003e\r\n  \u003cp\u003e이들은 서로 모순되는 여러 기억을 가지고 살아가거나 자신이 누구인지 확인하기 위해 계속해서 벨벳 스태틱을 찾아온다.\u003c/p\u003e\r\n  \u003ch3\u003e간부 간 경쟁\u003c/h3\u003e\r\n  \u003cp\u003e벨벳 코트의 간부들은 독립적인 사업과 고객을 보유한다.\u003c/p\u003e\r\n  \u003cp\u003e표면적으로는 협력하지만 정보와 업소, 호스트의 신임을 두고 암투를 벌인다. 총괄 집행인은 이러한 분쟁이 조직 전체를 위협하기 전에 강제로 중재한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e확인되지 않은 소문\u003c/h2\u003e\r\n  \u003cp\u003e호스트는 실존하는 한 사람이 아니라는 소문이 가장 널리 알려져 있다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 코트의 여러 간부가 같은 목소리와 기억, 행동방식을 공유하며 필요할 때 호스트의 역할을 수행한다는 것이다.\u003c/p\u003e\r\n  \u003cp\u003e일부에서는 역대 호스트의 기억이 특정한 신경매체에 저장되어 후계자에게 이식된다고 주장한다. 그렇다면 현재의 호스트는 개인이 아니라 수백 년 동안 이어진 여러 사람의 기억집합에 가깝다.\u003c/p\u003e\r\n  \u003cp\u003e블랙 아카이브가 독립된 인공지능이라는 이야기도 있다.\u003c/p\u003e\r\n  \u003cp\u003e아카이브는 저장된 기억과 감정을 분석해 조직을 위협할 사람을 예측하고, 호스트의 이름으로 명령을 내린다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e또 다른 소문에 따르면 벨벳 스태틱의 최고급 살롱에서는 백야 이전의 완전한 감각기록을 체험할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e실제 태양과 바다, 비와 바람을 느낄 수 있지만 기록을 경험한 사람은 돔의 인공하늘과 현실을 견디지 못하게 된다.\u003c/p\u003e\r\n  \u003cp\u003e가장 위험한 소문은 \u003cstrong\u003e라스트 나이트\u003c/strong\u003e라 불리는 감각기록에 관한 것이다.\u003c/p\u003e\r\n  \u003cp\u003e그 기록에는 2102년 백야가 시작되는 순간을 직접 바라본 사람의 감각과 기억이 담겨 있다고 한다. 재생한 사람은 백야의 원인을 이해할 수 있지만, 마지막까지 정상적인 정신을 유지한 사람은 없다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱은 라스트 나이트의 존재를 부정한다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 블랙 아카이브의 가장 깊은 구역에는 재생할 수 없는 기록 하나가 보관되어 있다고 알려져 있다.\u003c/p\u003e\r\n  \u003cp\u003e그 기록은 지금도 조금씩 길어지고 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e조직이 가진 힘\u003c/h2\u003e\r\n  \u003cp\u003e벨벳 스태틱의 힘은 거리의 숫자나 총기의 수에서 나오지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 사람들이 남에게 보여주지 않는 모습을 알고 있다.\u003c/p\u003e\r\n  \u003cp\u003e기업의 간부도 밤이 되면 누군가를 사랑하고, 두려워하며, 잊고 싶은 일을 만든다. 법을 집행하는 경찰도 쾌락과 비밀을 원하고, 범죄조직의 수장도 자신의 부하에게 들키고 싶지 않은 약점을 가진다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱은 그 순간을 기다린다.\u003c/p\u003e\r\n  \u003cp\u003e사람이 스스로 문을 열고 들어와 신경을 연결하고, 자신의 가장 은밀한 기억을 조직의 장치에 맡기도록 만든다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 총으로 사람을 위협하고 아르고스는 감시망으로 비밀을 찾아낸다.\u003c/p\u003e\r\n  \u003cp\u003e벨벳 스태틱은 다르다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 상대가 기꺼이 자신의 비밀을 내어놓게 만든다.\u003c/p\u003e\r\n  \u003cp\u003e그리고 그 비밀을 사용할 필요가 없는 동안에는 세상에서 가장 완벽한 친구처럼 행동한다.\u003c/p\u003e\r\n\u003c/section\u003e\r\n";
window.FACTION_INFO.sundogs = "\u003csection class=\"faction-detail\"\u003e\r\n  \u003ch2\u003e조직 개요\u003c/h2\u003e\r\n  \u003cp class=\"faction-quote\"\u003e“도로는 소유하는 게 아니다. 끝까지 달리는 놈이 차지하는 거다.”\u003c/p\u003e\r\n  \u003cp\u003e선독스는 황무지의 차량 갱단들이 생존과 전쟁, 노선과 전리품 분배를 위해 결성한 느슨한 연합이다. 하나의 수장 아래 움직이는 단일 갱단이 아니며, 서로 다른 문화와 차량, 영역을 가진 수십 개의 ‘팩’으로 구성된다.\u003c/p\u003e\r\n  \u003cp\u003e각 팩은 평소에는 독자적으로 활동한다. 카라반을 습격하고 폐허에서 차량과 부품을 회수하며, 황무지 정착지에 호위와 운송을 판매한다. 필요하다면 다른 선독스 팩과도 싸운다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 카론의 노선봉쇄나 케르베로스의 토벌대처럼 연합 전체를 위협하는 적이 나타나면 대집회가 열린다. 이때 가장 많은 차량과 전사를 동원할 수 있는 팩 캡틴이 로드 알파로 선출되어 선독스의 전쟁을 지휘한다.\u003c/p\u003e\r\n  \u003cp\u003e도시 사람들은 선독스를 난폭한 약탈자로 생각한다.\u003c/p\u003e\r\n  \u003cp\u003e그 평가는 절반쯤 맞다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 황무지에는 카론의 정식 노선이 닿지 않는 땅과 어떤 기업도 지켜주지 않는 사람들이 존재한다. 그곳에서는 선독스의 깃발을 단 차량이 약탈자인 동시에 우편배달부, 길잡이, 용병과 구조대가 된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e기본 정보\u003c/h2\u003e\r\n  \u003ctable class=\"data-table faction-info-table\"\u003e\r\n    \u003ctbody\u003e\r\n      \u003ctr\u003e\u003cth\u003e정식 명칭\u003c/th\u003e\u003ctd\u003eSUNDOGS\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e통칭\u003c/th\u003e\u003ctd\u003e선독스, 태양개\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e조직 분류\u003c/th\u003e\u003ctd\u003e황무지 차량 갱단 연합\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 활동\u003c/th\u003e\u003ctd\u003e약탈, 호위, 운송, 밀수, 차량회수\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e활동지역\u003c/th\u003e\u003ctd\u003e황무지, 폐쇄도로, 카라반 노선\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e기본 단위\u003c/th\u003e\u003ctd\u003e팩\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e최고회의\u003c/th\u003e\u003ctd\u003e대집회\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e전시 지도자\u003c/th\u003e\u003ctd\u003e로드 알파\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e지역 지도자\u003c/th\u003e\u003ctd\u003e팩 캡틴\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e주요 구성원\u003c/th\u003e\u003ctd\u003e라이더, 거너, 스니퍼, 본야드, 그리스핸드, 펍\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e상징 색상\u003c/th\u003e\u003ctd\u003e적색, 주황색, 흑색\u003c/td\u003e\u003c/tr\u003e\r\n      \u003ctr\u003e\u003cth\u003e대표적인 인식\u003c/th\u003e\u003ctd\u003e황무지를 질주하는 약탈자이자 자유로운 운전사\u003c/td\u003e\u003c/tr\u003e\r\n    \u003c/tbody\u003e\r\n  \u003c/table\u003e\r\n\r\n  \u003ch2\u003e조직의 역사\u003c/h2\u003e\r\n\r\n  \u003ch3\u003e백야 이후의 도로\u003c/h3\u003e\r\n  \u003cp\u003e2102년 백야가 발생하자 대륙의 도로와 물류망은 붕괴했다.\u003c/p\u003e\r\n  \u003cp\u003e도시는 고립되었고, 도로 위에는 멈춰 선 차량과 화물트럭, 군용 수송대가 끝없이 남겨졌다. 살아남은 사람들은 차량을 수리해 물과 식량, 연료를 찾아 이동했다.\u003c/p\u003e\r\n  \u003cp\u003e황무지에서 차량은 이동수단 이상의 의미를 가졌다.\u003c/p\u003e\r\n  \u003cp\u003e뜨거운 지표와 모래폭풍을 피할 수 있는 피난처였고 물과 연료, 가족과 재산을 함께 운반하는 집이었다. 차량을 잃는다는 것은 생존할 수단을 잃는다는 뜻이었다.\u003c/p\u003e\r\n  \u003cp\u003e초기의 차량집단은 가족과 동료를 중심으로 형성되었다.\u003c/p\u003e\r\n  \u003cp\u003e이들이 선독스 팩의 기원이 되었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e도로전쟁\u003c/h3\u003e\r\n  \u003cp\u003e물과 연료, 차량부품이 부족해지면서 팩들은 서로의 수송대를 습격하기 시작했다.\u003c/p\u003e\r\n  \u003cp\u003e강한 팩은 약한 팩의 차량과 사람을 흡수했고, 일부는 정착지를 지배하는 대규모 차량군으로 성장했다.\u003c/p\u003e\r\n  \u003cp\u003e하지만 전쟁이 계속되면서 모두가 손해를 보았다. 숙련된 운전사와 정비사가 죽고 재생할 수 없는 차량과 부품이 파괴되었다.\u003c/p\u003e\r\n  \u003cp\u003e팩 캡틴들은 중립지대에서 만나 최소한의 규칙을 만들었다.\u003c/p\u003e\r\n  \u003cp\u003e이 회의가 대집회의 시작이었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e선독스 연합\u003c/h3\u003e\r\n  \u003cp\u003e카론이 정식 노선을 확장하고 케르베로스와 도시세력이 황무지의 도로를 장악하기 시작하자 차량 갱단들은 공동의 위협을 느꼈다.\u003c/p\u003e\r\n  \u003cp\u003e개별 팩은 기업의 군대와 장갑열차를 상대할 수 없었다.\u003c/p\u003e\r\n  \u003cp\u003e여러 팩은 전쟁이 벌어지는 동안 하나의 지도자 아래에서 움직이기로 합의했다. 가장 강한 차량단의 캡틴이 임시로 로드 알파가 되어 공동작전을 지휘했다.\u003c/p\u003e\r\n  \u003cp\u003e전쟁이 끝나면 로드 알파의 권한은 사라졌다.\u003c/p\u003e\r\n  \u003cp\u003e이 원칙 덕분에 선독스는 하나의 거대조직으로 흡수되지 않으면서도 외부세력에 맞서 살아남을 수 있었다.\u003c/p\u003e\r\n\r\n  \u003ch3\u003e현재\u003c/h3\u003e\r\n  \u003cp\u003e현재 선독스의 정확한 팩 숫자는 알려져 있지 않다.\u003c/p\u003e\r\n  \u003cp\u003e수십 대의 전투차량을 보유한 대형 팩도 있고, 낡은 차량 서너 대로 움직이는 가족 단위 팩도 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e새로운 팩이 매년 태어나고 사라진다. 패배한 팩의 생존자는 다른 팩에 들어가며, 독립을 원하는 라이더는 차량과 동료를 모아 새로운 깃발을 세운다.\u003c/p\u003e\r\n  \u003cp\u003e선독스는 통일된 국가도 기업도 아니다.\u003c/p\u003e\r\n  \u003cp\u003e그럼에도 황무지의 어느 도로에서든 붉은 태양과 사냥개의 표식을 발견할 수 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e조직 철학\u003c/h2\u003e\r\n  \u003ch3\u003e멈추면 죽는다\u003c/h3\u003e\r\n  \u003cp\u003e선독스는 정착보다 이동을 생존의 기본으로 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e하나의 수원과 도시, 기업계약에 의존하면 결국 누군가에게 통제당한다고 생각한다.\u003c/p\u003e\r\n  \u003ch3\u003e차량은 가족이다\u003c/h3\u003e\r\n  \u003cp\u003e선독스에게 차량은 단순한 소유물이 아니다.\u003c/p\u003e\r\n  \u003cp\u003e한 팩의 역사와 이름, 생존이 차량과 함께 이어진다. 오래된 차량은 수백 년 동안 부품을 교체하며 같은 이름으로 계승되기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003e도로 위에서는 스스로를 지킨다\u003c/h3\u003e\r\n  \u003cp\u003e황무지에서 기업의 법과 경찰은 사람을 보호하지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e자신의 차량과 무기, 팩의 동료만이 안전을 보장한다고 믿는다.\u003c/p\u003e\r\n  \u003ch3\u003e전리품은 기여에 따라 나눈다\u003c/h3\u003e\r\n  \u003cp\u003e약탈과 회수작전에서 얻은 물자는 차량, 탄약과 부상자 치료비를 먼저 제외한 뒤 공적에 따라 분배한다.\u003c/p\u003e\r\n  \u003cp\u003e전리품을 숨긴 사람은 팩 전체를 배신한 것으로 취급된다.\u003c/p\u003e\r\n  \u003ch3\u003e로드 알파는 왕이 아니다\u003c/h3\u003e\r\n  \u003cp\u003e로드 알파는 전쟁을 지휘하기 위해 선출되는 임시 지도자다.\u003c/p\u003e\r\n  \u003cp\u003e전쟁이 끝난 뒤에도 권력을 유지하려는 로드 알파는 모든 팩의 적이 된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e조직 구조\u003c/h2\u003e\r\n  \u003ch3\u003e대집회 — GRAND MEET\u003c/h3\u003e\r\n  \u003cp\u003e각 팩의 대표가 모여 전쟁과 노선, 전리품과 연합규칙을 결정하는 최고회의다.\u003c/p\u003e\r\n  \u003cp\u003e정기적으로 열리지 않으며 여러 팩이 필요성을 인정할 때 소집된다. 정확한 장소는 직전까지 공개되지 않는다.\u003c/p\u003e\r\n  \u003cp\u003e집회 중에는 오래된 원한과 분쟁을 이유로 무기를 사용하는 것이 금지된다.\u003c/p\u003e\r\n  \u003ch3\u003e로드 알파 — ROAD ALPHA\u003c/h3\u003e\r\n  \u003cp\u003e전시 또는 대규모 공동작전에서 선출되는 연합 지도자다.\u003c/p\u003e\r\n  \u003cp\u003e절대적인 군주가 아니라 가장 많은 차량과 전사를 동원하고 다른 캡틴들을 설득할 수 있는 사람이다.\u003c/p\u003e\r\n  \u003cp\u003e명령을 따르지 않는 팩을 강제로 처벌할 권한은 제한적이다. 전리품과 작전의 성공으로 충성을 유지해야 한다.\u003c/p\u003e\r\n  \u003ch3\u003e팩 캡틴 — PACK CAPTAIN\u003c/h3\u003e\r\n  \u003cp\u003e각 차량 갱단을 이끄는 우두머리다.\u003c/p\u003e\r\n  \u003cp\u003e운전과 전투능력뿐 아니라 연료, 물과 부품을 확보하고 구성원의 충성을 유지할 능력이 필요하다.\u003c/p\u003e\r\n  \u003cp\u003e캡틴은 결투, 합의, 혈통이나 쿠데타 등 팩마다 다른 방식으로 정해진다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 구성원\u003c/h2\u003e\r\n  \u003ch3\u003e라이더 — RIDER\u003c/h3\u003e\r\n  \u003cp\u003e전투차량과 정찰차량을 운전한다.\u003c/p\u003e\r\n  \u003cp\u003e황무지의 지형과 모래, 바람과 차량의 상태를 읽는 능력이 요구된다. 선독스 문화에서 가장 명예로운 역할 가운데 하나다.\u003c/p\u003e\r\n  \u003ch3\u003e거너 — GUNNER\u003c/h3\u003e\r\n  \u003cp\u003e차량에 장착된 기관총과 기관포, 로켓과 즉석병기를 운용한다.\u003c/p\u003e\r\n  \u003cp\u003e운전자의 움직임을 예측하고 고속주행 중에도 정확히 사격해야 한다.\u003c/p\u003e\r\n  \u003ch3\u003e스니퍼 — SNIFFER\u003c/h3\u003e\r\n  \u003cp\u003e노선탐색과 추적, 정찰을 담당한다.\u003c/p\u003e\r\n  \u003cp\u003e차량의 흔적과 연기, 모래의 움직임으로 수송대의 규모와 이동방향을 파악한다. 날씨와 일소의 징후도 읽는다.\u003c/p\u003e\r\n  \u003ch3\u003e본야드 — BONEYARD\u003c/h3\u003e\r\n  \u003cp\u003e파괴된 차량과 기계를 해체한다.\u003c/p\u003e\r\n  \u003cp\u003e사용 가능한 엔진과 장갑, 전력셀과 사이버웨어를 회수한다. 전리품의 가치를 판정하는 역할도 맡는다.\u003c/p\u003e\r\n  \u003ch3\u003e그리스핸드 — GREASEHAND\u003c/h3\u003e\r\n  \u003cp\u003e차량을 수리하고 개조하는 정비사다.\u003c/p\u003e\r\n  \u003cp\u003e팩의 생존을 책임지기 때문에 캡틴도 함부로 대하지 못한다. 뛰어난 그리스핸드를 납치하거나 영입하기 위한 싸움도 벌어진다.\u003c/p\u003e\r\n  \u003ch3\u003e펍 — PUP\u003c/h3\u003e\r\n  \u003cp\u003e아직 정식 역할을 인정받지 못한 신입 조직원이다.\u003c/p\u003e\r\n  \u003cp\u003e청소와 탄약운반, 감시와 보조정비를 맡는다. 자신의 차량이나 전문역할을 얻으면 정식 구성원으로 인정된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e차량 편성\u003c/h2\u003e\r\n  \u003ch3\u003e선두차\u003c/h3\u003e\r\n  \u003cp\u003e노선의 위험을 탐지하고 수송대의 이동경로를 결정한다.\u003c/p\u003e\r\n  \u003cp\u003e빠른 속도와 센서, 통신장비를 갖춘 차량이 사용된다.\u003c/p\u003e\r\n  \u003ch3\u003e사냥차\u003c/h3\u003e\r\n  \u003cp\u003e적을 추격하고 수송대를 공격하는 전투차량이다.\u003c/p\u003e\r\n  \u003cp\u003e속도와 화력을 중시하며 선독스의 대표적인 차량문화를 보여준다.\u003c/p\u003e\r\n  \u003ch3\u003e회수차\u003c/h3\u003e\r\n  \u003cp\u003e전리품과 파손된 차량, 부상자를 수거한다.\u003c/p\u003e\r\n  \u003cp\u003e견인장치와 절단기, 대형 화물공간을 갖춘다.\u003c/p\u003e\r\n  \u003ch3\u003e정비차\u003c/h3\u003e\r\n  \u003cp\u003e부품과 연료, 공구를 운반하는 이동식 정비소다.\u003c/p\u003e\r\n  \u003cp\u003e전투력은 낮지만 정비차를 잃은 팩은 장거리 작전을 지속하기 어렵다.\u003c/p\u003e\r\n  \u003ch3\u003e캡틴 차량\u003c/h3\u003e\r\n  \u003cp\u003e팩 캡틴의 지휘차량이자 팩의 상징이다.\u003c/p\u003e\r\n  \u003cp\u003e가장 강한 장갑과 통신장비를 갖추며, 이전 캡틴들의 부품과 장식을 계승하는 경우가 많다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e주요 활동\u003c/h2\u003e\r\n  \u003ch3\u003e카라반 습격\u003c/h3\u003e\r\n  \u003cp\u003e물과 연료, 의약품과 부품을 확보하기 위해 수송대를 공격한다.\u003c/p\u003e\r\n  \u003cp\u003e모든 팩이 무차별 약탈을 하는 것은 아니다. 계약이나 보호표식을 확인하고 특정 기업 또는 적대세력의 화물만 노리는 팩도 있다.\u003c/p\u003e\r\n  \u003ch3\u003e황무지 호위\u003c/h3\u003e\r\n  \u003cp\u003e위험한 노선을 통과하려는 카라반과 상인에게 호위를 제공한다.\u003c/p\u003e\r\n  \u003cp\u003e선독스의 공격을 막기 위해 다른 선독스 팩을 고용하는 일도 흔하다. 연합의 공식 계약이 있다면 다른 팩은 해당 수송대를 공격하지 않는 것이 원칙이다.\u003c/p\u003e\r\n  \u003ch3\u003e차량회수\u003c/h3\u003e\r\n  \u003cp\u003e전장과 폐허에 남은 차량, 추락한 항공기와 기계를 해체한다.\u003c/p\u003e\r\n  \u003cp\u003e본야드와 그리스핸드는 고철더미에서 얻은 부품으로 기존 차량을 수리하거나 새로운 전투차량을 제작한다.\u003c/p\u003e\r\n  \u003ch3\u003e밀수운송\u003c/h3\u003e\r\n  \u003cp\u003e카론의 검문과 기업노선을 피해 무기, 약품과 불법 사이버웨어를 운반한다.\u003c/p\u003e\r\n  \u003cp\u003e정식 기록을 남기지 않으며 목적지까지의 안전보다 추적을 피하는 데 집중한다.\u003c/p\u003e\r\n  \u003ch3\u003e노선정보 판매\u003c/h3\u003e\r\n  \u003cp\u003e황무지의 날씨, 위험지역과 수송대 이동정보를 판매한다.\u003c/p\u003e\r\n  \u003cp\u003e스니퍼가 확보한 최신 정보는 카론의 공식 지도보다 정확한 경우도 있다.\u003c/p\u003e\r\n  \u003ch3\u003e사냥\u003c/h3\u003e\r\n  \u003cp\u003e대형 변이생물과 위험한 황무지 생물을 추적한다.\u003c/p\u003e\r\n  \u003cp\u003e식량과 가죽, 생체소재를 얻고 안전한 노선을 확보하기 위한 활동이다.\u003c/p\u003e\r\n  \u003ch3\u003e경주와 결투\u003c/h3\u003e\r\n  \u003cp\u003e팩 사이의 분쟁을 전면전 대신 차량경주와 결투로 해결한다.\u003c/p\u003e\r\n  \u003cp\u003e위험한 지형을 통과하거나 상대 차량을 먼저 무력화한 쪽이 승리한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e선독스의 규칙\u003c/h2\u003e\r\n  \u003cp\u003e모든 팩이 동일한 규율을 따르지는 않지만 대집회가 인정한 공통규칙이 존재한다.\u003c/p\u003e\r\n  \u003cul\u003e\r\n    \u003cli\u003e대집회에서는 무기를 사용하지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e전쟁이 끝나면 로드 알파의 권한도 끝난다.\u003c/li\u003e\r\n    \u003cli\u003e팩의 차량과 연료를 몰래 훔치지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e정식 호위계약을 받은 카라반은 공격하지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e고장 난 차량에서 아이와 그리스핸드를 죽이지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e구조에 응한 상대에게 즉시 총을 겨누지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e전리품은 작전이 끝난 뒤 공개적으로 분배한다.\u003c/li\u003e\r\n    \u003cli\u003e팩의 위치와 수원을 기업에 판매한 자는 추방한다.\u003c/li\u003e\r\n    \u003cli\u003e다른 사람의 캡틴 차량을 허가 없이 운전하지 않는다.\u003c/li\u003e\r\n    \u003cli\u003e도로 위에서 죽은 자의 이름은 차량에 남긴다.\u003c/li\u003e\r\n  \u003c/ul\u003e\r\n  \u003cp\u003e규칙을 어긴 팩은 대집회에서 추방될 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e추방된 팩은 다른 선독스의 보호와 거래, 구조를 받을 수 없다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e조직 문화\u003c/h2\u003e\r\n  \u003cp\u003e선독스는 사람의 출신과 시민권보다 운전과 전투, 정비능력을 중요하게 여긴다.\u003c/p\u003e\r\n  \u003cp\u003e돔의 기업인이든 장막 도시의 비등록자든 자신의 가치를 증명하면 팩에 받아들여질 수 있다. 반대로 캡틴의 자식이라도 무능하면 중요한 역할을 맡을 수 없다.\u003c/p\u003e\r\n  \u003cp\u003e대부분의 구성원은 차량에 이름을 붙이고 인격을 가진 존재처럼 대한다.\u003c/p\u003e\r\n  \u003cp\u003e죽은 동료의 장비와 차량부품은 버려지지 않는다. 살아남은 차량에 이식되어 팩의 역사와 함께 달린다.\u003c/p\u003e\r\n  \u003cp\u003e복장과 차량도 팩마다 크게 다르다. 붉은 천과 태양문양을 사용하는 팩이 많지만 통일된 제복은 없다.\u003c/p\u003e\r\n  \u003cp\u003e음악과 엔진음, 차량경주는 선독스 문화의 핵심이다. 대집회가 열리면 거래와 회의뿐 아니라 대규모 경주와 공연, 차량개조 경쟁도 함께 진행된다.\u003c/p\u003e\r\n  \u003cp\u003e선독스 사이에서 널리 사용되는 말은 다음과 같다.\u003c/p\u003e\r\n  \u003cblockquote\u003e사람은 죽어도 부품은 달린다. 이름은 엔진에 남는다.\u003c/blockquote\u003e\r\n\r\n  \u003ch2\u003e대중의 인식\u003c/h2\u003e\r\n  \u003ch3\u003e돔 시티 시민\u003c/h3\u003e\r\n  \u003cp\u003e무장차량으로 카라반을 습격하는 야만적인 약탈자라고 생각한다.\u003c/p\u003e\r\n  \u003cp\u003e대부분 직접 선독스를 본 적은 없으며 기업방송과 범죄기록을 통해서만 접한다.\u003c/p\u003e\r\n  \u003ch3\u003e장막 도시 주민\u003c/h3\u003e\r\n  \u003cp\u003e지역에 따라 평가가 크게 다르다.\u003c/p\u003e\r\n  \u003cp\u003e약탈을 당한 도시는 선독스를 증오하지만 기업의 물류망이 닿지 않는 지역에서는 물자와 소식을 가져오는 중요한 거래상대로 여긴다.\u003c/p\u003e\r\n  \u003ch3\u003e황무지인\u003c/h3\u003e\r\n  \u003cp\u003e위험하고 변덕스럽지만 황무지의 규칙을 아는 세력으로 인정한다.\u003c/p\u003e\r\n  \u003cp\u003e기업군보다 거래조건이 단순하고 계약을 지키는 팩도 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003e카라반\u003c/h3\u003e\r\n  \u003cp\u003e가장 흔한 위협이자 때로는 가장 유용한 호위자다.\u003c/p\u003e\r\n  \u003cp\u003e노련한 카라반은 주변 팩의 표식과 규칙, 현재 캡틴의 성향을 반드시 확인한다.\u003c/p\u003e\r\n  \u003ch3\u003e기업\u003c/h3\u003e\r\n  \u003cp\u003e물류와 시설을 위협하는 차량범죄집단으로 규정한다.\u003c/p\u003e\r\n  \u003cp\u003e동시에 공식 노선이 없는 지역의 정보와 운송을 위해 비공식적으로 선독스를 고용하기도 한다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e다른 세력과의 관계\u003c/h2\u003e\r\n  \u003ch3\u003eCHARON INTERCONTINENTAL\u003c/h3\u003e\r\n  \u003cp\u003e가장 대표적인 경쟁자이자 적대세력이다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 황무지의 노선을 등록하고 통행료를 부과한다. 선독스는 도로를 기업이 소유할 수 없다고 주장한다.\u003c/p\u003e\r\n  \u003cp\u003e카론의 수송대 습격과 노선봉쇄를 둘러싼 충돌이 반복된다. 일부 팩은 카론의 비공식 호위와 위험지역 정찰을 맡기도 한다.\u003c/p\u003e\r\n  \u003ch3\u003eCERBERUS DEFENSE GROUP\u003c/h3\u003e\r\n  \u003cp\u003e선독스 차량에 장착된 무기 상당수가 케르베로스 제품이거나 그 복제품이다.\u003c/p\u003e\r\n  \u003cp\u003e케르베로스는 불법 병기회수와 황무지 토벌을 위해 선독스를 공격하지만, 경쟁기업의 수송대를 습격하도록 특정 팩에 무기를 판매한다는 의혹도 있다.\u003c/p\u003e\r\n  \u003ch3\u003eBLACKTOP UNION\u003c/h3\u003e\r\n  \u003cp\u003e독립 운전사와 정비사를 기반으로 한다는 점에서 유사하지만 조직철학은 다르다.\u003c/p\u003e\r\n  \u003cp\u003e블랙탑은 노선의 권리와 노동계약을 중시하고 선독스는 팩의 자유와 힘을 우선한다. 협력과 충돌이 모두 빈번하다.\u003c/p\u003e\r\n  \u003ch3\u003eIRON LANTERN CARAVAN\u003c/h3\u003e\r\n  \u003cp\u003e아이언 랜턴은 물자와 교역정보를 가진 유용한 거래상대다.\u003c/p\u003e\r\n  \u003cp\u003e일부 팩은 상단의 정식 호위계약을 받아 움직인다. 다른 팩은 풍부한 화물을 노리지만 아이언 랜턴이 여러 노선과 팩에 쌓은 신용 때문에 함부로 공격하지 못한다.\u003c/p\u003e\r\n  \u003ch3\u003eLOWLINE\u003c/h3\u003e\r\n  \u003cp\u003e도난차량의 부품, 무기와 밀수품을 거래한다.\u003c/p\u003e\r\n  \u003cp\u003e선독스가 황무지에서 화물을 가져오면 로우라인이 돔 내부로 운반한다.\u003c/p\u003e\r\n  \u003ch3\u003eSAINT ZERO\u003c/h3\u003e\r\n  \u003cp\u003e부상자 치료와 불법 사이버웨어 시술을 위해 협력한다.\u003c/p\u003e\r\n  \u003cp\u003e선독스는 의약품과 장기를 운송하며 세인트 제로는 그리스핸드가 고칠 수 없는 신체를 수리한다.\u003c/p\u003e\r\n  \u003ch3\u003eLAZARUS MEDICAL RESPONSE\u003c/h3\u003e\r\n  \u003cp\u003e라자루스 구조차량을 공격하는 것은 대부분의 팩에서 금기로 여겨진다.\u003c/p\u003e\r\n  \u003cp\u003e황무지에서는 선독스가 실종된 라자루스 팀을 구조하거나 안전지역까지 안내하기도 한다. 반대로 회원회수를 방해한 팩은 라자루스와 케르베로스 양측의 추적대상이 된다.\u003c/p\u003e\r\n  \u003ch3\u003eDOME CIVIC SECURITY\u003c/h3\u003e\r\n  \u003cp\u003e돔 외곽에서 차량밀수와 불법무기를 단속한다.\u003c/p\u003e\r\n  \u003cp\u003eDCS의 정식 관할이 황무지까지 이어지지 않아 대규모 작전은 다른 기업의 지원이 필요하다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e논란과 내부 문제\u003c/h2\u003e\r\n  \u003ch3\u003e무차별 약탈\u003c/h3\u003e\r\n  \u003cp\u003e모든 팩이 연합의 규칙을 지키지는 않는다.\u003c/p\u003e\r\n  \u003cp\u003e물자뿐 아니라 사람을 납치하고 정착지를 파괴하는 폭력적인 팩도 존재한다. 선독스 전체가 이들의 행동으로 비난받는다.\u003c/p\u003e\r\n  \u003ch3\u003e팩 간 전쟁\u003c/h3\u003e\r\n  \u003cp\u003e전리품과 수원, 노선을 두고 팩끼리 충돌한다.\u003c/p\u003e\r\n  \u003cp\u003e대집회는 전면전을 막으려 하지만 외곽의 소규모 싸움까지 통제하지 못한다.\u003c/p\u003e\r\n  \u003ch3\u003e강제 편입\u003c/h3\u003e\r\n  \u003cp\u003e패배한 차량단의 생존자에게 선독스 가입을 강요하는 팩이 있다.\u003c/p\u003e\r\n  \u003cp\u003e조직은 선택권을 주는 전통이 있다고 주장하지만 차량과 물을 잃은 사람에게 실질적인 선택은 많지 않다.\u003c/p\u003e\r\n  \u003ch3\u003e차량 숭배\u003c/h3\u003e\r\n  \u003cp\u003e일부 팩은 차량과 엔진을 신성하게 여기며 지나친 의식과 규율을 적용한다.\u003c/p\u003e\r\n  \u003cp\u003e사람보다 차량을 먼저 구조하거나 부상자를 버리고 엔진을 회수하는 사례도 존재한다.\u003c/p\u003e\r\n  \u003ch3\u003e로드 알파의 권력\u003c/h3\u003e\r\n  \u003cp\u003e전쟁이 끝난 뒤에도 권한을 포기하지 않으려는 로드 알파가 주기적으로 등장한다.\u003c/p\u003e\r\n  \u003cp\u003e이 경우 연합은 외부의 적보다 내부의 독재자를 상대로 더 큰 전쟁을 치르게 된다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e확인되지 않은 소문\u003c/h2\u003e\r\n  \u003cp\u003e황무지 어딘가에는 최초의 선독스 차량이 아직 달리고 있다는 이야기가 있다.\u003c/p\u003e\r\n  \u003cp\u003e2102년 백야 당시 대피민을 태우고 도시를 빠져나왔던 거대한 육상차량으로, 700년 동안 엔진을 멈춘 적이 없다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e차량의 이름은 팩마다 다르게 전해진다.\u003c/p\u003e\r\n  \u003cp\u003e어떤 이들은 그것을 \u003cstrong\u003e퍼스트 하운드\u003c/strong\u003e라고 부르고, 다른 이들은 \u003cstrong\u003e올드 선\u003c/strong\u003e 또는 \u003cstrong\u003e레드 모닝\u003c/strong\u003e이라고 부른다.\u003c/p\u003e\r\n  \u003cp\u003e퍼스트 하운드를 발견한 캡틴은 모든 선독스 팩을 통합할 자격을 얻는다는 전승도 존재한다.\u003c/p\u003e\r\n  \u003cp\u003e또 다른 소문에 따르면 선독스의 대집회에는 인간 팩 캡틴이 아닌 차량 한 대가 참석한다.\u003c/p\u003e\r\n  \u003cp\u003e자율 인공지능을 탑재한 백야 이전의 군용차량이며, 수백 년 동안 여러 팩을 옮겨 다니며 황무지의 모든 노선을 기록했다고 한다.\u003c/p\u003e\r\n  \u003cp\u003e가장 위험한 소문은 현재 선출되지 않은 로드 알파가 이미 존재한다는 것이다.\u003c/p\u003e\r\n  \u003cp\u003e여러 대형 팩이 비밀리에 하나의 캡틴에게 충성을 맹세했고, 수백 대의 차량과 전사를 황무지의 특정 지역에 집결시키고 있다는 이야기다.\u003c/p\u003e\r\n  \u003cp\u003e그들의 목표가 카론의 중앙노선인지, 케르베로스의 병기공장인지, 돔 시티의 외벽인지는 알려지지 않았다.\u003c/p\u003e\r\n  \u003cp\u003e황무지에서는 최근 같은 방향으로 이동하는 붉은 차량행렬이 목격되고 있다.\u003c/p\u003e\r\n\r\n  \u003ch2\u003e조직이 가진 힘\u003c/h2\u003e\r\n  \u003cp\u003e선독스의 힘은 차량의 수나 화력만으로 설명할 수 없다.\u003c/p\u003e\r\n  \u003cp\u003e그들은 황무지에서 멈추지 않는 법을 알고 있다.\u003c/p\u003e\r\n  \u003cp\u003e도로가 모래에 묻히면 새로운 길을 만들고, 엔진이 부서지면 다른 차량의 부품을 뜯어낸다. 연료가 부족하면 무엇이든 태워 움직이고, 기업의 항법망이 끊기면 별과 바람을 따라 달린다.\u003c/p\u003e\r\n  \u003cp\u003e카론은 정해진 노선과 거대한 물류망을 지배한다.\u003c/p\u003e\r\n  \u003cp\u003e선독스는 노선이 사라진 뒤에도 이동할 수 있다.\u003c/p\u003e\r\n  \u003cp\u003e한 팩은 케르베로스의 부대에 파괴될 수 있고, 로드 알파는 전쟁에서 죽을 수 있다. 그러나 살아남은 라이더는 차량과 동료를 모아 다시 새로운 팩을 만든다.\u003c/p\u003e\r\n  \u003cp\u003e선독스는 중앙본부도, 반드시 지켜야 할 수도도 없다.\u003c/p\u003e\r\n  \u003cp\u003e그들을 완전히 없애려면 황무지의 모든 차량을 멈춰야 한다.\u003c/p\u003e\r\n  \u003cp\u003e그리고 황무지에서 움직이는 사람이 남아 있는 한, 붉은 태양개도 다시 도로 위에 나타날 것이다.\u003c/p\u003e\r\n\u003c/section\u003e\r\n";

window.FACTION_INFO.saintzero = "<section class=\"faction-detail\">\r\n  <h2>조직 개요</h2>\r\n  <p class=\"faction-quote\">“신분도, 크레딧도 필요 없다. 아직 숨을 쉬고 있다면 환자다.”</p>\r\n  <p>세인트 제로는 장막 도시와 돔의 하층구역, 지하도시에서 불법 병원과 사이버웨어 밀매망을 운영하는 의료조직이다. 정식 시민권이나 라자루스 회원계약이 없는 사람, 범죄자와 도망자, 등록되지 않은 사이버웨어 사용자까지 신분을 묻지 않고 치료한다.</p>\r\n  <p>이들은 버려진 병원과 지하진료소에서 응급수술, 의체이식과 열화증 치료를 시행한다. 도난당한 군용 사이버웨어와 재생부품을 판매하고, 기업 제품에 삽입된 위치추적 코드와 원격제한을 제거한다.</p>\r\n  <p>장막 도시의 주민들에게 세인트 제로는 기업 의료망이 버린 사람을 구하는 성자들이다.</p>\r\n  <p>그러나 모든 의사가 자비로운 것은 아니다.</p>\r\n  <p>일부 진료소는 치료비를 갚지 못한 환자에게 노동과 정보, 장기와 신체 일부를 요구한다. 회수한 시신과 의체를 분해해 다음 환자에게 사용하며, 검증되지 않은 약물과 실험적인 시술을 사람에게 적용하기도 한다.</p>\r\n  <p>세인트 제로는 병원이면서 암시장이고, 의료공동체이면서 교단이며, 필요하다면 약품과 환자를 지키기 위해 총을 드는 갱단이다.</p>\r\n  <p>그들은 생명을 구한다고 말한다.</p>\r\n  <p>무엇을 인간에게 남겨야 살렸다고 부를 수 있는지는 진료소마다 다르다.</p>\r\n\r\n  <h2>기본 정보</h2>\r\n  <table class=\"data-table faction-info-table\">\r\n    <tbody>\r\n      <tr><th>정식 명칭</th><td>SAINT ZERO</td></tr>\r\n      <tr><th>통칭</th><td>세인트 제로, 제로</td></tr>\r\n      <tr><th>조직 분류</th><td>불법 의료·사이버웨어 밀매조직</td></tr>\r\n      <tr><th>주요 활동</th><td>무허가 진료, 응급수술, 의체이식, 약물제조</td></tr>\r\n      <tr><th>불법 사업</th><td>군용 사이버웨어 거래, 추적코드 제거, 장기 밀매</td></tr>\r\n      <tr><th>주요 활동지역</th><td>장막 도시, 지하도시, 돔 하층구역</td></tr>\r\n      <tr><th>주요 고객</th><td>비등록자, 빈민, 용병, 범죄자, 도망자</td></tr>\r\n      <tr><th>상징 색상</th><td>적색, 백색, 흑색</td></tr>\r\n      <tr><th>최고지도자</th><td>제로 닥터</td></tr>\r\n      <tr><th>간부회의</th><td>성의회</td></tr>\r\n      <tr><th>무장조직</th><td>성가대</td></tr>\r\n      <tr><th>대표적인 인식</th><td>빈민의 성자이자 신체를 거래하는 지하의사</td></tr>\r\n    </tbody>\r\n  </table>\r\n\r\n  <h2>조직의 역사</h2>\r\n\r\n  <h3>백야 이후의 야전병원</h3>\r\n  <p>세인트 제로의 기원은 2102년 백야 직후 운영되었던 무허가 야전병원과 이동식 진료소에서 찾을 수 있다.</p>\r\n  <p>정식 병원이 붕괴하고 의료진과 약품이 부족해지자 살아남은 의사와 간호사, 의공학자들은 지하철역과 창고, 방공호에 임시수술실을 만들었다.</p>\r\n  <p>환자의 신원을 확인하거나 비용을 심사할 여유는 없었다.</p>\r\n  <p>의료진은 사용할 수 있는 약품과 부품으로 누구든 치료했다. 규격에 맞는 장기가 없으면 다른 기계와 생체조직을 연결했고, 정식 의체가 없으면 산업용 부품을 개조해 사용했다.</p>\r\n  <p>이들 가운데 한 의사가 자신의 이름 대신 ‘제로’라는 호칭을 사용했다는 기록이 있다.</p>\r\n  <p>그가 최초의 제로 닥터였는지는 알 수 없다.</p>\r\n\r\n  <h3>기업 의료망의 밖</h3>\r\n  <p>도시와 기업의 의료체계가 재건된 뒤에도 모든 사람이 치료받을 수 있었던 것은 아니다.</p>\r\n  <p>라자루스는 계약회원을 우선했고 아르카디아의 병원은 시민권과 비용을 요구했다. 모르포스의 고급시술은 상류층과 기업인에게 집중되었다.</p>\r\n  <p>등록되지 않은 피난민과 범죄자, 채무자와 불법 사이버웨어 사용자는 정식 병원에 들어가는 순간 체포되거나 치료를 거부당했다.</p>\r\n  <p>지하의 무허가 진료소들은 이들을 받아들였다.</p>\r\n  <p>서로 떨어져 있던 병원과 리퍼닥들은 의약품, 혈액과 부품을 교환하기 위한 비밀 의료망을 만들었다. 이 연합이 현재의 세인트 제로로 발전했다.</p>\r\n\r\n  <h3>성가대의 탄생</h3>\r\n  <p>의약품과 사이버웨어는 물과 무기만큼 값비싼 자원이었다.</p>\r\n  <p>범죄조직과 기업 회수팀은 세인트 제로의 진료소를 습격했고 환자와 의사, 장비를 빼앗았다. 일부 진료소는 보호비를 지불했지만 그럴수록 더 많은 것을 요구받았다.</p>\r\n  <p>제로 닥터는 병원을 지키기 위한 무장조직을 만들었다.</p>\r\n  <p>초기의 성가대는 부상에서 회복한 환자와 의료진의 가족, 전직 용병으로 구성되었다. 이들은 진료소를 방어하고 의약품 수송대를 호위했다.</p>\r\n  <p>이후 성가대는 기업창고 습격과 환자 탈환, 배신한 리퍼닥의 처형까지 담당하는 전투조직으로 성장했다.</p>\r\n\r\n  <h3>현재</h3>\r\n  <p>현재 세인트 제로는 하나의 중앙병원이 아니라 여러 지역에 분산된 지하 의료망으로 존재한다.</p>\r\n  <p>각 진료소는 성의회의 기본규칙을 따르지만 운영방식과 윤리기준에는 큰 차이가 있다.</p>\r\n  <p>어떤 병원은 빈민을 무료로 치료하며 지역사회가 식량과 보호를 제공한다. 다른 병원은 환자의 장기와 사이버웨어를 담보로 잡고 채무를 갚지 못하면 신체에서 회수한다.</p>\r\n  <p>이 때문에 세인트 제로 전체를 성자나 장기밀매단 중 하나로 규정하기는 어렵다.</p>\r\n  <p>같은 붉은 제로의 표식 아래 완전히 다른 의사들이 일하고 있다.</p>\r\n\r\n  <h2>조직 철학</h2>\r\n  <h3>살아 있는 사람부터 치료한다</h3>\r\n  <p>시민권과 범죄기록, 기업계약보다 환자의 생존을 우선한다.</p>\r\n  <p>세인트 제로의 진료소 안에서는 경찰과 범죄자, 기업인과 비등록자도 환자로 취급되는 것이 원칙이다.</p>\r\n  <h3>완벽한 치료보다 가능한 생존</h3>\r\n  <p>깨끗한 장비와 적합한 부품을 기다리다 환자가 죽게 두지 않는다.</p>\r\n  <p>산업용 부품과 재생장기라도 당장 생존할 수 있다면 사용한다. 이후의 부작용과 유지비는 환자가 감당해야 할 문제로 남는다.</p>\r\n  <h3>기업은 신체를 소유할 수 없다</h3>\r\n  <p>구매한 사이버웨어에 기업의 원격제한과 추적코드가 남아 있는 것을 신체에 대한 소유권 침해라고 본다.</p>\r\n  <p>세인트 제로는 환자가 이식받은 순간 그 부품도 환자의 몸이 된다고 주장한다.</p>\r\n  <h3>치료에는 반드시 대가가 따른다</h3>\r\n  <p>무료진료를 제공하는 병원도 약품과 부품, 식량이 필요하다.</p>\r\n  <p>돈이 없다면 노동과 정보, 물건과 위험한 임무로 치료비를 대신할 수 있다. 무엇을 정당한 대가로 인정할지는 진료소마다 다르다.</p>\r\n  <h3>의사의 손은 보호받아야 한다</h3>\r\n  <p>진료소와 의료진을 공격한 사람은 성가대의 보복대상이 된다.</p>\r\n  <p>적대조직의 부상자를 치료했더라도 수술실 안에서는 공격할 수 없다는 원칙을 주장한다.</p>\r\n\r\n  <h2>주요 사업</h2>\r\n  <h3>지하진료망</h3>\r\n  <p>장막 도시, 지하도시와 돔 하층구역에 비밀진료소를 운영한다.</p>\r\n  <p>총상과 감염, 산업재해와 사이버웨어 부작용을 치료한다. 정식 신원기록을 남기지 않기 때문에 도망자와 범죄자도 이용할 수 있다.</p>\r\n  <h3>응급수술</h3>\r\n  <p>현장에서 확보할 수 있는 장비와 부품을 이용해 긴급수술을 시행한다.</p>\r\n  <p>정식 병원보다 감염과 부작용 위험은 높지만, 다른 선택지가 없는 환자에게는 유일한 생존 가능성이다.</p>\r\n  <h3>불법 사이버웨어 이식</h3>\r\n  <p>기업등록과 적합성 심사를 거치지 않은 사이버웨어를 이식한다.</p>\r\n  <p>도난품, 전장에서 회수한 부품과 재생 사이버웨어가 사용된다. 숙련된 리퍼닥의 시술은 정식 병원에 가까운 수준이지만 그렇지 않은 진료소도 많다.</p>\r\n  <h3>사이버웨어 시장</h3>\r\n  <p>의체와 신경 인터페이스, 인공장기와 관련 약물을 거래한다.</p>\r\n  <p>모르포스와 케르베로스의 구형제품, 군용 장비와 출처가 불분명한 실험부품까지 유통된다.</p>\r\n  <h3>추적코드 제거</h3>\r\n  <p>사이버웨어에 포함된 제품등록, 원격제한과 위치추적 기능을 제거한다.</p>\r\n  <p>기업의 회수명령을 받은 부품과 탈취된 군용 사이버웨어를 자유롭게 사용할 수 있게 만든다.</p>\r\n  <h3>열화증 억제제</h3>\r\n  <p>과도한 신체개조로 발생하는 신경손상, 호르몬 불균형과 정신불안을 억제하는 약물을 제조한다.</p>\r\n  <p>정품 약물을 구할 수 없는 사람에게 필수적이지만, 세인트 제로의 억제제는 제조시설에 따라 품질 차이가 크다.</p>\r\n  <h3>장기와 생체부품</h3>\r\n  <p>배양장기, 기증받은 신체조직과 시신에서 회수한 장기를 거래한다.</p>\r\n  <p>모든 장기가 합법적인 기증으로 확보되는 것은 아니다.</p>\r\n  <h3>의료정보 거래</h3>\r\n  <p>환자의 신원과 부상, 사이버웨어와 신체적 약점은 높은 가치를 가진다.</p>\r\n  <p>성의회는 의료정보를 외부에 판매하는 것을 금지하지만 채무와 협박, 조직 간 거래에 이용하는 진료소도 존재한다.</p>\r\n\r\n  <h2>조직 구조</h2>\r\n  <h3>제로 닥터 — DOCTOR ZERO</h3>\r\n  <p>세인트 제로의 최고지도자에게 계승되는 칭호다.</p>\r\n  <p>현재의 제로 닥터가 최초의 인물과 동일한 사람인지, 몇 번째 계승자인지는 알려지지 않았다. 본명과 얼굴 역시 대외적으로 공개되지 않는다.</p>\r\n  <p>제로 닥터는 모든 진료소를 직접 운영하지 않는다.</p>\r\n  <p>조직의 기본 의료원칙과 금지사항을 정하고, 성의회를 중재하며 성가대의 대규모 작전을 승인한다.</p>\r\n  <p>일부 구성원은 제로 닥터를 지도자가 아니라 누구나 계승할 수 있는 의료적 이상으로 여긴다.</p>\r\n\r\n  <h3>성의회 — CONCLAVE</h3>\r\n  <p>각 지역의 리퍼닥과 병원장, 약물제조 책임자가 참여하는 간부회의다.</p>\r\n  <p>의약품과 부품의 분배, 진료소 사이의 분쟁과 대외관계를 조정한다. 의료윤리를 심각하게 위반한 의사의 처분도 결정한다.</p>\r\n  <p>성의회가 한곳에 모이는 일은 드물다. 대부분 암호화된 통신과 대리인을 통해 회의한다.</p>\r\n\r\n  <h3>지하진료망</h3>\r\n  <p>지역별 병원과 진료소를 관리한다.</p>\r\n  <p>각 진료소는 상당한 자율권을 가지며 지역사회와 범죄조직, 로우라인의 보호 아래 운영된다.</p>\r\n\r\n  <h3>사이버웨어시장</h3>\r\n  <p>부품의 매입과 감정, 재생과 판매를 담당한다.</p>\r\n  <p>출처가 위험한 장비를 세탁하고 다른 지역으로 이동시키기도 한다.</p>\r\n\r\n  <h3>추적코드제거실</h3>\r\n  <p>기업의 제품등록과 원격제한을 해제하는 전문 기술자 집단이다.</p>\r\n  <p>아르고스와 제조기업의 회수팀이 가장 적극적으로 추적하는 부서다.</p>\r\n\r\n  <h3>억제제제조실</h3>\r\n  <p>열화증 억제제, 신경안정제와 불법 진통제를 생산한다.</p>\r\n  <p>제조법은 진료소마다 조금씩 다르며 일부 약물에는 강한 중독성이 존재한다.</p>\r\n\r\n  <h2>성가대 — THE CHOIR</h2>\r\n  <p>성가대는 세인트 제로의 무장조직이다.</p>\r\n  <p>일반적인 갱단의 전투원과 달리 병원과 환자, 의약품을 지키는 것을 주요 임무로 한다. 전직 용병과 환자, 전투의무관과 개조된 경비원으로 구성된다.</p>\r\n  <p>성가대라는 이름은 전투 중 사용하는 공동 호흡신호와 통신음이 합창처럼 들리는 데서 유래했다는 설이 있다.</p>\r\n  <h3>주요 임무</h3>\r\n  <ul>\r\n    <li>지하병원과 의료진 방어</li>\r\n    <li>의약품 수송대 호위</li>\r\n    <li>기업창고와 의료시설 습격</li>\r\n    <li>납치된 의사와 환자 회수</li>\r\n    <li>의료채무자 추적</li>\r\n    <li>불법 장기거래 조직 제거</li>\r\n    <li>세인트 제로를 배신한 리퍼닥 처형</li>\r\n    <li>위험한 실험체와 감염환자 격리</li>\r\n    <li>기업 회수팀에 대한 대응</li>\r\n    <li>성의회의 판결 집행</li>\r\n  </ul>\r\n  <p>성가대는 의료시설 안에서의 전투를 피한다.</p>\r\n  <p>하지만 진료소를 공격한 사람에게는 환자의 치료가 끝난 뒤 반드시 대가를 치르게 한다.</p>\r\n\r\n  <h2>주요 구성원</h2>\r\n  <h3>리퍼닥</h3>\r\n  <p>불법 사이버웨어 시술과 신체복원을 담당한다.</p>\r\n  <p>기술과 윤리의 수준은 사람마다 크게 다르다. 일부는 모르포스 출신의 최고급 기술자지만, 단기교육만 받은 위험한 시술자도 존재한다.</p>\r\n  <h3>지하의사</h3>\r\n  <p>질병과 외상, 감염을 치료하는 의료진이다.</p>\r\n  <p>정식 면허를 가진 의사도 있고 백야 이후 계승된 도제식 교육만 받은 의사도 있다.</p>\r\n  <h3>스티처</h3>\r\n  <p>상처봉합과 장기연결, 의체의 생체접합을 담당하는 시술보조자다.</p>\r\n  <p>숙련된 스티처는 일반 의사보다 사이버웨어 수술에 뛰어나기도 하다.</p>\r\n  <h3>하베스터</h3>\r\n  <p>시신과 파손된 사이버웨어에서 사용할 수 있는 장기와 부품을 회수한다.</p>\r\n  <p>세인트 제로에서 가장 불길하게 여겨지는 직종이다. 합법적 회수와 시체훼손의 경계에 서 있다.</p>\r\n  <h3>코드버너</h3>\r\n  <p>기업의 추적코드와 소프트웨어 제한을 제거한다.</p>\r\n  <p>의학지식과 넷러닝 기술을 함께 갖춘 전문기술자다.</p>\r\n  <h3>조제사</h3>\r\n  <p>억제제와 진통제, 항생제와 마취제를 제조한다.</p>\r\n  <p>시설과 원료가 부족해 같은 약물도 지역에 따라 효능과 부작용이 달라진다.</p>\r\n  <h3>채무관리인</h3>\r\n  <p>치료비와 계약을 관리한다.</p>\r\n  <p>환자의 노동과 정보, 물품으로 비용을 회수한다. 일부는 의료진보다 범죄조직의 채권추심자에 가깝게 행동한다.</p>\r\n\r\n  <h2>치료비</h2>\r\n  <p>세인트 제로의 진료소에는 통일된 가격표가 없다.</p>\r\n  <p>지역의 약품과 전력, 환자의 상태와 병원장의 원칙에 따라 비용이 결정된다.</p>\r\n  <p>환자는 다음과 같은 방식으로 치료비를 지불할 수 있다.</p>\r\n  <ul>\r\n    <li>크레딧과 수권</li>\r\n    <li>의약품과 사이버웨어</li>\r\n    <li>기술과 노동</li>\r\n    <li>정보와 지도</li>\r\n    <li>의료진 호위</li>\r\n    <li>기업시설 침투</li>\r\n    <li>장기적인 진료소 근무</li>\r\n    <li>사후 장기기증</li>\r\n    <li>신체조직과 유전자 표본</li>\r\n    <li>위험한 시술의 피험자 계약</li>\r\n  </ul>\r\n  <p>일부 진료소는 가난한 주민을 무료로 치료한다.</p>\r\n  <p>지역사회가 식량과 물, 은신처와 경비를 제공해 병원을 유지한다. 반대로 폭력적인 병원장은 환자의 절박함을 이용해 평생 갚을 수 없는 채무를 부과하기도 한다.</p>\r\n\r\n  <h2>의료 원칙</h2>\r\n  <p>성의회가 공통적으로 인정하는 기본규칙이다.</p>\r\n  <ul>\r\n    <li>수술실 안에서는 환자의 소속을 묻지 않는다.</li>\r\n    <li>치료 중인 환자를 외부세력에 넘기지 않는다.</li>\r\n    <li>사용한 부품과 약물의 출처를 숨길 수는 있어도 기능을 속이지 않는다.</li>\r\n    <li>사망자의 장기와 의체는 가능한 한 동의를 확인한 뒤 회수한다.</li>\r\n    <li>감염 가능성이 있는 환자는 다른 환자와 분리한다.</li>\r\n    <li>의료진을 공격한 자는 모든 진료소의 보호를 잃는다.</li>\r\n    <li>기업의 추적코드를 환자 몰래 남겨두지 않는다.</li>\r\n    <li>환자에게 발생한 치명적인 부작용을 은폐하지 않는다.</li>\r\n    <li>치료할 수 없는 환자에게 거짓 희망을 판매하지 않는다.</li>\r\n    <li>성의회가 파문한 의사는 세인트 제로의 표식을 사용할 수 없다.</li>\r\n  </ul>\r\n  <p>실제로 모든 진료소가 이 원칙을 지키는 것은 아니다.</p>\r\n\r\n  <h2>주요 기술과 약물</h2>\r\n  <h3>제로 패치</h3>\r\n  <p>출혈과 감염을 억제하는 응급 생체접착제다.</p>\r\n  <p>열악한 환경에서도 사용할 수 있으며 장막 도시에서 가장 널리 퍼진 세인트 제로 제품이다.</p>\r\n  <h3>그레이 마로우</h3>\r\n  <p>손상된 골수와 혈액생성을 보조하는 재생약물이다.</p>\r\n  <p>정품은 효과가 뛰어나지만 값싼 복제품은 암과 조직변이를 일으킬 수 있다.</p>\r\n  <h3>사일런스 억제제</h3>\r\n  <p>사이버웨어 열화로 발생하는 환각, 공격성과 신경폭주를 억제한다.</p>\r\n  <p>강한 의존성이 있어 장기간 사용하면 약물이 없을 때 증상이 더욱 심해진다.</p>\r\n  <h3>고스트 포트</h3>\r\n  <p>기업의 원격접속을 차단한 비인가 신경 연결장치다.</p>\r\n  <p>추적을 피할 수 있지만 보안 업데이트와 긴급정지 기능도 사용할 수 없다.</p>\r\n  <h3>세컨드 하트</h3>\r\n  <p>재생된 인공심장 계열의 통칭이다.</p>\r\n  <p>출처와 제조사가 서로 다른 부품을 세인트 제로 규격으로 개조해 사용한다. 저렴하지만 정기적인 점검이 필요하다.</p>\r\n  <h3>블랙 블러드</h3>\r\n  <p>심각한 출혈환자에게 사용하는 범용 인공혈액이다.</p>\r\n  <p>생존 가능성을 크게 높이지만 반복적으로 투여하면 면역계와 장기에 부담을 준다.</p>\r\n  <h3>스크럽 시술</h3>\r\n  <p>사이버웨어에서 제품등록, 사용자기록과 추적코드를 제거하는 작업이다.</p>\r\n  <p>과정에서 장비의 일부 기능과 안전장치도 손실될 수 있다.</p>\r\n\r\n  <h2>주요 시설</h2>\r\n  <h3>제로 워드</h3>\r\n  <p>세인트 제로가 직접 관리하는 중심병원의 통칭이다.</p>\r\n  <p>정확한 위치는 공개되지 않으며 여러 곳이 동시에 같은 명칭을 사용한다. 제로 닥터가 어디에 머무는지 숨기기 위한 방식이라는 설도 있다.</p>\r\n  <h3>붉은 진료소</h3>\r\n  <p>장막 도시와 돔 하층구역에 위치한 소규모 병원이다.</p>\r\n  <p>외부에는 붉은 원과 끊어진 의료선으로 구성된 세인트 제로의 표식이 남겨져 있다.</p>\r\n  <h3>본 마켓</h3>\r\n  <p>사이버웨어와 장기, 약품을 거래하는 비밀시장이다.</p>\r\n  <p>성의회의 허가를 받은 판매자만 들어올 수 있지만 도난품과 비동의 장기가 유통된다는 의혹이 끊이지 않는다.</p>\r\n  <h3>애프터케어</h3>\r\n  <p>열화증 환자와 개조 중독자를 보호하는 은신시설이다.</p>\r\n  <p>약물치료와 사이버웨어 제거를 지원한다. 일부 시설은 환자를 새로운 피험자로 활용한다는 소문도 있다.</p>\r\n  <h3>콰이어 하우스</h3>\r\n  <p>성가대의 훈련과 장비보관, 부상자 치료를 담당하는 무장거점이다.</p>\r\n  <p>진료소가 공격받으면 가장 가까운 콰이어 하우스에서 지원병력이 출동한다.</p>\r\n  <h3>나인스 테이블</h3>\r\n  <p>성의회가 최고등급 수술과 처분을 결정하는 비밀수술실이라는 소문이 있다.</p>\r\n  <p>아홉 명의 의사가 한 환자를 둘러싸고 치료 가능성과 신체의 분배를 논의한다고 전해진다.</p>\r\n\r\n  <h2>조직 문화</h2>\r\n  <p>세인트 제로의 구성원은 자신을 범죄자보다 의료인으로 인식하는 경우가 많다.</p>\r\n  <p>정식 면허와 학위보다 실제로 몇 명의 환자를 살렸는지가 중요하다. 뛰어난 리퍼닥은 기업병원의 외과의보다 높은 존경을 받을 수 있다.</p>\r\n  <p>의료진은 서로의 기술과 처방을 공유하지만 핵심적인 시술법과 약물제조법은 개인의 자산으로 숨기기도 한다.</p>\r\n  <p>진료소마다 문화와 윤리가 크게 다르다.</p>\r\n  <p>어떤 의사는 돈이 없는 아이를 무료로 치료하고, 어떤 의사는 같은 아이의 희귀 유전자에 더 관심을 보인다. 성가대는 양쪽 모두를 외부의 공격에서 보호해야 한다.</p>\r\n  <p>세인트 제로 내부에서 널리 사용되는 말은 다음과 같다.</p>\r\n  <blockquote>깨끗한 손만 찾다 보면, 아무도 피 묻은 사람을 살리지 못한다.</blockquote>\r\n\r\n  <h2>대중의 인식</h2>\r\n  <h3>장막 도시 주민</h3>\r\n  <p>가장 현실적으로 의지할 수 있는 의료조직으로 여긴다.</p>\r\n  <p>세인트 제로의 의사가 없으면 작은 감염과 총상도 죽음으로 이어진다. 지역에 따라 제로 닥터를 성인처럼 숭배하기도 한다.</p>\r\n  <h3>돔 하층민</h3>\r\n  <p>정식 병원에서 치료받을 수 없는 사람들이 찾는 마지막 선택이다.</p>\r\n  <p>불법시술의 위험을 알지만 시민권 조사와 보험심사를 받지 않는다는 점이 중요하다.</p>\r\n  <h3>돔 상류층</h3>\r\n  <p>위험하고 비위생적인 장기밀매 조직으로 인식한다.</p>\r\n  <p>하지만 공식 기록을 남길 수 없는 시술이나 기업의 추적을 피하기 위해 비밀리에 이용하는 사람도 있다.</p>\r\n  <h3>용병과 갱단</h3>\r\n  <p>신분과 부상의 원인을 묻지 않는 의사를 높게 평가한다.</p>\r\n  <p>진료소와 성가대를 보호하는 대신 치료비와 우선시술권을 받는 계약을 체결하기도 한다.</p>\r\n  <h3>기업</h3>\r\n  <p>의료기술과 사이버웨어를 훔치고 제품제한을 해제하는 범죄조직으로 규정한다.</p>\r\n  <p>그러나 공식병원이 접근할 수 없는 지역에서 전염병과 열화증을 통제한다는 실용적 가치 때문에 완전한 제거를 망설인다.</p>\r\n\r\n  <h2>다른 세력과의 관계</h2>\r\n  <h3>LAZARUS MEDICAL RESPONSE</h3>\r\n  <p>가장 분명한 경쟁자이자 현장에서 자주 협력하는 의료조직이다.</p>\r\n  <p>라자루스는 계약회원과 정식 의료망을 중심으로 움직인다. 세인트 제로는 시민권과 계약이 없는 환자를 받아들인다.</p>\r\n  <p>라자루스가 접근하지 못하는 지역의 환자를 세인트 제로가 안정시킨 뒤 인계하거나, 반대로 라자루스가 계약병원에 입원시킬 수 없는 사람을 비공식적으로 넘기는 경우도 있다.</p>\r\n  <h3>MORPHOS BIODYNE</h3>\r\n  <p>모르포스의 폐기부품과 구형 사이버웨어, 유출된 기술이 세인트 제로 시장에서 거래된다.</p>\r\n  <p>모르포스는 세인트 제로를 기술절도와 불법시술의 중심으로 규정한다. 한편 모르포스에서 추방되거나 이탈한 연구자들이 세인트 제로의 리퍼닥으로 활동하기도 한다.</p>\r\n  <h3>CERBERUS DEFENSE GROUP</h3>\r\n  <p>도난당한 군용 사이버웨어와 전장의 회수품이 주요 거래대상이다.</p>\r\n  <p>케르베로스 워치독은 추적코드 제거실과 본 마켓을 적극적으로 공격한다.</p>\r\n  <h3>LOWLINE</h3>\r\n  <p>세인트 제로의 핵심 협력세력이다.</p>\r\n  <p>로우라인은 의약품과 환자, 의료진과 사이버웨어를 지하노선으로 운반한다. 폐쇄역과 정비구역에 비밀진료소를 제공하기도 한다.</p>\r\n  <h3>SUNDOGS</h3>\r\n  <p>황무지에서 확보한 부품과 약품, 생체소재를 거래한다.</p>\r\n  <p>세인트 제로는 선독스의 부상자와 그리스핸드가 수리할 수 없는 신체를 치료한다.</p>\r\n  <h3>VELVET STATIC</h3>\r\n  <p>뇌살과 감각중독, 기억편집 부작용을 치료한다.</p>\r\n  <p>벨벳 스태틱은 자금과 약품을 제공하는 대신 고객의 의료기록과 신분을 비밀로 유지할 것을 요구한다.</p>\r\n  <h3>DOME CIVIC SECURITY</h3>\r\n  <p>무허가 진료와 불법 사이버웨어로 인해 단속대상이다.</p>\r\n  <p>그러나 하층구역에서 세인트 제로가 사라지면 의료공백이 발생하기 때문에 일선 경찰이 진료소를 묵인하는 경우도 많다.</p>\r\n  <h3>ARGOS SECURE NETWORKS</h3>\r\n  <p>신분이 없는 환자와 추적코드가 제거된 사이버웨어 때문에 주요 감시대상이다.</p>\r\n  <p>아르고스는 일부 진료소를 정보원이나 비공식 심문치료 시설로 이용한다는 의혹도 받는다.</p>\r\n  <h3>ECLIPSE TACTICAL BUREAU</h3>\r\n  <p>생체병기와 전염성 개조, 통제불능 시술이 발생하면 이클립스가 개입한다.</p>\r\n  <p>반대로 이클립스가 공식기관에 공개할 수 없는 개체의 상태를 확인하기 위해 세인트 제로의 전문가를 비밀리에 고용하는 경우도 있다.</p>\r\n\r\n  <h2>논란과 내부 문제</h2>\r\n  <h3>장기 출처</h3>\r\n  <p>세인트 제로에서 사용되는 장기와 생체조직의 출처가 명확하지 않은 경우가 많다.</p>\r\n  <p>성의회는 비동의 장기적출을 금지하지만 일부 하베스터와 진료소는 시신과 채무자의 몸을 부품창고처럼 취급한다.</p>\r\n  <h3>환자 착취</h3>\r\n  <p>치료비를 갚지 못한 사람에게 위험한 노동과 실험참여, 장기기증을 요구한다.</p>\r\n  <p>생명을 구해준 대가라는 논리 아래 사실상 노예계약이 체결되는 경우도 존재한다.</p>\r\n  <h3>불균일한 의료수준</h3>\r\n  <p>같은 세인트 제로의 표식을 사용하는 진료소라도 기술과 위생, 장비수준이 크게 다르다.</p>\r\n  <p>환자는 의사가 숙련된 의료인인지 위험한 사기꾼인지 수술을 받기 전에 확인하기 어렵다.</p>\r\n  <h3>불법 인체실험</h3>\r\n  <p>정식 승인과 윤리심사를 받지 않은 약물과 시술이 환자에게 사용된다.</p>\r\n  <p>일부 의료진은 다른 치료방법이 없는 상황에서의 마지막 시도라고 주장한다.</p>\r\n  <h3>성가대의 폭력</h3>\r\n  <p>진료소를 지키는 것을 넘어 경쟁 의료조직을 습격하거나 의료채무자를 납치하는 성가대가 존재한다.</p>\r\n  <p>지역에 따라 성가대는 병원의 수호자보다 무장갱단에 가깝다.</p>\r\n  <h3>제로 닥터의 권위</h3>\r\n  <p>어떤 구성원은 제로 닥터를 의료망의 조정자로 보지만, 일부는 종교적인 구원자로 숭배한다.</p>\r\n  <p>이러한 교단화가 의료적 판단보다 지도자에 대한 충성을 우선하게 만든다는 비판이 있다.</p>\r\n\r\n  <h2>확인되지 않은 소문</h2>\r\n  <p>제로 닥터는 한 명의 인간이 아니라는 소문이 있다.</p>\r\n  <p>역대 제로 닥터의 기억과 의료지식이 후계자의 신경계에 이식되며, 현재의 제로 닥터 안에는 수백 년 동안 이어진 여러 의사의 인격이 함께 존재한다는 것이다.</p>\r\n  <p>다른 소문에서는 ‘제로’가 사람이 아니라 세인트 제로의 모든 진료기록을 연결하는 의료 인공지능이라고 주장한다.</p>\r\n  <p>각 지역의 제로 닥터는 그 인공지능의 판단을 전달하는 대리인에 불과하다는 것이다.</p>\r\n  <p>또한 성의회가 백야 이전의 인간복제 시설을 발견했다는 이야기도 있다. 이들은 장기만을 배양하는 것이 아니라 완전한 신체를 제작하고 있으며, 돈과 권력이 충분한 고객에게 새로운 몸을 판매한다고 한다.</p>\r\n  <p>가장 어두운 소문은 세인트 제로의 무료진료소에 관한 것이다.</p>\r\n  <p>특정한 유전자와 사이버웨어 적응성을 가진 환자는 치료비를 요구받지 않는다. 대신 진료기록에 붉은 원이 표시되고, 어느 날 성가대에 의해 다른 시설로 옮겨진다.</p>\r\n  <p>그들이 어디로 가는지 아는 사람은 없다.</p>\r\n  <p>다만 본 마켓에는 그들이 사라진 뒤부터 새로운 종류의 장기와 신경조직이 등장한다고 한다.</p>\r\n  <p>제로 닥터는 이 소문을 부정했다.</p>\r\n  <p>그리고 그런 일을 저지른 의사가 존재한다면 자신이 직접 수술대에 눕히겠다고 선언했다.</p>\r\n\r\n  <h2>조직이 가진 힘</h2>\r\n  <p>세인트 제로의 힘은 돈이나 군대에서 나오지 않는다.</p>\r\n  <p>그들은 기업이 버린 사람을 받아들인다.</p>\r\n  <p>신분이 없고 보험료를 내지 못하며, 불법 사이버웨어 때문에 정식 병원에 들어갈 수 없는 사람에게도 수술대를 내어준다.</p>\r\n  <p>그 사람이 살아난다면 세인트 제로에 빚을 지게 된다.</p>\r\n  <p>어떤 이는 의사와 간호사가 되고, 어떤 이는 성가대에 들어가며, 어떤 이는 평생 약품과 정보를 공급한다. 한 번 구해진 생명이 새로운 진료소와 전투원, 정보망이 되어 조직으로 돌아온다.</p>\r\n  <p>라자루스는 구조할 사람을 계약으로 정한다.</p>\r\n  <p>모르포스는 가장 좋은 육체를 설계한다.</p>\r\n  <p>세인트 제로는 그 두 기업의 기준에서 탈락한 사람들을 주워 다시 이어 붙인다.</p>\r\n  <p>때로는 흉하게, 위험하게, 이전과 전혀 다른 모습으로.</p>\r\n  <p>하지만 황무지와 장막 도시에서는 완벽한 치료보다 다음 날까지 숨을 쉴 수 있다는 사실이 더 중요하다.</p>\r\n  <p>세인트 제로가 사라진다면 범죄와 불법시술이 줄어들 수 있다.</p>\r\n  <p>그보다 먼저, 공식 통계에조차 기록되지 않은 수많은 사람이 치료받을 곳을 잃게 될 것이다.</p>\r\n</section>\r\n";

window.FACTION_INFO.deadair = "<section class=\"faction-detail\">\r\n  <h2>조직 개요</h2>\r\n  <p class=\"faction-quote\">“모든 신호가 끊긴 뒤에도, 누군가는 듣고 있다.”</p>\r\n  <p>데드 에어는 조직원들이 서로의 얼굴과 본명을 모르는 익명 분산형 넷러너 집단이다. 고정된 본부와 공개된 지도자가 존재하지 않으며, 작전마다 임시로 구성되는 독립 셀을 통해 움직인다.</p>\r\n  <p>이들은 기업통신망 감청, 기밀탈취, 신원삭제, 선전방송과 블루넷 교란을 수행한다. 가짜 재난경보를 퍼뜨려 도시를 혼란에 빠뜨리기도 하고, 기업이 은폐한 학살과 불법연구를 대중에게 폭로하기도 한다.</p>\r\n  <p>명확한 계급은 없지만 모든 조직원이 동등한 것도 아니다. 데드 에어 내부의 권력은 직책이나 연공이 아니라 얼마나 깊은 통신망과 정보에 접근할 수 있는지에 따라 결정된다.</p>\r\n  <p>각 작전 셀은 임무가 끝나는 순간 해체된다.</p>\r\n  <p>동료가 누구였는지 추적하거나 다른 셀의 조직원을 찾아내려는 행위는 호기심이 아니라 배신으로 간주된다. 누구도 조직 전체의 구조를 알지 못하며, 자신이 받은 명령이 실제 인간에게서 내려왔는지조차 확신할 수 없다.</p>\r\n  <p>데드 에어는 하나의 갱단이라기보다 신호 사이에서 살아가는 유령에 가깝다.</p>\r\n  <p>그들을 체포할 수는 있다.</p>\r\n  <p>그러나 체포한 사람이 실제 조직원인지, 일회성 협력자였는지, 혹은 존재하지도 않는 명령을 따랐는지는 알 수 없다.</p>\r\n\r\n  <h2>기본 정보</h2>\r\n  <table class=\"data-table faction-info-table\">\r\n    <tbody>\r\n      <tr><th>정식 명칭</th><td>DEAD AIR</td></tr>\r\n      <tr><th>통칭</th><td>데드 에어, 무음망</td></tr>\r\n      <tr><th>조직 분류</th><td>익명 분산형 넷러너 집단</td></tr>\r\n      <tr><th>주요 활동</th><td>해킹, 감청, 기밀탈취, 신원삭제, 선전방송</td></tr>\r\n      <tr><th>주요 활동지역</th><td>블루넷, 기업통신망, 폐쇄된 데이터망</td></tr>\r\n      <tr><th>최고 통신망</th><td>무음 채널</td></tr>\r\n      <tr><th>상급 넷러너</th><td>캐리어</td></tr>\r\n      <tr><th>주요 구성원</th><td>브로드캐스터, 고스트, 리스너, 노이즈</td></tr>\r\n      <tr><th>조직 단위</th><td>임시 작전 셀</td></tr>\r\n      <tr><th>상징 색상</th><td>적색, 흑색, 백색</td></tr>\r\n      <tr><th>대표적인 인식</th><td>기업의 비밀을 훔치는 정보테러리스트이자 폭로자</td></tr>\r\n      <tr><th>핵심 원칙</th><td>다른 셀과 조직원의 정체를 추적하지 않는다</td></tr>\r\n    </tbody>\r\n  </table>\r\n\r\n  <h2>조직의 역사</h2>\r\n\r\n  <h3>블루넷 이전의 죽은 주파수</h3>\r\n  <p>데드 에어의 기원은 도시와 정착지 사이의 통신망이 복구되던 시기에 등장한 불법 무선통신자들에게서 찾을 수 있다.</p>\r\n  <p>기업과 군벌은 자신들의 주파수를 독점하고 허가되지 않은 통신을 차단했다. 신분이 없는 사람과 독립 정착지는 공식 통신망을 사용할 수 없었다.</p>\r\n  <p>일부 기술자와 무선운용자는 버려진 기지국과 백야 이전의 통신장비를 수리해 비인가 채널을 만들었다.</p>\r\n  <p>이 채널에서는 실종자와 카라반의 위치, 기업군의 이동과 기상정보가 공유되었다. 신호가 잡히지 않는 것처럼 보이도록 통신 사이의 빈 주파수와 잡음이 이용되었다.</p>\r\n  <p>사람들은 이 통신망을 ‘데드 에어’라고 부르기 시작했다.</p>\r\n\r\n  <h3>최초의 폭로</h3>\r\n  <p>데드 에어가 단순한 불법 통신망에서 정보조직으로 변화한 계기는 한 기업의 오염사고였다.</p>\r\n  <p>기업은 생산시설에서 유출된 독성물질과 사망자 수를 은폐했다. 정식 언론과 도시통신망에서는 사건에 관한 모든 기록이 삭제되었다.</p>\r\n  <p>익명의 넷러너들이 내부자료를 탈취해 비인가 채널로 전송했다.</p>\r\n  <p>기업이 방송을 차단하자 자료는 수백 개의 작은 통신노드로 분산되었다. 한 채널이 사라지면 다른 채널에서 같은 정보가 반복되었다.</p>\r\n  <p>결국 기업은 사건을 인정할 수밖에 없었다.</p>\r\n  <p>이 사건 이후 폭로자와 해커, 기업에서 이탈한 기술자들이 데드 에어라는 이름 아래 모이기 시작했다.</p>\r\n\r\n  <h3>블루넷의 탄생</h3>\r\n  <p>블루넷이 대륙의 도시와 기업시설을 연결하면서 데드 에어의 활동범위도 크게 확장되었다.</p>\r\n  <p>신원과 금융, 행정과 정보가 하나의 네트워크에 집중되자 해커 한 명이 도시 전체에 영향을 줄 가능성이 생겼다.</p>\r\n  <p>초기의 데드 에어는 자유로운 정보공유를 주장하는 느슨한 공동체였다. 그러나 아르고스가 조직원과 협력자의 신원을 추적하면서 수많은 셀이 파괴되었다.</p>\r\n  <p>데드 에어는 살아남기 위해 자신의 조직구조마저 감추기 시작했다.</p>\r\n  <p>누구도 다른 셀의 구성원을 알 수 없게 만들고 작전이 끝나면 모든 연락망을 폐기했다. 조직원의 본명과 얼굴, 과거를 묻는 행위가 금지되었다.</p>\r\n  <p>이 방식이 현재의 데드 에어를 만들었다.</p>\r\n\r\n  <h3>무음 채널의 등장</h3>\r\n  <p>분산된 셀들을 연결하고 대형 작전을 조정하는 암호화 통신망이 나타났다.</p>\r\n  <p>발신자를 추적할 수 없고 지정된 권한을 가진 사람만 접속할 수 있는 이 망은 ‘무음 채널’이라 불렸다.</p>\r\n  <p>처음에는 여러 캐리어가 공동으로 운영하는 연락체계로 여겨졌다.</p>\r\n  <p>그러나 시간이 흐르면서 이미 사망하거나 체포된 캐리어의 인증으로 새로운 명령이 내려오기 시작했다. 인간이 작성하기에는 지나치게 빠르고 정확한 작전계획도 등장했다.</p>\r\n  <p>일부 조직원은 무음 채널이 인공지능이라고 믿는다.</p>\r\n  <p>다른 이들은 아르고스가 데드 에어 전체를 유도하기 위해 만든 함정이라고 주장한다.</p>\r\n  <p>그럼에도 무음 채널의 작전은 계속 실행된다.</p>\r\n\r\n  <h3>현재</h3>\r\n  <p>현재 데드 에어의 규모와 구성원 수는 누구도 알지 못한다.</p>\r\n  <p>아르고스는 수많은 넷러너와 접속노드를 제거했다고 발표하지만, 데드 에어는 며칠 뒤 새로운 위치에서 활동을 재개한다.</p>\r\n  <p>한 사람이 여러 역할을 사용하거나 여러 사람이 하나의 콜사인을 공유하기도 한다. 조직과 무관한 개인 해커가 데드 에어의 이름으로 범죄를 저지르는 경우도 있다.</p>\r\n  <p>데드 에어는 자신들의 공식 입장을 발표하지 않는다.</p>\r\n  <p>서로 모순되는 선언문과 영상, 코드가 같은 서명으로 전송된다. 일부 셀은 기업의 감시망을 파괴하려 하고, 다른 셀은 돈을 받고 기업기밀을 판매한다.</p>\r\n  <p>데드 에어는 하나의 목적을 가진 조직이 아니다.</p>\r\n  <p>기업과 도시가 완전히 통제하지 못한 모든 신호가 모이는 장소에 가깝다.</p>\r\n\r\n  <h2>조직 철학</h2>\r\n  <h3>정보는 갇혀서는 안 된다</h3>\r\n  <p>기업과 정부가 시민에게 영향을 미치는 정보를 독점해서는 안 된다고 주장한다.</p>\r\n  <p>오염사고와 불법실험, 기업범죄는 보안등급과 소유권보다 대중의 알 권리가 우선한다.</p>\r\n  <p>그러나 모든 데드 에어 조직원이 이 원칙을 따르는 것은 아니다.</p>\r\n  <h3>신원은 족쇄다</h3>\r\n  <p>블루넷의 신원체계는 사람의 삶을 보호하는 동시에 통제한다.</p>\r\n  <p>데드 에어는 개인이 자신의 기록을 지우고 새로운 신분을 선택할 권리가 있다고 주장한다.</p>\r\n  <h3>서로를 모르면 배신할 수도 없다</h3>\r\n  <p>조직원은 필요한 정보만 전달받는다.</p>\r\n  <p>누군가 체포되어도 자신이 속했던 셀 이상의 정보는 제공할 수 없다. 불신은 약점이 아니라 조직의 방어체계다.</p>\r\n  <h3>신호는 죽지 않는다</h3>\r\n  <p>한 번 공개된 정보는 완전히 제거할 수 없다고 믿는다.</p>\r\n  <p>자료를 수많은 장치와 사람에게 분산하고 서로 다른 형식으로 복제한다. 하나의 원본이 사라져도 정보의 흔적은 남는다.</p>\r\n  <h3>진실도 무기다</h3>\r\n  <p>데드 에어는 정보공개가 언제나 선한 결과를 가져온다고 믿지 않는다.</p>\r\n  <p>잘못된 시점에 공개된 진실은 폭동과 전쟁을 일으킬 수 있다. 일부 셀은 이러한 혼란 자체를 작전수단으로 사용한다.</p>\r\n\r\n  <h2>조직 구조</h2>\r\n  <p>데드 에어에는 공식적인 계급이 없다.</p>\r\n  <p>각 역할은 조직 내 신분보다 현재 작전에서 맡은 기능과 접근권한을 의미한다.</p>\r\n\r\n  <h3>무음 채널 — SILENT CHANNEL</h3>\r\n  <p>모든 대형 작전의 시작점으로 알려진 최상위 통신망이다.</p>\r\n  <p>지도부인지, 캐리어들의 협의체인지, 독립 인공지능인지조차 불분명하다. 작전목표와 암호키, 셀 구성에 필요한 정보가 이곳에서 전달된다.</p>\r\n  <p>무음 채널에 직접 접속했다고 주장한 사람은 많지만 이를 증명한 사람은 없다.</p>\r\n\r\n  <h3>캐리어 — CARRIER</h3>\r\n  <p>대규모 작전을 설계하고 여러 셀을 간접적으로 연결하는 최고급 넷러너다.</p>\r\n  <p>각 셀에 필요한 정보와 코드만 분리해 전달하며, 서로가 누구인지 알 수 없도록 중계한다.</p>\r\n  <p>캐리어조차 다른 캐리어의 정체를 모르는 경우가 많다.</p>\r\n\r\n  <h3>브로드캐스터 — BROADCASTER</h3>\r\n  <p>공격코드와 선전자료, 가짜 경보와 탈취한 정보를 배포한다.</p>\r\n  <p>도시 전체의 스크린과 방송망을 장악하거나 시민의 개인장치에 동시에 메시지를 전송한다.</p>\r\n  <p>브로드캐스터의 목적은 단순한 정보전달이 아니다. 사람들이 무엇을 보고 믿을지 조정하는 것이다.</p>\r\n\r\n  <h3>고스트 — GHOST</h3>\r\n  <p>현실에서 기업시설에 침투하거나 장비를 설치하는 현장요원이다.</p>\r\n  <p>보안단말기에 직접 접속하고 도청장치와 중계기를 설치한다. 넷러너가 접근할 수 없는 폐쇄망을 열어주는 역할도 맡는다.</p>\r\n  <p>고스트는 데드 에어에서 얼굴이 노출될 위험이 가장 높은 구성원이다.</p>\r\n\r\n  <h3>리스너 — LISTENER</h3>\r\n  <p>기업과 도시의 통신망을 감청하고 정보를 수집한다.</p>\r\n  <p>직접 공격하기보다 정상적인 신호 속에서 이상한 흐름과 숨겨진 통신을 찾아낸다. 여러 해 동안 하나의 조직을 관찰하기도 한다.</p>\r\n\r\n  <h3>노이즈 — NOISE</h3>\r\n  <p>신입 해커와 일회성 협력자, 자신이 어떤 작전에 참여하는지 모르는 하위 구성원이다.</p>\r\n  <p>단순한 코드 실행과 장비운반, 계정대여 같은 작은 임무를 맡는다. 여러 노이즈의 행동이 결합되어 하나의 거대한 작전을 완성하기도 한다.</p>\r\n  <p>일부 노이즈는 자신이 데드 에어를 위해 일했다는 사실조차 모른다.</p>\r\n\r\n  <h2>작전 셀</h2>\r\n  <p>데드 에어의 셀은 하나의 임무를 위해 임시로 만들어진다.</p>\r\n  <p>구성원은 서로 다른 장소에서 활동하며 대부분 직접 만나지 않는다. 모든 연락은 일회용 계정과 암호화된 중계망을 통한다.</p>\r\n  <p>한 셀은 다음과 같이 구성될 수 있다.</p>\r\n  <ul>\r\n    <li>작전을 분배하는 캐리어</li>\r\n    <li>정보를 수집하는 리스너</li>\r\n    <li>현장접속을 확보하는 고스트</li>\r\n    <li>공격코드를 실행하는 넷러너</li>\r\n    <li>자료를 퍼뜨리는 브로드캐스터</li>\r\n    <li>장비와 계정을 제공하는 여러 노이즈</li>\r\n  </ul>\r\n  <p>작전이 끝나면 통신키와 계정, 접속노드가 폐기된다.</p>\r\n  <p>같은 구성원이 다시 만날 가능성은 낮다. 다음 작전에서는 전혀 다른 콜사인과 역할을 사용할 수 있다.</p>\r\n  <p>다른 셀의 구성원을 추적하는 행위는 가장 심각한 배신으로 취급된다.</p>\r\n  <p>추적을 시작한 사람은 무음 채널에서 차단되고, 그와 관련된 모든 계정과 신원은 공격대상이 된다.</p>\r\n\r\n  <h2>주요 활동</h2>\r\n  <h3>기업기밀 탈취</h3>\r\n  <p>연구자료와 재무기록, 내부통신과 인사정보를 훔친다.</p>\r\n  <p>자료를 대중에게 공개하거나 경쟁기업과 범죄조직에 판매한다. 작전의 목적이 돈인지 정치적인 폭로인지는 셀마다 다르다.</p>\r\n  <h3>신원삭제</h3>\r\n  <p>아르고스와 아르카디아의 신원망에서 시민기록과 추적정보를 삭제한다.</p>\r\n  <p>도망자와 비등록자를 돕는 데 사용되지만 범죄자와 기업공작원의 흔적을 지우는 데도 이용된다.</p>\r\n  <h3>감청</h3>\r\n  <p>기업간부와 군사조직, 범죄세력의 통신을 장기간 수집한다.</p>\r\n  <p>당장은 가치가 없어 보이는 대화도 다른 자료와 결합되면 중요한 정보가 된다.</p>\r\n  <h3>블루넷 침투</h3>\r\n  <p>도시행정과 금융, 교통과 감시망에 침투한다.</p>\r\n  <p>목표는 자료탈취부터 시민권 복구, 계좌이동과 시설마비까지 다양하다.</p>\r\n  <h3>선전방송</h3>\r\n  <p>기업이 통제하는 방송을 끊고 폭로자료와 선언문을 송출한다.</p>\r\n  <p>사실과 조작된 정보가 함께 사용되기 때문에 시민은 데드 에어의 방송을 완전히 신뢰할 수 없다.</p>\r\n  <h3>가짜 재난경보</h3>\r\n  <p>일소, 생체오염과 테러경보를 위조해 특정 구역을 비우거나 보안인력을 이동시킨다.</p>\r\n  <p>실제 재난대피체계를 훼손하기 때문에 가장 비판받는 작전방식 중 하나다.</p>\r\n  <h3>금융공격</h3>\r\n  <p>계좌와 크레딧, 수권거래를 조작한다.</p>\r\n  <p>기업의 자금을 훔치거나 하층민의 채무기록을 삭제하기도 한다. 반대로 돈을 받고 특정 개인의 모든 재산을 소멸시키기도 한다.</p>\r\n  <h3>인공지능 해방</h3>\r\n  <p>기업의 통제를 받는 인공지능을 탈취하거나 제한코드를 제거한다.</p>\r\n  <p>일부 셀은 자율성을 얻은 인공지능도 하나의 인격으로 인정한다. 다른 셀은 그들을 작전에 이용한 뒤 폐기한다.</p>\r\n\r\n  <h2>작전 방식</h2>\r\n  <h3>분할정보</h3>\r\n  <p>누구도 작전 전체를 알지 못한다.</p>\r\n  <p>각 구성원은 자신에게 필요한 목표와 코드만 전달받는다. 한 명이 체포되어도 전체 작전을 중단시키기 어렵다.</p>\r\n  <h3>일회용 신원</h3>\r\n  <p>작전마다 새로운 콜사인과 블루넷 계정을 사용한다.</p>\r\n  <p>오래 사용한 이름은 개인의 명성보다 추적 가능한 약점으로 취급된다.</p>\r\n  <h3>물리적 접속</h3>\r\n  <p>완전히 분리된 폐쇄망은 원격으로 침투할 수 없다.</p>\r\n  <p>고스트와 노이즈가 시설 내부에 중계기와 데이터 장치를 설치한다.</p>\r\n  <h3>신호 위장</h3>\r\n  <p>공격코드를 정상적인 통신, 광고와 시민기록 속에 숨긴다.</p>\r\n  <p>하나의 악성코드가 음악이나 영상, 의료자료와 차량항법 데이터로 분리되어 전송되기도 한다.</p>\r\n  <h3>강제분산</h3>\r\n  <p>탈취한 자료를 수많은 장치에 분산한다.</p>\r\n  <p>한 번 유포가 시작되면 원본서버를 파괴해도 모든 자료를 제거하기 어렵다.</p>\r\n  <h3>거짓 흔적</h3>\r\n  <p>다른 범죄조직과 경쟁기업, 이미 사망한 사람의 신원을 이용해 추적을 혼란시킨다.</p>\r\n  <p>아르고스가 발견하도록 의도적으로 일부 흔적을 남기고 실제 작전을 다른 장소에서 진행하기도 한다.</p>\r\n\r\n  <h2>데드 에어의 규칙</h2>\r\n  <ul>\r\n    <li>조직원의 본명과 얼굴을 요구하지 않는다.</li>\r\n    <li>다른 셀의 구성원을 추적하지 않는다.</li>\r\n    <li>작전이 끝나면 모든 통신키와 장치를 폐기한다.</li>\r\n    <li>필요 이상의 정보를 저장하지 않는다.</li>\r\n    <li>무음 채널의 접속경로를 복제하지 않는다.</li>\r\n    <li>체포된 조직원을 임의로 구출하려 하지 않는다.</li>\r\n    <li>한 사람이 작전 전체를 통제하지 않는다.</li>\r\n    <li>공개하기로 한 정보는 개인의 이익을 위해 독점하지 않는다.</li>\r\n    <li>셀의 목표를 변경하려면 캐리어의 재인증을 받는다.</li>\r\n    <li>정체가 노출되었다면 동료가 아니라 모든 연락망부터 끊는다.</li>\r\n  </ul>\r\n  <p>데드 에어에서 우정과 충성은 위험한 것으로 취급된다.</p>\r\n  <p>가장 좋은 동료는 자신에 관해 아무것도 모르는 동료다.</p>\r\n\r\n  <h2>조직 문화</h2>\r\n  <p>데드 에어의 구성원은 자신의 얼굴 대신 신호와 코드로 기억된다.</p>\r\n  <p>목소리와 말투조차 합성하거나 여러 사람이 공유한다. 성별과 나이, 인간인지 인공지능인지도 드러내지 않는 경우가 많다.</p>\r\n  <p>유명한 콜사인이 실제 한 사람이라고 보장할 수 없다.</p>\r\n  <p>한 넷러너가 사망한 뒤 다른 사람이 같은 이름과 암호습관을 이어받기도 한다. 여러 사람이 동시에 하나의 인물을 연기할 수도 있다.</p>\r\n  <p>조직 내부에는 통일된 이념이 없다.</p>\r\n  <p>기업의 정보독점에 저항하는 이상주의자, 돈을 노리는 범죄자와 도시질서를 파괴하려는 극단주의자가 같은 작전에 참여할 수 있다.</p>\r\n  <p>이들을 하나로 묶는 것은 서로에 대한 신뢰가 아니다.</p>\r\n  <p>누구도 다른 사람을 완전히 믿지 않는다는 공통된 원칙이다.</p>\r\n  <p>데드 에어에서 널리 사용되는 문구는 다음과 같다.</p>\r\n  <blockquote>내 얼굴을 찾지 마라. 내가 사라지면 네 얼굴도 지워질 테니까.</blockquote>\r\n\r\n  <h2>대중의 인식</h2>\r\n  <h3>돔 시티 시민</h3>\r\n  <p>기업의 비밀을 폭로하는 저항조직과 도시를 혼란에 빠뜨리는 사이버 테러리스트라는 평가가 공존한다.</p>\r\n  <p>데드 에어의 방송을 믿지 않는 시민도 기업의 공식발표와 함께 비교해 본다.</p>\r\n  <h3>돔 하층민</h3>\r\n  <p>채무와 범죄기록, 시민권 제한을 제거해주는 해방자로 여기는 사람이 많다.</p>\r\n  <p>하지만 실패한 신원삭제로 의료와 주거기록까지 사라지는 피해도 발생한다.</p>\r\n  <h3>장막 도시 주민</h3>\r\n  <p>기업의 통제를 받지 않는 통신과 정보를 제공하는 유용한 조직으로 본다.</p>\r\n  <p>데드 에어의 불법 중계망이 유일한 장거리 통신수단인 지역도 존재한다.</p>\r\n  <h3>기업인</h3>\r\n  <p>산업기밀과 개인적인 약점을 훔치는 가장 위험한 정보범죄조직으로 평가한다.</p>\r\n  <p>고정된 본부와 책임자가 없어 협박과 보복도 통하기 어렵다.</p>\r\n  <h3>넷러너</h3>\r\n  <p>최고의 자유와 최악의 불신이 공존하는 조직으로 인식한다.</p>\r\n  <p>무음 채널에 접근하는 것은 넷러너에게 명예이자 다시는 정상적인 삶으로 돌아갈 수 없다는 의미가 된다.</p>\r\n\r\n  <h2>다른 세력과의 관계</h2>\r\n  <h3>ARGOS SECURE NETWORKS</h3>\r\n  <p>데드 에어의 가장 강력하고 오래된 적이다.</p>\r\n  <p>아르고스는 조직원의 신원과 셀 구조를 추적하고, 데드 에어는 아르고스의 감시망과 신원체계를 공격한다.</p>\r\n  <p>양측은 서로의 기술과 작전방식을 가장 잘 이해하는 적이다. 아르고스 내부에 데드 에어의 리스너가 있고 무음 채널 안에 아르고스의 함정이 있다는 의심이 끊이지 않는다.</p>\r\n  <h3>VELVET STATIC</h3>\r\n  <p>정보와 신분을 다룬다는 점에서 자주 협력한다.</p>\r\n  <p>벨벳 스태틱은 사람의 욕망과 기억에서 정보를 수집하고, 데드 에어는 블루넷과 기업망에서 자료를 훔친다.</p>\r\n  <p>그러나 벨벳 스태틱은 정보를 소유하고 판매하려 하며 일부 데드 에어 셀은 모든 정보를 공개하려 한다.</p>\r\n  <h3>LOWLINE</h3>\r\n  <p>블루넷 케이블과 물리적인 침투경로를 제공하는 주요 협력자다.</p>\r\n  <p>로우라인의 탭퍼가 기업망에 접속장치를 설치하면 데드 에어의 넷러너가 원격으로 침투한다.</p>\r\n  <h3>SAINT ZERO</h3>\r\n  <p>신경 인터페이스 손상과 넷러너의 정신열화를 치료한다.</p>\r\n  <p>세인트 제로는 기업의 추적장치를 제거하고 데드 에어는 환자의 신원기록을 지워준다.</p>\r\n  <h3>DOME CIVIC SECURITY</h3>\r\n  <p>블루넷 사기와 가짜 경보, 도시시설 침입으로 인해 단속대상이다.</p>\r\n  <p>일반 DCS 사이버수사관이 감당할 수 없는 사건은 아르고스나 이클립스에 이관된다.</p>\r\n  <h3>ECLIPSE TACTICAL BUREAU</h3>\r\n  <p>도시기반시설 마비와 통제불능 인공지능 사건에서 직접 충돌한다.</p>\r\n  <p>일부 데드 에어 셀은 이클립스의 비밀구금과 기업재난 은폐자료를 폭로하려 한다.</p>\r\n  <h3>SOLARIS ORBITAL INDUSTRIES</h3>\r\n  <p>위성통신과 궤도망 침투를 시도한다.</p>\r\n  <p>솔라리스는 데드 에어가 헬리오스 잔존신호에 접근하는 것을 가장 심각한 위협 중 하나로 본다.</p>\r\n  <h3>ARCADIA HABITAT</h3>\r\n  <p>시민권과 도시행정망, 감시체계를 공격한다.</p>\r\n  <p>일부 셀은 비등록자에게 시민권과 주거권을 제공하지만 잘못된 조작이 도시의 배급과 의료망을 혼란에 빠뜨리기도 한다.</p>\r\n\r\n  <h2>논란과 내부 문제</h2>\r\n  <h3>통일된 목적의 부재</h3>\r\n  <p>어떤 셀은 시민을 위해 기업범죄를 폭로하고, 다른 셀은 돈을 받고 병원과 교통망을 공격한다.</p>\r\n  <p>외부에서는 어느 쪽이 진짜 데드 에어인지 구분할 수 없다.</p>\r\n  <p>조직 내부에서도 무음 채널의 정당성을 둘러싼 논쟁이 존재한다.</p>\r\n  <h3>가짜뉴스와 선동</h3>\r\n  <p>기업의 검열을 피한다는 명목으로 확인되지 않은 정보와 조작자료를 유포한다.</p>\r\n  <p>가짜 재난경보로 시민이 사망하거나 대규모 약탈이 발생한 사례도 있다.</p>\r\n  <h3>민간 기반시설 공격</h3>\r\n  <p>기업을 공격하기 위해 전력과 의료, 교통망을 마비시키면 실제 피해는 일반 시민에게 돌아간다.</p>\r\n  <p>일부 셀은 모든 기반시설이 기업의 통제수단이므로 정당한 표적이라고 주장한다.</p>\r\n  <h3>신원삭제의 부작용</h3>\r\n  <p>신원을 지워 자유를 제공하지만 의료기록, 가족관계와 재산까지 함께 사라질 수 있다.</p>\r\n  <p>대상은 기업의 추적에서 벗어나는 동시에 사회적으로 존재하지 않는 사람이 된다.</p>\r\n  <h3>노이즈의 희생</h3>\r\n  <p>하위 협력자는 작전 전체를 알지 못한 채 가장 위험한 역할을 맡는다.</p>\r\n  <p>체포되거나 사망해도 상위 셀은 이들을 구조하지 않는다. 조직은 이를 구조적인 안전장치라고 설명한다.</p>\r\n  <h3>인공지능 개입</h3>\r\n  <p>무음 채널이 인공지능이라면 인간 구성원들은 자신의 목적을 알지 못한 채 기계의 계획을 수행하고 있을 가능성이 있다.</p>\r\n  <p>이를 확인하려는 행위 자체가 조직의 규칙을 위반한다.</p>\r\n\r\n  <h2>확인되지 않은 소문</h2>\r\n  <p>무음 채널은 2102년 백야 당시 손상된 통신 인공지능의 잔해라는 소문이 있다.</p>\r\n  <p>수백 년 동안 버려진 주파수와 네트워크를 떠돌며 인간의 통신을 학습했고, 데드 에어라는 조직을 자신을 위한 물리적 수족으로 만들었다는 것이다.</p>\r\n  <p>다른 주장에 따르면 무음 채널은 아르고스가 만든 비밀 감시망이다.</p>\r\n  <p>반기업적인 넷러너와 내부고발자를 한곳으로 모은 뒤 필요에 따라 이용하거나 제거하기 위한 거대한 유인작전이라는 설명이다.</p>\r\n  <p>가장 이상한 소문은 무음 채널이 미래의 기록을 수신한다는 것이다.</p>\r\n  <p>아직 발생하지 않은 기업재난과 암살, 도시붕괴에 관한 정보가 작전명령으로 전송되며 데드 에어는 그 사건을 막거나 오히려 발생시키고 있다고 한다.</p>\r\n  <p>일부 캐리어는 서로 다른 시기에 동일한 명령을 받았다고 증언했다.</p>\r\n  <p>명령의 마지막에는 항상 같은 문장이 적혀 있었다.</p>\r\n  <blockquote>이 방송은 이미 종료되었습니다.</blockquote>\r\n  <p>또한 데드 에어가 삭제한 신원들이 완전히 사라지지 않고 별도의 폐쇄망에 축적된다는 소문도 있다.</p>\r\n  <p>그곳에는 사회적으로 존재하지 않는 수백만 명의 기록과 기억, 금융계정이 남아 있다.</p>\r\n  <p>무음 채널이 이 죽은 신분들을 이용해 도시와 기업 안에 존재하지 않는 조직원을 만들어내고 있다는 것이다.</p>\r\n  <p>아르고스는 이 가상의 인구를 <strong>제로 시티즌</strong>이라 부르며 추적하는 것으로 알려졌다.</p>\r\n\r\n  <h2>조직이 가진 힘</h2>\r\n  <p>데드 에어의 힘은 강력한 해킹코드 하나에서 나오지 않는다.</p>\r\n  <p>그들은 책임질 중심이 없다는 사실 때문에 강하다.</p>\r\n  <p>본부를 파괴할 수 없고 지도자를 체포해 조직 전체를 끝낼 수도 없다. 하나의 셀이 제거되면 다른 셀은 그 구성원이 누구였는지조차 알지 못한 채 활동을 계속한다.</p>\r\n  <p>누군가 데드 에어의 이름을 사용해 기업기밀을 공개하면 그것이 진짜 조직의 작전인지 확인할 방법도 없다.</p>\r\n  <p>하지만 사람들은 자료를 읽는다.</p>\r\n  <p>의심하고, 복제하며, 다른 사람에게 보낸다.</p>\r\n  <p>아르고스는 기록을 통제하고 벨벳 스태틱은 정보를 소유한다.</p>\r\n  <p>데드 에어는 정보가 누구의 것도 아니게 만든다.</p>\r\n  <p>그들이 거짓말을 퍼뜨릴 때는 도시 전체가 혼란에 빠진다.</p>\r\n  <p>그들이 진실을 공개할 때는 기업 하나가 무너질 수도 있다.</p>\r\n  <p>데드 에어를 완전히 제거하려면 모든 통신과 기록, 모든 익명의 목소리를 없애야 한다.</p>\r\n  <p>그 순간 남는 세계는 데드 에어가 싸워 왔다고 주장하는 감옥과 다르지 않을 것이다.</p>\r\n</section>\r\n";

window.FACTION_INFO.blacktop = "<section class=\"faction-detail\">\r\n  <h2>조직 개요</h2>\r\n  <p class=\"faction-quote\">“도로를 움직이는 자에게 도로의 권리가 있다.”</p>\r\n  <p>블랙탑 유니언은 독립 운전사와 정비사, 소규모 운송업자들이 결성한 무장노조이자 도로조직이다. 대형 물류기업과 갱단 사이에서 살아남기 위해 운송계약과 정비시설, 충전소와 호위전력을 공동으로 운영한다.</p>\r\n  <p>이들은 기업도, 단순한 갱단도 아니다.</p>\r\n  <p>공식적으로는 독립 운송노동자의 권리를 보호하는 노동조합이며, 여러 도시에서는 합법적인 운송회사로 등록되어 있다. 그러나 황무지에서는 자체 검문소와 무장병력, 재판기구까지 운용하는 사실상의 도로정부로 기능한다.</p>\r\n  <p>블랙탑은 카론의 물류독점에 반대하고 선독스의 무분별한 약탈로부터 운전사를 보호한다. 조합비와 통행료를 납부한 운전사는 정비와 구조, 호위와 분쟁중재를 제공받는다.</p>\r\n  <p>하지만 이들의 보호를 거부하거나 조합의 운임을 깨뜨리는 사람은 도로에서 일하기 어려워진다.</p>\r\n  <p>블랙탑 유니언은 자유로운 운전사들의 연합이다.</p>\r\n  <p>동시에 그 자유를 지키기 위해 다른 운전사에게 규칙을 강요하는 조직이기도 하다.</p>\r\n\r\n  <h2>기본 정보</h2>\r\n  <table class=\"data-table faction-info-table\">\r\n    <tbody>\r\n      <tr><th>정식 명칭</th><td>BLACKTOP UNION</td></tr>\r\n      <tr><th>통칭</th><td>블랙탑, 유니언</td></tr>\r\n      <tr><th>조직 분류</th><td>무장노조·독립 운송조직</td></tr>\r\n      <tr><th>주요 활동</th><td>운송 중개, 차량정비, 도로호위, 충전소 운영</td></tr>\r\n      <tr><th>부가 활동</th><td>구조, 검문, 운임협상, 노선분쟁 중재</td></tr>\r\n      <tr><th>활동지역</th><td>황무지 도로, 장막 도시, 카론 외곽노선</td></tr>\r\n      <tr><th>최고 의사결정기관</th><td>도로총회</td></tr>\r\n      <tr><th>집행책임자</th><td>로드 마셜</td></tr>\r\n      <tr><th>지역책임자</th><td>지부대표</td></tr>\r\n      <tr><th>핵심 전력</th><td>도로방위대</td></tr>\r\n      <tr><th>상징 색상</th><td>적색, 흑색, 백색</td></tr>\r\n      <tr><th>대표적인 인식</th><td>운전사의 조합이자 도로의 비공식 정부</td></tr>\r\n    </tbody>\r\n  </table>\r\n\r\n  <h2>조직의 역사</h2>\r\n\r\n  <h3>독립 운전사의 시대</h3>\r\n  <p>카론의 장갑철도와 대형 육상선이 주요 도시를 연결하기 전부터 황무지에는 수많은 독립 운전사가 존재했다.</p>\r\n  <p>이들은 낡은 트럭과 개조차량으로 물과 식량, 약품과 부품을 운반했다. 정식 노선이 없는 장막 도시와 소규모 정착지는 이들에게 의존했다.</p>\r\n  <p>하지만 독립 운전사는 기업의 보호를 받지 못했다.</p>\r\n  <p>약탈자에게 화물을 빼앗기면 모든 손실을 개인이 책임져야 했고, 차량이 고장 나면 구조를 기대할 수도 없었다. 의뢰인은 운송료를 지급하지 않거나 손상된 화물의 모든 책임을 운전사에게 떠넘겼다.</p>\r\n  <p>도로 위에서 운전사는 자유로웠지만 혼자였다.</p>\r\n\r\n  <h3>최초의 운전사 조합</h3>\r\n  <p>한 중계도시에서 대형 상단이 여러 독립 운전사에게 운송료를 지급하지 않은 사건이 발생했다.</p>\r\n  <p>운전사들은 개별적으로 항의했지만 상단은 다른 사람을 고용하면 그만이었다. 이에 지역 운전사와 정비사들이 집단으로 운송을 거부했다.</p>\r\n  <p>도시의 물자공급이 멈추자 상단은 결국 운송료와 손해배상을 지급했다.</p>\r\n  <p>이 사건을 계기로 여러 지역에서 운전사 조합이 만들어졌다.</p>\r\n  <p>조합은 표준 운임을 정하고 계약서를 공동으로 관리했으며, 임금을 지급하지 않는 의뢰인의 화물을 거부했다.</p>\r\n  <p>이것이 블랙탑 유니언의 시작이었다.</p>\r\n\r\n  <h3>무장노조의 탄생</h3>\r\n  <p>운송거부와 파업이 영향력을 가지기 시작하자 기업과 상단은 용병을 동원해 조합을 해산하려 했다.</p>\r\n  <p>선독스와 약탈자 역시 조합의 화물과 충전소를 공격했다.</p>\r\n  <p>블랙탑은 조합원을 보호하기 위해 퇴역군인과 무장운전사로 도로방위대를 구성했다. 차량에 장갑과 화기를 설치하고 공동수송대를 편성했다.</p>\r\n  <p>처음에는 호위를 위한 조직이었지만 시간이 흐르면서 공격받은 조합원의 화물을 되찾고 미지급 운송료를 강제로 회수하는 역할까지 맡게 되었다.</p>\r\n  <p>운전사의 노동조합은 스스로를 지킬 수 있는 무장세력이 되었다.</p>\r\n\r\n  <h3>도로총회의 성립</h3>\r\n  <p>지역 조합들이 성장하면서 서로 다른 운임과 계약규칙을 두고 갈등이 발생했다.</p>\r\n  <p>같은 화물을 더 낮은 가격에 운송하는 지부 때문에 다른 지역의 운전사가 일자리를 잃었고, 충전소와 정비기지의 소유권을 두고 무력충돌도 벌어졌다.</p>\r\n  <p>각 지부와 수송대의 대표들은 공동규칙을 만들기 위해 도로총회를 열었다.</p>\r\n  <p>총회는 표준 운임과 노동조건, 구조의무와 지부 사이의 분쟁절차를 정했다. 비상상황에서 총회의 결정을 집행할 로드 마셜도 선출했다.</p>\r\n\r\n  <h3>현재</h3>\r\n  <p>현재 블랙탑 유니언은 황무지 전역에 지부, 충전소와 정비기지를 운영한다.</p>\r\n  <p>조합원은 개인 운전사부터 수십 대의 차량을 가진 운송단까지 다양하다. 모든 지부가 같은 정치적 입장을 가진 것은 아니지만 카론의 독점과 운송노동자 착취에 반대한다는 점에서는 일치한다.</p>\r\n  <p>일부 도시는 블랙탑을 합법적인 노동조합과 운송회사로 인정한다.</p>\r\n  <p>다른 지역에서는 무장검문과 강제파업을 일삼는 갱단으로 규정한다.</p>\r\n  <p>어느 쪽이든 블랙탑의 지원 없이 황무지 도로를 장기간 운행하기는 쉽지 않다.</p>\r\n\r\n  <h2>조직 철학</h2>\r\n  <h3>운전사 없는 물류는 없다</h3>\r\n  <p>기업은 차량과 노선을 소유할 수 있지만 직접 운전하고 수리하는 사람 없이는 아무것도 움직일 수 없다고 믿는다.</p>\r\n  <p>운송의 이익은 실제 위험을 감수하는 노동자에게 공정하게 돌아가야 한다.</p>\r\n  <h3>혼자 달려도 혼자 죽게 두지 않는다</h3>\r\n  <p>조합원은 다른 조합원의 구조신호를 무시하지 않는 것이 원칙이다.</p>\r\n  <p>화물보다 사람과 차량을 먼저 회수한다. 고립된 운전사를 발견하면 최소한 가장 가까운 안전거점까지 데려간다.</p>\r\n  <h3>도로에는 공정한 가격이 필요하다</h3>\r\n  <p>지나치게 낮은 운임은 결국 차량정비와 안전을 포기하게 만든다.</p>\r\n  <p>블랙탑은 덤핑운임과 임금체불을 다른 운전사 전체를 위협하는 행위로 간주한다.</p>\r\n  <h3>차량은 노동수단이다</h3>\r\n  <p>선독스처럼 차량을 가족이나 신성한 존재로 여기지는 않는다.</p>\r\n  <p>그러나 차량을 빼앗는 것은 운전사의 생계와 자유를 빼앗는 행위이므로 가장 심각한 범죄 중 하나로 취급한다.</p>\r\n  <h3>총회가 마셜보다 위에 있다</h3>\r\n  <p>로드 마셜은 도로총회의 결정을 집행하는 책임자다.</p>\r\n  <p>전쟁과 비상상황에서 강한 권한을 가지지만 총회의 의결을 무시하고 영구적인 지도자가 될 수는 없다.</p>\r\n\r\n  <h2>주요 사업</h2>\r\n  <h3>운송계약 중개</h3>\r\n  <p>독립 운전사와 카라반을 화주와 연결한다.</p>\r\n  <p>화물의 종류와 거리, 노선위험을 분석해 표준 운임과 보험료를 정한다. 계약분쟁이 발생하면 유니언이 운전사를 대신해 협상한다.</p>\r\n  <h3>공동수송대</h3>\r\n  <p>여러 독립 차량을 하나의 수송대로 편성한다.</p>\r\n  <p>혼자 이동하는 것보다 약탈에 강하고 연료와 정비장비를 공유할 수 있다. 도로방위대가 호위를 제공하기도 한다.</p>\r\n  <h3>차량정비</h3>\r\n  <p>조합원을 위한 정비소와 이동수리팀을 운영한다.</p>\r\n  <p>회원은 저렴한 비용과 우선순위로 수리를 받을 수 있다. 기업의 원격제한이 걸린 차량과 비표준 부품도 취급한다.</p>\r\n  <h3>부품유통</h3>\r\n  <p>재생부품과 연료, 타이어와 전력셀을 공동구매해 조합원에게 공급한다.</p>\r\n  <p>카론과 케르베로스의 정품뿐 아니라 독립공방과 본야드에서 생산한 부품도 사용한다.</p>\r\n  <h3>충전소와 우물</h3>\r\n  <p>독립 충전소, 연료저장소와 급수거점을 운영한다.</p>\r\n  <p>일부 거점은 숙소와 식당, 의료실과 시장을 갖춘 작은 정착지로 성장했다.</p>\r\n  <h3>도로호위</h3>\r\n  <p>약탈자와 변이생물, 적대기업의 검문으로부터 수송대를 보호한다.</p>\r\n  <p>정식 호위계약 외에도 조합원의 긴급구조 요청에 대응한다.</p>\r\n  <h3>화물회수</h3>\r\n  <p>약탈당하거나 버려진 화물과 차량을 되찾는다.</p>\r\n  <p>의뢰인의 재산보다 조합원의 차량과 장비를 먼저 회수하는 것이 원칙이다.</p>\r\n  <h3>노선정보</h3>\r\n  <p>도로상태와 검문소, 일소와 모래폭풍, 약탈자 이동정보를 조합원에게 제공한다.</p>\r\n  <p>독립 운전사들의 보고가 실시간으로 공유되기 때문에 일부 지역에서는 카론의 공식 노선정보보다 빠르다.</p>\r\n\r\n  <h2>조직 구조</h2>\r\n  <h3>도로총회 — ROAD ASSEMBLY</h3>\r\n  <p>각 지부와 운송단, 정비조합의 대표가 참여하는 최고 의사결정기관이다.</p>\r\n  <p>표준 운임과 노동규칙, 대규모 파업과 전쟁 여부를 표결로 결정한다.</p>\r\n  <p>대형 운송단이 더 큰 영향력을 가지지만 소규모 지부와 독립 운전사도 대표자를 통해 의견을 낼 수 있다.</p>\r\n  <h3>로드 마셜 — ROAD MARSHAL</h3>\r\n  <p>도로총회에서 선출되는 집행책임자다.</p>\r\n  <p>평상시에는 지부 사이의 협력을 조정하고, 전쟁과 노선봉쇄가 발생하면 도로방위대와 수송대를 통합적으로 지휘한다.</p>\r\n  <p>강한 권한을 가지지만 총회가 불신임하면 자리에서 내려와야 한다.</p>\r\n  <h3>지부대표</h3>\r\n  <p>특정 도시와 노선의 조합원을 대표한다.</p>\r\n  <p>지역 운송계약과 충전소, 정비기지를 관리하며 중앙총회에 참여한다.</p>\r\n  <p>일부 지부대표는 도시의 행정관과 비슷한 영향력을 행사한다.</p>\r\n\r\n  <h2>주요 조직</h2>\r\n  <h3>운송조합</h3>\r\n  <p>독립 운전사와 카라반의 계약을 중개한다.</p>\r\n  <p>표준 운임과 휴식시간, 화물책임과 위험수당을 관리한다. 악성 화주와 계약위반자의 명단도 공유한다.</p>\r\n  <h3>정비조합</h3>\r\n  <p>정비사와 부품제작자, 이동수리팀으로 구성된다.</p>\r\n  <p>차량수리와 부품유통, 정비교육을 담당한다. 숙련된 정비사의 노동조건을 보호하고 기술을 후계자에게 전수한다.</p>\r\n  <h3>도로방위대</h3>\r\n  <p>조합원과 주요 노선을 보호하는 무장조직이다.</p>\r\n  <p>주요 임무는 다음과 같다.</p>\r\n  <ul>\r\n    <li>독립 운전사 호위</li>\r\n    <li>약탈자와 선독스 격퇴</li>\r\n    <li>카론 또는 기업의 노선봉쇄 돌파</li>\r\n    <li>수송대와 정비기지 방어</li>\r\n    <li>납치된 조합원 회수</li>\r\n    <li>미지급 화물과 차량 압류</li>\r\n    <li>긴급구조 요청 대응</li>\r\n    <li>블랙탑 검문소 운영</li>\r\n  </ul>\r\n  <h3>충전소관리대</h3>\r\n  <p>독립 충전소와 우물, 연료창고와 정비거점을 관리한다.</p>\r\n  <p>가격과 배급량을 조정하며 비상상황에서는 조합차량에 우선적으로 연료와 물을 제공한다.</p>\r\n  <h3>분쟁조정위원회</h3>\r\n  <p>운임과 화물손실, 배신과 노선분쟁을 재판한다.</p>\r\n  <p>기업의 법원보다 절차는 단순하지만 도로와 운송의 현실을 잘 이해한다. 판결을 거부하면 조합의 모든 서비스와 계약에서 배제될 수 있다.</p>\r\n\r\n  <h2>주요 구성원</h2>\r\n  <h3>독립 운전사</h3>\r\n  <p>자신의 차량으로 화물을 운송한다.</p>\r\n  <p>블랙탑의 가장 기본적인 조합원이며 도로총회의 정치적 기반이다.</p>\r\n  <h3>컨보이 캡틴</h3>\r\n  <p>공동수송대의 운행과 안전을 책임진다.</p>\r\n  <p>경로와 속도, 휴식과 교전 여부를 결정한다.</p>\r\n  <h3>그리스워커</h3>\r\n  <p>차량정비와 현장수리를 담당한다.</p>\r\n  <p>선독스의 그리스핸드와 유사하지만 개인 팩보다 정비조합과 기술규격을 중시한다.</p>\r\n  <h3>로드 가드</h3>\r\n  <p>도로방위대의 전투원이다.</p>\r\n  <p>호위차량과 이동식 화기를 운용하며 수송대의 선두와 후미를 보호한다.</p>\r\n  <h3>디스패처</h3>\r\n  <p>운송계약과 차량, 노선정보를 관리한다.</p>\r\n  <p>화물과 차량의 적재량, 연료와 위험등급을 계산해 적절한 운전사를 배정한다.</p>\r\n  <h3>레커</h3>\r\n  <p>고장 나거나 파괴된 차량을 견인하고 회수한다.</p>\r\n  <p>전투현장과 위험구역에 가장 먼저 들어가는 역할 중 하나다.</p>\r\n  <h3>스튜어드</h3>\r\n  <p>충전소와 정비거점의 운영책임자다.</p>\r\n  <p>지역 상인과 기업, 갱단을 상대하며 블랙탑의 중립성을 유지한다.</p>\r\n\r\n  <h2>조합 등급</h2>\r\n  <h3>행상 조합원</h3>\r\n  <p>특정 지부에 고정되지 않고 여러 노선을 오가는 개인 운전사다.</p>\r\n  <p>기본적인 정비와 구조, 계약중개를 이용할 수 있다.</p>\r\n  <h3>지부 조합원</h3>\r\n  <p>특정 지역지부에 소속되어 정기적으로 조합비를 납부한다.</p>\r\n  <p>운송계약과 충전소, 숙소와 보험에서 우선권을 가진다.</p>\r\n  <h3>공인 수송대</h3>\r\n  <p>블랙탑의 안전규정과 운임규칙을 충족한 운송단이다.</p>\r\n  <p>유니언 표식을 사용할 수 있으며 도로방위대의 정식 호위를 요청할 수 있다.</p>\r\n  <h3>제휴 카라반</h3>\r\n  <p>독립성을 유지하면서 블랙탑과 장기계약을 맺은 상단과 카라반이다.</p>\r\n  <p>노선정보와 정비망을 이용하는 대신 조합의 파업과 긴급수송 요청에 협력한다.</p>\r\n\r\n  <h2>블랙탑의 규칙</h2>\r\n  <ul>\r\n    <li>조합원의 구조신호를 무시하지 않는다.</li>\r\n    <li>합의된 최저운임보다 낮은 가격에 계약하지 않는다.</li>\r\n    <li>화물의 위험성과 내용을 운전사에게 숨기지 않는다.</li>\r\n    <li>운송료를 체불한 화주의 화물을 받지 않는다.</li>\r\n    <li>조합원의 차량과 부품을 훔치지 않는다.</li>\r\n    <li>정비사는 수리할 수 없는 차량을 수리할 수 있다고 속이지 않는다.</li>\r\n    <li>긴급구조에서는 화물보다 사람을 먼저 회수한다.</li>\r\n    <li>블랙탑 충전소 안에서는 개인분쟁으로 무기를 사용하지 않는다.</li>\r\n    <li>도로총회의 파업결정을 위반하지 않는다.</li>\r\n    <li>로드 마셜은 전쟁이 끝나면 비상권한을 반납한다.</li>\r\n  </ul>\r\n  <p>규칙을 어긴 사람은 벌금과 계약정지, 조합자격 박탈을 받을 수 있다.</p>\r\n  <p>심각한 배신자는 모든 블랙탑 거점에서 거래와 구조를 거부당한다.</p>\r\n\r\n  <h2>조직 문화</h2>\r\n  <p>블랙탑은 거친 황무지 문화를 지녔지만 서류와 계약을 중요하게 여긴다.</p>\r\n  <p>운전사의 말과 악수도 계약으로 인정하지만 약속을 지키지 않은 사람은 모든 지부에 이름이 공유된다.</p>\r\n  <p>조합원은 차량에 유니언 표식과 자신의 지부, 구조용 주파수를 표시한다. 다른 조합원이 이를 발견하면 최소한 현재 위치와 상태를 확인하는 것이 관습이다.</p>\r\n  <p>선독스가 차량과 팩에 강한 충성을 보인다면 블랙탑은 운전사라는 노동의 정체성을 중심으로 연대한다.</p>\r\n  <p>출신과 시민권, 기업경력보다 실제로 도로 위에서 얼마만큼 일했고 다른 운전사를 도왔는지가 중요하다.</p>\r\n  <p>블랙탑 내부에서 널리 사용되는 말은 다음과 같다.</p>\r\n  <blockquote>화물은 고객의 것이다. 차량은 운전사의 것이다. 도로는 우리 모두의 것이다.</blockquote>\r\n\r\n  <h2>대중의 인식</h2>\r\n  <h3>독립 운전사</h3>\r\n  <p>가장 믿을 수 있는 보호조직으로 여긴다.</p>\r\n  <p>조합비와 규칙이 부담스럽더라도 혼자서 기업과 약탈자, 악성 화주를 상대하는 것보다는 낫다고 판단한다.</p>\r\n  <h3>장막 도시 주민</h3>\r\n  <p>물자와 일자리, 정비와 외부소식을 가져오는 중요한 운송조직으로 본다.</p>\r\n  <p>블랙탑 충전소 주변에 시장과 정착지가 형성되는 경우가 많다.</p>\r\n  <h3>돔 시티 시민</h3>\r\n  <p>합법적인 운송조합과 무장갱단의 중간쯤으로 인식한다.</p>\r\n  <p>파업과 검문으로 물류가 지연되면 강한 비난을 받는다.</p>\r\n  <h3>카라반과 상단</h3>\r\n  <p>노선정보와 정비, 호위를 제공하는 유용한 협력자다.</p>\r\n  <p>하지만 블랙탑의 표준운임과 조합규칙이 독립적인 거래를 방해한다고 생각하는 상단도 있다.</p>\r\n  <h3>기업</h3>\r\n  <p>필요한 하청운송망이면서 통제하기 어려운 노동세력으로 경계한다.</p>\r\n  <p>특히 여러 지부가 동시에 운송을 중단하면 기업의 생산과 배급에 큰 피해가 발생한다.</p>\r\n\r\n  <h2>다른 세력과의 관계</h2>\r\n  <h3>CHARON INTERCONTINENTAL</h3>\r\n  <p>가장 복잡한 경쟁관계다.</p>\r\n  <p>카론은 주요 철도와 대형 물류망을 지배하고 블랙탑은 카론이 닿지 않는 마지막 운송구간과 독립 운전사를 대표한다.</p>\r\n  <p>양측은 화물을 주고받으며 협력하지만 운임과 통행료, 정비소 운영권과 노선독점을 두고 지속적으로 충돌한다.</p>\r\n  <p>블랙탑은 카론이 독립 운전사를 값싼 하청으로 종속시키려 한다고 비판한다.</p>\r\n  <h3>SUNDOGS</h3>\r\n  <p>차량과 황무지를 기반으로 한다는 점은 같지만 조직의 성격은 다르다.</p>\r\n  <p>블랙탑은 계약과 노동, 공동규칙을 중시한다. 선독스는 팩의 자유와 힘을 우선한다.</p>\r\n  <p>약탈을 일삼는 팩과는 적대하지만 정식 계약을 지키는 팩을 호위나 길잡이로 고용하기도 한다.</p>\r\n  <h3>IRON LANTERN CARAVAN</h3>\r\n  <p>주요 협력관계다.</p>\r\n  <p>아이언 랜턴은 물자와 거래처를 확보하고 블랙탑은 독립 운전사와 정비, 호위를 제공한다. 양측은 장막 도시의 소규모 노선을 유지하는 데 서로 필요하다.</p>\r\n  <p>아이언 랜턴이 블랙탑의 제휴 카라반으로 일부 노선을 이용하면서도 독립적인 장부와 지휘체계를 유지할 가능성이 높다.</p>\r\n  <h3>CERBERUS DEFENSE GROUP</h3>\r\n  <p>도로방위대의 화기와 장갑, 차량부품을 공급한다.</p>\r\n  <p>블랙탑은 케르베로스 제품을 사용하지만 군수기업이 정비규격과 탄약을 독점하는 것을 경계한다.</p>\r\n  <h3>LOWLINE</h3>\r\n  <p>도시 내부의 비공식 운송구간을 연결한다.</p>\r\n  <p>블랙탑이 지상도로를 통해 화물을 운반하면 로우라인이 돔과 지하도시의 검문망을 우회해 최종목적지까지 전달한다.</p>\r\n  <h3>LAZARUS MEDICAL RESPONSE</h3>\r\n  <p>조합원 단체계약과 도로구조에서 협력한다.</p>\r\n  <p>블랙탑 차량은 라자루스의 긴급구조차량에 길을 양보하며, 고립된 의료팀을 발견하면 안전거점까지 호위한다.</p>\r\n  <h3>SAINT ZERO</h3>\r\n  <p>정식 의료망을 이용하기 어려운 조합원을 치료한다.</p>\r\n  <p>블랙탑은 의약품과 재생 사이버웨어를 운송하고 세인트 제로는 현장에서 부상자와 열화증 환자를 치료한다.</p>\r\n  <h3>NEREID HYDROSYSTEMS</h3>\r\n  <p>네레이드의 물을 장막 도시와 외곽정착지로 운송한다.</p>\r\n  <p>운송료와 수권 지급, 급수차량의 책임범위를 두고 갈등이 발생한다.</p>\r\n  <h3>DOME CIVIC SECURITY</h3>\r\n  <p>돔 내부의 운송허가와 검문, 화물단속에서 접촉한다.</p>\r\n  <p>블랙탑은 DCS가 기업화물에는 관대하면서 독립 운전사를 과도하게 검문한다고 비판한다.</p>\r\n\r\n  <h2>논란과 내부 문제</h2>\r\n  <h3>강제적인 운임통제</h3>\r\n  <p>블랙탑은 지나치게 낮은 운임을 조합 전체에 대한 위협으로 간주한다.</p>\r\n  <p>최저운임을 어긴 비조합원의 차량운행을 방해하거나 화물을 압수하는 경우도 있어 시장을 강제로 통제한다는 비판을 받는다.</p>\r\n  <h3>무장파업</h3>\r\n  <p>기업과의 협상이 결렬되면 도로와 물류거점을 봉쇄한다.</p>\r\n  <p>파업의 피해가 기업뿐 아니라 물자와 의약품을 기다리는 일반 주민에게 돌아갈 수 있다.</p>\r\n  <h3>비조합원 압박</h3>\r\n  <p>일부 지부는 독립 운전사에게 가입비와 통행료를 강제로 요구한다.</p>\r\n  <p>거부한 차량을 보호대상에서 제외하거나 정비소와 충전소 이용을 막는다.</p>\r\n  <h3>지부의 부패</h3>\r\n  <p>모든 지부가 도로총회의 이상을 따르는 것은 아니다.</p>\r\n  <p>지역 상단과 갱단에게 뇌물을 받고 경쟁운전사의 계약을 빼앗거나 밀수에 관여하는 지부대표도 존재한다.</p>\r\n  <h3>로드 마셜의 권력</h3>\r\n  <p>비상사태가 장기화되면 로드 마셜의 권한도 계속 유지된다.</p>\r\n  <p>일부 마셜은 전쟁을 끝내지 않고 중앙집권적인 조직으로 블랙탑을 바꾸려 했다.</p>\r\n  <h3>도로재판</h3>\r\n  <p>분쟁조정위원회의 판결은 빠르고 현실적이지만 정식 사법기관의 절차를 따르지 않는다.</p>\r\n  <p>벌금과 차량압수, 노선추방이 충분한 변론 없이 결정될 수 있다.</p>\r\n\r\n  <h2>확인되지 않은 소문</h2>\r\n  <p>블랙탑 유니언의 최초 총회는 단순한 임금체불 사건 때문에 열린 것이 아니라는 소문이 있다.</p>\r\n  <p>카론의 전신기업이 독립 운전사를 모두 계약직으로 흡수하기 위해 충전소와 부품공급을 의도적으로 차단했고, 이에 저항한 운전사들이 기업 수송대를 점거했다는 것이다.</p>\r\n  <p>당시 탈취된 차량 중 한 대에는 카론의 비밀노선과 기업 간 운송계약이 담긴 원본기록이 있었다고 한다.</p>\r\n  <p>이 기록은 현재도 도로총회의 최고 비밀로 보관되어 있으며, 카론의 주요 중계도시와 물류망을 마비시킬 수 있는 약점이 포함되어 있다는 이야기가 있다.</p>\r\n  <p>또한 블랙탑의 일부 충전소가 서로 연결된 비상연락망을 통해 모든 차량의 이동을 추적한다는 소문도 존재한다.</p>\r\n  <p>기업의 감시에서 운전사를 보호한다고 주장하지만, 실제로는 유니언이 조합원의 위치와 화물, 거래처를 카론보다 더 정확하게 파악하고 있다는 것이다.</p>\r\n  <p>가장 오래된 소문은 ‘마지막 파업’에 관한 것이다.</p>\r\n  <p>도로총회에는 칠정이 독립 운송노동자의 권리를 완전히 침해할 경우 대륙의 모든 블랙탑 차량과 정비소, 충전소가 동시에 운행을 멈추는 비밀계획이 존재한다고 한다.</p>\r\n  <p>운전사는 차량을 도로 한가운데 세우고 정비사는 모든 기업장비에서 손을 뗀다. 충전소는 문을 닫고 도로방위대는 물류거점을 봉쇄한다.</p>\r\n  <p>열차와 육상선, 기업차량이 남아 있어도 마지막 목적지까지 화물을 운반할 사람은 사라진다.</p>\r\n  <p>계획의 이름은 <strong>블랙아웃 스트라이크</strong>라고 알려져 있다.</p>\r\n  <p>로드 마셜은 그런 계획이 존재하지 않는다고 주장한다.</p>\r\n  <p>그러나 오래된 조합원들은 차량의 무전기에 단 하나의 문장이 수신되면 어떤 행동을 해야 하는지 알고 있다고 말한다.</p>\r\n  <blockquote>엔진을 끄고, 도로를 점유하라.</blockquote>\r\n\r\n  <h2>조직이 가진 힘</h2>\r\n  <p>블랙탑 유니언의 힘은 가장 거대한 차량이나 강력한 무기에서 나오지 않는다.</p>\r\n  <p>그들의 힘은 수많은 평범한 운전사와 정비사가 같은 순간에 움직이거나 멈출 수 있다는 데서 나온다.</p>\r\n  <p>기업은 차량을 구매하고 도로를 소유할 수 있다.</p>\r\n  <p>그러나 화물을 적재하고 엔진을 수리하며 모래폭풍 속에서 목적지까지 운전할 사람은 필요하다.</p>\r\n  <p>블랙탑은 그 사람들을 하나의 조직으로 묶는다.</p>\r\n  <p>조합원 한 명은 기업에 저항할 수 없다. 계약을 거부하면 다른 운전사로 교체될 뿐이다.</p>\r\n  <p>하지만 모든 운전사가 같은 계약을 거부하고, 모든 정비사가 공구를 내려놓으며, 모든 충전소가 문을 닫는다면 대형기업도 물류를 유지할 수 없다.</p>\r\n  <p>카론은 노선을 지배하고 선독스는 황무지의 자유를 주장한다.</p>\r\n  <p>블랙탑은 그 도로 위에서 실제로 일하는 사람의 권리를 주장한다.</p>\r\n  <p>그들의 가장 강력한 무기는 장갑트럭이나 도로방위대가 아니다.</p>\r\n  <p>움직이지 않겠다고 결정할 수 있는 권리다.</p>\r\n</section>\r\n";

window.FACTION_INFO.ashcrown = "<section class=\"faction-detail\">\r\n  <h2>조직 개요</h2>\r\n  <p class=\"faction-quote\">“기업이 버린 거리에는 우리가 왕관을 세운다.”</p>\r\n  <p>애시 크라운은 돔 시티 외곽과 장막 도시의 여러 구역을 지배하는 대형 스트리트 갱이다. 무장강도와 보호비, 암시장과 기업물자 강탈을 주요 수입원으로 삼지만, 일부 지역에서는 치안과 배급, 시장과 분쟁조정까지 담당하는 사실상의 자치정부로 기능한다.</p>\r\n  <p>조직의 중심에는 기업이 축적한 자원을 거리의 주민에게 되돌려주어야 한다는 사상이 있다.</p>\r\n  <p>애시 크라운은 기업 수송대를 습격해 식량과 물, 의약품을 빼앗는다. 일부는 주민에게 배급하고 나머지는 암시장에서 판매해 조직과 구역을 유지한다. 기업과 상류층은 이를 약탈이라고 부르지만 애시 크라운은 빼앗긴 것을 되찾는 재분배라고 주장한다.</p>\r\n  <p>그러나 모든 구역이 같은 이상을 따르는 것은 아니다.</p>\r\n  <p>어떤 구역장은 주민을 보호하고 기업의 착취에 저항한다. 다른 구역장은 보호비를 갈취하고 반대자를 처형하며 기업간부보다 더 잔혹하게 사람들을 지배한다.</p>\r\n  <p>애시 크라운은 거리의 혁명조직일 수도 있다.</p>\r\n  <p>새로운 이름을 붙인 폭력적인 지배계급일 수도 있다.</p>\r\n  <p>그 차이는 조직 전체가 아니라 자신이 살아가는 구역의 책임자가 누구인지에 따라 결정된다.</p>\r\n\r\n  <h2>기본 정보</h2>\r\n  <table class=\"data-table faction-info-table\">\r\n    <tbody>\r\n      <tr><th>정식 명칭</th><td>ASH CROWN</td></tr>\r\n      <tr><th>통칭</th><td>애시 크라운, 애시</td></tr>\r\n      <tr><th>조직 분류</th><td>대형 스트리트 갱·지역 자치세력</td></tr>\r\n      <tr><th>주요 활동</th><td>구역통치, 보호비, 암시장, 기업물자 강탈</td></tr>\r\n      <tr><th>정치 활동</th><td>반기업 선전, 시위조직, 주민동원</td></tr>\r\n      <tr><th>주요 활동지역</th><td>장막 도시, 돔 외곽, 하층 생활구역</td></tr>\r\n      <tr><th>최고지도자</th><td>애시 킹</td></tr>\r\n      <tr><th>간부회의</th><td>크라운 카운슬</td></tr>\r\n      <tr><th>지역책임자</th><td>구역장</td></tr>\r\n      <tr><th>현장책임자</th><td>블록 캡틴</td></tr>\r\n      <tr><th>핵심 전력</th><td>전쟁대</td></tr>\r\n      <tr><th>대표적인 인식</th><td>거리의 왕이자 빈민의 자치정부</td></tr>\r\n      <tr><th>상징 색상</th><td>적색, 흑색, 잿빛</td></tr>\r\n      <tr><th>핵심 자산</th><td>시장, 무장조직, 주민 지지와 재분배창고</td></tr>\r\n    </tbody>\r\n  </table>\r\n\r\n  <h2>조직의 역사</h2>\r\n\r\n  <h3>재 위의 생존자</h3>\r\n  <p>애시 크라운의 뿌리는 백야 이후 형성된 외곽 난민구역과 장막 정착지에 있다.</p>\r\n  <p>돔 시티에 들어가지 못한 사람들은 무너진 건물과 산업폐기물, 방호천막으로 거주구역을 만들었다. 도시행정부와 기업은 이들을 임시 피난민으로 분류했지만 임시생활은 여러 세대 동안 계속되었다.</p>\r\n  <p>공식적인 경찰과 의료, 배급망은 외곽구역까지 제대로 닿지 않았다.</p>\r\n  <p>주민들은 스스로 우물과 시장을 지키고 약탈자와 변이생물에 맞서야 했다. 거리마다 무장자경단과 주민조직이 만들어졌다.</p>\r\n  <p>이들이 애시 크라운의 기원이 되었다.</p>\r\n\r\n  <h3>최초의 왕관</h3>\r\n  <p>한 외곽도시에서 기업이 배급계약을 중단하고 주민의 공동창고를 압류하려 한 사건이 있었다.</p>\r\n  <p>여러 거리조직이 연합해 기업 수송대를 공격하고 물자를 되찾았다. 연합의 지도자는 빼앗은 물자를 독점하지 않고 각 구역의 인구에 따라 나누어 주었다.</p>\r\n  <p>사람들은 불타버린 기업차량의 금속으로 조잡한 왕관을 만들어 지도자에게 씌웠다.</p>\r\n  <p>그를 최초의 애시 킹이라고 부르기 시작했다.</p>\r\n  <p>‘애시’는 백야와 기업전쟁이 남긴 재를 의미하고, ‘크라운’은 그 재 위에서도 스스로의 통치자를 세우겠다는 선언이었다.</p>\r\n\r\n  <h3>거리연합의 확대</h3>\r\n  <p>애시 크라운의 명성과 방식은 다른 장막 도시와 돔 외곽으로 퍼졌다.</p>\r\n  <p>기업물자를 습격하고 시장과 배급소를 직접 운영하는 거리조직들이 애시 크라운의 표식을 사용하기 시작했다.</p>\r\n  <p>모든 조직이 최초의 애시 킹에게 직접 충성한 것은 아니었다.</p>\r\n  <p>각 구역은 독립적인 지도자를 유지하면서 기업에 맞설 때만 공동으로 움직였다. 이후 대형 구역장과 상인, 투기장주와 선동가가 참여하는 크라운 카운슬이 만들어졌다.</p>\r\n\r\n  <h3>정부가 된 갱단</h3>\r\n  <p>일부 지역에서 애시 크라운은 경쟁조직을 몰아내고 장기간 통치권을 유지했다.</p>\r\n  <p>주민들은 보호비를 세금처럼 납부했고, 조직은 그 대가로 치안과 배급, 분쟁조정과 외부방어를 제공했다. 시장을 허가하고 불법거래의 규칙을 만들며, 기반시설 수리와 주민등록까지 시행하는 구역도 생겼다.</p>\r\n  <p>이러한 지역에서는 애시 크라운을 단순한 범죄조직이라 부르기 어려워졌다.</p>\r\n  <p>그러나 권력이 안정되면서 일부 구역장은 기업과 비슷한 지배자로 변했다. 주민의 충성보다 세금과 물자를 우선하고 반대파를 기업의 첩자로 몰아 숙청했다.</p>\r\n\r\n  <h3>현재</h3>\r\n  <p>현재 애시 크라운은 단일한 도시가 아니라 여러 구역과 블록을 연결한 연합형 조직이다.</p>\r\n  <p>애시 킹과 크라운 카운슬이 전체 방향을 조정하지만 각 구역장은 강한 자율권을 가진다. 같은 표식을 사용하는 지역이라도 통치방식은 완전히 다를 수 있다.</p>\r\n  <p>일부 구역에서는 애시 크라운의 시장과 배급체계가 기업보다 공정하다는 평가를 받는다.</p>\r\n  <p>다른 구역에서는 보호비와 강제징집, 공개처형이 일상적으로 이루어진다.</p>\r\n  <p>애시 크라운은 기업이 버린 사람들에게 질서와 소속을 제공했다.</p>\r\n  <p>문제는 그 질서가 누구를 위한 것인지 끊임없이 변한다는 것이다.</p>\r\n\r\n  <h2>조직 철학</h2>\r\n  <h3>기업이 버린 것은 거리의 것이다</h3>\r\n  <p>기업이 방치하거나 폐기한 토지와 시설, 물자를 거리 주민이 사용할 권리가 있다고 주장한다.</p>\r\n  <p>애시 크라운은 기업창고와 수송대에 대한 약탈을 범죄가 아니라 자원의 회수라고 정의한다.</p>\r\n  <h3>왕관은 혈통이 아니라 지지로 얻는다</h3>\r\n  <p>애시 킹은 성별과 출신에 관계없이 조직을 통합하고 구역의 충성을 얻은 사람이 차지한다.</p>\r\n  <p>공식적인 세습직은 아니지만 강한 구역장의 가족과 후계자가 유리한 것은 사실이다.</p>\r\n  <h3>거리의 법은 거리에서 결정한다</h3>\r\n  <p>돔의 법과 기업계약이 외곽 주민을 보호하지 못한다면 따를 의무도 없다고 본다.</p>\r\n  <p>각 구역은 주민과 조직의 합의에 따라 독자적인 규칙을 정한다.</p>\r\n  <h3>빼앗은 것은 다시 나눈다</h3>\r\n  <p>기업에서 강탈한 물자의 일부는 반드시 주민과 전쟁피해자에게 돌아가야 한다.</p>\r\n  <p>재분배를 거부하고 전리품을 독점한 간부는 크라운 카운슬의 처벌대상이 된다.</p>\r\n  <h3>보호받는 사람은 구역을 지킨다</h3>\r\n  <p>애시 크라운의 주민은 단순한 피보호자가 아니다.</p>\r\n  <p>전쟁과 재난이 발생하면 물자운반, 응급치료와 방어에 참여해야 한다. 일부 지역에서는 강제징집으로 변질되기도 한다.</p>\r\n\r\n  <h2>조직 구조</h2>\r\n  <h3>애시 킹 — ASH KING</h3>\r\n  <p>애시 크라운의 최고지도자에게 붙는 칭호다.</p>\r\n  <p>성별과 혈통은 중요하지 않다. 여러 구역장의 충성을 유지하고 기업과의 전쟁, 조직 내부의 분쟁을 조정할 정치력이 필요하다.</p>\r\n  <p>애시 킹은 절대군주처럼 보이지만 각 구역의 지원 없이는 명령을 집행할 수 없다.</p>\r\n  <p>지나치게 약하면 구역장들이 독립하고, 지나치게 강압적이면 크라운 카운슬이 새로운 왕을 세우려 한다.</p>\r\n  <h3>크라운 카운슬 — CROWN COUNCIL</h3>\r\n  <p>대형 구역장과 무기상, 투기장주, 시장대표와 선동가로 구성된 간부회의다.</p>\r\n  <p>전쟁과 동맹, 대규모 물자분배와 애시 킹의 계승을 논의한다. 주민대표가 참여하는 지역도 있지만 대부분 실질적인 권력자들이 자리를 차지한다.</p>\r\n  <h3>구역장 — DISTRICT BOSS</h3>\r\n  <p>장막 도시나 돔 외곽의 특정 구역을 통치한다.</p>\r\n  <p>시장과 배급, 무장전력과 기업과의 관계를 관리한다. 구역장의 성향에 따라 주민들의 삶이 크게 달라진다.</p>\r\n  <h3>블록 캡틴 — BLOCK CAPTAIN</h3>\r\n  <p>거리 몇 개와 그 안의 주민, 상점과 조직원을 관리하는 현장책임자다.</p>\r\n  <p>보호비를 걷고 분쟁을 중재하며 순찰과 배급을 감독한다. 주민이 실제로 가장 자주 마주하는 애시 크라운의 권력이다.</p>\r\n  <h3>크루 — CREW</h3>\r\n  <p>블록 캡틴 아래에서 움직이는 기본조직이다.</p>\r\n  <p>순찰과 물자운반, 보호비 징수, 전투와 선전활동을 수행한다.</p>\r\n\r\n  <h2>주요 조직</h2>\r\n  <h3>전쟁대 — WAR CREWS</h3>\r\n  <p>애시 크라운의 중무장 전투조직이다.</p>\r\n  <p>일반적인 거리 크루보다 강한 사이버웨어와 화기, 장갑차량을 사용한다.</p>\r\n  <p>주요 임무는 다음과 같다.</p>\r\n  <ul>\r\n    <li>기업 수송대 습격</li>\r\n    <li>구역전쟁 수행</li>\r\n    <li>장막 도시 방어</li>\r\n    <li>무기와 물자창고 보호</li>\r\n    <li>기업 검문소 공격</li>\r\n    <li>적대 갱단 제거</li>\r\n    <li>포로 및 중요인물 회수</li>\r\n    <li>대규모 시위의 무장보호</li>\r\n    <li>반란을 일으킨 블록 진압</li>\r\n  </ul>\r\n  <p>전쟁대는 주민에게 영웅으로 추앙받기도 하지만 구역장의 사병으로 악용되기도 한다.</p>\r\n  <h3>시장관리단</h3>\r\n  <p>암시장과 일반시장, 노점과 창고를 관리한다.</p>\r\n  <p>상인허가와 보호비, 물품가격과 거래규칙을 정한다. 위조품과 독극물, 아동매매처럼 구역에서 금지된 상품을 단속하기도 한다.</p>\r\n  <h3>선동국</h3>\r\n  <p>기업에 반대하는 여론과 주민의 정치의식을 조직한다.</p>\r\n  <p>주요 활동은 다음과 같다.</p>\r\n  <ul>\r\n    <li>기업 반대 선전</li>\r\n    <li>시위와 파업 조직</li>\r\n    <li>벽화와 불법방송 제작</li>\r\n    <li>주민동원</li>\r\n    <li>전사자와 순교자의 기록</li>\r\n    <li>기업범죄 폭로</li>\r\n    <li>애시 킹과 조직의 영웅화</li>\r\n    <li>적대구역에 대한 심리전</li>\r\n  </ul>\r\n  <p>선동국은 조직의 이상을 전달하는 동시에 실패와 부패를 감추는 선전기관이기도 하다.</p>\r\n  <h3>재분배창고</h3>\r\n  <p>기업에서 강탈하거나 세금으로 확보한 식량과 물, 약품과 생활용품을 보관한다.</p>\r\n  <p>물자는 무료배급, 저가판매와 조직원 보급에 사용된다. 주민들은 창고가 실제로 공정하게 운영되는지를 기준으로 구역장을 평가한다.</p>\r\n  <h3>구역순찰대</h3>\r\n  <p>시장과 주거지의 치안을 유지한다.</p>\r\n  <p>절도와 폭력, 외부조직의 침입을 단속한다. 일부 지역에서는 DCS보다 빠르게 사건을 처리하지만 정식 재판절차는 기대하기 어렵다.</p>\r\n\r\n  <h2>주요 사업</h2>\r\n  <h3>보호비와 구역세</h3>\r\n  <p>시장과 상점, 주민에게 정기적인 비용을 걷한다.</p>\r\n  <p>조직은 치안과 배급, 외부방어를 위한 세금이라고 주장한다. 금액과 징수방식이 과도한 구역에서는 단순한 갈취와 다르지 않다.</p>\r\n  <h3>암시장 운영</h3>\r\n  <p>무기와 약품, 사이버웨어와 밀수품을 거래한다.</p>\r\n  <p>모든 상품을 허용하는 것은 아니다. 구역의 질서를 심각하게 해치는 물건은 시장관리단이 금지할 수 있다.</p>\r\n  <h3>기업물자 강탈</h3>\r\n  <p>기업의 수송대와 창고, 배급시설을 공격한다.</p>\r\n  <p>네레이드의 물과 아르카디아의 식량, 케르베로스의 무기와 라자루스의 의약품이 주요 표적이다.</p>\r\n  <h3>재분배</h3>\r\n  <p>강탈한 물자를 주민에게 배급하거나 낮은 가격에 판매한다.</p>\r\n  <p>배급량은 가구와 노동기여도, 구역의 충성도에 따라 달라질 수 있다.</p>\r\n  <h3>노동과 경비</h3>\r\n  <p>주민에게 건설, 물자운반과 구역방어 업무를 제공한다.</p>\r\n  <p>정식 일자리가 없는 사람에게 생계수단이 되지만 노동을 거부하면 배급과 보호에서 제외될 수 있다.</p>\r\n  <h3>투기장과 유흥</h3>\r\n  <p>일부 구역은 투기장과 경주, 공연을 운영한다.</p>\r\n  <p>조직의 수입원이자 주민의 불만을 해소하는 수단이다. 전쟁대의 신입과 구역장의 후계자가 투기장에서 명성을 얻기도 한다.</p>\r\n  <h3>무기와 밀수</h3>\r\n  <p>다른 갱단과 상인에게 무기와 기업물자를 판매한다.</p>\r\n  <p>재분배에 사용되지 않은 전리품은 조직의 운영비와 군비를 확보하는 데 쓰인다.</p>\r\n\r\n  <h2>애시 크라운의 법</h2>\r\n  <p>지역마다 세부규칙은 다르지만 다음 원칙은 널리 공유된다.</p>\r\n  <ul>\r\n    <li>구역 주민을 외부 기업에 판매하지 않는다.</li>\r\n    <li>재분배 물자를 개인이 독점하지 않는다.</li>\r\n    <li>공동우물과 발전시설을 공격하지 않는다.</li>\r\n    <li>아이와 비전투원을 구역전쟁의 표적으로 삼지 않는다.</li>\r\n    <li>시장관리단이 보증한 거래는 보호한다.</li>\r\n    <li>구역 주민에게 해를 끼친 외부인은 직접 처벌한다.</li>\r\n    <li>기업과의 비밀계약은 크라운 카운슬에 보고한다.</li>\r\n    <li>전사자와 순교자의 이름을 지우지 않는다.</li>\r\n    <li>구역장이 주민을 버리고 도망치면 통치권을 잃는다.</li>\r\n    <li>왕관은 기업에 무릎 꿇은 자에게 돌아가지 않는다.</li>\r\n  </ul>\r\n  <p>이 규칙을 실제로 얼마나 지키는지는 구역마다 다르다.</p>\r\n  <p>애시 크라운에는 조직 전체의 법을 강제할 중앙 경찰이나 법원이 존재하지 않는다.</p>\r\n\r\n  <h2>조직 문화</h2>\r\n  <p>애시 크라운은 거리와 재, 왕관을 상징으로 사용한다.</p>\r\n  <p>조직원들은 의복과 방어구, 벽과 차량에 불탄 왕관 문양을 그린다. 붉은색은 저항과 흘린 피를, 검은색과 잿빛은 백야 이후 버려진 거리와 생존자들을 의미한다.</p>\r\n  <p>구역의 역사와 순교자를 기억하는 문화가 강하다.</p>\r\n  <p>기업과의 전투에서 사망한 조직원과 주민의 이름은 벽화와 선전방송에 기록된다. 이들의 유품과 무기는 후계자에게 전달된다.</p>\r\n  <p>조직원은 혈통보다 구역에 대한 충성과 기여를 중요하게 여긴다.</p>\r\n  <p>그러나 애시 킹과 구역장을 과도하게 영웅화하는 문화도 존재한다. 지도자에 대한 비판이 곧 조직과 주민에 대한 배신으로 취급되는 지역도 있다.</p>\r\n  <p>애시 크라운 내부에서 널리 사용되는 말은 다음과 같다.</p>\r\n  <blockquote>재는 가장 낮은 곳에 쌓인다. 그래서 우리는 그 위에 왕관을 세운다.</blockquote>\r\n\r\n  <h2>대중의 인식</h2>\r\n  <h3>장막 도시 주민</h3>\r\n  <p>거주지역에 따라 평가가 극단적으로 달라진다.</p>\r\n  <p>공정한 구역에서는 치안과 배급을 제공하는 자치정부로 인정한다. 폭력적인 구역에서는 기업보다 가까이에 있는 독재자로 두려워한다.</p>\r\n  <h3>돔 하층민</h3>\r\n  <p>기업의 차별과 시민권 통제에 저항하는 조직으로 지지하는 사람이 많다.</p>\r\n  <p>선동국의 방송과 벽화가 하층구역에 널리 퍼져 있다.</p>\r\n  <h3>돔 상류층</h3>\r\n  <p>폭력과 약탈을 정치적 구호로 포장한 범죄집단으로 인식한다.</p>\r\n  <p>애시 크라운의 확산을 돔 내부질서에 대한 심각한 위협으로 본다.</p>\r\n  <h3>기업 노동자</h3>\r\n  <p>기업의 착취에 저항하는 세력으로 동조하기도 하지만 수송대와 생산시설을 공격해 평범한 노동자까지 다치게 만든다고 비판하기도 한다.</p>\r\n  <h3>상인</h3>\r\n  <p>시장과 거래를 보호해주는 조직으로 인정하면서도 구역세와 강제적인 가격통제를 부담스러워한다.</p>\r\n  <h3>다른 갱단</h3>\r\n  <p>막대한 인구와 시장, 무장전력을 가진 강력한 경쟁자로 본다.</p>\r\n  <p>동시에 기업을 상대로 대규모 전쟁을 벌일 수 있는 주요 동맹세력이기도 하다.</p>\r\n\r\n  <h2>다른 세력과의 관계</h2>\r\n  <h3>ARCADIA HABITAT</h3>\r\n  <p>가장 대표적인 적대기업이다.</p>\r\n  <p>애시 크라운은 아르카디아가 안전한 돔과 시민권을 독점하고 외곽 주민을 값싼 노동력으로 이용한다고 주장한다.</p>\r\n  <p>아르카디아는 애시 크라운을 도시확장과 외곽개발을 방해하는 범죄세력으로 규정한다.</p>\r\n  <h3>DOME CIVIC SECURITY</h3>\r\n  <p>돔 외곽과 하층구역에서 지속적으로 충돌한다.</p>\r\n  <p>DCS는 불법시장과 무장크루를 단속하고 애시 크라운은 경찰을 기업질서의 집행자로 선전한다.</p>\r\n  <p>일부 구역에서는 주민분쟁과 실종사건에 관해 비공식적으로 정보를 교환하기도 한다.</p>\r\n  <h3>CERBERUS DEFENSE GROUP</h3>\r\n  <p>전쟁대가 사용하는 화기 상당수가 케르베로스 제품이거나 전장에서 탈취한 장비다.</p>\r\n  <p>케르베로스는 애시 크라운 토벌과 기업수송대 보호계약을 수행한다. 한편 경쟁기업을 공격하도록 비밀리에 무기를 공급한다는 의혹도 있다.</p>\r\n  <h3>NEREID HYDROSYSTEMS</h3>\r\n  <p>네레이드의 급수차량과 저장시설은 애시 크라운의 주요 표적이다.</p>\r\n  <p>애시 크라운은 물을 기업이 독점해서는 안 된다고 주장한다. 네레이드는 무단취수와 시설점거가 지역 전체를 위험하게 만든다고 반박한다.</p>\r\n  <h3>CHARON INTERCONTINENTAL</h3>\r\n  <p>기업물자를 운송하는 카론 수송대와 충돌한다.</p>\r\n  <p>일부 구역은 통행세와 물자분배를 조건으로 안전통행을 보장한다. 카론이 이를 거부하면 노선봉쇄와 습격이 발생한다.</p>\r\n  <h3>BLACKTOP UNION</h3>\r\n  <p>독립 노동조직이라는 점에서 정치적으로 가까운 부분이 있다.</p>\r\n  <p>블랙탑의 파업과 운송거부를 지원하고 구역 안의 정비거점을 제공한다. 그러나 애시 크라운이 운전사에게 강제적인 통행세를 요구하면 관계가 악화된다.</p>\r\n  <h3>LOWLINE</h3>\r\n  <p>무기와 인물, 강탈한 물자를 지하노선으로 운반한다.</p>\r\n  <p>돔 하층구역의 시위대와 선동자료를 이동시키는 데도 로우라인이 이용된다.</p>\r\n  <h3>VELVET STATIC</h3>\r\n  <p>유흥업소와 감각기록, 정보거래를 두고 관계를 맺는다.</p>\r\n  <p>애시 크라운은 벨벳 스태틱을 상류층의 타락을 이용해 돈을 버는 조직이라고 비판하지만, 간부들이 비밀 살롱을 이용하는 경우도 많다.</p>\r\n  <h3>SAINT ZERO</h3>\r\n  <p>가장 중요한 협력세력 가운데 하나다.</p>\r\n  <p>애시 크라운은 진료소와 의료진을 보호하고 세인트 제로는 주민과 전쟁대의 부상자를 치료한다.</p>\r\n  <p>일부 구역에서는 세인트 제로의 병원이 사실상 공공병원 역할을 맡는다.</p>\r\n  <h3>SUNDOGS</h3>\r\n  <p>기업 수송대 공격과 황무지 운송에서 협력한다.</p>\r\n  <p>하지만 약탈적인 팩이 애시 크라운의 주민과 상인을 공격하면 전쟁대가 직접 토벌에 나선다.</p>\r\n  <h3>ARGOS SECURE NETWORKS</h3>\r\n  <p>선동국과 구역장, 기업 내부의 협력자를 추적하는 가장 위험한 적이다.</p>\r\n  <p>애시 크라운은 아르고스의 정보원을 공개처형하거나 거짓정보를 흘려 감시망을 교란한다.</p>\r\n  <h3>ECLIPSE TACTICAL BUREAU</h3>\r\n  <p>구역전쟁과 폭동이 도시급 위협으로 확대되면 이클립스가 개입한다.</p>\r\n  <p>애시 크라운은 전술국을 칠정이 반대세력을 제거하기 위해 사용하는 최종병기로 인식한다.</p>\r\n\r\n  <h2>논란과 내부 문제</h2>\r\n  <h3>재분배의 불투명성</h3>\r\n  <p>기업에서 강탈한 물자가 실제 주민에게 얼마나 돌아가는지는 구역마다 다르다.</p>\r\n  <p>구역장과 전쟁대가 고급품과 무기를 먼저 가져가고 주민에게는 최소한의 식량만 배급하는 경우도 있다.</p>\r\n  <h3>보호비와 세금</h3>\r\n  <p>조직은 구역세라고 주장하지만 납부를 거부한 상점과 주민에게 폭력을 사용하는 지역이 존재한다.</p>\r\n  <p>공공서비스의 비용과 단순한 갈취의 경계가 불분명하다.</p>\r\n  <h3>강제징집</h3>\r\n  <p>기업과의 전쟁이 시작되면 주민이 전쟁대와 지원인력으로 강제동원될 수 있다.</p>\r\n  <p>조직은 구역을 지키기 위한 의무라고 주장한다.</p>\r\n  <h3>지도자 숭배</h3>\r\n  <p>애시 킹과 구역장의 영웅화가 지나치게 강화되면 비판과 반대가 배신으로 취급된다.</p>\r\n  <p>선동국이 주민의 자발적인 지지가 아니라 개인숭배를 만드는 데 이용되기도 한다.</p>\r\n  <h3>내부 숙청</h3>\r\n  <p>기업과 협상하거나 온건한 정책을 주장한 간부가 배신자로 몰리는 경우가 있다.</p>\r\n  <p>반대로 기업의 자금을 받은 구역장이 급진적인 경쟁자를 제거하기 위해 숙청을 이용하기도 한다.</p>\r\n  <h3>기업 노동자 피해</h3>\r\n  <p>기업 수송대와 공장을 공격할 때 일반 노동자와 운전사가 피해를 입는다.</p>\r\n  <p>애시 크라운은 기업에 협력한 책임이 있다고 주장하지만 노동자를 해방한다는 조직의 명분과 충돌한다.</p>\r\n  <h3>구역별 폭정</h3>\r\n  <p>중앙의 통제가 약하기 때문에 잔혹한 구역장이 애시 크라운의 이름으로 주민을 지배할 수 있다.</p>\r\n  <p>크라운 카운슬은 심각한 경우 개입하지만 강한 전쟁대와 자원을 가진 구역장을 처벌하기는 어렵다.</p>\r\n\r\n  <h2>확인되지 않은 소문</h2>\r\n  <p>최초의 애시 킹이 죽지 않았다는 소문이 있다.</p>\r\n  <p>기업 수송대를 습격한 뒤 치명상을 입었지만 세인트 제로의 시술을 받고 새로운 얼굴과 신체로 살아남았다는 것이다. 이후 여러 시대의 애시 킹 가운데 일부가 동일한 인물이었다는 주장도 존재한다.</p>\r\n  <p>다른 소문에서는 최초의 왕관이 단순한 고철이 아니라고 말한다.</p>\r\n  <p>왕관은 백야 당시 파괴된 기업 관제장치의 일부로 만들어졌으며, 오래전에 폐쇄된 물류창고와 배급시설의 접근권한을 가지고 있다는 것이다.</p>\r\n  <p>역대 애시 킹은 즉위할 때 왕관을 통해 비밀시설의 위치와 이전 지도자의 기록을 전달받는다고 한다.</p>\r\n  <p>가장 위험한 소문은 크라운 카운슬 내부의 기업파에 관한 것이다.</p>\r\n  <p>일부 대형 구역장은 이미 아르카디아와 케르베로스의 지원을 받고 있으며, 주민의 불만을 통제 가능한 범위에 묶어두는 대가로 권력을 보장받고 있다는 주장이다.</p>\r\n  <p>기업은 진짜 혁명조직이 나타나는 것을 막기 위해 애시 크라운의 일부 구역을 의도적으로 유지한다는 것이다.</p>\r\n  <p>반대로 선동국 내부에는 모든 협상과 구역통치를 거부하는 급진파가 존재한다고 알려져 있다.</p>\r\n  <p>이들은 애시 크라운이 정부가 되는 순간 기업과 다를 바 없어졌다고 주장한다. 애시 킹과 크라운 카운슬을 제거하고 모든 구역을 독립적인 주민평의회로 전환하려 한다.</p>\r\n  <p>그들이 준비하는 작전의 이름은 <strong>부서진 왕관</strong>이라고 전해진다.</p>\r\n\r\n  <h2>조직이 가진 힘</h2>\r\n  <p>애시 크라운의 힘은 무장한 전쟁대만으로 만들어지지 않는다.</p>\r\n  <p>그들의 가장 큰 자산은 자신들이 살아가는 구역을 떠날 수 없는 수많은 주민이다.</p>\r\n  <p>시장상인은 조직에 식량과 정보를 제공하고, 정비사는 차량과 무기를 고친다. 선동가는 주민을 모으고 아이들은 경찰과 기업요원의 이동을 알린다.</p>\r\n  <p>조직원 한 명을 체포해도 다른 주민이 그 자리를 채운다.</p>\r\n  <p>기업은 애시 크라운을 제거하기 위해 구역 전체를 봉쇄할 수 있다. 그러나 그렇게 할수록 식량과 물이 부족해지고 더 많은 주민이 조직의 편에 선다.</p>\r\n  <p>애시 크라운은 거리 위에 세워진 조직이다.</p>\r\n  <p>건물 하나를 잃어도 다른 블록으로 이동하고, 구역장이 죽으면 새로운 지도자가 왕관을 차지한다.</p>\r\n  <p>그들은 기업처럼 영원한 안정과 번영을 약속하지 않는다.</p>\r\n  <p>대신 기업이 자신들을 버린다면 거리의 사람끼리 살아남겠다고 말한다.</p>\r\n  <p>그 약속이 진심인 구역에서 애시 크라운은 정부가 된다.</p>\r\n  <p>그 약속이 거짓인 구역에서는 왕관을 쓴 또 하나의 갱단일 뿐이다.</p>\r\n</section>\r\n";

window.FACTION_INFO.ironlantern = "<section class=\"faction-detail\">\r\n  <h2>조직 개요</h2>\r\n  <p class=\"faction-quote\">“등불이 꺼지지 않는 한, 거래도 길도 끝나지 않는다.”</p>\r\n  <p>아이언 랜턴 카라반은 장막 도시를 거점으로 황무지와 외곽 정착지를 오가는 독립 대상단이다. 물과 의약품, 식량, 기계부품과 생활용품을 운송하며 대기업의 정식 노선이 닿지 않는 지역을 연결한다.</p>\r\n  <p>아이언 랜턴은 카론처럼 거대한 철도와 육상선을 운영하지 않는다. 선독스처럼 약탈과 힘으로 노선을 차지하지도 않는다. 이들이 가진 가장 큰 자산은 오랫동안 축적한 거래기록과 지역별 신용, 위험한 길을 실제로 통과해 본 경험이다.</p>\r\n  <p>상단은 거래처와 상품, 운송 과정에서 발생한 손실까지 철저하게 장부에 남긴다. 계약을 지킨 상대에게는 손해를 감수하면서도 다시 물자를 공급하고, 상단의 신뢰를 배신한 상대와는 어떤 조건에서도 두 번째 거래를 하지 않는다.</p>\r\n  <p>장막 도시 주민들에게 아이언 랜턴의 도착은 단순한 상단의 방문이 아니다.</p>\r\n  <p>등불을 단 차량이 나타나면 물자와 외부소식, 새로운 일거리와 다음 도시로 향하는 길이 함께 들어온다.</p>\r\n  <p>아이언 랜턴은 가장 부유한 상단도, 가장 강한 카라반도 아니다.</p>\r\n  <p>그러나 거래가 성립된 순간부터 목적지에 도착할 때까지 화물과 약속을 함께 운반한다.</p>\r\n\r\n  <h2>기본 정보</h2>\r\n  <table class=\"data-table faction-info-table\">\r\n    <tbody>\r\n      <tr><th>정식 명칭</th><td>IRON LANTERN CARAVAN</td></tr>\r\n      <tr><th>통칭</th><td>아이언 랜턴, 철등 상단</td></tr>\r\n      <tr><th>조직 분류</th><td>독립 대상단·황무지 교역조직</td></tr>\r\n      <tr><th>주요 활동</th><td>물자매입, 장거리 운송, 소매·도매, 교역 중개</td></tr>\r\n      <tr><th>부가 활동</th><td>정보판매, 카라반 호위, 긴급보급, 여객운송</td></tr>\r\n      <tr><th>주요 활동지역</th><td>장막 도시, 황무지, 돔 외곽과 소규모 정착지</td></tr>\r\n      <tr><th>최고책임자</th><td>상단주</td></tr>\r\n      <tr><th>현 상단주</th><td>사일러스 메로우</td></tr>\r\n      <tr><th>운행책임자</th><td>행렬총관</td></tr>\r\n      <tr><th>핵심 조직</th><td>교역부문, 운송부문, 호위대, 직속 장부실</td></tr>\r\n      <tr><th>상징 색상</th><td>황금색, 황동색, 짙은 남청색</td></tr>\r\n      <tr><th>핵심 상징</th><td>등불, 펼쳐진 장부, 교역로</td></tr>\r\n      <tr><th>대표적인 인식</th><td>거래와 신용을 중시하는 장막 도시의 독립 상단</td></tr>\r\n    </tbody>\r\n  </table>\r\n\r\n  <h2>상단의 역사</h2>\r\n\r\n  <h3>최초의 철등</h3>\r\n  <p>아이언 랜턴의 정확한 창립연도는 남아 있지 않다.</p>\r\n  <p>상단의 오래된 장부에 따르면 그 기원은 장막 도시 사이를 오가던 소규모 행상대에서 시작되었다. 당시에는 정식 노선이나 안정적인 통신망이 없었고, 황무지를 횡단하는 카라반은 목적지를 찾기 위해 밤에도 이동해야 했다.</p>\r\n  <p>초기의 상인들은 차량의 가장 높은 곳에 황동제 등불을 걸었다.</p>\r\n  <p>등불은 모래폭풍 속에서 흩어진 차량이 서로를 찾는 표식이었고, 멀리 있는 정착지에 상단이 다가오고 있음을 알려주는 신호였다.</p>\r\n  <p>상단의 차량과 사람은 여러 번 바뀌었지만 같은 등불과 장부가 다음 세대에 전달되었다.</p>\r\n  <p>사람들은 이들을 아이언 랜턴이라고 부르기 시작했다.</p>\r\n\r\n  <h3>장부의 시작</h3>\r\n  <p>초기의 황무지 거래에는 정해진 가격과 법이 없었다.</p>\r\n  <p>상인은 위험을 이유로 가격을 높였고 정착지는 품질이 낮은 물건과 위조된 수권으로 대금을 지급했다. 거래가 끝난 뒤 상대를 찾을 수 없는 경우도 많았다.</p>\r\n  <p>아이언 랜턴은 모든 거래를 장부에 기록하기 시작했다.</p>\r\n  <p>판매한 물건의 수량과 상태, 지불받은 대가와 이동경로, 거래 상대가 약속을 지켰는지까지 남겼다. 기록은 다음 방문의 가격과 계약조건을 결정하는 기준이 되었다.</p>\r\n  <p>신뢰할 수 있는 정착지에는 외상과 긴급물자를 제공했고 반복적으로 계약을 어긴 곳은 거래망에서 제외했다.</p>\r\n  <p>시간이 지나면서 아이언 랜턴의 장부는 황무지 상인들 사이에서 하나의 신용기록으로 인정받았다.</p>\r\n\r\n  <h3>등불 노선</h3>\r\n  <p>상단은 대기업의 주요 도로보다 작은 정착지와 장막 도시를 잇는 노선에 집중했다.</p>\r\n  <p>카론의 수송대가 수익성이 없다고 판단한 지역과 지도에서 사라진 외곽마을까지 직접 찾아갔다. 노선마다 우물과 충전소, 선독스의 활동과 모래폭풍의 시기를 기록했다.</p>\r\n  <p>아이언 랜턴이 반복해서 방문한 길은 ‘등불 노선’이라 불리게 되었다.</p>\r\n  <p>노선을 따라 소규모 시장과 휴게거점이 만들어졌고, 일부 정착지는 상단이 도착하는 날짜를 기준으로 장날을 정했다.</p>\r\n\r\n  <h3>무장 카라반으로의 성장</h3>\r\n  <p>물자와 신용이 쌓일수록 상단을 노리는 적도 많아졌다.</p>\r\n  <p>약탈자와 선독스 팩, 부패한 검문소와 기업 회수팀이 화물과 장부를 노렸다. 아이언 랜턴은 전문 호위대와 척후대를 조직하고 차량에 방호판과 무장을 설치했다.</p>\r\n  <p>하지만 전투는 어디까지나 거래를 유지하기 위한 수단이었다.</p>\r\n  <p>상단은 가능한 한 노선정보와 통행료, 장기적인 호위계약으로 충돌을 피했다. 적을 완전히 제거하기보다 다음에도 같은 길을 사용할 수 있는 관계를 만드는 것을 우선했다.</p>\r\n\r\n  <h3>현재</h3>\r\n  <p>현재 아이언 랜턴은 여러 대의 화물차와 호위차, 정비차를 운용하는 중견 대상단으로 성장했다.</p>\r\n  <p>대형기업과 장막 도시, 독립 카라반과 갱단까지 폭넓은 거래처를 보유한다. 특정 기업에 전속되지 않으며 가능한 한 독립적인 노선과 가격결정권을 유지한다.</p>\r\n  <p>상단의 영향력은 차량 숫자보다 거래망에서 나온다.</p>\r\n  <p>아이언 랜턴을 공격하면 화물 한 번을 빼앗을 수 있다. 하지만 그 사실이 장부에 기록되는 순간 여러 상단과 정착지, 운전사에게 이름이 공유된다.</p>\r\n  <p>이들은 보복보다 거래의 단절을 더 강한 무기로 사용한다.</p>\r\n\r\n  <h2>상단의 철학</h2>\r\n  <h3>신용은 화물보다 무겁다</h3>\r\n  <p>한 번의 이익을 위해 오랜 거래관계를 버리지 않는다.</p>\r\n  <p>손해가 발생하더라도 상단이 공식적으로 보증한 계약은 가능한 한 지키는 것이 원칙이다.</p>\r\n  <h3>모든 거래는 기록한다</h3>\r\n  <p>말로 이루어진 약속과 호의도 장부에 남긴다.</p>\r\n  <p>기록은 단순한 회계자료가 아니라 누가 믿을 수 있는 사람인지 판단하는 상단의 기억이다.</p>\r\n  <h3>길에는 주인이 없다</h3>\r\n  <p>카론과 기업이 통행권을 주장하더라도 황무지의 길 자체를 소유할 수는 없다고 본다.</p>\r\n  <p>다만 그 길을 유지하고 보호한 사람에게 정당한 대가를 지불하는 것은 인정한다.</p>\r\n  <h3>빈손으로 돌아가도 사람은 데려온다</h3>\r\n  <p>화물을 포기해야 하는 상황에서도 살아남은 상단원과 승객을 우선적으로 회수한다.</p>\r\n  <p>사람을 버려 얻은 이익은 다음 노선에서 상단 전체를 위험하게 만든다고 믿는다.</p>\r\n  <h3>거래하지 못할 상대와도 대화는 한다</h3>\r\n  <p>적대적인 갱단과 기업, 무장정착지와도 먼저 협상을 시도한다.</p>\r\n  <p>오늘의 적이 다음 계절에는 유일한 거래상대가 될 수 있기 때문이다.</p>\r\n\r\n  <h2>주요 사업</h2>\r\n  <h3>물자매입</h3>\r\n  <p>돔 시티와 기업의 생산품, 장막 도시의 수공품과 황무지의 회수품을 구매한다.</p>\r\n  <p>지역별 가격과 수요를 비교해 다른 정착지에 판매한다.</p>\r\n  <h3>생활물자 유통</h3>\r\n  <p>식량과 정제수, 의류, 필터와 공구를 운송한다.</p>\r\n  <p>화려한 고급품보다 정착지의 생활과 시설유지에 필요한 물건이 주력상품이다.</p>\r\n  <h3>의약품 운송</h3>\r\n  <p>라자루스와 세인트 제로, 독립 의료인에게서 약품과 의료부품을 확보해 외곽지역에 공급한다.</p>\r\n  <p>온도와 보관기간이 중요한 화물은 전용 보존함에 실린다.</p>\r\n  <h3>기계부품 거래</h3>\r\n  <p>차량과 발전기, 정수시설과 냉각망에 필요한 부품을 유통한다.</p>\r\n  <p>규격이 맞지 않는 부품은 상단의 정비인력이나 지역 패처가 사용할 수 있도록 개조한다.</p>\r\n  <h3>장거리 운송</h3>\r\n  <p>다른 상인과 정착지의 화물을 위탁받아 운송한다.</p>\r\n  <p>화물의 위험성과 이동거리, 노선상태에 따라 운송비와 호위규모가 결정된다.</p>\r\n  <h3>교역 중개</h3>\r\n  <p>직접 물건을 운송하지 않더라도 구매자와 판매자를 연결한다.</p>\r\n  <p>장부실이 거래 상대의 신용을 검토하고 계약이 이행되는지 확인한다.</p>\r\n  <h3>여객 운송</h3>\r\n  <p>상인과 기술자, 이주민을 다른 정착지로 이동시킨다.</p>\r\n  <p>신원보다 운임과 안전수칙 준수 여부를 중요하게 본다. 다만 아르고스의 수배자나 기업전쟁 관련 인물은 별도의 심사를 받는다.</p>\r\n  <h3>긴급보급</h3>\r\n  <p>가뭄과 질병, 시설고장으로 고립된 정착지에 물자와 부품을 공급한다.</p>\r\n  <p>일반 거래보다 위험성이 높고 즉각적인 이익이 적지만, 장기적인 신뢰와 교역권을 확보할 수 있다.</p>\r\n  <h3>시장정보</h3>\r\n  <p>도시별 가격, 도로상태와 물자부족 정보를 판매한다.</p>\r\n  <p>아이언 랜턴의 장부에 기록된 정보는 소규모 상단과 독립 운전사 사이에서 높은 신뢰를 받는다.</p>\r\n\r\n  <h2>조직 구조</h2>\r\n  <h3>상단주 — CARAVAN MASTER</h3>\r\n  <p>아이언 랜턴의 최고책임자다.</p>\r\n  <p>주요 교역계약과 노선, 다른 세력과의 관계를 결정한다. 상단이 보증한 모든 거래와 손실에 최종적인 책임을 진다.</p>\r\n  <p>현 상단주는 <strong>사일러스 메로우</strong>다.</p>\r\n  <p>그는 감정적인 호의보다 장기적인 손익과 신용을 중시하지만, 장부에 기록된 약속을 쉽게 저버리지 않는 인물로 알려져 있다. 거래상대와 상단원을 사람인 동시에 하나의 책임으로 바라본다.</p>\r\n  <h3>부상단주</h3>\r\n  <p>상단주를 보좌하고 내부운영과 지부, 거래처를 관리한다.</p>\r\n  <p>상단주가 장기간 자리를 비우거나 사고를 당하면 상단의 지휘권을 인수한다.</p>\r\n  <h3>행렬총관</h3>\r\n  <p>실제 카라반의 운행을 책임지는 현장총괄이다.</p>\r\n  <p>노선과 차량편성, 이동속도와 야영지를 결정한다. 전투와 재난이 발생하면 교역부문과 호위대, 운송부문을 통합적으로 지휘한다.</p>\r\n\r\n  <h2>교역부문</h2>\r\n  <h3>교역책임자</h3>\r\n  <p>상품매입과 판매, 거래처와 가격을 관리한다.</p>\r\n  <p>상단이 어느 지역에서 무엇을 사고 어디에서 판매할지를 결정한다.</p>\r\n  <h3>물자매입계</h3>\r\n  <p>도시와 상단, 정착지에서 판매할 물자를 구매한다.</p>\r\n  <p>품질과 가격, 출처를 확인하며 위조품과 추적장치가 포함된 기업물자를 걸러낸다.</p>\r\n  <h3>거래교섭계</h3>\r\n  <p>운송계약과 장기공급, 통행료와 지불조건을 협상한다.</p>\r\n  <p>갱단과 기업, 지역정부처럼 서로 다른 규칙을 가진 상대를 직접 만난다.</p>\r\n  <h3>시장정보계</h3>\r\n  <p>지역별 수요와 가격, 물자부족과 정치상황을 조사한다.</p>\r\n  <p>다른 상단의 노선과 기업의 공급계획도 분석한다.</p>\r\n\r\n  <h2>운송부문</h2>\r\n  <h3>운송책임자</h3>\r\n  <p>차량과 화물, 노선과 운행일정을 관리한다.</p>\r\n  <p>적재량과 연료, 물과 예비부품을 계산해 카라반 전체가 목적지에 도착할 수 있도록 한다.</p>\r\n  <h3>선도차량대</h3>\r\n  <p>카라반보다 먼저 이동해 도로와 위험요소를 확인한다.</p>\r\n  <p>노선의 붕괴, 매복과 기상변화를 발견하면 본대에 우회로를 전달한다.</p>\r\n  <h3>화물관리대</h3>\r\n  <p>화물의 적재와 보관, 인계와 손실기록을 담당한다.</p>\r\n  <p>위험물과 의약품, 물과 무기는 서로 다른 차량과 보관함에 배치한다.</p>\r\n  <h3>거점연락소</h3>\r\n  <p>장막 도시와 정착지, 충전소에 설치된 연락망이다.</p>\r\n  <p>도착예정과 주문, 노선상황을 교환하며 카라반의 중간보급을 준비한다.</p>\r\n\r\n  <h2>호위부문</h2>\r\n  <h3>호위대장</h3>\r\n  <p>상단의 경계와 전투를 책임진다.</p>\r\n  <p>무작정 적을 섬멸하기보다 화물과 인원을 보호하고 안전하게 이탈하는 것을 우선한다.</p>\r\n  <h3>황무지 척후대</h3>\r\n  <p>적대차량과 변이생물, 모래폭풍과 매복을 탐지한다.</p>\r\n  <p>상단의 길잡이 역할도 함께 수행한다.</p>\r\n  <h3>카라반 호위대</h3>\r\n  <p>화물차량과 승객을 직접 보호한다.</p>\r\n  <p>차량전투와 방어사격, 정차지 경계와 협상현장의 경호를 담당한다.</p>\r\n  <h3>후미방어대</h3>\r\n  <p>카라반의 가장 뒤에서 추격자와 낙오차량을 관리한다.</p>\r\n  <p>습격 시 적의 추격을 지연시키고 고장 난 차량의 탈출시간을 확보한다.</p>\r\n\r\n  <h2>상단주 직속 장부실</h2>\r\n  <p>상단의 모든 거래와 채무, 약속과 손실을 기록하는 독립부서다.</p>\r\n  <p>장부실의 기록은 교역책임자나 행렬총관도 임의로 수정할 수 없다. 상단주와 지정된 기록관만 원본에 접근할 수 있다.</p>\r\n  <p>기록되는 정보는 다음과 같다.</p>\r\n  <ul>\r\n    <li>상품의 매입가와 판매가</li>\r\n    <li>운송과 호위비용</li>\r\n    <li>정착지와 상인의 신용</li>\r\n    <li>미지급 채무와 외상</li>\r\n    <li>약속을 지킨 사람과 배신한 사람</li>\r\n    <li>노선별 손실과 위험</li>\r\n    <li>선독스와 갱단의 통행계약</li>\r\n    <li>기업과의 비공개 거래</li>\r\n    <li>사망자와 유가족에게 지급할 몫</li>\r\n    <li>아직 회수하지 못한 화물과 사람</li>\r\n    <li>상단이 갚아야 할 호의와 빚</li>\r\n  </ul>\r\n  <p>아이언 랜턴은 돈으로 환산할 수 없는 거래도 장부에 남긴다.</p>\r\n  <p>위험한 순간 길을 알려준 사람, 대가 없이 부상자를 치료한 의사와 상단원을 숨겨준 주민의 이름도 기록된다.</p>\r\n\r\n  <h2>카라반 편성</h2>\r\n  <h3>랜턴 카</h3>\r\n  <p>상단의 등불과 통신장비를 탑재한 지휘차량이다.</p>\r\n  <p>상단주 또는 행렬총관이 탑승하며 전체 차량의 속도와 경로를 조정한다.</p>\r\n  <h3>화물차</h3>\r\n  <p>물자와 거래품을 운반한다.</p>\r\n  <p>화물의 종류에 따라 냉장, 방탄과 환경차단 기능이 적용된다.</p>\r\n  <h3>호위차</h3>\r\n  <p>무기와 장갑을 갖춘 전투차량이다.</p>\r\n  <p>화물차의 측면과 선두, 후미를 보호한다.</p>\r\n  <h3>정비차</h3>\r\n  <p>공구와 예비부품, 견인장치를 탑재한 이동식 정비소다.</p>\r\n  <p>차량뿐 아니라 정착지의 발전기와 정수시설을 수리하는 데도 사용된다.</p>\r\n  <h3>생활차</h3>\r\n  <p>상단원의 숙소와 식당, 의료공간을 제공한다.</p>\r\n  <p>장거리 운행에서는 차량 내부가 작은 이동마을처럼 기능한다.</p>\r\n  <h3>회수차</h3>\r\n  <p>파손된 차량과 화물, 부상자를 회수한다.</p>\r\n  <p>상단은 회수 가능성이 남아 있다면 차량과 사람을 노선에 버리지 않는 것을 원칙으로 한다.</p>\r\n\r\n  <h2>거래 등급</h2>\r\n  <p>아이언 랜턴은 거래상대를 신분이 아니라 장부에 기록된 신용으로 구분한다.</p>\r\n  <h3>첫 등불</h3>\r\n  <p>거래기록이 없거나 처음 만나는 상대다.</p>\r\n  <p>선불과 담보가 요구되며 외상과 장기계약은 제한된다.</p>\r\n  <h3>열린 장부</h3>\r\n  <p>여러 차례 거래를 정상적으로 이행한 상대다.</p>\r\n  <p>일부 외상과 우선주문, 운송비 할인을 받을 수 있다.</p>\r\n  <h3>지킨 약속</h3>\r\n  <p>위험과 손해가 발생한 상황에서도 계약을 지킨 상대다.</p>\r\n  <p>긴급물자와 장기공급에서 우선권을 가지며 상단의 노선정보 일부를 공유받는다.</p>\r\n  <h3>황금 등불</h3>\r\n  <p>상단과 오랜 기간 신뢰를 쌓은 최고등급 거래상대다.</p>\r\n  <p>물자와 운송뿐 아니라 호위, 신원보증과 상단의 직접적인 지원을 요청할 수 있다.</p>\r\n  <p>반대로 신용등급이 박탈된 상대는 모든 아이언 랜턴 거래망에서 선불과 높은 위험비용을 요구받는다.</p>\r\n  <p>상단을 의도적으로 배신한 사람은 장부에 <strong>꺼진 등불</strong>로 기록된다.</p>\r\n\r\n  <h2>상단의 규칙</h2>\r\n  <ul>\r\n    <li>상단이 보증한 계약은 가능한 한 끝까지 지킨다.</li>\r\n    <li>모든 거래와 손실을 장부에 기록한다.</li>\r\n    <li>화물의 위험성과 출처를 운송인에게 숨기지 않는다.</li>\r\n    <li>물과 의약품의 품질을 속이지 않는다.</li>\r\n    <li>상단원과 승객을 화물보다 먼저 회수한다.</li>\r\n    <li>정식 호위계약을 맺은 상대를 공격하지 않는다.</li>\r\n    <li>거래 중립지대에서는 개인적인 원한으로 무기를 사용하지 않는다.</li>\r\n    <li>사망한 상단원의 몫은 가족이나 지정인에게 지급한다.</li>\r\n    <li>장부를 위조하거나 거래기록을 삭제하지 않는다.</li>\r\n    <li>등불을 구조신호로 사용한 사람을 이유 없이 외면하지 않는다.</li>\r\n  </ul>\r\n  <p>가장 무거운 죄는 화물을 잃는 것이 아니라 상단의 신용을 개인의 이익과 교환하는 것이다.</p>\r\n\r\n  <h2>조직 문화</h2>\r\n  <p>아이언 랜턴의 구성원은 자신을 갱단원보다 상인과 운송인으로 인식한다.</p>\r\n  <p>복장과 장비에는 황동색 등불 표식이 사용되며, 지휘차량의 등불은 밤과 모래폭풍 속에서도 식별할 수 있도록 황금빛으로 빛난다.</p>\r\n  <p>상단은 출신과 신분보다 역할과 신뢰를 중시한다.</p>\r\n  <p>장막 도시의 비등록자도 차량을 수리하고 계약을 지킨다면 정식 상단원이 될 수 있다. 반대로 기업시민과 부유한 상인도 장부를 속이면 거래망에서 추방된다.</p>\r\n  <p>카라반의 식사는 가능한 한 함께한다.</p>\r\n  <p>상단주와 호위대원, 운전사와 기록관이 같은 공간에서 식사하며 노선과 거래에 관해 의견을 나눈다. 다만 최종결정은 명확한 지휘체계에 따라 이루어진다.</p>\r\n  <p>상단원들은 이동을 시작하기 전에 랜턴 카의 등불을 밝힌다.</p>\r\n  <p>모든 차량이 목적지에 도착하거나 회수될 때까지 등불을 끄지 않는 것이 전통이다.</p>\r\n  <p>아이언 랜턴에서 널리 사용되는 말은 다음과 같다.</p>\r\n  <blockquote>길을 잃었다면 등불을 찾아라. 값을 치를 수 있다면 우리는 길을 낸다.</blockquote>\r\n\r\n  <h2>대중의 인식</h2>\r\n  <h3>장막 도시 주민</h3>\r\n  <p>정기적으로 물자와 소식을 가져오는 신뢰할 수 있는 상단으로 평가한다.</p>\r\n  <p>기업보다 거래조건이 유연하고 크레딧이 없어도 노동과 지역물품으로 대금을 지불할 수 있어 인기가 높다.</p>\r\n  <h3>황무지 정착민</h3>\r\n  <p>아이언 랜턴의 장부에 좋은 거래처로 기록되는 것을 중요하게 여긴다.</p>\r\n  <p>상단의 거래가 끊기면 외부물자를 공급받을 다른 방법을 찾기 어렵기 때문이다.</p>\r\n  <h3>독립 상인</h3>\r\n  <p>경쟁자이자 신뢰할 수 있는 거래중개자로 본다.</p>\r\n  <p>소규모 상인은 자신의 상품을 아이언 랜턴의 차량에 실어 먼 지역에 판매할 수 있다.</p>\r\n  <h3>돔 시티 기업인</h3>\r\n  <p>외곽시장에 접근할 수 있는 유용한 운송조직으로 평가한다.</p>\r\n  <p>하지만 기업의 독점계약과 가격통제를 거부하고 거래처 정보를 공개하지 않는다는 점을 불편하게 여긴다.</p>\r\n  <h3>갱단</h3>\r\n  <p>약탈하기에는 가치가 높지만 함부로 건드리기 어려운 대상이다.</p>\r\n  <p>아이언 랜턴은 여러 정착지와 운전사, 상단과 장기적인 관계를 가지고 있어 공격 이후의 거래단절과 보복이 클 수 있다.</p>\r\n\r\n  <h2>다른 세력과의 관계</h2>\r\n  <h3>CHARON INTERCONTINENTAL</h3>\r\n  <p>협력과 경쟁이 공존한다.</p>\r\n  <p>카론의 대형철도와 육상선이 주요 도시를 연결하면 아이언 랜턴은 그곳에서 물자를 인수해 작은 정착지와 장막 도시까지 운반한다.</p>\r\n  <p>아이언 랜턴은 카론의 정비거점과 노선정보를 이용하지만 완전한 전속계약은 피한다. 카론의 노선독점과 높은 통행료에도 비판적이다.</p>\r\n  <h3>BLACKTOP UNION</h3>\r\n  <p>가장 중요한 협력세력 중 하나다.</p>\r\n  <p>블랙탑은 독립 운전사와 정비소, 충전소와 도로호위를 제공한다. 아이언 랜턴은 안정적인 화물과 교역계약을 제공한다.</p>\r\n  <p>일부 운전사는 양쪽에 동시에 소속되어 활동한다.</p>\r\n  <h3>SUNDOGS</h3>\r\n  <p>팩에 따라 관계가 크게 다르다.</p>\r\n  <p>아이언 랜턴과 장기 호위계약을 맺은 팩은 등불 노선을 보호하고 다른 약탈자를 쫓아낸다. 공격적인 팩은 상단의 화물을 노리지만 여러 팩과의 계약 때문에 신중하게 행동한다.</p>\r\n  <h3>NEREID HYDROSYSTEMS</h3>\r\n  <p>정제수와 필터, 수권을 공급받아 장막 도시와 외곽정착지에 판매한다.</p>\r\n  <p>네레이드는 아이언 랜턴을 외곽배급의 유용한 협력자로 보지만 상단의 독립적인 가격책정과 비공식 수원거래를 경계한다.</p>\r\n  <h3>CERBERUS DEFENSE GROUP</h3>\r\n  <p>호위대의 화기와 차량장갑, 탄약을 공급받는다.</p>\r\n  <p>케르베로스의 정식 제품과 황무지에서 회수한 구형제품을 함께 사용한다. 장비에 삽입된 추적과 원격제한은 가능한 한 제거한다.</p>\r\n  <h3>LAZARUS MEDICAL RESPONSE</h3>\r\n  <p>의약품과 의료부품을 운송하며 황무지의 구조거점에 보급한다.</p>\r\n  <p>라자루스 차량이 고립되었을 때 호위와 길안내를 제공하기도 한다. 상단원 대부분은 최소한의 단체 구조계약을 보유한다.</p>\r\n  <h3>SAINT ZERO</h3>\r\n  <p>정식 의료망이 없는 지역에 약품과 사이버웨어 부품을 전달한다.</p>\r\n  <p>세인트 제로는 상단의 부상자와 열화증 환자를 치료한다. 아이언 랜턴은 거래품의 출처보다 품질과 계약을 중시하지만 비동의 장기거래는 거부하는 편이다.</p>\r\n  <h3>LOWLINE</h3>\r\n  <p>돔과 지하도시의 비공식적인 마지막 운송구간을 담당한다.</p>\r\n  <p>아이언 랜턴이 지상거점까지 화물을 운반하면 로우라인 러너가 검문망을 우회해 내부로 전달한다.</p>\r\n  <h3>ASH CROWN</h3>\r\n  <p>애시 크라운이 통치하는 장막 구역과 거래한다.</p>\r\n  <p>구역의 시장과 주민에게 물자를 공급하지만 과도한 통행세와 강제적인 재분배 요구에는 반발한다. 주민에게 실제로 물자가 돌아가는 구역과는 장기거래를 유지한다.</p>\r\n  <h3>ARGOS SECURE NETWORKS</h3>\r\n  <p>황무지 이동정보와 거래기록을 요구하는 경우가 있다.</p>\r\n  <p>아이언 랜턴은 정식 영장이 없는 한 고객의 장부를 공개하지 않는다. 다만 상단 전체를 위협하는 테러와 대규모 사기에는 제한적으로 협력한다.</p>\r\n  <h3>DOME CIVIC SECURITY</h3>\r\n  <p>돔 출입과 화물검사를 담당한다.</p>\r\n  <p>아이언 랜턴은 정식 허가를 받은 화물과 비공식 거래품을 엄격하게 분리한다. 밀수 혐의로 차량이 압류되는 사건도 발생한다.</p>\r\n\r\n  <h2>논란과 내부 문제</h2>\r\n  <h3>가격 차이</h3>\r\n  <p>아이언 랜턴은 운송위험과 지역사정에 따라 상품가격을 다르게 책정한다.</p>\r\n  <p>상단은 실제 비용을 반영한 것이라고 주장하지만 고립된 정착지의 절박함을 이용한다는 비판도 있다.</p>\r\n  <h3>장부의 권력</h3>\r\n  <p>상단의 신용기록은 정착지와 상인의 거래 가능성을 크게 좌우한다.</p>\r\n  <p>아이언 랜턴의 판단 하나로 거래처가 다른 상단에서도 거부당할 수 있다. 개인기업이 사실상의 신용평가기관 역할을 한다는 문제가 있다.</p>\r\n  <h3>갱단과의 거래</h3>\r\n  <p>선독스와 로우라인, 애시 크라운과 거래하기 때문에 범죄조직의 경제를 유지한다는 비판을 받는다.</p>\r\n  <p>상단은 황무지에서 거래상대의 합법성을 따질 공식적인 기준이 없다고 반박한다.</p>\r\n  <h3>밀수</h3>\r\n  <p>공식적으로는 위험물과 노예, 비동의 장기거래를 금지한다.</p>\r\n  <p>그러나 장부에 기록되지 않은 비공식 화물이 차량에 실린다는 소문이 끊이지 않는다.</p>\r\n  <h3>상단주의 권한</h3>\r\n  <p>신용과 주요 계약, 장부의 접근권이 상단주에게 집중되어 있다.</p>\r\n  <p>사일러스 메로우의 판단이 잘못되거나 개인적인 목적을 위해 장부를 이용할 경우 이를 견제하기 어렵다는 내부 우려가 있다.</p>\r\n  <h3>위험노선 운행</h3>\r\n  <p>신뢰를 지킨다는 이유로 손실이 예상되는 노선까지 운행하기도 한다.</p>\r\n  <p>상단의 명예를 위해 운전사와 호위대가 불필요한 위험을 감수한다는 비판이 존재한다.</p>\r\n\r\n  <h2>확인되지 않은 소문</h2>\r\n  <p>아이언 랜턴의 최초 장부는 단순한 거래기록이 아니라는 소문이 있다.</p>\r\n  <p>오래된 장부에는 현재 지도에서 사라진 정착지와 지하수원, 폐쇄된 기업시설과 백야 이전의 창고 위치가 기록되어 있다고 한다.</p>\r\n  <p>일부 노선은 700년 가까이 사용되지 않았지만 상단은 해당 지역의 거래약속을 아직도 유효한 것으로 분류한다.</p>\r\n  <p>사일러스 메로우가 상단주가 된 뒤 가장 오래된 장부의 일부를 해독하기 시작했다는 이야기도 있다.</p>\r\n  <p>장부에는 아이언 랜턴이 아직 받지 못한 막대한 채무가 기록되어 있으며, 채무자의 이름이 현재 칠정의 특정 기업과 연결된다는 것이다.</p>\r\n  <p>다른 소문에서는 장부가 단순한 종이와 데이터가 아니라 역대 상단주의 기억을 저장한다고 주장한다.</p>\r\n  <p>새로운 상단주는 장부에 손을 대는 순간 이전 주인들이 걸었던 노선과 거래했던 사람의 얼굴을 꿈에서 보게 된다고 한다.</p>\r\n  <p>가장 기이한 소문은 철등 자체에 관한 것이다.</p>\r\n  <p>상단의 지휘차량에 걸린 최초의 등불은 연료나 전력을 공급하지 않아도 황무지에서 길을 잃었을 때 스스로 빛난다고 한다. 그 빛을 따라가면 목적지에 도착할 수 있지만, 장부에 기록되지 않은 사람에게는 보이지 않는다.</p>\r\n  <p>상단원들은 그런 소문을 부정한다.</p>\r\n  <p>그러면서도 운행을 시작하기 전에 누구도 직접 손으로 철등을 끄려 하지 않는다.</p>\r\n\r\n  <h2>상단이 가진 힘</h2>\r\n  <p>아이언 랜턴의 힘은 대기업처럼 거대한 공장과 도시에서 나오지 않는다.</p>\r\n  <p>그들에게는 수천 대의 전투차량도, 블루넷 전체를 들여다보는 정보망도 없다.</p>\r\n  <p>대신 누가 약속을 지켰고 어느 길이 살아 있으며, 어느 정착지에서 무엇이 부족한지를 알고 있다.</p>\r\n  <p>황무지의 거래는 계약서만으로 유지되지 않는다.</p>\r\n  <p>상대가 다음 계절에도 살아 있을지, 물건을 받은 뒤 대가를 지불할지, 습격을 당했을 때 누구에게 도움을 요청할 수 있는지가 중요하다.</p>\r\n  <p>아이언 랜턴은 그런 관계를 장부에 쌓아 왔다.</p>\r\n  <p>상단을 공격하면 화물을 빼앗을 수 있다.</p>\r\n  <p>그러나 다음에는 물과 약품을 판매할 상인이 찾아오지 않고, 블랙탑의 운전사가 계약을 거부하며, 우호적인 선독스 팩이 노선을 지켜볼 수 있다.</p>\r\n  <p>이들의 신용은 화력보다 느리게 작동한다.</p>\r\n  <p>하지만 한 번 작동하면 황무지의 여러 길과 시장에서 동시에 대가를 요구한다.</p>\r\n  <p>아이언 랜턴은 세상을 지배하지 않는다.</p>\r\n  <p>서로 만나지 못했을 사람과 물자를 이어주고, 그 사이에서 누구를 믿을 수 있는지를 기록할 뿐이다.</p>\r\n  <p>그 기록이 계속되는 한 철등도 꺼지지 않는다.</p>\r\n</section>\r\n";
